class Node {
public:
    Node *nxt;
    int idx;

    /*
    Node() {
        this = new Node;
        this->nxt = nullptr;
        idx = 0;
    }
    */
};


class Graph {
    int N;

public:
    Node **adj;

    Graph() {
        adj = nullptr;
    }

    Graph(const int N) {
        adj = new Node*[N + 1];
        for (int i = 0 ; i <= N ; ++i) adj[i] = nullptr;
        this->N = N;
    }

    void add_edge(int u, int v) {
        Node *new_node = new Node;
        new_node->nxt = adj[u];
        new_node->idx = v;
        adj[u] = new_node;
    }

    bool get_next(Node *curr) {
        if (curr->nxt != nullptr) {
            curr = curr->nxt;
            return true;
        }
        return false;
    }

    ~Graph() {
        for (int i = 0 ; i <= N ; ++i) {
            while (adj[i] != nullptr) {
                Node *curr = adj[i];
                adj[i] = adj[i]->nxt;
                delete curr;
            }
        }
    }
};


Graph G;
int edge[SIZE][SIZE], vis[SIZE], col[SIZE];
int cnt[2];

bool dfs1(int v) {
    ++cnt[col[v]];
    for (Node *curr = G.adj[v] ; curr != nullptr ; curr = curr->nxt) {
        int t = curr->idx;
        if (col[t] == -1) {
            col[t] = col[v] ^ 1;
            if (!dfs1(t)) return false;
        }
        if (col[t] != (col[v] ^ 1)) return false;
    }
    return true;
}

vector<pii> num;

bool bipartite(int n) {
    for (int i = 1 ; i <= n ; ++i) {
        cnt[0] = cnt[1] = 0;
        if (col[i] != -1) continue;
        col[i] = 0;
        if (!dfs1(i)) return false;
        num.PB(MP(cnt[0], cnt[1]));
    }
    return true;
}

int dp[SIZE][SIZE];

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    G = Graph(n);
    for (int i = 1 ; i <= n ; ++i) for (int j = 1 ; j <= n ; ++j) edge[i][j] = 0;

    for (int i = 0 ; i < m ; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        edge[u][v] = edge[v][u] = 1;
    }   
    for (int i = 1 ; i <= n ; ++i) {
        col[i] = -1;
        for (int j = 1 ; j <= n ; ++j) {
            if (edge[i][j] || j == i) continue;
            G.add_edge(i, j);
        }
    }

    if (!bipartite(n)) {
        printf("-1\n");
        return 0;
    }

    int sz = num.size();
    dp[0][num[0].X] = dp[0][num[0].Y] = 1;
    for (int i = 1 ; i < sz ; ++i) {
        for (int j = 0 ; j <= n ; ++j) {
            if (j >= num[i].X && dp[i - 1][j - num[i].X]) dp[i][j] = 1;
            if (j >= num[i].Y && dp[i - 1][j - num[i].Y]) dp[i][j] = 1;
        }
    }

    for (int i = n / 2 ; i <= n ; ++i) {
        if (dp[sz - 1][i]) {
            int j = n - i;
            printf("%d\n", i * (i - 1) / 2 + j * (j - 1) / 2); 
            delete G;
            return 0;
        }
    }


}

