#include<bits/stdc++.h>
const int N = 705;
using namespace std;

typedef pair <int, int> ii;
vector <ii> mv;
int n, m, E[N][N], d[N];
int dp[N], Max;

int main(){
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= m; i++){
        int x, y; cin >> x >> y;
        E[x][y] = E[y][x] = 1;

    }
    for (int i = 1; i <= n; i++) d[i] = -1;
    for (int i = 1; i <= n; i++){
        if (d[i] != -1) continue;
        queue <int> mq;
        mq.push(i); d[i] = 0;
        int cnt[2] = {0, 0};
        while (mq.size()){
            int u = mq.front(); mq.pop();
            cnt[d[u]]++;
            for (int v = 1; v <= n; v++){
                if (v == u || E[u][v]) continue;
                if (d[v] != -1 && d[u] == d[v]) return cout << "-1", 0;
                if (d[v] == -1){
                    d[v] = d[u] ^ 1;
                    mq.push(v);
                }
            }
        }
        mv.push_back(ii(cnt[0], cnt[1]));
    }
    dp[0] = 1;
    for (auto x : mv){
        for (int i = n; i >= 0; i--){
            if (i >= x.first) dp[i] |= dp[i-x.first];
            if (i >= x.second) dp[i] |= dp[i-x.second];
        }
    }
    for (int i = 0; i <= n/2; i++){
        if (dp[i]) Max = i;
    }
    cout << Max * (Max - 1) / 2 + (n - Max) * (n - Max - 1) / 2;
}

