	if (color[pos] == 1)c1++;
	else c2++;
	for (int i = 0; i < N; i++) {
		if (complementary_edge[pos][i] && i != bef) {
			if (color[i] == 0) {
				color[i] = color[pos] == 1 ? 2 : 1;
				dfs(i, pos);
			}
			else {
				if ((color[pos] == 1 && color[i] == 2) || (color[pos] == 2 && color[i] == 1)) {
					//ok!
				}
				else f = true;//補グラフは二部グラフではない
			}
		}
	}
