		for (int j = 0; j < N; j++)
			if(i != j)
				complementary_edge[i][j] = true;

	for (int i = 0; i < M; i++) {
		int A, B;
		cin >> A >> B;
		A--, B--;
		edge[A][B] = true;
		edge[B][A] = true;
		complementary_edge[A][B] = false;
