#define until(p) while(!(p))

using ll = std::int64_t;
using P = std::tuple<int,int>;

int N, M;
bool G[701][701];
int colors[701], dp[701][701];
std::vector<P> ps;

bool dfs(int v, int c, int (&n)[2]){
    colors[v] = c;
    n[c] += 1;

    for(int w=1;w<=N;++w){
        if(w == v){
            continue;
        }

        if(G[v][w] == 0){
            if(colors[w] == -1){
                unless(dfs(w, !c, n)){
                    return false;
                }
            }else if(colors[w] == c){
                return false;
            }
        }
    }

    return true;
}

int rec(int i, int s1, int s2){
    if(i == ps.size()){
        return s1 * (s1 - 1) / 2 + s2 * (s2 - 1) / 2;
    }

    if(dp[i][s1] != -1){
        return dp[i][s1];
    }

    int a, b;
    std::tie(a, b) = ps[i];

    return dp[i][s1] = std::min(rec(i + 1, s1 + a, s2 + b), rec(i + 1, s1 + b, s2 + a));
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> M;

    for(int i=0;i<M;++i){
        int A, B;
        std::cin >> A >> B;

        G[A][B] = G[B][A] = 1;
    }

    memset(colors, -1, sizeof(colors));

    for(int i=1;i<=N;++i){
        if(colors[i] == -1){
            int n[2] = {0, 0};
            unless(dfs(i, 0, n)){
                std::cout << -1 << std::endl;
                return 0;
            }
            ps.emplace_back(n[0], n[1]);
        }
    }

    memset(dp, -1, sizeof(dp));

    int mn = rec(0, 0, 0);
    std::cout << mn << std::endl;
}

