typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

void add_edge(Graph &G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n, m;
    cin >> n >> m;

    vec<P> res;
    REP(i, m) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        res.push_back({a, b});
        res.push_back({b, a});
    }
    if(m == n * (n - 1) / 2) {
        cout << m - n / 2 * (n / 2 + n % 2) << en;
        return;
    }

    sort(all(res));

    Graph g(n);
    REP(i, n) {
        REP(j, n) {
            if(i == j)
                continue;
            if(!binary_search(all(res), make_pair((ll)i, (ll)j))) {
                add_edge(g, i, j, 1, false, 0);
            }
        }
    }

    vec<ll> used(n, -1);
    ll con0 = 0;
    ll con1 = 0;

    auto dfs = [&](auto &&self, int v, int p) -> bool {
        if(used[v])
            con1++;
        else
            con0++;
        for(auto e : g[v]) {
            if(e.to == p)
                continue;
            if(used[e.to] == -1) {
                used[e.to] = !used[v];
                if(!self(self, e.to, v)) {
                    return false;
                }
            } else {
                if(used[e.to] == used[v]) {
                    return false;
                }
            }
        }
        return true;
    };

    vec<P> con;
    REP(i, n) {
        if(used[i] != -1)
            continue;
        con0 = 0;
        con1 = 0;
        used[i] = 0;
        if(!dfs(dfs, i, -1)) {
            cout << -1 << en;
            return;
        }
        con.push_back({con0, con1});
    }

    vvec<ll> dp(con.size() + 1, vec<ll>(n + 1, 0));
    dp[0][0] = 1;

    REP(i, con.size()) {
        REP(j, n) {
            if(!dp[i][j])
                continue;
            dp[i + 1][j + con[i].first] = 1;
            dp[i + 1][j + con[i].second] = 1;
        }
    }

    ll num = n;
    REP(i, n) {
        if(dp[con.size()][i])
            chmin(num, max(n - i, (ll)i));
    }

    cout << num * (num - 1) / 2 + (n - num) * (n - num - 1) / 2 << en;
}

