int findroot(int x)
{
    int root;
    int col=0;
    for (root=x;fa[root]!=-1;)
    {
        col=col^c[root];
        root=fa[root];
    }
    return_col=col;
    int tempx,tempc;
    for (;fa[x]!=-1;)
    {
        tempx=fa[x];
        tempc=c[x]^col;
        fa[x]=root;
        c[x]=col;
        x=tempx;
        col=tempc;
    }
    return root;
}
