bool bipartite(int u, int c, int* count)
{
    if(color[u]!=-1)
        return color[u]==c;
    color[u] = c;
    count[c]++;
    for(int v = 1; v <= n; v++)
        if(adj[u][v] && !bipartite(v,c^1,count))
            return false;
    return true;
}
int memo[N+1][N+1];
int dp(int i, int diff, vector<int>& d)
{
    if(i==d.size())
        return diff;
    else if(memo[i][diff] != -1)
        return memo[i][diff];
    else
        return memo[i][diff] = min(dp(i+1,diff+d[i],d),dp(i+1,abs(diff-d[i]),d));
}
