    vector<int> d;
    memset(color,-1,sizeof color);
    for(int u = 1; u <= n; u++)
        if(color[u]==-1)
        {
            int count[] = {0,0};
            if(!bipartite(u,0,count))
                return -1;
            d.push_back(abs(count[0]-count[1]));
        }

    memset(memo,-1,sizeof memo);
    int diff = dp(0,0,d);

    int x = (n-diff)/2;
    int y = n-x;
    return x*(x-1)/2 + y*(y-1)/2;
}
