struct gaoxiao
{
	bool f[N*2];

	void reset(){f[0]=1;}
	void insert(int x)
	{
		for(int i=n;~i;i--)
			if(f[i])f[i+x]=1;
	}
	int ask(int x)
	{
		return x*(x-1)/2;
	}
	int calc()
	{
		int ret=M;
		for(int i=0;i<=n;i++)
			if(f[i])ret=std::min(ret,ask(i)+ask(n-i));
		return ret;
	}
}d;

