			if (cnt[1]!=cnt[2])
			a[++ca]=cnt[1]-cnt[2];
		}
	}
	f[0]=true;
	for(int i=1; i<=ca; ++i) {
		for(int j=N; j>=a[i]; --j) {
			if (f[j-a[i]]) f[j]=true;
		}
	}
	int mn=9999999;
