using namespace std;
const int N=2005;
int n,m,a[N],b[N];
int g[N][N];
int dp[N],vis[N],x,y,f=0;
void dfs(int p,int t){
	if (vis[p]){
		if (vis[p]!=t+1)
			f=1;
		return;
	}
	vis[p]=t+1;
	if (t)
		x++;
	else
		y++;
	for (int i=1;i<=n;i++)
		if (i!=p&&!g[p][i])
			dfs(i,t^1);
}
int calc(int x){
	return x*(x-1)/2;
}
int main(){
	scanf("%d%d",&n,&m);
	for (int i=1;i<=m;i++){
		scanf("%d%d",&a[i],&b[i]);
		g[a[i]][b[i]]=g[b[i]][a[i]]=1;
	}
	memset(dp,0,sizeof dp);
	dp[0]=1;
	for (int i=1;i<=n;i++){
		if (vis[i])
			continue;
		x=0,y=0;
		dfs(i,0);
		for (int j=n;j>=0;j--)
			dp[j+x]|=dp[j];
		for (int j=n;j>=0;j--)
			dp[j+y]|=dp[j];
	}
	if (f){
		puts("-1");
		return 0;
	}
	int ans=n*n*2;
	for (int i=0;i<=n;i++)
		if (dp[i])
			ans=min(ans,calc(i)+calc(n-i));
	printf("%d",ans);
	return 0;
}

