using namespace std;
template<class T, class T2> inline int chkmax(T &x, const T2 &y) { return x < y ? x = y, 1 : 0; }
template<class T, class T2> inline int chkmin(T &x, const T2 &y) { return x > y ? x = y, 1 : 0; }
const int MAXN = (1 << 10);

int n, m;
vector<int> adj[MAXN];
vector<int> nadj[MAXN];

void read()
{
	cin >> n >> m;
	for(int i = 0; i < m; i++)
	{
		int u, v;
		cin >> u >> v;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

int col[MAXN], C, cnt;

void dfs(int u, int c)
{
	if(col[u] != -1 && col[u] != c)
	{
		cout << -1 << endl;
		exit(0);
	}
	else if(col[u] != -1) return;

	C += c;
	cnt++;

	col[u] = c;
	for(int v: nadj[u])
		dfs(v, c ^ 1);
}

bitset<MAXN> bs;

void solve()
{
	for(int i = 1; i <= n; i++) 
	{
		sort(adj[i].begin(), adj[i].end());
		for(int j = 1; j <= n; j++)
			if(j != i && (lower_bound(adj[i].begin(), adj[i].end(), j) == adj[i].end() || *lower_bound(adj[i].begin(), adj[i].end(), j) != j))
				nadj[i].push_back(j);
	}

	bs[0] = 1;
	memset(col, -1, sizeof(col));
	for(int i = 1; i <= n; i++)
		if(col[i] == -1)
		{
			C = cnt = 0;
			dfs(i, 1);
			bs = (bs << C) | (bs << (cnt - C));
		}

	int answer = n * n;
	for(int cnt1 = 0; cnt1 <= n; cnt1++)
		if(bs[cnt1]) chkmin(answer, cnt1 * (cnt1 - 1) / 2 + (n - cnt1) * (n - cnt1 - 1) / 2);

	cout << answer << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

