int dp[N*N];

int kol[N*N];

int czy[N*N];

bool zle;

int t[N*N];

void dfs(int v,int k){
	czy[v] = 1;
	t[k]++;
	kol[v] = k;

	FOR(i,1,n){
		if (G[v][i] == 1){
			if (czy[i] == 0){
				dfs(i,k^1);
			}else{
				if (kol[v] == kol[i])
					zle = 1;
			}
		}
	}
}

void dodaj(int x,int y){
	FORR(i,n,0){
		if (dp[i]){
			dp[i+x] = 1;
			dp[i+y] = 1;
		}
	}
}

int s(int x){
	return x*(x-1)/2;
}

void solve()
{	
	cin >> n >> m;

	FOR(i,1,m){
		int a,b;
		cin >> a >> b;

		g[a][b] = g[b][a] = 1;
	}

	FOR(i,1,n){
		g[i][i] = 1;
	}

	FOR(i,1,n){
		FOR(j,1,n){
			G[i][j] = g[i][j] ^ 1;
		}
	}

	dp[0] = 1;

	FOR(i,1,n){
		if (czy[i] == 0){
			t[0] = t[1] = 0;
			dfs(i,0);
			dodaj(t[0],t[1]);
		}
	}

	int res = INF;

	if (zle){
		cout << -1 << endl;
		return;
	}

	FOR(i,0,n){
		if (dp[i]){
			res = min(s(i) + s(n-i),res);
		}
	}

	cout << res << endl;;

    return;
}

