#include <bits/stdc++.h>

int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    std::vector<std::vector<bool>> graph(n, std::vector<bool>(n, true));
    for (int i = 0; i < n; i++)
        graph[i][i] = false;
    for (int i = 0, u, v; i < m; i++) {
        scanf("%d%d", &u, &v);
        --u, --v;
        graph[u][v] = graph[v][u] = false;
    }
    std::vector<bool> color(n), vis(n), dp(n + 1);
    dp[0] = true;
    bool flag = true;
    for (int i = 0; i < n && flag; i++) {
        if (vis[i]) continue;
        bool is_bipartite = true;
        std::queue<int> q({i});
        vis[i] = true;
        int count[2] = {};
        for (; !q.empty(); q.pop()) {
            int u = q.front();
            count[color[u]]++;
            for (int v = 0; v < n; v++) {
                if (not graph[u][v]) continue;
                if (vis[v] && color[v] == color[u])
                    is_bipartite = false;
                else if (not vis[v]) {
                    color[v] = 1 ^ color[u];
                    vis[v] = true;
                    q.push(v);
                }
            }
        }
        std::vector<bool> dp2(n + 1);
        for (int j = 0; j <= n; j++) {
            if (not dp[j]) continue;
            dp2[j + count[0]] = true;
            dp2[j + count[1]] = true;
        }
        dp.swap(dp2);
        if (not is_bipartite)
            flag = false;
    }
    if (not flag)
        puts("-1");
    else {
        int ans = INT_MAX;
        for (int i = 0; i <= n; i++) {
            if (not dp[i]) continue;
            ans = std::min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
        printf("%d\n", ans);
    }
    return 0;
}

