bool can = true;

vector<vector<bool> > bridge(700, vector<bool>(700, false));
vector<bool> non_visit(700, false);

vector<bool> black(700,false);

int paint(int idx,bool b){
  non_visit[idx] = false;
  black[idx] = b;
  int blacksum = 0;
  REP(i, bridge[idx].size())
  {
    if(bridge[idx][i]){
      if(non_visit[i]){
        blacksum+=paint(i, !b);
      }
      else
      {
        if(black[i] != !b){
          can = false;
        }
      }
    }
  }
  blacksum += b ? 1 : -1;
  return blacksum;
}

int main() {
  int N, M;
  cin >> N >> M;
  REP(i,N){
  REP(j,N){
    if(i!=j){
      bridge[i][j] = true;
    }
  }
  non_visit[i] = true;
  }
  REP(i,M){
    int a, b;
    cin >> a >> b;
    bridge[a - 1][b - 1] = false;
    bridge[b - 1][a - 1] = false;
  }

  vector<int> num(0);

  REP(i, N)
  {
    if(non_visit[i]){
      num.push_back(abs(paint(i,true)));
    }
  }

  if(can){
    vector<bool> hoge(4000, false);
    hoge[2000] = true;
    REP(i,num.size()){
    vector<bool> newhoge(4000, false);
    for (int j = 1000; j <= 3000;++j){
      if(hoge[j+num[i]]||hoge[j-num[i]]){
        newhoge[j] = true;
      }
    }
    REP(i,newhoge.size()){
      hoge[i] = newhoge[i];
    }
    }
    int min = 9999;
    REP(i,hoge.size()){
      if(hoge[i]){
        if(min>abs(i-2000)){
          min = abs(i - 2000);
        }
      }
    }
    for (int i = 0; i <= N;++i){
      int n = i;
      int m = N - i;
      if(abs(n-m)==min){
        cout << n * (n - 1) / 2 + m * (m - 1) / 2 << endl;
        break;
      }
    }
  }
  else
  {
    cout << -1 << endl;
  }
}

