vector<vector<int> > g;
int Not(int u) {
	if (u < n)
		return u + n;
	return u - n;
}
void addEdge(int a, int b) {
	g[Not(a)].push_back(b);
	g[Not(b)].push_back(a);
}
int low[2 * N], idx[2 * N], dfs, cmp, compH[2 * N];
vector<int> S;
int comp[2 * N];
bool vis[2 * N];
void DFS(int u) {
	S.push_back(u);
	low[u] = idx[u] = ++dfs;
	vis[u] = true;
	for (auto &v : g[u]) {
		if (!idx[v])
			DFS(v);
		if (vis[v])
			low[u] = min(low[u], idx[v]);
	}
	if (low[u] == idx[u]) {
		compH[cmp] = u;
		while (true) {
			int v = S.back();
			S.pop_back();
			vis[v] = false;
			comp[v] = cmp;
			if (u == v)
				break;
		}
		++cmp;
	}
}
