		for (int j = i + 1; j < n; ++j)
			if (!e[i][j]) {
				addEdge(i, j);
				addEdge(Not(i), Not(j));
			}
	for (int i = 0; i < g.size(); ++i)
		if (!idx[i])
			DFS(i);
	for (int i = 0; i < n; ++i)
		if (comp[i] == comp[i + n]) {
			puts("-1");
			return 0;
		}
	vector<int> in(cmp);
	vector<vector<int> > G(cmp);
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			if (comp[i] != comp[g[i][j]]) {
				G[comp[i]].push_back(comp[g[i][j]]);
				++in[comp[g[i][j]]];
			}
	queue<int> q;
	for (int i = 0; i < in.size(); ++i)
		if (!in[i])
			q.push(i);
	vector<char> res(cmp, -1);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (res[u] == -1) {
			res[u] = false;
			res[comp[Not(compH[u])]] = true;
		}
		for (auto &v : G[u])
			if (!--in[v])
				q.push(v);
	}
	vector<int> v[2];
	for (int i = 0; i < n; ++i)
		v[res[comp[i]]].push_back(i);
	if (v[0].size() < v[1].size())
		v[0].swap(v[1]);
	for (int i = 0; v[0].size() > v[1].size() && i < v[0].size(); ++i) {
		int u = v[0][i];
		bool can = true;
		for (auto &V : v[1])
			if (!e[u][V]) {
				can = false;
				break;
			}
		if (can) {
			v[1].push_back(v[0][i]);
			v[0][i] = v[0].back();
			v[0].pop_back();
			--i;
		}
	}
	int R = 0;
	for (int i = 0; i < 2; ++i)
		R += v[i].size()*((int)v[i].size() - 1) / 2;
	printf("%d\n", R);
	return 0;
}

