void dfs(int v, int color, int& red, int& blue) {
    if (color == 1) red ++;
    if (color == 2) blue ++;
    x[v] = color;
    for (int i = 1; i <= n; i++) {
        if (i == v) continue;
        if (edge[v][i]) {
            if (x[i] != 0) {
                if (x[i] != 3 - color) valid = false;
            } else {
                dfs(i, 3 - color, red, blue);
            }
        }
    }
    return;
}

void solve() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            edge[i][j] = true;
        }
    }
    for (int i = 0; i < m; i++) {
        cin >> a >> b;
        edge[a][b] = false;
        edge[b][a] = false;
    }
    vector<int> cs;
    ll base = 0;
    for (int i = 1; i <= n; i++) {
        int red = 0, blue = 0;
        if (x[i] == 0) {
            dfs(i, 1, red, blue);
        }
        base += min(red, blue);
        cs.pb(max(red, blue) - min(red, blue));
    }
    if (!valid) {
        p(-1);
        return;
    }
    vec dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < cs.size(); i++) {
        int c1 = cs[i];
        for (int j = n; j >= 0; j--) {
            if (j - c1 >= 0 && dp[j - c1] != 0) {
                dp[j] = 1;
            }
        }
    }
    ll ans = INF;
    for (int i=0;i<=n;i++){
        if (dp[i] == 0) continue;
        int v1 = base + i, v2 = n - base - i;
        ll res = v1 * (v1 - 1) + v2 * (v2 - 1);
        res /= 2;
        ans = min(ans, res);
    }
    p(ans);
    return;
}

