    ll cnt2 = (n - sub) / 2LL;
    ll ans = 0LL;
    ans += ((cnt1 >= 2LL) ? combination(cnt1, 2LL) : 0LL);
    ans += ((cnt2 >= 2LL) ? combination(cnt2, 2LL) : 0LL);

    debug_printf("---- ans\n");
    cout << ans << endl;
}

