int main() {
	int n, m;
	cin >> n >> m;

	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			A[i][j] = i != j;
		}
	}

	for (int j = 0; j < m; ++j) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		A[a][b] = false;
		A[b][a] = false;
	}

	Graph g(n);
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if (A[i][j]) g.add(i, j);
		}
	}

	if (!isBipartite(g)) {
		cout << -1 << endl;
		return 0;
	}

	auto col = colorBipartiteGraph(g);

	std::vector<int> diffs;
	for (auto&& group : connectedComponents(g)) {
		int cnt = 0;
		for (int v : group) {
			cnt += col[v];
		}

		int diff = int(group.size()) - 2 * cnt;
		diffs.push_back(abs(diff));
	}

	Bits sum;
	sum[MAX] = true;
	for (int diff : diffs) {
		sum = (sum << diff) | (sum >> diff);
	}

	int mn;
	for (int i = 0; i <= n; ++i) {
		if (sum[MAX + i] || sum[MAX - i]) {
			mn = i;
			break;
		}
	}

	int a = (n + mn) / 2;
	int b = (n - mn) / 2;
	cout << a * (a - 1) / 2 + b * (b - 1) / 2 << endl;
	return 0;
}

