ll fastpow(ll a, ll pw, ll MOD) {
    ll res = 1;
    while (pw) {
        if (pw & 1) res = res * a % MOD;
        a = a * a % MOD;
        pw >>= 1;
    }
    return res;
}
void makefact(ll n, ll MOD){//MODは素数かつnより大きい
    ll ans = 1;
    fact.at(0) = ans;
    fact_inv.at(0) = ans;
    reps(i,1,n+1){
        (ans *= i)%=MOD;
        fact.at(i) = ans;
        fact_inv.at(i) = fastpow(ans,MOD-2,MOD);
    }
    return;
}
void makenCm(ll n, ll MOD){
    rep(i,n+1){
        ll ans = fact.at(n);
        (((ans*=fact_inv.at(n-i))%=MOD)*=fact_inv.at(i))%=MOD;
        nCm.at(i) = ans;
    }
    return;
}

