using namespace std;

double compute (long long x) {
    double sum = 0;
    while (x) {
        sum += x % 10;
        x /= 10;
    }
    return x / sum;
}

long long getNext (long long n) {
    long long cpn = n;
    long long power = 1;
    while (cpn % 10 == 9) {
        power *= 10;
        cpn /= 10;
    }
    long long bestFTM = n + power;
    long long local = n;
    double bestC = compute(bestFTM);
    for (int i = static_cast<int>(cpn % 10 + 1); i < 10; ++i) {
        local += power;
        if (bestC > compute(local)) {
            bestC = compute(local);
            bestFTM = local;
        }
    }
    return bestFTM;
}

