int find(int x) {
    return x == fa[x] ? x : fa[x] = find(fa[x]);
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++) {
        fa[i] = i;
        for (int j = 1; j <= n; j++) {
            G[i][j] = 1;
        }
    }
    for (int i = 1, u, v; i <= m; i++) {
        scanf("%d %d", &u, &v);
        G[u][v] ^= 1, G[v][u] ^= 1;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) if (i ^ j && G[i][j]) {
            fa[find(i)] = find(j), H[i].push_back(j);
        }
    }
    memset(col, -1, sizeof(col));
    function<void(int)> dfs = [&](int v) {
        for (int u : H[v]) if (!~col[u]) {
            col[u] = col[v] ^ 1, dfs(u);
        }
    };
    for (int i = 1; i <= n; i++) {
        if (i == find(i)) col[i] = 0, dfs(i);
    }
    for (int i = 1; i <= n; i++) {
