const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N, M;
  cin >> N >> M;

  VVI G(N, VI(N, 1));
  REP(i,M){
	int u, v;
	cin >> u >> v;
	--u;
	--v;
	G[u][v] = G[v][u] = 0;
  }
  REP(i,N) G[i][i] = 0;

  int ans = 0;
  VI col(N);
  vector<PII> comp;
  REP(i,N){
	if(col[i]) continue;
	queue<int> q;
	PII cnt(1,0);
	VI as, bs;
	col[i] = 1;
	as.PB(i);

	REP(j,N){
	  if(G[i][j]){
		col[j] = -1;
		cnt.SS++;
		bs.PB(j);
		q.push(j);
	  }
	}
	if(q.empty()){
	  comp.EB(1, 0);
	  continue;
	}

	bool ok = true;
	while(!q.empty()){
	  int u = q.front();
	  q.pop();
	  REP(to,N){
		if(G[u][to]){
		  if(col[to]){
			if(col[u] == col[to]){
			  ok = false;
			  break;
			}
		  }
		  else{
			col[to] = col[u] * -1;
			++(col[to] > 0 ? cnt.FF : cnt.SS);
			(col[to] > 0 ? as : bs).PB(to);
			q.push(to);
		  }
		}
	  }
	}

	if(!ok){
	  cout << -1 << endl;
	  return 0;
	}
	comp.PB(cnt);
	for(int a: as){
	  for(int b: bs){
		if(!G[a][b])
		  ++ans;
	  }
	}
  }

  VVI dp(2, VI(710, -1e9));
  int S = 0, crt = 0, nxt = 1;
  dp[crt][0] = 0;
  for(auto& p: comp){
	for(int k=0;k<=S;++k){
	  maxi(dp[nxt][k + p.FF], dp[crt][k] + k * p.SS + (S-k) * p.FF);
	  maxi(dp[nxt][k + p.SS], dp[crt][k] + k * p.FF + (S-k) * p.SS);
	}
	S += p.FF + p.SS;
	swap(crt, nxt);
  }

  int mx = 0;
  REP(i,S+1) maxi(mx, dp[crt][i]);

  cout << M - ans - mx << endl;

  return 0;
}

