const long long int MOD = 1000000007;
const long double EPS = 1e-8;

long long int N, M, K, H, W, L, R;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	vector<vector<int>>edge(N, vector<int>(N));
	vector<int>z_connected;
	vector<int>z_noconnected;
	for (int i = 0; i < M; i++) {
		cin >> L >> R;
		L--;
		R--;
		edge[L][R] = 1;
		edge[R][L] = 1;
	}
	z_connected.push_back(0);
	for (int i = 1; i < N; i++) {
		if (edge[0][i]) {
			z_connected.push_back(i);
		}
		else {
			z_noconnected.push_back(i);
		}
	}
	vector<int>dis_node(N);
	vector<vector<int>>dis_edge(N);
	for (int i = 0; i < z_connected.size(); i++) {
		for (int j = i + 1; j < z_connected.size(); j++) {
			if (!edge[z_connected[i]][z_connected[j]]) {
				dis_node[z_connected[i]] = 1;
				dis_node[z_connected[j]] = 1;
				dis_edge[z_connected[i]].push_back(z_connected[j]);
				dis_edge[z_connected[j]].push_back(z_connected[i]);
			}
		}
	}
	queue<int>Q;
	int st = 0;
	for (int i = 0; i < N; i++) {
		if (dis_node[i]) {
			st = i;
			break;
		}
	}
	vector<int>dis(N, MOD);
	dis[st] = 0;
	Q.push(st);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : dis_edge[cn]) {
			if (dis[i] > dis[cn] + 1) {
				dis[i] = dis[cn] + 1;
				Q.push(i);
			}
		}
	}
	bool imp = false;
	for (int i = 0; i < N; i++) {
		for (auto j : dis_edge[i]) {
			if (dis[i] % 2 == dis[j] % 2) {
				imp = true;
			}
		}
	}
	if (imp) {
		cout << -1 << endl;
		return 0;
	}
	long long int ans = MOD;
	for (int i = 0; i < 2; i++) {
		auto box = z_noconnected;
		for (int j = 0; j < N; j++) {
			if (dis_node[j] && dis[j] % 2 == i) {
				box.push_back(j);
			}
		}
		bool can = true;
		for (int j = 0; j < box.size(); j++) {
		//	cout << box[j] << endl;
			for (int k = j+1; k < box.size(); k++) {
				if (!edge[box[j]][box[k]]) {
					can = false;
				}
			}
		}
		if (can) {
			ans = min(ans, (long long int)box.size()*(long long int)(box.size() - 1) / 2 + (long long int)(N - box.size())*(long long int)(N - box.size() - 1) / 2);
			if (N - (long long int)box.size() > (long long int)box.size()) {
				K = N - N / 2;
				ans = min(ans, N / 2 * (N / 2 - 1) / 2 + K * (K - 1) / 2);
			}
		}
	}

	if (ans == MOD) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}
	return 0;
}

