typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 29;
const int MOD = 1e9 + 7;

const int N = 700;
bool g[N][N];
int visit[N];
bool dp[N];

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      g[i][j] = true;
    }
    g[i][i] = false;
  }
  while (m--) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x; --y;
    g[x][y] = g[y][x] = false;
  }
  fill(visit, visit + n, -1);
  vector<int> Q;
  vector<ii> a;
  for (int i = 0; i < n; ++i) {
    if (visit[i] >= 0) continue;
    Q.clear();
    Q.push_back(i);
    visit[i] = 0;
    for (int k = 0; k < Q.size(); ++k) {
      int u = Q[k];
      for (int v = 0; v < n; ++v) {
        if (g[u][v]) {
          if (visit[v] < 0) {
            visit[v] = 1 - visit[u];
            Q.push_back(v);
          } else if (visit[v] + visit[u] != 1) {
            // trace(u, v, visit[u], visit[v]);
            puts("-1");
            return 0;
          }
        }
      }
    }
    int sum = 0;
    for (int k = 0; k < Q.size(); ++k) {
      sum += visit[Q[k]] == 0;
    }
    // trace(sum, Q.size());
    a.push_back({sum, Q.size() - sum});
  }
  dp[0] = true;
  for (auto& it : a) {
    int x = it.first, y = it.second;
    for (int i = n; i >= 0; --i) {
      if (i >= x && dp[i - x]) dp[i] = true;
      if (i >= y && dp[i - y]) dp[i] = true;
    }
  }
  int ret = INF;
  for (int i = 1; i < n; ++i) {
    if (dp[i]) {
      int j = n - i;
      ret = min(ret, i * (i - 1) / 2 + j * (j - 1) / 2);
    }
  }
  if (ret == INF) ret = -1;
  printf("%d\n", ret);
  return 0;
}

