int BipartiteGraph(LL point, vector<int>&color) {
	int cnt = 0;
	function<bool(int, int, int)> dfs = [&](int u, int prev, int c) {
		color[u] = c;
		if (c == 1) cnt++;
		rep(v, n)if (v != prev && v != u && f[u][v] == 0) {
			if (color[v] == -1) {
				if (!dfs(v, u, 1 - c)) return false;
			}
			else if (color[v] != 1 - c) {
				return false;
			}
		}
		return true;
	};
	if (!dfs(point, -1, 0)) return -1;
	return cnt;
}
