		za--, zb--;
		d[za][zb] = d[zb][za] = 0;
	}
	uf.init();
	for (int i = 0; i < num; i++)for (int j = 0; j < num; j++)if (d[i][j])uf.unite(i * 2, j * 2 + 1), uf.unite(i * 2 + 1, j * 2);
	for (int i = 0; i < num; i++)
	{
		if (uf.find(i * 2) == uf.find(i * 2 + 1))
		{
			printf("-1\n");
			return 0;
		}
		cnt1[uf.find(i * 2)]++, cnt2[uf.find(i * 2 + 1)]++;
	}
	vector<pii>v;
	for (int i = 0; i < num * 2; i++)
	{
		int s = cnt1[uf.find(i)], t = cnt2[uf.find(i)];
		if (!flag[uf.find(i)])
		{
			v.push_back(make_pair(s, t));
			flag[uf.find(i)] = flag[uf.find(i % 2 ? i - 1 : i + 1)] = true;
		}
	}
	dp[0][0] = 1;
	for (int i = 0; i < v.size(); i++)for (int j = 0; j <= num; j++)if (dp[i][j])dp[i + 1][j + v[i].first] = dp[i + 1][j + v[i].second] = 1;
