int const MOD = 1e9 + 7;
int st, ed;

struct Edge {
    int v, w;
    Edge(const int &v, const int &w) : v(v), w(w) { }
};

vector<Edge> e[maxn];

void dijkstra(int s, ll d[], bool v[], ll ans[]) {
    priority_queue<pair<ll, int> > q;
    d[s] = 0;
    ans[s] = 1;
    q.emplace(0, s);
    while (!q.empty()) {
        int u = q.top().second;
        q.pop();
        if (v[u]) continue;
        v[u] = 1;
        for (auto & x : e[u]) {
            int w = x.w;
            int v = x.v;
            if (d[v] > d[u] + w) {
                d[v] = d[u] + w;
                ans[v] = ans[u];
                q.emplace(make_pair(-d[v], v));
            } else if (d[v] == d[u] + w) {
                ans[v] = (ans[v] + ans[u]) % MOD;
            }
        }
    }

}

