constexpr int N = 700;
std::array<std::bitset<N>, N> E;
std::array<int, N> D;
std::bitset<N+1> P, PP;

int main(void){
    int n, m; scanf("%d%d", &n, &m);
    REP(i, n){ E[i].flip(); E[i][i] = false;}
    REP(_, m){
        int a, b; scanf("%d%d", &a, &b); a--; b--;
        E[a][b] = false; E[b][a] = false;
    }
    std::queue<int> Q;
    std::vector<std::pair<int, int>> S;
    REP(i, n) if(D[i] == 0){
        std::array<int, 2> A{0, 0};
        Q.push(i);  D[i] = 1; A[0]++;
        while(not Q.empty()){
            int v = Q.front(); Q.pop();
            int nm = (D[v] & 1) + 1;
            REP(u, n) if(E[u][v]){
                if(D[u] == 0){ D[u] = nm; Q.push(u); A[nm-1]++;}
                else if(D[u] != nm){ puts("-1"); return 0; }
            }
        }
        S.emplace_back(A[0], A[1]);
    }
    P[0] = true;
    for(auto& itr : S) PP = (P << itr.first) | (P << itr.second), std::swap(P, PP);
    int ans = 2e9;
    REP(i, n) if(P[i]){
        int p = i * (i - 1) + (n - i) * (n - i - 1); p /= 2;
        if(ans > p) ans = p;
    }
    printf("%d\n", ans);
