        tmp1--;
        tmp2--;
        connect[tmp1][tmp2] = connect[tmp2][tmp1] = true;
    }

    vector<vector<int> > newedge(N);
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
