    for (int i = 0; i < N; i++)
    {
        if (N_renketsu[i] >= 0) continue;

        queue<pair<int, int>> q_tmp;
        q_tmp.push(make_pair(i, 0));

        while (!q_tmp.empty())
        {
            int q = q_tmp.front().first;
            int color_tmp = q_tmp.front().second;
            q_tmp.pop();
            N_renketsu[q] = num_ren;
            if (color[q] >= 0 && color[q] != color_tmp)
            {
                // cout << q << endl;
                cout << -1 << endl;
                return 0;
            }
            color[q] = color_tmp;
            for (auto nxt : newedge[q])
            {
                if ((N_renketsu[nxt] != -1 && N_renketsu[nxt] != num_ren) || (color[nxt] != -1 && color[nxt] != 1-color_tmp))
                {
                    // cout << q << " " << nxt << " " << N_renketsu[nxt] << " " << num_ren << " " << color_tmp << " " << color[nxt] << endl;
                    cout << -1 << endl;
