                }
                if (N_renketsu[nxt] == -1)
                {
                    q_tmp.push(make_pair(nxt, 1 - color_tmp));
                }
            }
        }
        num_ren++;
    }

    vector<pair<int, int> > shukei(num_ren);
    for (int i = 0; i < N; i++)
    {
        if (color[i] == 0) shukei[N_renketsu[i]].first++;
        if (color[i] == 1) shukei[N_renketsu[i]].second++;
    }

    vector<int> napz;
    int sameparam = 0;
    int napz_sum = 0;
