    {
        if (st[i]) min_dist = min(min_dist, abs(napz_sum - 2 * i));
    }

    cout << comb(sameparam + (napz_sum - min_dist)/2) + comb(sameparam + (napz_sum+min_dist)/2) << endl;
    return 0;
}

