int co[2];

int go(int node,int c)
{
	if(col[node]!=-1) return col[node]==c;
	col[node]=c;
	co[c]++;
	int ans=1;
	for(int i=1;i<=n;i++)
	{
		if(adj[node][i]||node==i) continue;
		ans&=go(i,c^1);
	}
	return ans;
}

int can(int x,int y)
{
	if(y<0) return 0;
	if(x==got.size()) return (y==0?1:0);
	if(mem[x][y]!=-1) return mem[x][y];
	return mem[x][y]=can(x+1,y-got[x].first)|can(x+1,y-got[x].second);
}

int main()
{
