  UnionFind uf2(N);
  for(int i = 0; i < N; i++) {
    for(int j = i + 1; j < N; j++) {
      if(!g[i][j]) {
        bp.unite(i, j + N);
        bp.unite(j, i + N);
        uf2.unite(i, j);
      }
    }
  }

  if(!bp.bipartite_graph_coloring()) {
    cout << -1 << endl;
  } else {
    throw 0;
    vector< pair< int, int > > mex;

    int ask = 0;
    int black = 0, white = 0;
