  }

  for(int i = 0; i < n; i++){
    for(int j = 0; j < n; j++){
      if(i != j && _G[i][j]){
        G[i].push_back(j);
      }
    }
  }

  vector<int> color(n, -1), cnt(2, 0);
  function< void(int,int,int) > dfs =
  [&](int u, int pre, int t){
    if(color[u] != -1){
      if(color[u] != t){
        cout << -1 << endl;
        exit(0);
      }
      return;
    }
    color[u] = t;
    cnt[t]++;
    for(int v : G[u]){
