    }
    return;
  };

  vector<int> dp(n+1, 0);
  dp[0] = 1;
  for(int i = 0; i < n; i++){
    if(color[i] == -1){
      cnt[0] = cnt[1] = 0;
      dfs(i, -1, 0);
      for(int j = n; j >= 0; j--){
        if(dp[j]){
          dp[j + cnt[0]] = 1;
          dp[j + cnt[1]] = 1;
        }
      }
    }
  }

  int ans = INF;
  for(int i = 0; i <= n; i++){
    if(dp[i]){
      int j = n - i;
      ans = min(ans, i * (i-1) / 2 + j * (j-1) / 2);
    }
  }
  cout << ans << endl;

  return 0;
}

