class DisJointSet{
public:
    vector<int> v;//親の添字を入れる
    DisJointSet(int n){//初期化
        v = vector<int>(n);
        rep(i, n)v[i] = i;
    }
    int find(int x){//親を返す
        if(v[x] == x)return x;
        else return v[x] = find(v[x]);
    }
    void unite(int x, int y){//xとyをくっつける
        x = find(x);
        y = find(y);
        if(x == y)return;
        v[x] = y;
    }
    bool same(int x, int y){//xとyが同じ集合かどうか
        return find(x) == find(y);
    }
};

vector<vector<int> > V;

vector<int> countSize(int now, map<int, int> &visited, int c){
    if(visited.count(now)){
        if(visited[now] != c){
            vector<int> tmp(2);
            tmp[0] = -1;
            return tmp;
        }
        else return vector<int>(2);
    }
    visited[now] = c;
    c = (c+1)%2;

    vector<int> ret(2);
    ret[0] = ret[1] = 0;
    ret[c] = 1;
    rep(i, V.size()){
        if(V[now][i] == 0)continue;
        vector<int> tmp = countSize(i, visited, c);
        if(min(tmp[0], tmp[1]) == -1)return tmp;
        ret[0] += tmp[0];
        ret[1] += tmp[1];
    }
    return ret;
}



