int main(){
	int N, M;
	while(cin >> N >> M){
		vector<vector<int>> adj(N, vector<int>(N, 0));
		for(int i=0;i<M;i++){
			int a, b; cin >> a >> b;
			--a; --b;
			adj[a][b] = adj[b][a] = 1;
		}
		vector<vector<int>> g(N);
		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				if(!adj[i][j]){
					g[i].push_back(j);
					g[j].push_back(i);
				}
			}
		}
		vector<int> dp(N+1, 0);
		dp[0] = 1;
		vector<int> group(N, -1);
		bool ok = true;
		for(int i=0;i<N;i++){
			if(group[i] != -1) continue;
			vector<int> cnt(2, 0);
			group[i] = 0;
			cnt[0]++;
			queue<int> qu; qu.push(i);
			while(!qu.empty()){
				int p = qu.front(); qu.pop();
				for(int t : g[p]){
					if(group[p] == group[t]) ok = false;
					if(group[t] != -1) continue;
					group[t] = 1 - group[p];
					cnt[group[t]]++;
					qu.push(t);
				}
			}
			if(!ok) break;
			for(int j=N;j>=0;j--){
				if(dp[j]){
					for(int k=0;k<2;k++) dp[j+cnt[k]] = 1;
				}
			}
		}
		if(!ok){
			cout << -1 << endl;
			continue;
		}
		int res = M;
		for(int i=1;i<N;i++){
			if(dp[i]){
				res = min(res, i*(i-1)/2 + (N-i)*(N-i-1)/2);
			}
		}
		cout << res << endl;
	}
}

