pair<int, int> bfs(int s){
	//cerr << "bfs(" << s << ")" << endl;
	int count = 0, half = 0;
	queue<int> q; q.push(s);q.push(1);
	while(!q.empty()){
		int now = q.front(); q.pop();
		int mark = q.front(); q.pop();
		//cerr << now << ":" << mark << endl; 
		flg[now] = mark;
		count++; if (mark==1) half++;
		for(int i=0;i<nolist[now].size();i++){
			int next = nolist[now][i];
			if (flg[next]==0){
				q.push(next); q.push(3 - mark);
				flg[next] = 3 - mark;
			}else{
				if (flg[next] != 3 - mark) return make_pair(-1, -1);
			}
		}
	}
	return make_pair(half, count - half);
}


