void dfs(int u, int co) {
  if (vs[u]) {
    if (col[u] != co) {
      cout << -1;
      exit(0);
    }
    return;
  }
  vs[u] = 1;
  cnt[co]++;
  col[u] = co;
  for (auto v : adj[u]) {
    dfs(v, co ^ 1);
  }
}

int main() {
  cin >> n >> m;

  for (int i = 0; i < m; i++) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    D[x][y] = 1;
    D[y][x] = 1;
  }

  rep(i, 0, n) {
    rep(j, 0, n) {
      if (i == j) continue;
      if (D[i][j] == 0) adj[i].pb(j);
    }
  }

  rep(i, 0, n) {
    if (!vs[i]) {
      G++;
      cnt[0] = cnt[1] = 0;
      dfs(i, 0);
      has.pb(mp(cnt[0], cnt[1]));
    }
  }

  int cur1 = 0, cur2 = 0;
  rep(i, 0, G) {
    if (cur1 > cur2) swap(cur1, cur2);
    int lo = min(has[i].fi, has[i].se);
    int hi = max(has[i].fi, has[i].se);
    if ((cur1 + hi) * (cur1 + hi - 1) / 2 + (cur2 + lo) * (cur2 + lo - 1) / 2 < (cur1 + lo) * (cur1 + lo - 1) / 2 + (cur2 + hi) * (cur2 + hi - 1) / 2) {
      cur1 += hi;
      cur2 += lo;
    } else {
      cur1 += hi;
      cur2 += lo;
    }
  }

  int ans = ((cur1 * (cur1 - 1)) / 2) + ((cur2 * (cur2 - 1)) / 2);
  cout << ans;

  return 0;
}

