bool bip(ll now, map<ll, bool> &m, bool which, pair<ll, ll> &count){
    (which ? count.first : count.second)++;
    m[now] = which;
    for(ll next : v[now]){
        if(m.find(next) == m.end()){
            if(!bip(next, m, !which, count)){
                return false;
            }
        }else if(m[next] == which){
            return false;
        }
    }
    return true;
}
