#include <bits/stdc++.h>

using namespace std;

using int64 = long long;
const int INF = 1 << 30;

struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

struct Bipartite_Graph : UnionFind {
  vector< int > color;

  Bipartite_Graph(int v) : color(v + v, -1), UnionFind(v + v) {}

  bool bipartite_graph_coloring() {
    for(int i = 0; i < color.size() / 2; i++) {
      int a = find(i);
      int b = find(i + (int) color.size() / 2);
      if(a == b) return (false);
      if(color[a] < 0) color[a] = 0, color[b] = 1;
    }
    return (true);
  }

  bool operator[](int k) {
    return (bool(color[find(k)]));
  }
};

int main() {
  int N, M;
  bool g[700][700] = {{}};
  cin >> N >> M;
  for(int i = 0; i < M; i++) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    g[x][y] = true;
    g[y][x] = true;
  }
  Bipartite_Graph uf(N);
  for(int i = 0; i < N; i++) {
    for(int j = 0; j < i; j++) {
      if(g[i][j]) continue;
      uf.unite(i + N, j);
      uf.unite(j + N, i);
    }
  }
  if(uf.bipartite_graph_coloring()) {
    int sz[701][2] = {{}};
    for(int i = 0; i < N; i++) {
      sz[min(uf.find(i + N), uf.find(i))][uf[i]]++;
    }
    bitset< 701 > bit;
    bit[0] = true;
    for(int i = 0; i < 2 * N; i++) {
      bit = (bit << sz[i][0]) | (bit << sz[i][1]);
    }
    int ret = INF;
    for(int i = 0; i <= N; i++) {
      int rest = N - i;
      if(bit[i]) ret = min(ret, i * (i - 1) / 2 + rest * (rest - 1) / 2);
    }
    cout << ret << endl;
  } else {
    cout << -1 << endl;
  }
}

