void dfs(int v,set<int> &s,Graph &g){
    if(s.count(v)) return;
    s.insert(v);
    for(int i=0;i<g[v].size();i++){
        int to=g[v][i];
        dfs(to,s,g);
    }
    return;
}

int main(){
    int n,m;
    cin>>n>>m;
    Graph g(2*n);
    vector<vector<int>> adj(n,vector<int>(n,0));
    for(int i=0;i<m;i++){
        int a,b;
        cin>>a>>b;
        a--,b--;
        adj[a][b]=true;
        adj[b][a]=true;
    }

    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            if(i!=j && !adj[i][j]){
                g[i].push_back(j+n);
                g[i+n].push_back(j);
            }
        }
    }


    vector<int> av;
    vector<int> bv;
    vector<int> used(n,false);
    for(int i=0;i<n;i++){
        if(!used[i]){
            set<int> vs;
            dfs(i,vs,g);
            int a=0;
            int b=0;
            for(auto &e:vs){
                if(vs.count(e+n)){
                    cout<<-1<<endl;
                    return 0;
                }
                if(e<n){
                    used[e]=true;
                    a++;
                }
                else{
                    used[e-n]=true;
                    b++;
                }
            }
            av.push_back(a);
            bv.push_back(b);
        }
    }
    vector<vector<int>> dp(av.size()+1,vector<int>(n+1,0));
    dp[0][0]=true;

    for(int i=0;i<av.size();i++){
        for(int j=0;j<=n;j++){
            dp[i+1][j]|=dp[i][j];
            if(j+av[i]<=n) dp[i+1][j+av[i]]|=dp[i][j];
            if(j+bv[i]<=n) dp[i+1][j+bv[i]]|=dp[i][j];
        }
    }

    int res=1e8;
    for(int i=0;i<=n;i++){
        if(dp[av.size()][i]){
            res=min(res,i*(i-1)/2+(n-i)*(n-i-1)/2);
        }
    }
    cout<<res<<endl;
    return 0;
}

