public:
    Node **adj;

    Graph() {
        adj = nullptr;
    }

    Graph(const int N) {
        adj = new Node*[N + 1];
        for (int i = 0 ; i <= N ; ++i) adj[i] = nullptr;
        this->N = N;
    }

    void add_edge(int u, int v) {
        Node *new_node = new Node;
        new_node->nxt = adj[u];
        new_node->idx = v;
        adj[u] = new_node;
    }

    bool get_next(Node *curr) {
        if (curr->nxt != nullptr) {
            curr = curr->nxt;
            return true;
        }
        return false;
    }

    ~Graph() {
        for (int i = 0 ; i <= N ; ++i) {
            while (adj[i] != nullptr) {
                Node *curr = adj[i];
                adj[i] = adj[i]->nxt;
                delete curr;
            }
        }
    }
};

