int c2(int x) { return x * (x - 1) / 2; }

int main() {
    scanf("%d %d", &n, &m);
    set<pii> S;
    for(int i = 1; i <= n; ++i) 
        for(int j = i+1; j <= n; ++j) 
            S.emplace(i, j);
    for(int i = 0, u, v; i < m; ++i) {
        scanf("%d %d", &u, &v); 
        if(u > v) swap(u, v);
        S.erase(pii(u, v));
    }
    vector<vector<int>> g(N);
    for(auto x : S) g[x.x].emplace_back(x.y), g[x.y].emplace_back(x.x);
    vector<int> col(N);
    bitset<N> chk; chk[0] = true;
    auto f = [&](int v) {
        for(int i = n - v; ~i; --i) if(chk[i]) chk[i+v] = true;
    };
    for(int i = 1; i <= n; ++i) if(!col[i]) {
        queue<int> Q; Q.emplace(i); col[i] = 1;
        int cnt1 = 0, cnt2 = 0;
        while(!Q.empty()) {
            int u = Q.front(); Q.pop();
            if(col[u] == 1) cnt1++;
            if(col[u] == 2) cnt2++;
            for(int v : g[u]) {
                if(!col[v]) col[v] = col[u] ^ 3, Q.emplace(v);
                if(col[v] == col[u]) return !printf("-1\n");
            }
        }
        f(cnt1), f(cnt2);
    }
    int mn = 1e9;
    for(int i = 0; i <= n; ++i) if(chk[i]) mn = min(mn, c2(i) + c2(n-i));
    printf("%d\n", mn);
}

