	for(int i=1; i<=n; i++){
		C[i] = -1;
		for(int j=i+1; j<=n; j++){
			M[i][j] = M[j][i] = 1;
		}
	}
	int a, b;
	for(int i=0; i<m; i++){
		ri2(a,b);
		M[a][b] = M[b][a] = 0;
	}
	for(int i=1; i<=n; i++){
		for(int j=i+1; j<=n; j++){
			if(M[i][j]){
				G[i].emplace_back(j);
				G[j].emplace_back(i);
			}
		}
	}
	int ans;
	if(!bipartite()) ans = -1;
	else{
		memo[0][0] = true;
		for(int i=1; i<=comps.size(); i++){
			for(int val=0; val <= n; val++){
				if(val >= comps[i-1].first){
					if(memo[i-1][val - comps[i-1].first]) memo[i][val] = true;
				}
				if(val >= comps[i-1].second){
					if(memo[i-1][val - comps[i-1].second]) memo[i][val] = true;
				}
			}
		}
		ans = INT_MAX;
		for(int i=0; i<=n; i++){
			if(memo[comps.size()][i]){
				ans = min(ans,getValue(i,n-i));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

