int return_col;
int findroot(int x)
{
    int root;
    int col=0;
    for (root=x;fa[root]!=-1;)
    {
        col=col^c[root];
        root=fa[root];
    }
    return_col=col;
    int tempx,tempc;
    for (;fa[x]!=-1;)
    {
        tempx=fa[x];
        tempc=c[x]^col;
        fa[x]=root;
        c[x]=col;
        x=tempx;
        col=tempc;
    }
    return root;
}
int size[705][2];
void u(int x,int y)
{
    int now=1;
    x=findroot(x);
    now^=return_col;
    y=findroot(y);
    now^=return_col;
    if (x==y)
    {
        if (now!=0)
        {
            puts("-1");
            exit(0);
        }
        return;
    }
    fa[x]=y;
    c[x]=now;
    size[y][0]+=size[x][now];
    size[y][1]+=size[x][now^1];
}
