const int N=705;

int p[N],n,m,u[N*N],v[N*N],ans,fa,fb,ga,gb,tmp,f[N];
bool G[N][N],zt[N],zz[N];

int getf(int x){
	if(x==p[x]) return x;
	int fa=getf(p[x]);
	zt[x]^=zt[p[x]],p[x]=fa;
	return fa;
}

int getp(int x){
	if(x==f[x]) return x;
	int fa=getp(f[x]);
	zz[x]^=zz[f[x]],f[x]=fa;
	return fa;
}

inline bool solve(){
	for(int i=1;i<=n;i++)
	    for(int j=i+1;j<=n;j++) if(!G[i][j]){
	    	fa=getf(i),fb=getf(j);
	    	ga=zt[i],gb=zt[j];

	    	if(fa==fb&&ga==gb) return 0;
	    	if(fa!=fb) p[fa]=fb,zt[fa]^=(zt[i]^1^zt[j]);
		}

	memcpy(zz,zt,sizeof(zt));
	memcpy(f,p,sizeof(p));

	for(int i=1;i<=m;i++){
	    fa=getf(u[i]),fb=getf(v[i]);
	    ga=zt[u[i]],gb=zt[v[i]];

	    if(getp(u[i])==getp(v[i])&&zz[u[i]]==zz[v[i]]) continue;

		if(fa!=fb) p[fa]=fb,zt[fa]^=(zt[u[i]]^1^zt[v[i]]),ans++;
		else if(ga!=gb) ans++;
		else tmp++;
	}

	return 1;
}

