/*
動的に二部グラフを構築するやつ。
col[i] := -2:二部グラフではない, 0:塗られていない, 1or-1:色
*/


bool binary_color(int u, int c) {
	if (c != -2 && col[u] == -2) {
		binary_color(u, -2);
		return false;
	}
	col[u] = c;

	REP(i, g[u].size()) {
		int v = g[u][i];

		if (c == 0 || c == -2) {
			if (col[v] != c) binary_color(v, c);
		}
		else {
			if (col[v] == -c) continue;

			if (col[v] == c) return false;
			if (!binary_color(v, -c)) return false;
		}
	}
	return true;
}

void add_edge(int x, int y) {
	if (uf.same(x, y)) {
		if (col[x] != 0 && col[y] != 0 && col[x] == col[y]) col[x] = -2;
	}
	else {
		if (col[x] == 0 || col[x] == -2 || col[y] == 0 || col[y] == -2) {
			if (col[y] == 0 || col[y] == -2) swap(x, y);
		}
		else if (col[x] == col[y]) {
			if (uf.size(x) > uf.size(y)) swap(x, y);
			binary_color(x, 0);
		}
	}

	g[x].push_back(y);
	g[y].push_back(x);
	uf.unite(x, y);

	if (col[y] == 0) binary_color(y, 1);
	else binary_color(y, col[y]);
}

