	int NOW = 0;
	vector<bool> Flag(N, false);
	vector<int> C(N, -1);
	queue<int> Q;
	for (int i = 0; i < N; i++) {
		if (!Flag[i]) {
			Q.push(i);
			C[i] = 0;
			int COUNT[2] = {};
			while (!Q.empty()) {
				int P = Q.front();
				Q.pop();
				Flag[P] = true;
				COUNT[C[P]]++;
				for (int NP = 0; NP < N; NP++) {
					if (NP == P) continue;
					if (V[P][NP]) {
						if (C[NP] == -1) {
							C[NP] = 1 - C[P];
							Q.push(NP);
						}
						else {
							if (C[NP] != 1 - C[P]) {
								cout << -1 << endl;
								return 0;
							}
						}
					}
				}
			}
			VP.push_back({ COUNT[0], COUNT[1] });
			NOW++;
		}
	}
	vector<bool> DP(N + 1, false);
	DP[0] = true;
	for (int i = 0; i < NOW; i++) {
		vector<bool> CurDP(N + 1, false);
		for (int j = 0; j <= N; j++) {
			if (DP[j]) {
				if (j + VP[i].first <= N) CurDP[j + VP[i].first] = true;
				if (j + VP[i].second <= N) CurDP[j + VP[i].second] = true;
			}
		}
		for (int j = 0; j <= N; j++) {
			DP[j] = CurDP[j];
		}
	}
	int ANS = M;
	for (int i = 0; i <= N; i++) {
		if (DP[i]) {
			ANS = min(ANS, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
		}
	}
	cout << ANS << endl;
}

