set<PII> s;

int calc(int pos, int K) {
	int &y = dp[pos][K];
	if(y!=-1) return y;
	if(SZ(component) == pos) {
		return y = (K == 0);
	}
	y = 0;
	if(component[pos][0] <= K) y|= calc(pos+1, K-component[pos][0]);
	if(component[pos][1] <= K) y|= calc(pos+1, K-component[pos][1]);
	return y;
}

