#include <bits/stdc++.h>
using namespace std;

const int kN = 700 + 5;
int adj[kN][kN], cl[kN], uf[kN], ck[kN][2];
bitset<kN> dp;

bool Dfs(int x, int c, int n) {
    cl[x] = c;
    for (int i = 0; i < n; ++i) {
        if (x == i || adj[x][i]) continue;
        if (cl[i] == -1) {
            if (!Dfs(i, c ^ 1, n)) return false;
        } else {
            if (cl[i] == cl[x]) return false;
        }
    }
    return true;
}

int Find(int x) {
    if (x == uf[x]) return x;
    return uf[x] = Find(uf[x]);
}

void Merge(int x, int y) {
    uf[Find(x)] = Find(y);
}

int main() {
    int n, m; scanf("%d%d", &n, &m);
    for (int i = 0; i < m; ++i) {
        int u, v; scanf("%d%d", &u, &v);
        --u, --v;
        adj[u][v] = adj[v][u] = 1;
    }
    memset(cl, -1, sizeof(cl));
    for (int i = 0; i < n; ++i) {
        if (cl[i] == -1) {
            if (!Dfs(i, 0, n)) {
                puts("-1");
                return 0;
            }
        }
    }
    for (int i = 0; i < n; ++i) uf[i] = i;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (!adj[i][j]) Merge(i, j);
        }
    }
    for (int i = 0; i < n; ++i) ++ck[Find(i)][cl[i]];
    dp[0] = true;
    for (int i = 0; i < n; ++i) {
        if (Find(i) == i)
            dp |= ((dp << ck[i][0]) | (dp << ck[i][1]));
    }
    int ans = n * n;
    for (int i = 0; i <= n; ++i) {
        if (dp[i])
            ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
    printf("%d\n", ans);
    return 0;
}

