void dfs(int v, int c) {
    color[v] = c;
    colornum[c] ++;
    rep(i, n) {
        if(i == v || !G[v][i]) continue;
        if(color[i] = -1) dfs(i, 1 - c);
        else if(color[i] == c) isbipartite = false;
    }
}


void solve() {
    cin >> n >> m;
    rep(i, n) {
        rep(j, n) {
            G[i][j] = 1;
        }
    }
    rep(i, m) {
        int a, b; cin >> a >> b;
        a --; b --;
        G[a][b] = G[b][a] = 0;
    }
    vector<P> nums;
    rep(i, n) color[i] = -1;
    rep(v, n) {
        if(color[v] != -1) continue;
        colornum[0] = colornum[1] = 0;
        dfs(v, 0);
        nums.pb(P(colornum[0], colornum[1]));
    }

    if(!isbipartite) {
        cout << -1 << endl;
        return;
    }

    bool dp[2000];
    rep(i, n) dp[i] = 0;
    dp[0] = 1;
    for(auto p : nums) {
        for(int j = n; j >= 0; j--) {
            if(!dp[j]) continue;
            dp[j] = 0;
            dp[j + p.fr] = 1;
            dp[j + p.sc] = 1;
        }
    }
    int a = -1;
    int mid = n;
    rep(i, n + 1) {
        if(!dp[i]) continue;
        if(mid > abs(i - n / 2)) mid = abs(i - n / 2), a = i;
    }
    int b = n - a;
    cout << a * (a - 1) / 2 + b * (b - 1) / 2 << endl;
}

