#include <bits/stdc++.h>
using namespace std;
using ll  = long long;
using pll = pair<ll, ll>;
using vl  = vector<ll>;
using vvl = vector<vl>;
using vb  = vector<bool>;

#define rng(i,a,b) for(int i = (a); i < (b); ++i)
#define rep(i,n) for(int i = 0; i < (n); ++i)
#define DEBUG(x) cerr<<__LINE__<<": "<<#x<<" = "<<x<<"\n"

int N, M, ans;
vb used;
vl color;
vvl edges;
bool ok;

void init() {
    ans = 1e9;
    ok = true;
    cin >> N >> M;
    edges.assign(N, vl(N, 1));
    used.assign(N, false);
    color.assign(N, -1);
    rep(i,N) edges[i][i] = 0;
    rep(i,M) {
        int a, b; cin >> a >> b;
        a--; b--;
        edges[a][b] = edges[b][a] = 0;
    }
}

void coloring(int node, int c, vl &st) {
    if (used[node]) {
        if (color[node] != c) ok = false;
        return;
    }
    DEBUG(node);
    used[node] = true;
    color[node] = c;
    st[c]++;
    for (int to = 0; to < N; ++to) {
        if (edges[node][to] == 0) continue;
        coloring(to, 1-c, st);
    }
}

void solve() {
    set<pll> dp;
    dp.insert(pll(0,0));
    rep(i,N) {
        if (used[i]) continue;
        vl st(2,0);
        coloring(i, 0, st);
        set<pll> ndp;
        for (auto it : dp) {
            int s = it.first, t = it.second;
            ndp.insert(pll(s+st[0], t+st[1]));
            ndp.insert(pll(s+st[1], t+st[0]));
        }
        dp = ndp;
    }
    for (auto it : dp) {
        int s = it.first, t = it.second;
        ans = min(ans, s*(s-1)/2 + t*(t-1)/2);
    }
}

void output() {
    if (ok) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
}

int main() {
    init();
    solve();
    output();
    return 0;
}

