i32 cl[701];

pair<i64, i64> dfs_cl(i64 u, i32 c) {
  cl[u] = c;
  i64 r = c == 1 ? 1 : 0, b = 1 - r;
  for (i64 v = 1; v <= n; ++v) {
    if (u != v && g[u][v] == 0) {
      if (cl[v] == 0) {
        auto p = dfs_cl(v, -c);
        if (p.first == -1) return p;
        r += p.first;
        b += p.second;
      } else if (cl[v] == c) {
        return { -1, -1 };
      }
    }
  }
  return { r, b };
}

