  for (i64 u = 1; u <= n; ++u) {
    if (cl[u] == 0) {
      ps.push_back(dfs_cl(u, 1));
      if (ps.back().first == -1) { cout << -1 << '\n'; return 0; }
    }
  }

  sort(begin(ps), end(ps));
