void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}

int e[710][710];

bool isBipartite(const Graph &g, long long v, long long c, vector<long long> &color) {
    color[v] = c;
    for(auto e : g[v]) {
        if (color[e.to] < 0) {
            bool f = isBipartite(g, e.to, c ^ 1, color);
            if (!f) return false;
        } else {
            if ((c^1) != color[e.to]) {
                return false;
            }
        }
    }
    return true;
}

void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    for(int i = 0; i < M; ++i) {
        e[A[i]][B[i]] = e[B[i]][A[i]] = 1;
    }
    Graph g(N + 1);
    for(int i = 1; i <= N; ++i) for(int j = i + 1; j <= N; ++j) {
        if(!e[i][j]) {
            addUndirectedEdge(g, i, j, 1);
        }
    }
    vector<int> color(N + 1, -1);
    int c = 0;
    for(int i = 1; i <= N; ++i) {
        if (color[i] < 0) {
            if (!isBipartite(g, i, c, color)) {
                cout << -1 << endl;
                return;
            }
            c += 2;
        }
    }
    vector<int> cnt(c);
    for(int i = 1; i <= N; ++i) cnt[color[i]]++;
    vector<vector<bool>> dp(c / 2 + 1, vector<bool>(N + 1));
    dp[0][0] = true;
    for(int i = 0; i * 2 < c; i++) {
        for(int j = N; j >= 0; --j) {
            for(int k = 0; k < 2; ++k) {
                if (j - cnt[i * 2 + k] >= 0) {
                    dp[i + 1][j] = dp[i + 1][j] || dp[i][j - cnt[i * 2 + k]];
                }
            }
        }
    }
    int res = N * (N - 1) / 2;
    for(int i = 0; i <= N; ++i) {
        if (dp[c / 2][i]) {
            int a = i, b = N - i;
            res = min(res, a * (a - 1) / 2 + b * (b - 1) / 2);
        }
    }
    cout << res << endl;
}

