    dp[0] = 1;
    for(int i = 1; i <= tot; i++) {
        for(int j = n; j >= 0; j--) {
            if(j >= num[i].fi) dp[j] |= dp[j - num[i].fi];
            if(j >= num[i].se) dp[j] |= dp[j - num[i].se];
        }
    }
    int ans = 1e9;
    for(int i = 0; i <= n; i++) {
        if(dp[i]) {
            ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
    }
    cout << ans << '\n';
}

