		for (auto i : dis_edge[cn]) {
			if (dis[i] > dis[cn] + 1) {
				dis[i] = dis[cn] + 1;
				Q.push(i);
			}
		}
	}
	bool imp = false;
	for (int i = 0; i < N; i++) {
		for (auto j : dis_edge[i]) {
			if (dis[i] % 2 == dis[j] % 2) {
				imp = true;
			}
		}
