void setgroup(size_t v, int group) {
    //std::cout << "set " << v << ' ' << group << std::endl;
    V[v] = group;
    for (size_t i = v + 1; i <= N; i++) {
        if (E[v][i]) {
            continue;
        }
        if (V[i] == -1) {
            setgroup(i, group ^ 1);
        } else if (V[i] == (group ^ 1)){
            continue;
        } else if (V[i] == group) {
            //std::cout << v << ' ' << i << ' ' << V[i] << std::endl;
            std::cout << "-1" << std::endl;
            exit(0);
        } else {
            size_t x = V[i];
            // unify group with V[i]
            //std::cout << "unify " << x << ' ' << group << std::endl;
            for (size_t j = 1; j <= N; j++) {
                if (V[j] == x) {
                    V[j] = group ^ 1;
                } else if (V[j] == (x ^ 1)) {
                    V[j] = group;
                }

            }

        }

    }
}

int main()
{

    for (size_t i = 0; i < NMAX + 1; i++) {
        for (size_t j = 0; j < NMAX; j++) {
            E[i][j] = 0;
        }
    }

    for (size_t i = 0; i < NMAX + 1; i ++) {
        V[i] = -1;
    }


    std::cin >> N >> M;
    for (size_t i = 0; i < M; i++) {
        int a, b;
        std::cin >> a >> b;
        E[a][b] = E[b][a] = 1;
    }

    int group = 0;

    for (size_t i = 1; i <= N; i++) {
        if (V[i] != -1) {
            continue;
        }

        V[i] = group;
        setgroup(i, group);
        group += 2;
    }

    size_t maxsum = 0;
    for (size_t g = 0; g < group; g += 2) {
        std::pair<size_t, size_t> pair = {0, 0};
        for (size_t i = 1; i <= N; i++) {
            if (V[i] == g) {
                pair.first += 1;
            }
            if (V[i] == g + 1) {
                pair.second += 1;
            }
        }
        maxsum += std::max(pair.first, pair.second);
        //std::cout << pair.first << ' ' << pair.second << std::endl;
    }

    for (int i = 1; i <= N; i++) {
        std::cout << V[i] << std::endl;
