    size_t g2 = N - maxsum;
    //std::cout << g1 << ' ' << g2 << std::endl;

    std::cout << (g1 * (g1 - 1)) / 2 + (g2 * (g2 - 1)) / 2 << std::endl;

    return 0;
}

