using namespace std;

const int N = 701;

int n;

int used[N];
int g[N][N];
int cl[N];

int fl = 0;

void dfs(int cur, int c, int &c1, int &c2) {
	cl[cur] = c;
	used[cur] = 1;
	if (c) c1++;
	else c2++;
	for (int i = 0; i < N; i++) {
		if (!used[i] && g[cur][i]) {
			dfs(i, c ^ 1, c1, c2);
		}
		if (used[i] && cl[cur] == cl[i] && g[cur][i]) {
			fl = 1;
		}
	}
}

void init() {
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			g[i][j] = (i != j);
		}
	}
}

vector<pair<int, int>> solve() {
	vector<pair<int, int>> v;
	for (int i = 0; i < n; i++) {
		if (!used[i]) {
			int c1 = 0;
			int c2 = 0;
			dfs(i, 0, c1, c2);
			v.push_back({c1, c2});
		}
	}
	if (fl) {
		cout << -1 << endl;
		exit(0);
	}
	return v;
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);


	int m;
