	init();
	for (int i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--;
		v--;
		g[u][v] ^= 1;
		g[v][u] ^= 1;
	}
	vector<pair<int, int>> v = solve();
	bitset<N> cn;
	cn[0] = 1;
	for (auto t : v) {
		cn = (cn << t.first) | (cn << t.second);
	}
	int ans = m;
	for (int lp = 0; lp <= n; lp++) {
		if (!cn[lp]) continue;
		int rp = n - lp;
		ans = min(ans, lp * (lp - 1) / 2 + rp * (rp - 1) / 2);
	}
	cout << ans << endl;
}

