		rep(i, 0, N) rep(j, 0, N) if(f[i][j] == sz(a) + 1) {
			ans = min(ans, (i - 1) * i / 2 + (j - 1) * j / 2);
		}
		printf("%d\n", ans);
	}
	return 0;
}

