using namespace std;
constexpr int INF = 1000000;

bool adj[700][700], pwede[701][701];

int choose2(int i) {
	return (i)*(i-1)/2;
}

int main() {
	int n, m; scanf("%d %d", &n, &m);
	for (int i = 0; i < m; ++i) {
		int u, v; scanf("%d %d", &u, &v);
		adj[--u][--v] = true;
		adj[v][u] = true;
	}
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if (i != j) adj[i][j] = not adj[i][j];
		}
	}
	int cbc = 0;
	vector<int> bdivc(n, -1);
	for (int i = 0; i < n; ++i) {
		if (bdivc[i] == -1) {
			bdivc[i] = cbc;
			queue<int> q; q.push(i);
			while (not q.empty()) {
				int cur = q.front(); q.pop();
				// printf("color %d %d\n", cur, bdivc[cur]);
				for (int next = 0; next < n; ++next) {
					if (adj[cur][next] and bdivc[next] == -1) {
						bdivc[next] = bdivc[cur] ^ 1;
						q.push(next);
					}
				}
			}
			cbc += 2;
		}
	}
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if (i != j and adj[i][j] and bdivc[i] == bdivc[j]) {printf("-1\n"); return 0;}
		}
	}
	vector<int> compCount(cbc);
	for (int i = 0; i < n; ++i) ++compCount[bdivc[i]];
	vector<int> a, b;
	for (int i = 0; i < cbc; ++i) {
		// printf("comp %d %d\n", i, compCount[i]);
		if (i % 2 == 0) a.push_back(compCount[i]);
		else b.push_back(compCount[i]);
	}
	pwede[0][0] = true;
	for (int i = 1; i <= a.size(); ++i) {
		// printf("pair %d %d\n", a[i-1] , b[i-1]);
		for (int fas = 0; fas <= n; ++fas) {
			if (fas >= a[i-1]) pwede[i][fas] = pwede[i][fas] || pwede[i-1][fas - a[i-1]];
			if (fas >= b[i-1]) pwede[i][fas] = pwede[i][fas] || pwede[i-1][fas - b[i-1]];
		}
	}
	int ans = 1000000000;
	for (int as = 0; as <= n; ++as) {
		if (pwede[a.size()][as]) {
			ans = min(choose2(as) + choose2(n - as), ans);
		}
	}
	printf("%d\n", ans);
	return 0;
}

