bool bad;
int ntot, n1;

void gogo (int cloc, int cv)
{
    if (bp[cloc])
    {
        if (bp[cloc] != cv)
            bad = true;
        return;
    }
    bp[cloc] = cv;

    ntot++;
    if (cv == 1)
        n1++;

    for (int ne : neigh[cloc])
        gogo (ne, 3 - cv);
}

int cp[MAXN];
int np[MAXN];

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> M;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            edge[i][j] = 0;

    for (int i = 0; i < M; i++)
    {
        int x, y;
        cin >> x >> y;
        x--, y--;
        edge[x][y] = edge[y][x] = 1;
    }

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
        {
            if (i != j && !edge[i][j])
                neigh[i].push_back(j);
        }

    cp[0] = 1;
    for (int i = 1; i <= N; i++)
        cp[i] = 0;

    for (int i = 0; i < N; i++)
        bp[i] = 0;

    bad = false;
    for (int i = 0; i < N; i++)
    {
        if (!bp[i])
        {
            ntot = 0;
            n1 = 0;
            gogo (i, 1);

            for (int j = 0; j <= N; j++)
                np[j] = 0;

            for (int j = N; j >= 0; j--)
                if (cp[j])
                    np[j+n1] = np[j+ntot-n1] = 1;
            for (int j = 0; j <= N; j++)
                cp[j] = np[j];
        }
    }

    int ans = 1e9;
    for (int i = 0; i <= N; i++)
        if (cp[i])
            ans = min (ans, i * (i - 1) / 2 + ((N - i) * (N - i - 1)) / 2);

    if (bad)
        cout << "-1\n";
    else
        cout << ans << "\n";
}

