const int N = 710;
bool f[N], g[N];
int a[N][N], col[N], cnt[2];
int n, m;

void dfs(int u, int w) {
  col[u] = w, cnt[w]++;
  for(int i = 1; i <= n; ++i) {
    if(u == i || a[u][i]) continue;
    if(col[i] == -1) dfs(i, w ^ 1);
    else if(col[i] == w) {
      puts("-1");
      exit(0);
    }
  }
}

int main() {
  memset(col, -1, sizeof col);
  scanf("%d%d", &n, &m);
  for(int i = 1, x, y; i <= m; ++i) {
    scanf("%d%d", &x, &y);
    a[x][y] = a[y][x] = 1;
  }
  f[0] = 1;
  for(int i = 1; i <= n; ++i) {
    if(col[i] == -1) {
      memset(g, 0, sizeof g);
      memset(cnt, 0, sizeof cnt);
      dfs(i, 0);
//      printf("cnt1 = %d cnt2 = %d\n", cnt[0], cnt[1]);      
      for(int j = 0; j <= n; ++j) {
        g[j + cnt[0]] |= f[j];
        g[j + cnt[1]] |= f[j];
      }
      for(int j = 0; j <= n; ++j)
        f[j] = g[j];
    }
  }
  int ans = 1e9;
  for(int i = 0; i <= n; ++i)
    if(f[i]) {
//      printf("qwq%d\n", i);
      ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
  printf("%d\n", ans);
  return 0;
}

