bool flag = false;

void dfs(int v, int col, int cc)
{
    used[v] = 1;
    color[v] = col;
    num[v] = cc;

    if (col) bal[cc]--;
    else bal[cc]++;

    for (int u = 0; u < n; u++)
    {
        if (u == v) continue;
        if (gr[v][u])
        {
            if (!used[u])
                dfs(u, 1 - col, cc);
            else
                if (color[u] == color[v])
                {
                    flag = true;
                }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin >> n >> m;

    memset(gr, 1, sizeof gr);

    for (int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        u--, v--;
        gr[u][v] = false;
        gr[v][u] = false;
    }

    vector <pair <int, int> > v;

    int cc = 0;
    for (int i = 0; i < n; i++)
    {
        if (!used[i])
            dfs(i, 0, cc);

        if (flag)
        {
            cout << -1 << '\n';
            return 0;
        }

        v.push_back({abs(bal[cc]), i});
        cc++;
    }
    int cur_bal = 0;
    sort(v.rbegin(), v.rend());
    for (auto x : v)
    {
        if (cur_bal >= 0)
        {
            if (x.X >= 0)
            {
                cur_bal -= x.X;
            }
            else
            {
                cur_bal += x.X;
            }
        }
        else
        {
            if (x.X >= 0)
            {
                cur_bal += x.X;
            }
            else
            {
                cur_bal -= x.X;
            }
        }
    }
    int half = (n - cur_bal) / 2;
    cout << (half*(half - 1))/2 + ((n - half)*(n - half - 1))/2;
    return 0;
}

