using namespace std;

typedef pair<int,int> pii;

int N, M, col[MAXN], a, b, vs[2], dp[2][MAXN], ans;
vector <int> G[MAXN];
bool B[MAXN][MAXN], FAIL = false, cur = 0, pre = 1;
vector<pii> P;

void dfs(int x, int c) {
    col[x] = c;
    vs[c]++;
    for (auto y : G[x]) {
        if (col[y] == -1) dfs(y, !c);
        if (col[y] == col[x]) FAIL = true;
    }
}

int cal(int x) {
    return x * (x-1) / 2;
}

int main() {
    scanf("%d%d",&N,&M);
    for (int i=0;i<M;++i) {
        scanf("%d%d",&a,&b);
        B[a][b] = B[b][a] = 1;
    }
    for (int i=1;i<=N;++i)
        for (int j=i+1;j<=N;++j)
            if (!B[i][j]) {
                G[i].push_back(j);
                G[j].push_back(i);
            }
    memset(col,-1,sizeof(col));
    for (int i=1;i<=N;++i)
        if (col[i] == -1) {
            vs[0] = vs[1] = 0;
            dfs(i, 0);
            P.push_back(pii(vs[0],vs[1]));
        }
    if (FAIL) {
        printf("-1\n");
    }
    else {
        dp[pre][0] = 1;
        for (auto p : P) {
            //printf("(%d, %d)\n", p.first, p.second);
            memset(dp[cur],0,sizeof(dp[cur]));
            for (int i=p.first;i<=N;++i) dp[cur][i] |= dp[pre][i-p.first];
            for (int i=p.second;i<=N;++i) dp[cur][i] |= dp[pre][i-p.second];
            cur = !cur;
            pre = !pre;
        }
        ans = cal(N);
        for (int i=1;i<=N;++i)
            if (dp[pre][i]) ans = min(ans, cal(i) + cal(N-i));
        printf("%d\n",ans);
    }
}

