int main() {
    int N, M;
    cin >> N >> M;
    vector<vector<bool>> edge(N+1, vector<bool>(N+1, false));
    for (int i = 0; i < M; i++) {
        int A, B;
        cin >> A >> B;
        edge[A][B] = true;
        edge[B][A] = true;
    }
    vector<bool> use(N+1, false);
    vector<int> color(N+1, 0);
    bitset<777> bs;
    bs[0] = 1;
    for (int i = 1; i <= N; i++){
        if (use[i]) continue;
        use[i] = true;
        queue<int> q;
        q.push(i);
        color[i] = 1;
        int b = 1, w = 0;
        while(!q.empty()){
            int now = q.front();
            q.pop();
            for (int nxt = 1; nxt <= N; nxt++) {
                if (edge[now][nxt] || now==nxt) continue;
                if (color[now] == color[nxt]) {
                    cout << -1 << endl;
                    return 0;
                }
                if (use[nxt]) continue;
                color[nxt] = 3 - color[now];
                if (color[now]==1) w++;
                else b++;
                use[nxt] = true;
                q.push(nxt);
            }
        }
        bs = (bs << b) | (bs << w);
    }
    ll S = N/2;
    while (bs[S] == 0) S--;
    ll T = N-S;
    cout << S*(S-1)/2 + T*(T-1)/2 << endl;
    return 0;
}

