				if (x != y && !e[x][y]) {
					puts("-1");
					return 0;
				}
	}
	int R = 1e9;
	for (int it = 0; it < 2; ++it) {
		int cR = 0;
		for (int i = 0; i < 2; ++i)
			cR += (int)v[i].size()*((int)v[i].size() - 1) / 2;
		R = min(R, cR);
		for (int i = 0; i < v[0].size(); ++i) {
			int u = v[0][i];
			bool can = true;
			for (auto &V : v[1])
				if (!e[u][V]) {
					can = false;
					break;
				}
			if (can) {
				v[1].push_back(v[0][i]);
				v[0][i] = v[0].back();
				v[0].pop_back();
				--i;
			}
			int cR = 0;
			for (int i = 0; i < 2; ++i)
				cR += (int)v[i].size()*((int)v[i].size() - 1) / 2;
			R = min(R, cR);
		}
		v[0].swap(v[1]);
	}
	printf("%d\n", R);
	return 0;
}

