		int u, v; cin >> u >> v;
		g[u][v] = g[v][u] = 1;
	}
	for(int i = 1; i <= n; i++) {
		if(!vis[i]) {
			cur.clear();
			dfs(i);
			int x = 0, y = 0;
			for(int u : cur) {
				x += col[u];
				y += 1 ^ col[u];
			}
			s.emplace_back(x);
			t.emplace_back(y);
		}
	}
	s.insert(s.begin(), 0);
	t.insert(t.begin(), 0);
	for(int i = 0; i <= n; i++) {
		dp[0][i] = i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2;
	}
	for(int i = 1; i < s.size(); i++) {
		for(int j = 0; j + s[i] <= n or j + t[i] <= n; j++) {
			dp[i][j] = INT_MAX;
			if(j + s[i] <= n) dp[i][j] = dp[i - 1][j + s[i]];
			if(j + t[i] <= n) dp[i][j] = min(dp[i][j], dp[i - 1][j + t[i]]);
		}
	}
	cout << dp[s.size() - 1][0] << endl;
