const int MAX = 1000;
const int INF = 100000000;

int series(int n) {
	return (n * (n + 1)) / 2;
}

int f(int N, bool G[MAX][MAX], int table[MAX]) {
	vector<int> v;
	bool find = true;

	int v1 = 0;
	int v2 = -1;
	int m = INF;

	for (int i = 0; i < N; i++) {
		int cnt = 0;

		if (table[i] != 0)continue;

		for (int j = 0; j < N; j++) {
			if (G[i][j])cnt++;
		}
		if (m > cnt) {
			m = cnt;
			v1 = i;
		}
	}

	for (int i = 0; i < N; i++) {
		if (G[v1][i] && table[i] == 0) {
			v2 = i;
			break;
		}
	}

	table[v1]++;
	v.push_back(v1);

	if (v2 != -1) {
		table[v2]++;
		v.push_back(v2);
	}

	while (find) {
		find = false;

		for (int i = 0; i < N; i++) {
			int cnt = 0;

			for (int j = 0; j < v.size(); j++) {
				if (G[i][v[j]])cnt++;
			}

			if (cnt == v.size()) {
				table[i]++;
				v.push_back(i);
				find = true;
				break;
			}
		}
	}

	return v.size();
}

int main() {
	int N, M;
	bool G[MAX][MAX] = { {false} };

	cin >> N >> M;
	for (int i = 0; i < M; i++) {
		int a, b;

		cin >> a >> b;
		a--; b--;

		G[a][b] = true;
		G[b][a] = true;
	}

	int table[MAX] = { 0 };
	int n1 = f(N, G, table);
	int n2 = f(N, G, table);
	int cnt = 0;
	bool impossible = false;

	for (int i = 0; i < N; i++) {
		if (table[i] == 0)impossible = true;
		if (table[i] == 2)cnt++;
	}

	n1 -= cnt;
	n2 -= cnt;

	if (n1 < n2)swap(n1, n2);

	n2 += cnt;
	if (n2 - n1 > 0) {
		int x = (n2 - n1) / 2;

		n1 += x;
		n2 -= x;
	}

	if (impossible)cout << -1 << endl;
	else cout << series(n1 - 1) + series(n2 - 1) << endl;

	return 0;
}

