        for(auto l : left){
            for(auto to : g[l]){
                if(0 < left.count(to))  return -1;
                if(0 < right.count(to)) continue;

                right.insert(to);
                update = true;
            }
        }

        for(auto r : right){
            for(auto to : g[r]){
                if(0 < right.count(to)) return -1;
                if(0 < left.count(to))  continue;

                left.insert(to);
                update = true;
            }
        }
    }

    int ln = left.size();
    int rn = right.size();
    int rem = n - ln - rn;

    rep(i, rem){
        if(ln < rn) ln++;
        else        rn++;
    }

    return (ln*(ln-1) + rn*(rn-1))/2;
}

