int calc(int a , int b)
{
	return a * b + a * (a-1) / 2 ;
}

int solve(int idx , int cnt0 , int cnt1)
{
	if(idx == vp.size())
		return 0 ;
	int &ret = dp[idx][cnt0] ; // cnt1 is unique for every state
	if(ret != -1)
		return ret ;
	ret = solve(idx+1 , cnt0 + vp[idx].first , cnt1 + vp[idx].second) + calc(vp[idx].first , cnt0) + calc(vp[idx].second , cnt1) ;
