bool isBipartite_proc(int, int);
bool isBipartite() {
  color.resize(g.size(), 0);
  rep(i, 0, g.size()) {
    if (color[i] == 0) {
      if (!isBipartite_proc(i, 1))
        return false;
    }
  }
  return true;
}
bool isBipartite_proc(int v, int c) {
  color[v] = c;
  for (auto u : g[v]) {
    if (color[u] == c)
      return false;
    if (color[u] == 0 and !isBipartite_proc(u, -c))
      return false;
  }
  return true;
}
