const int MAX = 700 + 5;
bool memo[MAX][MAX], visited[MAX][MAX];
int adj[MAX][MAX], color[MAX];
int n, m;

void die() {
	puts("-1");
	exit(0);
}

ii bfs(int source) {
	queue<int> q;
	q.push(source);
	color[source] = 0;
	int c[2] = {0};
	while(!q.empty()) {
		int cur = q.front(); q.pop();
		c[color[cur]]++;
		fori(i, 1, n + 1) {
			if(!adj[cur][i]) {
				continue;
			}
			if(color[i] == -1) {
				color[i] = !color[cur];
				q.push(i);
			}
			else if(color[cur] == color[i]) {
				die();
			}
		}
	}
	return ii(c[0], c[1]);
}

vector<ii> pairs;
bool roll(int idx, int got) {
	if(got < 0) {
		return false;
	}
	else if(idx == -1) {
		return got == 0;
	}
	bool &ans = memo[idx][got];
	if(visited[idx][got]) {
		return ans;
	}
	visited[idx][got] = true;
	ans = roll(idx - 1, got - pairs[idx].first) || roll(idx - 1, got - pairs[idx].second);	
	return ans;
}

int main() {
	scanf("%d %d", &n, &m);

	fori(i, 1, n + 1) {
		fori(j, 1, n + 1) {
			adj[i][j] = 1;
		}
		adj[i][i] = 0;
	}

	fori(i, 0, m) {
		int u, v;
		scanf("%d %d", &u, &v);
		adj[u][v] = adj[v][u] = 0;
	}

	memset(color, -1, sizeof color);
	fori(i, 1, n + 1) {
		if(color[i] == -1) {
			ii p = bfs(i);
			pairs.push_back(p);
		}
	}

	int half = n / 2; 
	int ans = 0;
	ford(i, half, 0) {
		if(roll((int) pairs.size() - 1, i)) {
			int a = i;
			int b = n - i;
			ans = (a * (a - 1)) / 2 + (b * (b - 1)) / 2;
			break;
		}
	}

	printf("%d\n", ans);

	return 0;
}

