const int MAXN = 1400;

int n, m;

int A[MAXN + 5][MAXN + 5];

inline void input()
{
	n = read<int>(), m = read<int>();
	for(int i = 1; i <= m; ++i)
	{
		int u = read<int>(), v = read<int>();
		A[u][v] = A[v][u] = 1;
	}
}

int cnt[2], fg;
int col[MAXN + 5];

inline void color(int u, int c0)
{
	++cnt[col[u] = c0];
	for(int v = 1; v <= n; ++v) if(A[u][v])
	{
		if(col[v] == col[u]) { fg = 1; return; }
		else if(col[v] == -1) color(v, !c0);
	}
}

inline void solve()
{
	int edge_cnt = 0;
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
			if(i != j) edge_cnt += (A[i][j] ^= 1) == 1;
	edge_cnt /= 2;

	static vector<int> V;
	memset(col, -1, sizeof col);
	for(int i = 1; i <= n; ++i) if(col[i] == -1)
	{
		cnt[0] = cnt[1] = fg = 0;
		color(i, 0);
		if(fg) { puts("-1"); return; }
		V.push_back(abs(cnt[0] - cnt[1]));
	}

	static bool f[MAXN + 5];

	f[V.back()] = 1, V.pop_back();
	for(auto k : V)
		for(int i = 0; i <= n; ++i) if(f[i])
		{
			if(i - k >= 0) f[i - k] = 1;
			if(i + k <= n) f[i + k] = 1;
		}

	for(int i = 0; i <= n; ++i) if(f[i])
	{
		int p = (n + i) / 2, q = (n - i) / 2;
		printf("%d\n", p * (p - 1) / 2 + q * (q - 1) / 2);
		return;
	}
}

