using namespace std;

const int N = 700 + 10;
bool adj[N][N], r[N], mark[N];
bool dp[N][N];
int n;

void dfs(int root, int color) {
    mark[root] = true;
    r[root] = color;
    for (int i = 0; i < n; i++)
        if(!mark[i] && !adj[root][i] && root != i)
            dfs(i, 1 - color);
}

pair<int, int> dfs2(int root) {
    pair<int, int> res;
    res.first = 1;
    res.second = 0;
    mark[root] = true;
    for (int i = 0; i < n; i++)
        if(!mark[i] && !adj[root][i] && root != i) {
            pair<int, int> x = dfs2(i);
            res.first += x.second;
            res.second += x.first;
        }
    return res;
}

