void dfs_comp(vector<vector<int>> const& adjlist, vector<int>& comp, vector<int>& oddity, int v, int color, int odd = 0)
{
    if (comp[v] == -1) {
        comp[v] = color;
        oddity[v] = odd;
        for (int nn : adjlist[v]) {
            dfs_comp(adjlist, comp, oddity, nn, color, 1 - odd);
        }
    }
}

int main()
{
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adjlist(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b; --a; --b;
        adjlist[a].push_back(b);
        adjlist[b].push_back(a);
    }

    vector<vector<int>> inv_adjlist(n);
    for (int i = 0; i < n; ++i) {
        sort(adjlist[i].begin(), adjlist[i].end());
        for (int j = 0, k = 0; j < n; ++j) {
            if (k < (int) adjlist[i].size() && adjlist[i][k] == j) {
                ++k;
            } else if (i != j) {
                inv_adjlist[i].push_back(j);
            }
        }
    }

    vector<int> comp(n, -1);
    vector<int> oddity(n, -1);
    int ncomp = 0;
    for (int i = 0; i < n; ++i) {
        if (comp[i] == -1) {
            dfs_comp(inv_adjlist, comp, oddity, i, ncomp);
            ncomp += 1;
        }
    }

    // Проверить двудольность
    for (int i = 0; i < n; ++i) {
        for (int nn : inv_adjlist[i]) {
            if (oddity[nn] == oddity[i]) {
                cout << -1 << endl;
                return 0;
            }
        }
    }

    vector<int> comp_size(ncomp);
    vector<int> comp_oddsize(ncomp);
    for (int i = 0; i < n; ++i) {
        comp_size[comp[i]] += 1;
        comp_oddsize[comp[i]] += oddity[i];
    }

    vector<int8_t> knapsack(n + 1), nknapsack(n + 1);
    knapsack[0] = 1;
    for (int icomp = 0; icomp < ncomp; ++icomp) {
        for (int i = 0; i <= n; ++i) {
            if (knapsack[i]) {
                nknapsack[i + comp_oddsize[icomp]] = 1;
                nknapsack[i + comp_size[icomp] - comp_oddsize[icomp]] = 1;
            }
        }
        knapsack.assign(n + 1, 0);
        knapsack.swap(nknapsack);
    }

    int v = 0;
    for (int i = n / 2; i >= 0; --i) {
        if (knapsack[i]) {
            v = i;
            break;
        }
    }

    cout << (v * (v - 1) / 2 + (n - v) * (n - v - 1) / 2) << endl;
}

