ll N, M;
vector<vector<bool>> connect(N, vector<bool>(N, false));

enum Dir {
    LEFT, RIGHT, UNDEFINEED
};

vector<Dir> dir;
vector<ll> tmp_nums;
bool isOK = true;

void dfs(ll v, Dir curr_dir) {
    dir[v] = curr_dir;
    tmp_nums[curr_dir]++;
    for (ll e = 0; e < N; e++) {
        if (e == v || !connect[v][e]) {
            continue;
        }

        Dir next_dir = (curr_dir == RIGHT ? LEFT : RIGHT);
        if (dir[e] == UNDEFINEED) {
            dfs(e, next_dir);
        } else if (dir[e] != next_dir) {
            isOK = false;
        }
    }
}

int main() {
