        A--; B--;
        connect[A][B] = connect[B][A] = false;
    }

    //とりあえず二部グラフを作って配分の数を記録していく
    dir.resize(N, UNDEFINEED);
    vector<vector<ll>> nums;
    for (ll i = 0; i < N; i++) {
        if (dir[i] != UNDEFINEED) {
            continue;
        }
        tmp_nums.assign(2, 0);
        dfs(i, LEFT);
        nums.push_back(tmp_nums);
    }

    if (!isOK) {
        cout << -1 << endl;
        return 0;
    }

    vector<bool> dp(N + 1, false);
    dp[0] = true;
    for (auto num : nums) {
        for (ll i = N; i >= 0; i--) {
