P dfs(int i, int taka = 1) {
    // cout << "    now on "<< i + 1 <<" col:"  << taka << endl; 
    state[i] = taka;
    bool fl = true;
    P ans = make_pair(0, 0);
    for (int k = 0; k < N; ++k) {
        if (!adj[i][k]) {
            //cout << k + 1 << endl;
            if (state[k] != 0) {
                if (state[k] != taka * -1) {
                    return make_pair(-1, -1);
                }
                continue;
            }
            fl = false;
            P recv = dfs(k, taka * -1);
            if (recv.first == -1) return make_pair(-1, -1);
            ans = ans + recv;
        }
    }
    P cur = taka == 1 ? make_pair(1, 0) : make_pair(0, 1);
    if (fl) {
        return cur;
    }
    return ans + cur;
}

