  for ( int i = 0; i < M; i++ ) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    edges[a][b] = edges[b][a] = true;
  }

  // 補グラフ生成
  for ( int i = 0; i < N; i++ ) {
    for ( int j = 0; j < N; j++ ) { 
      if ( i == j ) continue;
      if ( !edges[i][j] ) {
	G[i].push_back(j);
      }
    }
  }

  vector<P> bi_graphs;
  vector<int> used(N, 0);  
  for ( int i = 0; i < N; i++ ) {
    if ( used[i] ) continue;
    used[i] = 1;
    int cnt[3] = {0};
    queue<int> Q;
    Q.push(i); // node, color
    while ( !Q.empty() ) {
      int p = Q.front(); Q.pop();
      cnt[used[p]]++;      

      for ( int u: G[p] ) {
	if ( used[p] == used[u] ) {
	  cout << -1 << endl;
	  return 0;
	}
	if ( used[u] ) continue;
	used[u] = 3-used[p];	
	Q.push(u);	
      }
    }

    bi_graphs.push_back(P(cnt[1], cnt[2]));    
  }

  int n = bi_graphs.size();
  vector<int> dp(N+1, 0);
  dp[0] = 1;  
  for ( int i = 0; i < n; i++ ) {
    int a = bi_graphs[i].first, b = bi_graphs[i].second;
    vector<int> nxt(N+1, 0);
    for ( int j = 0; j <= N; j++ ) {
      if ( !dp[j] ) continue;
      if ( j+a <= N ) nxt[j+a] = 1;
      if ( j+b <= N ) nxt[j+b] = 1;
    }
    swap(dp, nxt);    
  }

  int ans = M;
  for ( int i = 0; i <= N; i++ ) {    
    if ( !dp[i] ) continue;
    int a, b;
    a = i*(i-1)/2;
    b = (N-i)*(N-i-1)/2;          
    ans = min(ans, a+b);
  }

  cout << ans << endl;

  return 0;
}

