    x--; y--;
    D[x][y] = 1;
    D[y][x] = 1;
  }

  rep(i, 0, n) {
    rep(j, 0, n) {
      if (i == j) continue;
      if (D[i][j] == 0) adj[i].pb(j);
    }
  }

  rep(i, 0, n) {
    if (!vs[i]) {
      G++;
      cnt[0] = cnt[1] = 0;
      dfs(i, 0);
      has.pb(mp(cnt[0], cnt[1]));
    }
  }

  int cur1 = 0, cur2 = 0;

  sort(has.begin(), has.end, cmp);

  rep(i, 0, G) {
    if (cur1 > cur2) swap(cur1, cur2);
    cur1 += max(has[i].fi, has[i].se);
    cur2 += min(has[i].fi, has[i].se);
  }

  int ans = ((cur1 * (cur1 - 1)) / 2) + ((cur2 * (cur2 - 1)) / 2); 
  cout << ans;

  return 0;
}

