vector<int> nog[700];
int col[700];
UnionFind uf;
bool done[700], dp[701][701];

bool bin_col(int u, int c) {
	col[u] = c;
	REP(i, nog[u].size()) {
		int v = nog[u][i];
		if (col[v] == 0) {
			uf.unite(u, v);
			if (!bin_col(v, -c)) return false;
		}
		else {
			if (col[v] == col[u]) return false;
		}
	}
	return true;
}

int main() {
	cin >> N >> M;
	REP(i, M) {
		int a, b;
		scanf("%d %d", &a, &b);
		a--; b--;
		g[a][b] = g[b][a] = 1;
	}
	REP(i, N) g[i][i] = 1;

	REP(i, N) REP(j, N) if (!g[i][j]) nog[i].push_back(j);

	uf = UnionFind(N);
	REP(i, N) if (col[i] == 0) {
		if (!bin_col(i, 1)) {
			puts("-1");
			return 0;
		}
	}

	vector<pii> v;
	REP(i, N) if (!done[i]) {
		pii cur(0, 0);
		REP(j, N) if (uf[i] == uf[j]) {
			done[j] = true;
			if (col[i] == col[j]) cur.fi++;
			else cur.se++;
		}
		v.push_back(cur);
	}

	dp[0][0] = 1;
	REP(i, v.size()) {
		REP(j, N + 1) if (dp[i][j]) {
			dp[i + 1][j + v[i].fi] = true;
			dp[i + 1][j + v[i].se] = true;
		}
	}

	int ans = INF;
	REP(i, N + 1) if (dp[v.size()][i]) {
		int x = i, y = N - i;
		chmin(ans, max(x*(x-1)/2, 0) + max(y*(y-1)/2, 0));
	}

	cout << ans << endl;

	return 0;
}

