int main() {
    ll N, M;
    cin >> N >> M;
    vector<vector<bool>> connect(N, vector<bool>(N, false));
    for (ll i = 0; i < M; i++) {
        ll A, B;
        cin >> A >> B;
        A--; B--;
        connect[A][B] = connect[B][A] = true;
    }

    deque<pair<set<ll>, set<ll>>> candidates[2];
    candidates[1].push_back({ { 0 }, {} });

    for (ll i = 1; i < N; i++) {
        while (!candidates[i % 2].empty()) {
            auto candidate = candidates[i % 2].back();
            candidates[i % 2].pop_back();

            //iはfirstに入れるか
            bool f1 = true;
            for (auto e : candidate.first) {
                if (!connect[i][e]) {
                    f1 = false;
                    break;
                }
            }
            if (f1) {
                candidate.first.insert(i);
                candidates[(i % 2) ^ 1].push_back(candidate);
                candidate.first.erase(i);
            }

            //iはsecondに入れるか
            bool f2 = true;
            for (auto e : candidate.second) {
                if (!connect[i][e]) {
                    f2 = false;
                    break;
                }
            }
            if (f2) {
                candidate.second.insert(i);
                candidates[(i % 2) ^ 1].push_back(candidate);
            }
        }
    }

    ll ans = INT_MAX;
    for (auto candidate : candidates[N % 2]) {
        ll tmp = 0;
        for (auto e1 : candidate.first) {
            for (auto e2 : candidate.first) {
                if (connect[e1][e2]) {
                    tmp++;
                }
            }
        }
        for (auto e1 : candidate.second) {
            for (auto e2 : candidate.second) {
                if (connect[e1][e2]) {
                    tmp++;
                }
            }
        }
        ans = min(ans, tmp / 2);
    }

    cout << (ans == INT_MAX ? -1 : ans) << endl;
}

