int color[MAX_N];

void coloring(int pos, int c = 1) {
    if(color[pos] == 0 || color[pos] == c)
        color[pos] = c;
    else {
        color[pos] = -1;
        return;
    }

    int nextColor = (c == 1 ? 2 : 1);
    for(int i = 0; i < edgeList[pos].size(); i++) {
        int next = edgeList[pos][i];
        if(color[next] == nextColor) {
            continue;
        }
        coloring(next, nextColor);
    }
}

bool used[MAX_N];
int counter(int pos, int c = 1) {
    int ret = 0;
    used[pos] = true;
    if(color[pos] == c) {
        ret++;
    }

    for(int i = 0; i < edgeList[pos].size(); i++) {
        int next = edgeList[pos][i];
        if(!used[next]) {
            ret += counter(next, c);
        }
    }

    return ret;
}

