                continue;
            }
            auto p = dfs(didx, nodes[idx].color);
            ret.first += p.first;
            ret.second += p.second;
        }
        // printd(idx, ret);
        return ret;
    }
    void rev(int idx, int prev, int p = -1){
        nodes[idx].color = prev == 1 ? 2 : 1;
        for(int didx : nodes[idx].dests){
            if(p == didx){ continue; }
            rev(didx, nodes[idx].color, didx);
        }
    }
};

