using namespace std;

const int MAX_N = 705;

int sign (int x) {
  return x / abs(x);
}

int conn [MAX_N][MAX_N];
vector<int> adj [MAX_N];

int part [MAX_N];
int swing [MAX_N];
bool fail;
void dfs (int vertex, int color) {
  part[vertex] = color;
  swing[abs(color)] += sign(color);

  for (int nxt : adj[vertex]) {
    if (part[nxt] == 0) {
      dfs(nxt, -color);
    } else if (part[nxt] == color) {
      fail = 1;
    }
  }
}

int dp [2 * MAX_N + 1][MAX_N];

int& dpAt (int i, int j) {
  return dp[i + MAX_N][j];
}

int edges (int x) {
  return x * (x - 1) / 2;
}

int main () {
  int vertexc, edgec;
  cin >> vertexc >> edgec;

  for (int i = 0; i < edgec; i++) {
    int u, v;
    cin >> u >> v;

    conn[u][v] = 1;
    conn[v][u] = 1;
  }

  for (int i = 1; i <= vertexc; i++) {
    for (int j = i + 1; j <= vertexc; j++) {
      if (conn[i][j] == 0) {
        adj[i].push_back(j);
        adj[j].push_back(i);
      }
    }
  }

  int curPart = 1;
  for (int i = 1; i <= vertexc; i++) {
    if (part[i] == 0) {
      dfs(i, curPart);
      curPart++;
    }
  }

  if (fail) {
    cout << -1 << endl;
    return 0;
  }

  dpAt(0, 0) = 1;
  for (int i = 1; i < curPart; i++) {
    for (int j = -MAX_N; j < MAX_N; j++) {
      if (dpAt(j, i - 1)) {
        dpAt(j + swing[i], i) = 1;
        dpAt(j - swing[i], i) = 1;
      }
    }
  }

  int finalSwing = MAX_N + 5;
  for (int i = -MAX_N; i < MAX_N; i++) {
    if (dpAt(i, curPart - 1)) {
      finalSwing = min(finalSwing, abs(i));
    }
  }

  int parta = (vertexc - finalSwing) / 2;
  int partb = (vertexc + finalSwing) / 2;

  cout << edges(parta) + edges(partb) << endl;
}

