const int maxn=705;
const int maxx=1500;
int n,m,b[maxn],all=0;
bool f[maxn][maxx];
bool a[maxn][maxn];
namespace graph {
	vector<int> g[maxn];
	int col[maxn],sum;
	inline void add(int x,int y) {
		g[x].push_back(y);
		g[y].push_back(x);
	}
	void dfs(int x,int c) {
		if (col[x]) {
			if (col[x]!=c) puts("-1"),exit(0);
			return;
		}
		col[x]=c;
		sum+=c;
		for (const int &v:g[x]) dfs(v,-c);
	}
	void work() {
		for (int i=1;i<=n;++i) if (!col[i]) {
			sum=0;
			dfs(i,1);
			b[++all]=abs(sum);
		}
	}
