	f[0][n]=true;
	for (int i=1;i<=all;++i) {
		int x=b[i];
		for (int j=0;j<=n*2;++j) if (j+x<=2*n) f[i][j+x]|=f[i-1][j];
		for (int j=0;j<=n*2;++j) if (j-x>=0) f[i][j-x]|=f[i-1][j];
	}
	int res=INT_MAX;
	for (int i=0;i<=n;++i) if (f[all][n-i] || f[all][n+i]) {
		res=i;
		break;
	}
	int lef=(n+res)/2,rig=n-lef;
	int ans=lef*(lef-1)/2+rig*(rig-1)/2;
	printf("%d\n",ans);
