using namespace std;

int N, M;
constexpr int MAX_N = 710;
bool d[MAX_N][MAX_N];
int check[MAX_N];
bool nibugraph = true;

void dfs(int s, int n, int& m1, int& m2){
    check[s] = n;
    if(n == 1) ++m1;
    else ++m2;
    for(int i = 0; i < N; ++i){
        if(d[s][i]){
            if(check[i] == check[s]){
                nibugraph = false;
            }
            if(check[i] == 0){
                dfs(i, n % 2 + 1, m1, m2);
            }
        }
    }
}

int main(){
    cin >> N >> M;

    for(int i = 0; i < N; ++i) for(int j = 0; j < N; ++j){
        if(i != j) d[i][j] = true;
    }

    for(int i = 0; i < M; ++i){
        int A, B;
        cin >> A >> B;
        --A, --B;
        d[A][B] = false;
        d[B][A] = false;
    }

    vector<int> v1;
    vector<int> v2;
    for(int i = 0; i < N; ++i){
        if(check[i] == 0){
            int m1 = 0;
            int m2 = 0;
            dfs(i, 1, m1, m2);
            v1.push_back(m1);
            v2.push_back(m2);
        }
    }
    if(!nibugraph){
        cout << -1 << endl;
        return 0;
    }

    bool dp[3000];
    dp[0] = 1;
    for(size_t i = 0; i < v1.size(); ++i){
        for(int j = N-1; j >= 0; --j){
            if(!dp[j]) continue;
            dp[j] = 0;
            dp[j + v1[i]] = 1;
            dp[j + v2[i]] = 1;
        }
    }

    int64_t a = 0;
    int64_t mid = N;
    for(int i = 0; i < N; ++i){
        if(!dp[i]) continue;
        if(mid > abs(i - N/2)){
            mid = abs(i - N/2);
            a = i;
        }
    }
    int64_t b = N - a;
    cout << a*(a-1)/2 + b*(b-1)/2 << endl;
}

