typedef vector<vector<int>> Graph;

struct UF {
	vector<int> data;
	UF(int size) : data(size, -1) { }
	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool find(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

bool dfs(const Graph &g, vector<int> &v,int node, int pre){
    int sz=g[node].size();
    bool f=true;
    for(int i=0;i<sz;i++){
        int next=g[node][i];
        if(next==pre) continue;
        if(v[node]==v[next]) return f;
        if(v[next]==-1){
            v[next]=1-v[node];
            f &= dfs(g,v,next,node);
        }
    }
    return f;
}

