            a[K][1] = n2;
        }
    }
    f[0][0] = 1;
    for (int i = 1, s = 0; i <= K; i ++) {
        int x = a[i][0], y = a[i][1];
        s += abs(x - y);
        for (int j = 0; j <= s; j ++) {
            f[i & 1][j] = f[i & 1 ^ 1][abs(j + x - y)] || f[i & 1 ^ 1][abs(j - x + y)];
        }
    }
    for (n1 = 0; !f[K & 1][n1]; n1 ++);
    n1 = N + n1 >> 1;
    n2 = N - n1;
    M = n1 * (n1 - 1) + n2 * (n2 - 1) >> 1;
    printf("%d\n", M);
    return 0;
}

