            for (int j = abs(x[i] - y[i]); j <= n; j++) {
                dp[i][j] = dp[i - 1][j - abs(x[i] - y[i])] | dp[i - 1][j + abs(x[i] - y[i])];
            }
        }
        for (int i = n; i >= 0; i--)
            if(dp[x.size() - 1][i]) {
                int t1 = (n - i) / 2, t2 = (n - i) / 2 + i;
                ans2 = (t1 * (t1 - 1)) / 2 + (t2 * (t2 - 1)) / 2;
            }
    }
    cout << (ans? ans2: -1) << endl;
    return 0;
}

