	if (!ok) cout << -1 << endl;
	else {
	  for (int i = 0; i < MAX; ++i) for (int j = 0; j < MAX; ++j) dp[i][j] = 0;
	  dp[0][0] = true;
	  for (int i = 0; i <= (int)nums.size(); ++i) {
		int u = nums[i].first;
		int v = nums[i].second;

		//for (int j = 0; j <= N; ++j) if (dp[i][j]) cout << pint(i, j) << endl;

		if (i == nums.size()) break;
		for (int j = 0; j <= N; ++j) {
		  dp[i+1][j + u] |= dp[i][j];
		  dp[i+1][j + v] |= dp[i][j];
		}
	  }

	  long long a = -1;
	  long long mindif = N;
	  for (int i = 0; i <= N; ++i) {
		if (dp[nums.size()][i]) {
		  if (mindif > abs(i - N/2)) {
			mindif = abs(i - N/2);
			a = i;
		  }
		}
	  }
	  long long b = N-a;

	  //COUT(a); COUT(b);

	  cout << a*(a-1)/2 + b*(b-1)/2 << endl;

	}

  }
}

