        dp[i + p.first] = 1;
        dp[i + p.second] = 1;
      }
    }
  }
  int ans = INT_MAX;
  rng (i, 0, n + 1) {
    if (dp[i]) {
      chkmin(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
  }
  println(ans);

#if defined LOCAL && !defined DUIPAI
