bool dfs(int u) {
  cnt[side[u] - 1] ++;
  for (int v = 0; v < n; ++ v) if (graph[u][v]) {
    if (side[v]) {
      if (side[v] == side[u])
        return false;
    } else {
      side[v] = side[u] ^ 3;
      if (!dfs(v))
        return false;
    }
  }
  return true;
}

int main() {
