    graph[a][b] = graph[b][a] = false;
  }
  for (int i = 0; i < n; ++ i) if (side[i] == 0) {
    cnt[0] = cnt[1] = 0;
    side[i] = 1;
    if (!dfs(i))
      return puts("-1"), 0;
    vec.emplace_back(cnt[0], cnt[1]);
  }
  dp[0][0] = true;
  int s = 0;
  for (const auto& pair : vec) {
