    int b = pair.second;
    for (int i = s; i >= 0; -- i) {
      for (int j = s; j >= 0; -- j) if (dp[i][j]) {
        dp[i + a][j + b] = true;
        dp[i + b][j + a] = true;
      }
    }
    s += std::max(a, b);
  }
  int result = 0;
  for (int i = 0; i <= s; ++ i) {
    for (int j = 0; j <= s; ++ j) if (dp[i][j]) {
      result = std::max(result, i * j);
    }
  }
  result = m - (result - (n * (n - 1) / 2 - m));
  printf("%d\n", result);
}

