		for(int sum = 0; sum<=n; sum++){
			if (sum-opt1>=0) dp[i][sum] |= dp[i-1][sum-opt1];
			if (sum-opt2>=0) dp[i][sum] |= dp[i-1][sum-opt2];
		}
	}
	for(int i = 1; i<=n; i++){
		if (dp[len][i]) {
			int t = n-i;
			ans = min((i*(i-1))/2 + (t*(t-1))/2, ans);
		}
	}
	printf("%d\n", ans);
	return 0;
}

