		all[i]=1;
		for(int j=1; j<=n; ++j){
			all[i]&=lnk[i][j]||i==j;
			if(i!=j&&!lnk[i][j]) U::merge(i<<1,j<<1|1);
		}
	}
	if(!get_fbuk()){
