			z_connected.push_back(i);
		}
		else {
			z_noconnected.push_back(i);
		}
	}
	vector<int>dis_node(N,0);
	vector<vector<int>>dis_edge(N);
	for (int i = 0; i < z_connected.size(); i++) {
		for (int j = i + 1; j < z_connected.size(); j++) {
			if (!edge[z_connected[i]][z_connected[j]]) {
				dis_node[z_connected[i]] = 1;
				dis_node[z_connected[j]] = 1;
				dis_edge[z_connected[i]].push_back(z_connected[j]);
				dis_edge[z_connected[j]].push_back(z_connected[i]);
			}
		}
	}
	queue<int>Q;
	vector<int>pare(N, MOD);
	vector<int>dis(N, MOD);
	for (int i = 0; i < N; i++) {
		if (dis_node[i]) {
			if (pare[i] == MOD) {
				Q.push(i);
				while (!Q.empty()) {
					int cn = Q.front();
					pare[cn] = i;
					Q.pop();
					for (auto i : dis_edge[cn]) {
						if (dis[i] > dis[cn] + 1) {
							dis[i] = dis[cn] + 1;
							Q.push(i);
						}
					}
				}
			}
		}
	}
	vector<pair<int, int>>pnum(N);
	vector<pair<bool, bool>>pflag(N);
	for (int i = 0; i < N; i++) {
		if (pare[i] == MOD)continue;
		pflag[pare[i]].first = true;
		pflag[pare[i]].second = true;
	}
	for (int i = 0; i < N; i++) {
		if (dis[i] == MOD)continue;
		for (auto j : z_noconnected) {
			if (!edge[i][j]) {
				if (dis[i] % 2) {
					pflag[pare[i]].second = false;
				}
				else {
					pflag[pare[i]].first = false;
				}
			}
		}
	}
	for (int i = 0; i < N; i++) {
		if (pnum[i].first + pnum[i].second) {
			if (!pflag[i].first&&pflag[i].second) {
				cout << -1 << endl;
				return 0;
			}
		}
	}
	vector<int>dp(N + 1);
	dp[0] = 1;
	for (int i = 0; i < N; i++) {
		if (pnum[i].first + pnum[i].second) {
			for (int j = N; j >= 0; j--) {
				if (!dp[j])continue;
				if (pflag[i].first&&pflag[i].second) {
					dp[j + pnum[i].first] = 1;
					dp[j + pnum[i].second] = 1;
					dp[j] = 0;
				}
				else if (pflag[i].first) {
					dp[j + pnum[i].first] = 1;
				}
				else {
					dp[j + pnum[i].second] = 1;
				}
			}
		}
	}
	for (int i = 0; i < N; i++) {
		if (pare[i] == MOD)continue;
		if (dis[i] % 2) {
			pnum[pare[i]].second++;
		}
		else {
			pnum[pare[i]].first++;
		}
	}
	int ans = MOD;
	for (int i = 0; i <= N; i++) {
		if (!dp[i])continue;
		int l = z_noconnected.size() + i;
		int r = N - l;
		ans = min(ans,l*(l - 1) / 2 + r * (r - 1) / 2);
	}

	if (ans == MOD) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}
	return 0;
}

