/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */

// # define DEBUG
// # define DEBUG_CASE_NUM 4

void solve() {
    ll N, M;
    cin >> N >> M;

    bool coedge[N + 1][N + 1];
    fill(coedge[0], coedge[N + 1], true);

    FOR(_, 1, M) {
        ll A, B;
        cin >> A >> B;
        coedge[A][B] = coedge[B][A] = false;
    }

    V<ll> path[N + 1];
    FOR(i, 1, N) {
        FOR(j, 1, N) {
            if (coedge[i][j]) path[i].pb(j);
        }
    }

    V<ll> color(N + 1, -1);

    bitset<1000> dp;
    dp[0] = true;

    FOR(i, 1, N) {
        if (color[i] == 2) continue;

        queue<ll> que;
        que.push(i);
        color[i] = 0;

        while (!que.empty()) {
            ll v = que.front();
            que.pop();
            // cout << v << ":" << path[v] << endl;

            for (ll sv : path[v]) {
                if (v == sv) continue;
                if (color[sv] < 0) {
                    color[sv] = 1 - color[v];
                    que.push(sv);
                    continue;
                }

                if (color[sv] == color[v]) {
                    cout << -1 << endl;
                    return;
                }
            }
        }

        V<ll> cnt(2, 0);

        FOR(j, 1, N) {
            if (color[j] >= 0 && color[j] < 2) {
                cnt[color[j]]++;
                color[j] = 2;
            }
        }

        // cout << cnt << endl;

        dp = ((dp << cnt[0]) | (dp << cnt[1]));
    }

    ll ans = sq(N);

    FOR(i, 0, N) {
        if (dp[i]) {
            ans = min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
        }
    }

    cout << ans << endl;
    return;
}

