bool connected(set<int>& s, set<pair<int,int>> edges, int i) {
  for(auto it=s.begin(); it!=s.end(); it++) {
    pair<int,int> p;
    if(*it > i) {
      p = make_pair(i, *it);
    } else {
      p = make_pair(*it, i);
    }

    if(edges.find(p) == edges.end()) {
      return false;
    }
  }
  return true;
}

