int main(){
    int n, m;
    scanf("%d %d", &n, &m);
    vector<vector<int>> vviRoad(n+1, vector<int>(n+1,0));
    for(int i = 0; i < m; i++){
        int a, b;
        scanf("%d %d", &a, &b);
        vviRoad[a][b] = 1;
        vviRoad[b][a] = 1;
    }

    vector<int> viDiffer;    //分離すべき2グループの元の個数の差
    vector<int> viSearch(n+1,0);    //探索状態
    for(int i = 1; i <= n; i++){
        if(viSearch[i] == 1){
            continue;
        }
        vector<int> aviGroup[2];
        queue<int> aqiGroupTmp[2];
        char iCheck = 0;
        aqiGroupTmp[0].push(i);
        viSearch[i] = 1;
        while(!aqiGroupTmp[0].empty() || !aqiGroupTmp[1].empty()){
            if(iCheck == 0){
                int iSeed = aqiGroupTmp[0].front();
                aqiGroupTmp[0].pop();
                for(int j = 1; j <= n; j++){
                    if(viSearch[j] == 1){
                        continue;
                    }
                    if(vviRoad[iSeed][j] == 0){//iSeedとjが道でつながってなければ分離
                        aqiGroupTmp[1].push(j);
                        viSearch[j] = 1;
                    }
                }
                aviGroup[0].push_back(iSeed);
                if(aqiGroupTmp[0].empty()){
                    iCheck = 1;
                }
            }
            else if(iCheck == 1){
                int iSeed = aqiGroupTmp[1].front();
                aqiGroupTmp[1].pop();
                for(int j = 1; j <= n; j++){
                    if(viSearch[j] == 1){
                        continue;
                    }
                    if(vviRoad[iSeed][j] == 0){//iSeedとjが道でつながってなければ分離
                        aqiGroupTmp[0].push(j);
                        viSearch[j] = 1;
                    }
                }
                aviGroup[1].push_back(iSeed);
                if(aqiGroupTmp[1].empty()){
                    iCheck = 0;
                }
            }
        }
        if(!aviGroup[0].empty()){
            for(int j = 0; j < aviGroup[0].size() - 1; j++){
                for(int k = j + 1; k < aviGroup[0].size(); k++){
                    int a = aviGroup[0][j];
