                }
            }
        }
        if(!aviGroup[1].empty()){
            for(int j = 0; j < aviGroup[1].size() - 1; j++){
                for(int k = j + 1; k < aviGroup[1].size(); k++){
                    int a = aviGroup[1][j];
                    int b = aviGroup[1][k];
                    if(vviRoad[a][b] == 0){
                        printf("-1");
                        return 0;
                    }
                }
            }
        }
        int i0 = aviGroup[0].size();
        int i1 = aviGroup[1].size();
        viDiffer.push_back(abs(i1 - i0));
        //分離したグループの元の個数の差を記録
    }

//    DP  viDefferの元の和と差でなるべく0に近づける
    int iNum = viDiffer.size();
    vector<vector<int>> vviDP(iNum, vector<int>(n+1, 0)); //可能な値は高々n
    vviDP[0][viDiffer[0]] = 1;
    for(int i = 1; i < iNum; i++){
        for(int j = 0; j < n+1; j++){
            if(vviDP[i - 1][j] == 1){
                vviDP[i][j + viDiffer[i]] = 1;
                vviDP[i][abs(j - viDiffer[i])] = 1;
            }
        }
    }
    int iDiffer = 0;
    for(; iDiffer < n+1; iDiffer++){
        if(vviDP[iNum-1][iDiffer] == 1){//viDifferの元の和と差で表せる最小値をとる
            break;
        }
    }
    int i = (n + iDiffer) / 2;
    int j = (n - iDiffer) / 2;    //可能な最良の分け方
    printf("%d", (i * (i-1) + j * (j-1)) / 2);

    return 0;
}

