#define fi first
#define se second

const int maxn = 703;

int n, m;
int vs[maxn], col[maxn];
vector<pair<int, int> > has;
vector<int> adj[maxn];
int D[maxn][maxn];
int cnt[2];
int G;

int cmp(pair<int, int> a, pair<int, int> b) {
  if (a.fi > a.se) swap(a.fi, a.se);
  if (b.fi > b.se) swap(b.fi, b.se);
  return a.se - a.fi > b.se - b.fi;
}

void dfs(int u, int co) {
  if (vs[u]) {
    if (col[u] != co) {
      cout << -1;
      exit(0);
    }
    return;
  }
  vs[u] = 1;
  cnt[co]++;
  col[u] = co;
  for (auto v : adj[u]) {
    dfs(v, co ^ 1);
  }
}

