using namespace std;
const int MAXN = 705;

int n, m, cnt, a, b, color[MAXN];
bool del[MAXN], Map[MAXN][MAXN];
queue<int> q;

namespace Graph{
	int ecnt, head[MAXN], nxt[MAXN<<1], to[MAXN<<1];
	inline void init(){
		ecnt = 0;
		memset( head, -1, sizeof head );
	}
	inline void adde( int u, int v ){
		to[++ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt;
		to[++ecnt] = u; nxt[ecnt] = head[v]; head[v] = ecnt;
	}
}

inline bool bfs( int s ){
	using namespace Graph;
	color[s] = 1; q.push(s);
	while( !q.empty() ){
		int u = q.front(); q.pop();
		if( color[u] == 1 ) ++a;
		else ++b;
		for( int i = head[u]; ~i; i = nxt[i] ){
			int v = to[i];
			if( color[v] == color[u] ) return 0;
			if( color[v] == 3 - color[u] ) continue;
			color[v] = 3 - color[u]; q.push(v);
		}
	}
	return 1;
}

int main(){
	scanf( "%d%d", &n, &m );
	Graph::init();
	for( int i = 1; i <= m; ++i ){
		int x, y; scanf( "%d%d", &x, &y );
		Map[x][y] = Map[y][x] = 1;
	}
	for( int i = 1; i <= n; ++i ){
		bool flag = 1;
		for( int j = 1; j <= n; ++j )
			if( i != j && Map[i][j] == 0 ){
				flag = 0; break;
			}
		if(flag) ++cnt, del[i] = 1;
	}
	for( int i = 1; i <= n; ++i ){
		if( del[i] ) continue;
		for( int j = i + 1; j <= n; ++j ){
			if( del[j] || Map[i][j] ) continue;
			Graph::adde( i, j );
		}
	}
	for( int i = 1; i <= n; ++i )
		if( !del[i] && !color[i] && !bfs(i) )
			return puts( "-1" ), 0;
	if( a < b ) swap( a, b );
	int delta = min( a - b, cnt );
	b += delta; cnt -= delta;
	a += cnt >> 1; b += cnt >> 1;
	if( cnt&1 ) ++a;
	int ans = a * (a-1) / 2 + b * (b-1) / 2;
	printf( "%d\n", ans );
	return 0;
}

