pair<int,int> go(int i, int w, int b){
	if(i == op.size())
		return {w, b};
	if(dp.find({i,{w, b}}) != dp.end())
		return dp[{i,{w, b}}];
	pair<int,int> tmp1 = go(i + 1, w + op[i].first, b + op[i].second);
	pair<int,int> tmp2 = go(i + 1, w + op[i].second, b + op[i].first);
	if(abs(tmp1.first - tmp1.second) < abs(tmp2.first - tmp2.second))
		return dp[{i,{w, b}}] = tmp1;
	return dp[{i,{w, b}}] = tmp2;
}

