int n, m;
typedef bitset<704> maskt;
maskt G[704];

//too lazy to write a 1/64 constant... QWQ
int first1(maskt cur)
{
	rep1(i, n) if(cur[i]) return i;
	return -1;
}
int popcnt(maskt cur)
{
	int tot = 0;
	rep1(i, n) if(cur[i]) tot ++;
	return tot;
}
maskt rev(maskt cur, int l)
{
	maskt ret;
	for(int i = 0; i <= l; i ++)
	if(cur[i]) ret[l - i] = true;
	return ret;
}
maskt ori()
{
	maskt ret;
	rep1(i, n) ret[i] = true;
	return ret;
}

maskt solve(maskt lft, maskt s1, maskt s2)
{
	if(popcnt(lft) == 0) return 1;
	if(((s1 | s2) & lft) != lft) return 0;
	if(s1 == s2) {
		int cv = first1(lft);
		lft[cv] = false;
		s1[cv] = false;
		s2[cv] = false;
		bitset<704> ca = solve(lft, s1 & G[cv], s2);
		return (ca << 1) | rev(ca, popcnt(lft));
	} else {
		int cv = first1(s1 ^ s2);
		lft[cv] = false;
		if(s1[cv]) {
			s1[cv] = false;
			return solve(lft, s1 & G[cv], s2) << 1;
		} else {
			s2[cv] = false;
			return solve(lft, s1, s2 & G[cv]);
		}
	}
}

int egcnt(int k)
{
	return k * (k - 1) / 2;
}

