    else B.push_back(u);

    for(int v = 0; v < N; v++) {
        if(u == v) continue;
        if(adj[u][v]) continue;
        if(col[v] != -1) {
            if(col[v] == col[u]) return false;
            continue;
        }
        col[v] = col[u] ^ 1;
        if(!dfs(v)) return false;
    }
    return true;
}

int tot, sum;
