            }
        }

        int a = A.size();
        int b = B.size();
        if(a > b) swap(a, b);
        sum += a;
        V.push_back(b - a);
    }

    dp[0] = 1;
    for(int i = 0; i < V.size(); i++) {
        for(int j = MN * MN - 1; j >= V[i]; j--) {
            dp[j] |= dp[ j - V[i] ];
        }
    }

    int mul = 0;
    for(int i = 0; i < MN * MN; i++) {
        if(dp[i]) {
            int a = sum + i;
            int b = N - a;
            mul = max(mul, a * b);
