pair<int,int> dfs(const vector<vector<int>> &G, int v, vector<int> &C){
  pair<int,int> ret(0,0);
  int c = C[v];
  if(c) ++ret.first;
  else ++ret.second;
  for(int v_ : G[v]){
    if(C[v_] < 0){
      C[v_] = 1-c;
      pair<int,int> p = dfs(G,v_,C);
      if(p.first < 0) return {-1,-1};
      ret.first += p.first;
      ret.second += p.second;
    }else if(C[v_] == c){
      return {-1,-1};
    }
  }
  return ret;
}

