PR partite(int v, int c) {
    if (p[v] != -1) {
        if (p[v] != c) return PR();
        return PR(2, 0);
    }

    p[v] = c;

    PR res(2, 0); res[c] += 1;
    for (int i = 0; i < N; ++i) {
        if (G[v][i] == 1) {
            PR m = partite(i, 1-c);
            if (m.size() == 0) return m;
            res[0] += m[0];
            res[1] += m[1];
        }
    }

    return res;
}


