using ll = long long;

void solve() {
  int n, m;
  cin >> n >> m;
  vector<vector<int>> adj(n);
  {
    vector<vector<bool>> mt(n, vector<bool>(n));
    while (m--) {
      int a, b;
      cin >> a >> b, --a, --b;
      mt[a][b] = mt[b][a] = 1;
    }
    REP(i, n) FOR(j, i + 1, n - 1) if (!mt[i][j]) {
      adj[i].EB(j); 
      adj[j].EB(i); 
    }
  }

  vector<int> vis(n, -1);

  auto bfs = [&](int u) -> pair<int,int> {
    queue<int> q;
    vector<int> cc;
    q.push(u);
    pair<int,int> ans;
    while (!q.empty()){
      u = q.front();
      cc.EB(u);
      q.pop();
      if (vis[u] == 0) ++ans.F;
      else ++ans.S;
      for(int v : adj[u]){
        if (vis[v] == -1){
          vis[v] = vis[u] ^ 1;
          q.push(v);
        } else if (vis[v] == vis[u]){
          return {-1, -1};
        }
      }
    }
    return ans;
  };

  vector<pair<int,int>> comp;
  REP(i, n){
    if (vis[i] == -1){
      vis[i] = 0;
      auto p = bfs(i);
      if (p == make_pair(-1, -1)){
        cout << "-1\n";
        return;
      }
      comp.EB(p);
    }
  }
  int k = comp.size();
  vector<int> cur(n + 1);
  cur[0] = 1;
  for(int i = 1; i <= k; ++i){
    vector<int> nxt(n + 1);
    for(int j = 0; j <= n; ++j){
      for(int x : {comp[i - 1].F, comp[i - 1].S}){
        int f = j - x;
        if (f >= 0 && cur[f]){
          nxt[j] = 1;
        }
      }
    }
    swap(cur, nxt);
  }
  const int INF = 1e9;
  int ans = INF;
  for(int i = 0; i <= n; ++i){
    if (cur[i]){
      ans = min(ans, i * (i - 1)/ 2 + (n - i) * (n - i - 1) / 2);
    }
  }
  cout << ans << "\n";
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  int T = 1;
  // cin >> T;
  while (T--) {
    solve();
  }
}

