    FOR(i, N) {
        vis[i] = vis2[i] = 0;
        FOR(j, N) {
            GC[i][j] = i != j;
            dp[i][j] = -1;
        }
    }
    int a, b;
    FOR(i, M) {
        read(a, b);
        a--; b--;
        edges.eb(a, b);
        GC[a][b] = GC[b][a] = 0;
    }
    FOR(i, N) FOR(j, N) if (GC[i][j]) adjC[i].pb(j);
    FOR(i, N) {
        if (!vis[i]) {
            vis[i] = 1;
            if (!dfs(i)) {
                if (M == N * (N - 1) / 2) writeln(M);
                else writeln(-1);
                return 0;
            }
            CNT.pb(cnt(i));
        }
    }
    writeln(solve(0, 0));
    return 0;
}

