struct unionFind {
    vector<int> data;
    unionFind(int size) {
        for (int i = 0; i < size; i++) {
            data.push_back(i);
        }
    }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if(data[y] < data[x]) {
                swap(x, y);
            }
            //data[x] += data[y];
            data[y] = -1 * data[x];
        }
        return x != y;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        if (data[x] == x) {
            return x;
        }
        if (data[x] > 0) {
            data[x] = root(data[x]);
            return data[x];
        } else {
            data[x] = -1 * root(data[x]);
            return data[x];
        }
    }

    int rank(int x) {
        return -data[root(x)];
    }
};

