};

int V;
vector<edge> G[1000000];
ll d[1000000];

vector<pii> vp;

bool BFS() {
    fill(d, d + V, -1);
    while (true) {
        int num = 0;
        for (int i = num; i < V; i++) {
            if (d[num] == -1) {
                break;
            }
            num++;
        }
        if (d[num] != -1) {
            return true;
        }
        d[num] = 0;
        queue<int> que;
        que.push(num);
        int x = 1;
        int y = 0;
        while (que.size() > 0) {
            int base = que.front();
            que.pop();
            int s = G[base].size();
            for (int i = 0; i < s; i++) {
                int to = G[base][i].to;
                if (d[to] == -1) {
                    if (d[base] == 0) {
                        d[to] = 1;
                        y++;
                    } else {
                        d[to] = 0;
                        x++;
                    }
                    que.push(to);
                } else {
                    if (d[to] == 1 && d[base] == 1) {
                        return false;
                    } else if (d[to] == 0 && d[base] == 0) {
                        return false;
                    }
                }
            }
        }
        vp.push_back(pii(x, y));
    }
}

