				dp[i+1][j+v[i]]=1;
				dp[i+1][j-v[i]]=1;
			}
		}
	}
	int min=1e9;
	rep(i,2*n+1) {
		if(dp[v.size()][i]) min=std::min(min,std::abs(i-z));
	}
	assert((n-min)%2==0);
	int a=(n-min)>>1;
	int b=n-a;
	print(a*(a-1)/2+b*(b-1)/2);
	return 0;
}

