int fun(int p, int rem) {
	if(rem < 0) return -INF;
	if(p == 0) return 0;

	int &memo = dp[p][rem];
	if(memo != -1) return memo;

	return memo = max(fun(p-1, rem), A[p] + fun(p-1, rem-A[p]));
}

