bool hoge(int cur, vector< vector<int> >& g, vector<int>& color) {
    for (int i : g[cur]) {
        if (color[i] == color[cur]) return false;
        if (color[i] == -1) {
            color[i] = !color[cur];
            if (!hoge(i, g, color)) return false;
        }
    }
    return true;
}

bool link[705][705];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        link[a][b] = true;
        link[b][a] = true;
    }

    vector< vector<int> > g(n);
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (!link[i][j]) {
                g[i].push_back(j);
                g[j].push_back(i);
            }
        }
    }

    vector<int> color(n, -1);
    vector<int> dp(n + 1, false);
    dp[0] = true;
    for (int i = 0; i < n; i++) {
        if (color[i] == -1) {
            color[i] = 0;
            if (!hoge(i, g, color)) {
                cout << -1 << endl;
                return 0;
            }

            vector<int> cnt(2, 0);
            for (int j = 0; j < n; j++) {
                if (color[j] <= -1) continue;
                cnt[color[j]]++;
                color[j] = -2;
            }

            for (int j = n; j >= 0; j--) {
                dp[j] = false;
                dp[j] |= (j - cnt[0] >= 0 && dp[j - cnt[0]]);
                dp[j] |= (j - cnt[1] >= 0 && dp[j - cnt[1]]);
            }
        }
    }

    int ans = m;
    for (int i = 1; i <= n; i++) {
        if (!dp[i]) continue;
        ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2 );
    }

    cout << ans << endl;
    return 0;
}

