bool graph[705][705];
int color[705];
int n, m;

int count0, count1;
bool feasible;

int candidates[705][2];
int ccnt;

void visit(int x, int c) {
  if (color[x] != -1) {
    if (color[x] != c) feasible = false;
    return;
  }
  color[x] = c;
  if (c == 0) count0++;
  else count1++;
  for (int ni = 1; ni <= n; ni++) {
    if (x != ni && graph[x][ni]) {
      if (color[ni] == -1) visit(ni, 1 - c);
      else if (color[ni] == c) {
        feasible = false;
        return;
      }
    }
  }
}

int main() {
  cin >> n >> m;
  for (int ni = 1; ni <= n; ni++) {
    for (int nj = 1; nj <= n; nj++) {
      graph[ni][nj] = true;
    }
    color[ni] = -1;
  }
  for (int mi = 0; mi < m; mi++) {
    int a, b;
    cin >> a >> b;
    graph[a][b] = graph[b][a] = false;
  }
  feasible = true;
  ccnt = 0;
  for (int ni = 1; ni <= n; ni++) {
    if (color[ni] == -1) {
      count0 = 0;
      count1 = 0;
      visit(ni, 0);
      candidates[ccnt][0] = count0;
      candidates[ccnt][1] = count1;
      ccnt++;
    }
  }
  if (feasible) {
    bool x[2][705];
    for (int i = 0; i < 2; i++) {
      for (int ni = 0; ni <= n; ni++) {
        x[i][ni] = false;
      }
    }
    x[0][0] = true;
    for (int ci = 0; ci < ccnt; ci++) {
      int cur = ci % 2;
      int nxt = 1 - cur;
      for (int ni = 0; ni <= n; ni++) {
        x[nxt][ni] = false;
      }
      for (int ni = 0; ni <= n; ni++) {
        if (x[cur][ni]) {
          x[nxt][ni + candidates[ci][0]] = true;
          x[nxt][ni + candidates[ci][1]] = true;
        }
      }
    }
    int answer = 987654321;
    for (int ni = 0; ni <= n; ni++) {
      if (x[ccnt % 2][ni]) {
        answer = min(answer, ni * (ni - 1) / 2 + (n - ni) * (n - ni - 1) / 2);
      }
    }
    cout << answer << endl;
  } else {
    cout << -1 << endl;
  }
  return 0;
}

