int N,M,C[3]; bitset<707> can;
bool chk[707][707]; int col[707];

void go(int x)
{
	C[col[x]]++;
	for (int y=1;y<=N;y++) if (!chk[x][y]){
		if (col[y]){
			if (col[x] + col[y] != 3){
				puts("-1");
				exit(0);
			}
		}
		else{
			col[y] = 3 - col[x];
			go(y);
		}
	}
}

int main()
{
	scanf ("%d %d",&N,&M);
	for (int i=1;i<=N;i++) chk[i][i] = 1;
	for (int i=0;i<M;i++){
		int x,y; scanf ("%d %d",&x,&y);
		chk[x][y] = chk[y][x] = 1;
	}

	can[0] = 1;
	for (int i=1;i<=N;i++) if (!col[i]){
		C[1] = C[2] = 0;
		col[i] = 1, go(i);
		can = (can << C[1]) | (can << C[2]);
	}

	int ans = N * (N - 1) / 2;
	for (int i=0;i<=N;i++) if (can[i]){
		int now = i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2;
		if (ans > now)
			ans = now;
	}

	printf ("%d\n",ans);
	return 0;
}

