#include <iostream>
#include <bitset>

const int inf = 1e9;
const int N = 700;
bool edge[N][N];
int group[N];
int gs[N];
std::bitset<N+1> cans;
int n;

bool dfs(int i, int g) {
	if (group[i] != -1) {
		if (group[i] == (g ^ 1)) return false;
		return true;
	}
	group[i] = g;
	++gs[g];
	for (int t = 0; t < n; ++t) {
		if (i == t) continue;
		if (! edge[i][t]) {
			if (!dfs(t, g^1)) return false;
		}
	}
	return true;
}

int main() {
	int m;
	std::cin >> n;
	std::cin >> m;
	for (int i = 0; i < n; ++i) edge[i][i];
	for (int i = 0; i < m; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		edge[a][b] = true;
		edge[b][a] = true;
	}
	for (int i = 0; i < n; ++i) group[i] = -1;

	bool fail = false;
	int gc = 0;
	for (int i = 0; i < n; ++i) {
		if (group[i] == -1) {
			fail |= ! dfs(i, 2 * gc);
			++gc;
		}
	}
	if (fail) {
		std::cout << -1 << '\n';
	} else {
		for (int i = 0; i <= n; ++i) cans[i] = 0;
		cans[0] = 1;

		for (int j = 0; j < gc; ++j) {
			cans = ((cans << gs[2*j]) | (cans << gs[2*j+1]));
		}
		int min_ans = inf;
		for (int i = 0; i <= n; ++i) {
			if (cans[i]) {
				min_ans = std::min(min_ans, std::max(0, i*(i-1)/2) + std::max(0, (n-i) * (n-i-1)/2));
			}
		}
		std::cout << min_ans << '\n';
	}
}

