int main() {
    ll N, M;
    cin >> N>>M;
    vector<vector<ll>> gmat(N + 1, vector<ll>(N + 1, 0));

    repn(i, M) {
        ll a, b;
        cin >> a >> b;
        gmat[a][b] = 1;
        gmat[b][a] = 1;
    }
    repn(i, N) gmat[i][i] = 1;

    vector<vector<ll>> g(N + 1);

    repn(i, N)repn(j, N) {
        if (gmat[i][j] == 0) {
            //cout << i << j << endl;
            g[i].push_back(j);
        }
    }

    vector<ll> col(N + 1, -1);
    vector<ll> zero;
    vector<ll> one;
    ll b = 1;

    repn(v, N) {
        if (col[v] != -1) { continue; }

        col[v] = 0;
        ll num[2] = { 1,0 };
        queue<ll> q;
        q.push(v);

        while (!q.empty()) {
            ll w = q.front();
            q.pop();
            ll i = (col[w] + 1) % 2;
            for (ll u : g[w]) {
                if (col[u] == -1) {
                    col[u] = i;
                    num[i]++;
                    q.push(u);
                }
                else {
                    if (col[u] != i) { b = 0;}
                }
            }
        }

        zero.push_back(num[0]);
        one.push_back(num[1]);

    }

    if (b == 0) { cout << -1; }
    else {
        ll M = zero.size();
        vector<vector<ll>> dp(M + 1, vector<ll>(N + 1, 0));
        dp[0][0] = 1;

        repn(i, M)repn(j, N) {
            if (j >= zero[i - 1] && dp[i - 1][j - zero[i - 1]] == 1) { dp[i][j] = 1; }
            if (j >= one[i - 1] && dp[i - 1][j - one[i - 1]] == 1) { dp[i][j] = 1; }
        }

        ll ans = INF;

        rep(i, N+1) {
            if (dp[M][i] == 1) {
                ans = min(i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2, ans);
            }
        }

        cout << ans;
    }


	system("PAUSE");
}

