int main(){

  n = in();
  m = in();
  REP(i, n){
    REP(j, i){
      G[i][j] = G[j][i] = 1;
    }
  }
  REP(i, m){
    int a = in() - 1;
    int b = in() - 1;
    G[a][b] = G[b][a] = 0;
  }

  REP(i, n){
    col[i] = -1;
  }

  vector<P> cs(0);
  REP(i, n){
    if(col[i] == -1){
      cnt[0] = cnt[1] = 0;
      dfs(i, 0);
      cs.pb(cnt[0], cnt[1]);
      // cout << cs.back() << endl;
    }
  }

  dp[0][0] = true;
  REP(i, SZ(cs)){
    REP(j, n+1){
      if(dp[i][j]){
        dp[i+1][j+cs[i].fi] = true;
        dp[i+1][j+cs[i].se] = true;
      }
    }
  }

  ll ans = INFLL;
  REP(i, n+1){
    if(dp[SZ(cs)][i]){
      chmin(ans, i * (i-1) / 2 + (n-i) * (n-i-1) / 2);
    }
  }

