bool dfs(int u, int c) {
    color[u] = c;
    parts[c].emplace_back(u);
    for (int v = 0; v < V; v++) if (v != u && mat[u][v]) {
        if (~color[v]) {
            if (color[v] == color[u]) return false;
        } else {
            if (!dfs(v, c ^ 1)) return false;
        }
    }
    return true;
}

bool is_bipartite() {
    color.assign(V, -1);
    parts.clear(); parts.resize(2);
    for (int u = 0; u < V; u++) if (!~color[u]) {
        if (!dfs(u, 0)) return false;
        ab.emplace_back(parts[0].size(), parts[1].size());
        parts.clear(); parts.resize(2);
    }
    return true;
}

int main() {
    int E; cin >> V >> E;
    mat.assign(V, vector<int>(V, 1));
    for (int i = 0; i < E; i++) {
        int a, b; cin >> a >> b; a--; b--;
        mat[a][b] = mat[b][a] = 0;
    }
    if (!is_bipartite()) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> dp(V * 2 + 1, false);
    dp[0] = true;
    for (auto &p: ab) {
        for (int j = V; j >= 0; j--) if (dp[j]) {
            dp[j] = false;
            dp[j + p.first] = dp[j + p.second] = true;
        }
    }
    int idx = -1;
    for (int j = 0; j <= V; j++) if (dp[j]) {
        if (abs(idx - V / 2) > abs(j - V / 2)) idx = j;
    }
    int a = idx, b = V - idx;
    int res = a * (a - 1) / 2 + b * (b - 1) / 2;
    cout << res << endl;
    return 0;
}

