struct UnionFind {
    vector<int> data;

    UnionFind(int size) : data(size, -1) {}

    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }

    bool findSet(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    int size(int x) {
        return -data[root(x)];
    }
};

int g[700][700] = {};

void solve(ll N, ll M, vector<ll> A, vector<ll> B) {
    for (int i = 0; i < 700; i++) g[i][i] = 1;
    for (int i = 0; i < A.size(); i++) {
        A[i]--;
        B[i]--;
        g[A[i]][B[i]] = g[B[i]][A[i]] = 1;
    }
    UnionFind uf(N);
    for (int i = 0; i < N; i++) {
        bool flg = true;
        vector<int> items;
        for (int j = 0; j < N; j++) {
            if (g[i][j] == 0) items.push_back(j);
        }
        for (auto x : items) {
            uf.unionSet(items[0], x);
        }
    }

    bitset<1000> dp;
    dp[0] = 1;
    for (int i = 0; i < N; i++) {
        if (uf.root(i) != i) continue;

        vector<int> items;

        for (int j = 0; j < N; j++) {
            if (i == uf.root(j)) {
                items.push_back(j);
            }
        }
        bool f = true;
        for (auto &&x : items) {
            for (auto &&y : items) {
                if (g[x][y] == 0) f = false;
            }
            if (!f) break;
        }
        if (!f) {
            cout << "-1" << endl;
            return;
        }
        dp = dp | (dp << items.size());
    }

    int ans = 1e9;
    for (int i = 0; i <= N; i++) {
        if (dp[i]) {
            ans = min<int>(ans, i * (i - 1) + (N - i) * (N - i - 1));
        }
    }
    cout << ans / 2 << endl;
}


void main_(istream &cin) {
    ll N;
    ll M;
    cin >> N;
    cin >> M;
    vector<ll> A(M - 1 + 1);
    vector<ll> B(M - 1 + 1);
    for (int i = 0; i <= M - 1; i++) {
        cin >> A[i];
        cin >> B[i];
    }
    solve(N, M, A, B);
}

