void DFS(int u){
	sum += vis[u];
	for (int i = 1; i <= a[u][0]; ++i){
		int v = a[u][i];
		if (vis[v] == 0){
			vis[v] = -vis[u];
			DFS(v);
		}
		else if (vis[u] == vis[1]){
			puts("-1");
			exit(0);
		}
	}
