vector<pair<int, int>> BipartiteGraph(const VVI& graph) {
	int V = graph.size(), cnt1 = 0, cnt2 = 0;
	vector<int> flag(V);
	function<bool(int, int)> dfs = [&](int v, int c) {
		flag[v] = c;
		cnt1 += c == 1;
		cnt2 += c == -1;
		for (auto e : graph[v]) {
			if (flag[e] == c)return false;
			if (flag[e] == 0 && !dfs(e, -c))return false;
		}
		return true;
	};
	vector<pair<int, int>> x;
	for (int i = 0; i < V; i++) {
		if (flag[i] == 0) {
			if (!dfs(i, 1))return {};
			x.emplace_back(cnt1, cnt2);
			cnt1 = 0; cnt2 = 0;
		}
	}
	return x;
}

