class BipartiteGraph{
public:
    vector<vector<ll>> G; // グラフ
    ll N; // 頂点数
    vector<int> color; // 頂点iの色(1 or -1);

    vector<ll> lv,rv;
    BipartiteGraph(int _N):N(_N){ G.resize(N); color.resize(N,0); }
    BipartiteGraph(ll _N):N(_N){ G.resize(N); color.resize(N,0); }

    void init(ll _N){
        N = _N;
        G.clear(); color.clear();
        G.resize(N); color.resize(N,0);
    }

    void add_edge(ll u,ll v){
        G[u].push_back(v);
        G[v].push_back(u);
    }

    bool dfs(ll v,int c){
        color[v] = c; // 頂点vをcで塗る
        for(int i = 0; i < G[v].size(); i++){
            // 隣接している頂点が同じ色ならfalse
            if(color[G[v][i]] == c) return false;
            // 隣接している頂点がまだ塗られていないなら-cで塗る
            if(color[G[v][i]] == 0 && !dfs(G[v][i],-c)) return false;
        }
        // すべての頂点を濡れたらtrue
        return true;
    }

    bool build(){
        for(int i = 0; i < N;i++){
            if(color[i] == 0){
                // まだ頂点iが塗られていなければ1で塗る
                if(!dfs(i,1)) return false;
            }
        }
        return true;
    }

    void make(){
        for(int i = 0; i < N;i++){
            if(color[i] == 1) lv.push_back(i);
            if(color[i] == -1) rv.push_back(i);
        }
    }
};

ll solve(){
    ll res = 0;
    int N,M; cin >> N >> M;
    vector<int> A(M),B(M); for(int i = 0; i < M;i++) cin >> A[i] >> B[i];

    vector<vector<int>> G(N,vector<int>(N,0));
    for(int i = 0; i < M;i++){
        A[i]--; B[i]--;
        G[A[i]][B[i]] = G[B[i]][A[i]] = 1;
    }

    BipartiteGraph BG(N);
    for(int i = 0; i < N;i++){
        for(int j = i+1; j < N;j++){
            if(G[i][j] == 0){
                BG.add_edge(i, j);
            }
        }
    }

    if(!BG.build()) return -1;
    BG.make();

    for(int i = 0; i < M;i++){
        if(BG.color[A[i]] == BG.color[B[i]]) res++;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

