int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, m; std::cin >> n >> m;
  auto adj = make_vector<2,int>(n,n,0);
  loop(m) {
    int u, v; std::cin >> u >> v;
    u--,v--;
    if (u > v) std::swap(u,v);
    at(adj,u,v) = 1;
  }
  std::vector<std::vector<int>> graph(n);
  rep(i,0,n) rep(j,i+1,n) {
    if (at(adj,i,j)) continue;
    graph.at(i).emplace_back(j);
    graph.at(j).emplace_back(i);
  }
  debug(graph);

  std::vector<int> par(n,-1);
  auto dfs = [&] (auto&& dfs, int x, int px, std::vector<int>& sz) -> void {
    sz.at(px)++;
    debug(x,sz);
    for (int y : graph.at(x)) {
      int& py = par.at(y);
      if (py != -1) {
        require(px!=py);
        continue;
      }
      py = !px;
      dfs(dfs,y,py,sz);
    }
  };
  std::vector<int> dp(n+1,false);
  dp.at(0) = true;
  rep(i,0,n) {
    if (par.at(i)!=-1)continue;
    std::vector<int> sz(2);
    par.at(i) = 0;
    dfs(dfs,i,0,sz);
    debug(sz);
    for (int i = n; i >= 0; i--) {
      for (int x : sz) {
        if (i+x<=n) {
          dp.at(i+x) |= dp.at(i);
        }
      }
      if (sz.at(0)!=0 && sz.at(1)!=0) {
        dp.at(i) = false;
      }
    }
  }
  debug(par);
  debug(dp);

  auto tri = [&] (lint k) {
    return k * (k - 1) / 2;
  };
  lint ans = tri(n);
  rep(i,0,n+1) {
    if (!dp.at(i)) continue;
    lint now = tri(i) + tri(n-i);
    debug(now);
    cmn(ans,now);
  }
  std::cout << ans << std::endl;
  return 0;
}

