template<class T>
void read(T &res) {
    res = 0;T f = 1;char c = getchar();
    while(c < '0' || c > '9') {
	if(c == '-') f = -1;
	c = getchar();
    }
    while(c >= '0' && c <= '9') {
	res = res * 10 + c - '0';
	c = getchar();
    }
    res *= f;
}
template<class T>
void out(T x) {
    if(x < 0) {x = -x;putchar('-');}
    if(x >= 10) out(x / 10);
    putchar('0' + x % 10);
}
int N,M;
int g[705][705];
struct node {
    int to,next;
}E[1000005];
int sumE,head[705],tot,col[705],que[705],qr;
pii conn[705];
bool f[2][705];
void add(int u,int v) {
    E[++sumE].next = head[u];
    E[sumE].to = v;
    head[u] = sumE;
}
bool dfs(int u) {
    if(col[u] == -1) col[u] = 0;
    que[++qr] = u;
    for(int i = head[u] ; i ; i = E[i].next) {
	int v = E[i].to;
	if(col[v] == col[u]) return false;
	else if(col[v] == -1) {
	    col[v] = col[u] ^ 1;
	    if(!dfs(v)) return false;
	}
    }
    return true;
}
void Solve() {
    read(N);read(M);
    int u,v;
    for(int i = 1 ; i <= M ; ++i) {
	read(u);read(v);
	g[u][v] = g[v][u] = 1;
    }
    for(int i = 1 ; i <= N ; ++i) {
	for(int j = i + 1 ; j <= N ; ++j) {
	    if(!g[i][j]) {add(i,j);add(j,i);}
	}
    }
    memset(col,-1,sizeof(col));
    for(int i = 1 ; i <= N ; ++i) {
	if(col[i] == -1) {
	    qr = 0;
	    if(!dfs(i)) {puts("-1");return;}
	    int cnt[2] = {0,0};
	    for(int j = 1 ; j <= qr ; ++j) cnt[col[que[j]]]++;
	    conn[++tot] = mp(cnt[0],cnt[1]);
	}
    }
    int cur = 0;
    f[0][0] = 1;
    for(int i = 1 ; i <= tot ; ++i) {
	memset(f[cur ^ 1],0,sizeof(f[cur ^ 1]));
	for(int j = N ; j >= 0 ; --j) {
	    if(j >= conn[i].fi) f[cur ^ 1][j] |= f[cur][j - conn[i].fi];
	    if(j >= conn[i].se) f[cur ^ 1][j] |= f[cur][j - conn[i].se];
	}
	cur ^= 1;
    }
    int ans = N * N;
    for(int i = 0 ; i <= N ; ++i) {
	if(f[cur][i]) {
	    ans = min(i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2,ans);
	}
    }
    out(ans);enter;
}
int main() {
