const int N = 705;

vector <int> G[N];
int a[N][N], dp[N];
int color[N];
int B, W;
queue <int> q;

bool bfs(int x){
	int u, v;
	B = W = 0;
	q.push(x);
	color[x] = 1;
	while (!q.empty()){
		u = q.front(); q.pop();
		if (color[u] == 1) B++;
		else W++;
		for (int i = 0; i < (int)G[u].size(); i++){
			v = G[u][i];
			if (color[v] == color[u]) return false;
			else if (color[v] == -1){
				q.push(v);
				color[v] = 3 - color[u];
			}
		}
	}
	return true;
}

int main(){
	int n, m, u, v, cnt, ans;
	scanf("%d %d",&n,&m);
	for (int i = 1; i <= n; i++){
		for (int j = 1; j <= n; j++){
			if (i == j) a[i][j] = 0;
			else a[i][j] = 1;
		}
	}
	for (int i = 1; i <= m; i++){
		scanf("%d %d",&u,&v);
		a[u][v] = 0;
		a[v][u] = 0;
	}
	cnt = 0;
	for (int i = 1; i <= n; i++){
		for (int j = 1; j <= n; j++){
			if (a[i][j]){
				G[i].push_back(j);
				if (i < j) cnt++;
			}
		}
	}
	memset(color, -1, sizeof(color));
	memset(dp, 0, sizeof(dp));
	dp[0] = dp[n] = 1;
	for (int i = 1; i <= n; i++){
		if (color[i] == -1){
			if (!bfs(i)){
				printf("-1\n");
				return 0;
			}
			for (int j = n; j >= 1; j--){
				if (j >= B) dp[j] |= dp[j - B];
				if (j >= W) dp[j] |= dp[j - W];
			}
		}
	}
	ans = 1e9;
	for (int i = 0; i <= n; i++){
		if (dp[i]) ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	}
	printf("%d\n", ans);
	return 0;
}

