const int MAXN = 712;
int par[MAXN];
int msize[MAXN];
int gpar(int n){
    if(par[n] == n)return n;
    return par[n] = gpar(par[n]);
}

bool adjm[MAXN][MAXN];
vi forbidden[MAXN];
bool fail;
void resolve(int n){
    if(gpar(n) != n || fail)return;
    bool merged = false;
    int id = -1;
    for(auto to: forbidden[n]){
        to = gpar(to);
        if(to == n)fail = true;
        else if(id == -1)id = to;
        else if(id != to){
            merged = true;
            msize[id] += msize[to];
            msize[to] = 0;
            par[to] = id;
            for(auto it: forbidden[to])forbidden[id].push_back(it);
            forbidden[to].clear();
        }
    }
    forbidden[n].clear();
    if(id != -1)forbidden[n].push_back(id);
    if(merged)resolve(id);
}

bool dp[MAXN];

int main(){
    int N,M;
    mscanf("%d%d",&N,&M);
    FOR(i,0,N)FOR(j,0,N)adjm[i][j] = (i==j);
    FOR(i,0,M){
        int a,b;
        mscanf("%d%d",&a,&b);
        --a;--b;
        adjm[a][b] = adjm[b][a] = 1;
    }
    FOR(i,0,N)forbidden[i].clear();
    FOR(i,0,N)FOR(j,0,N)if(!adjm[i][j])forbidden[i].push_back(j);
    FOR(i,0,N)par[i] = i;
    FOR(i,0,N)msize[i] = 1;
    fail = false;
    FOR(i,0,N)resolve(i);
    if(fail){
        cout << -1 << endl;
    } else {
        int NH = N/2+1;
        FOR(j,0,NH)dp[j] = false;
        dp[0] = true;
        FOR(n,0,N)if(gpar(n) == n){
            assert(sz(forbidden[n]) <= 1);
            if(sz(forbidden[n]) == 1){
                assert(forbidden[n][0] != n);
                assert(sz(forbidden[forbidden[n][0]]) == 1);
                assert(forbidden[forbidden[n][0]][0] == n);
                if(n > forbidden[n][0])continue;
            }
            if(sz(forbidden[n]) == 1){
                int s1 = msize[n], s2 = msize[forbidden[n][0]];
                FORD(j,0,NH)dp[j] = (((j>=s1)?dp[j-s1]:false) | ((j>=s2)?dp[j-s2]:false));
            } else {
                assert(sz(forbidden[n]) == 0);
                int s = msize[n];
                FORD(j,0,NH)dp[j] = (dp[j] | ((j>=s)?dp[j-s]:false));
            }
        }
        --NH;
        while(!dp[NH])--NH;
        cout << NH << endl;
        int nH = N - NH;
        cout << ((NH * (NH-1)) + (nH * (nH-1)))/2 << endl;
    }
	return 0;
}

