	}
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j < i; ++j)
			if(!E[i][j]) add(i, j);
	for(int i = 1; i <= n; ++i)
		if(!vis[i])
		{
			++tot;
			if(!dfs(i, 0)) { puts("-1"); return 0; }
		}
	f[0] = 1;
	for(int i = 1; i <= tot; ++i) f = (f << a[i]) | (f << b[i]);
