struct UnionFind {
	const int V;
	// par[x] := xのroot
	vector<int> par;
	// sz[x] := xを含む集合のサイズ
	vector<int> sz;
	UnionFind(const int V) :
		V(V),
		par(vector<int>(V)),
		sz(vector<int>(V, 1))
		{
			for(int i = 0; i < V; ++i) par[i] = i;
		}
	bool unite(int x, int y) {
		x = root(x), y = root(y);
		if(same(x, y)) return false;
		if(y < x) swap(x, y);
		par[y] = x;
		sz[x] += sz[y];
		return true;
	}
	int root(int x) {
		if(par[x] == x) return x;
		return (par[x] = root(par[x]));
	}
	bool same(int x, int y) {
		return (root(x) == root(y));
	}
	int size(int x) {
		return sz[root(x)];
	}
};

struct BipartiteGraph {
	struct Edge {
		const int from;
		const int to;
		Edge(const int from, const int to) :
			from(from),
			to(to)
			{}
	};
	const int V;
	vector<vector<Edge>> G;
	vector<int> color;
	BipartiteGraph(const int V) :
		V(V),
		G(vector<vector<Edge>>(V, vector<Edge>())),
		color(vector<int>(V, -1))
		{}
	void addEdge(const int from, const int to) {
		G[from].emplace_back(from, to);
		G[to].emplace_back(to, from);
	}
	bool dfs(const int from, const int col) {
		color[from] = col;
		bool ret = true;
		for(Edge e : G[from]) {
			if(color[e.to] == -1) {
				ret &= dfs(e.to, col ^ 1);
			}
			if(color[e.to] == col) {
				return false;
			}
		}
		return ret;
	}
	int bipart() {
		if(not dfs(0, 0)) throw "NOT Bipartite Graph";
		int ret = 0;
		for(int i : color) ret += i;
		return ret;
	}
};

int main() {
	int n, m; cin >> n >> m;
	bool g[n][n] = {};
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < n; ++j) {
			if(i == j) continue;
			g[i][j] = true;
		}
	}
	while(m--) {
		int a, b; cin >> a >> b;
		--a; --b;
		g[a][b] = g[b][a] = false;
	}
	UnionFind uf(n);
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < n; ++j) {
			if(g[i][j]) {
				uf.unite(i, j);
			}
		}
	}
	set<int> v[n];
	for(int i = 0; i < n; ++i) {
		v[uf.root(i)].insert(i);
	}
	set<int> S = {0};
	for(int i = 0; i < n; ++i) {
		int nn = v[i].size();
		if(nn == 0) continue;
		map<int, int> mp;
		int cnt = 0;
		for(int x : v[i]) {
			mp[x] = cnt;
			++cnt;
		}
		BipartiteGraph bg(nn);
		for(int x : v[i]) {
			for(int y : v[i]) {
				if(g[x][y]) {
					bg.addEdge(mp[x], mp[y]);
				}
			}
		}
		try {
			int s = bg.bipart();
			set<int> tmp;
			for(int ss : S) {
				tmp.insert(s + ss);
			}
			S = tmp;
		}
		catch(...) {
			cout << -1 << '\n';
			return 0;
		}
	}
	int ans = 1e9;
	for(int s : S) {
		int t = n - s;
		int tmp = s * (s - 1) / 2 + t * (t - 1) / 2;
		ans = min(ans, tmp);
	}
	cout << ans << '\n';
	return 0;
}

