vi E[707];
int vis[707], col[707];
pii dfs(int cu, int co = 0) {
	vis[cu] = 1;
	col[cu] = co;
	pii res = { 0,0 };
	if (co == 0)res.first++;
	else res.second++;

	for (auto to : E[cu]) {
		if (vis[to]) {
			if (col[to] == co)return { -1,-1 };
		}
		else {
			auto p = dfs(to, 1 - co);
			if (p.first < 0)return{ -1,-1 };
			res.first += p.first;
			res.second += p.second;
		}
	}
	return res;
}

