const int N = 709;

int g[N][N];
bool was[N];
int q[N];
int color[N];
int f[N][N];

int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  memset(g, 0, sizeof g);
  for (int i = 0; i < m; ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x;
    --y;
    g[x][y] = 1;
    g[y][x] = 1;
  }
  memset(was, false, sizeof was);
  int cnt = 0;
  bool good = true;
  for (int i = 0; i < n; ++i) {
    if (was[i]) {
      continue;
    }
    ++cnt;
    was[i] = true;
    q[0] = i;
    int edges = 0;
    int qt = 1;
    for (int qh = 0; qh < qt; ++qh) {
      int x = q[qh];
      for (int y = 0; y < n; ++y) {
        if (g[x][y] == 0) {
          continue;
        }
        ++edges;
        if (!was[y]) {
          was[y] = true;
          q[qt++] = y;
        }
      }
    }
    if (edges != qt * (qt - 1)) {
      good = false;
    }
  }
  if (cnt >= 3) {
    puts("-1");
    return 0;
  }
  if (cnt == 2) {
    printf("%d\n", good ? m : -1);
    return 0;
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      if (j != i) {
        g[i][j] = 1 - g[i][j];
      }
    }
  }
  memset(color, -1, sizeof color);
  vector<int> a, b;
  for (int i = 0; i < n; ++i) {
    if (color[i] != -1) {
      continue;
    }
    color[i] = 0;
    q[0] = i;
    int cnt0 = 0;
    int qt = 1;
    for (int qh = 0; qh < qt; ++qh) {
      int x = q[qh];
      if (color[x] == 0) {
        ++cnt0;
      }
      for (int y = 0; y < n; ++y) {
        if (g[x][y] == 0) {
          continue;
        }
        if (color[y] == -1) {
          color[y] = 1 - color[x];
          q[qt++] = y;
        } else
        if (color[y] == color[x]) {
          puts("-1");
          return 0;
        }
      }
    }
    a.push_back(cnt0);
    b.push_back(qt - cnt0);
  }
  const int inf = 1'000'000'000;
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= n; ++j) {
      f[i][j] = inf;
    }
  }
  f[0][0] = 0;
  int s = 0;
  for (int i = 0; i < (int)a.size(); ++i) {
    int va = a[i] * (a[i] - 1) / 2;
    int vb = b[i] * (b[i] - 1) / 2;
    for (int j = 0; j <= n; ++j) {
      if (j + a[i] <= n) {
        f[i + 1][j + a[i]] = min(f[i + 1][j + a[i]], f[i][j] + j * a[i] + (s - j) * b[i] + va + vb);
      }
      if (j + b[i] <= n) {
        f[i + 1][j + b[i]] = min(f[i + 1][j + b[i]], f[i][j] + j * b[i] + (s - j) * a[i] + va + vb);
      }
    }
    s += a[i] + b[i];
  }
  int ans = inf;
  for (int i = 0; i <= n; ++i) {
    ans = min(ans, f[(int)a.size()][i]);
  }
  printf("%d\n", ans);
}

