int solve() {
    for (int i = 0; i < m; i++) {
        G[a[i]].insert(b[i]);
        G[b[i]].insert(a[i]);
    }
    int num_e = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j != i && G[i].count(j) == 0) {
                H[i].push_back(j);
                num_e++;
            }
        }
    }
    num_e /= 2;

    vector<P> vec;
    memset(color, -1, sizeof(color));
    for (int i = 0; i < n; i++) {
        if (color[i] < 0) {
            temp[0] = temp[1] = 0;
            if (!dfs(i, 0))
                return -1;
            vec.push_back(make_pair(temp[0], temp[1]));
        }
    }

    bool c[n+1];
    memset(c, false, sizeof(c));
    c[0] = true;
    for (P p : vec) {
        for (int i = n; i >= 0; i--) {
            if (c[i]) {
                c[i] = false;
                c[i+p.first] = true;
                c[i+p.second] = true;
            }
        }
    }

    int res = inf;
    for (int i = 1; i < n; i++) {
        if (c[i]) {
            res = min(res, m - (i * (n - i) - num_e));
        }
    }
    return res;
}

