namespace union_find {
  int parent[MAX_N];
  int rank[MAX_N];
  void init()
  {
    for (int i = 0; i < n; i++) {
      parent[i] = i;
      rank[i] = 0;
    }
  }

  int find(int a)
  {
    if (parent[a] == a) return a;
    return parent[a] = find(parent[a]);
  }

  void merge(int a, int b)
  {
    a = find(a);
    b = find(b);

    if (a == b) return;
    if (rank[a] < rank[b]) {
      parent[a] = b;
    } else {
      parent[b] = a;
      if (rank[a] == rank[b])
        rank[a]++;
    }
  }
}

bool dfs(int v, int p, int c)
