	for(int i=1; i<=N; ++i) {
		if (c[i]==0) {
			c[i]=1;
			dfs(i);
			if (cnt[1]<cnt[2]) swap(cnt[1],cnt[2]);
			ans+=cnt[2];
			if (cnt[1]!=cnt[2])
			a[++ca]=cnt[1]-cnt[2];
		}
	}
	f[0]=true;
	for(int i=1; i<=ca; ++i) {
		for(int j=N; j>=a[i]; --j) {
			if (f[j-a[i]]) f[j]=true;
		}
	}
	int mn=9999999;
	for(int i=0; i<=N; ++i) {
		if (f[i]) {
			int t=ans+i,t2=N-t;
			mn=min(mn,t*(t-1)/2+t2*(t2-1)/2);
		}
	}
	cout<<mn<<endl;
}

