const int N = 7e2 + 10, MOD = 1e9 + 7, LOG = 21;

int dp[N][N], n, res, m, fr, to, c[N], cs[N], sz, cmp[N], in[N];
bool mtrx[N][N], vis[N];
vector<vector<int> > g(N), org(N);
vector<int> items;

int DFS(int u, int p, int clr, int comp) {
	cmp[u] = comp;
	vis[u] = true;
	c[u] = clr;
	sz++;
	int cur = clr;
	for (int i = 0; i < g[u].size(); i++) {
		if (!vis[g[u][i]]) {
			cur += DFS(g[u][i], u, !clr, comp);
		} else {
			if (clr == c[g[u][i]] && p != g[u][i]) {
				printf("-1");
				exit(0);
			}
		}
	}
	return cur;
}

int calc(int ind, int sum1) {
	if (ind == items.size())
		return 0;
	int &ret = dp[ind][sum1];
	if (ret != -1)
		return ret;
	int prevNodes = cs[ind];
	int prev1 = sum1;
	int prev0 = prevNodes - prev1;
	int oneCnt1 = items[ind];
	int zeroCnt1 = cs[ind + 1] - cs[ind] - items[ind];
	int oneCnt2 = zeroCnt1;
	int zeroCnt2 = oneCnt1;

	return ret = (in[ind + 1] / 2)
			+ max(
					zeroCnt1 * prev1 + oneCnt1 * prev0
							+ calc(ind + 1, oneCnt1 + sum1),
					zeroCnt2 * prev1 + oneCnt2 * prev0
							+ calc(ind + 1, oneCnt2 + sum1));
}

int main() {
	//freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);
	memset(dp, -1, sizeof(dp));
	scanf("%d%d", &n, &m);
	for (int i = 0; i < m; i++) {
		scanf("%d%d", &fr, &to);
		fr--, to--;
		mtrx[fr][to] = mtrx[to][fr] = true;
		org[fr].push_back(to);
		org[to].push_back(fr);
	}
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++) {
			if (!mtrx[i][j] && i != j)
				g[i].push_back(j);
		}
	int ind = 1;
	for (int i = 0; i < n; i++) {
		if (!vis[i]) {
			res = 0;
			sz = 0;
			items.push_back(DFS(i, -1, 0, ind));
			cs[ind] = cs[ind - 1] + sz;
			ind++;
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < org[i].size(); j++) {
			if (cmp[i] == cmp[org[i][j]])
				in[cmp[i]] += (c[org[i][j]] != c[i]);
		}
	}
	cout << m - calc(0, 0);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int N, M;
vector<vector<int>> E;
vector<int> color;
vector<pair<int,int>> A;
vector<map<int,int>> memo;
bool f(int p, int c, int& n1, int& n2) {
	color[p] = c;
	if (c == 1) ++ n1; else ++ n2;
	for (auto& x : E[p]) {
		if (color[x] == 0) {
			if (!f(x, 3-c, n1, n2)) return false;
		} else {
			if (color[x] == color[p]) return false;
		}
	}
	return true;
}
int g(int p, int n) {
	if (p == (int)A.size()) {
		int m = N-n;
		return n*(n-1)/2 + m*(m-1)/2;
	}
	if (memo[p].count(n)) return memo[p][n];
	return memo[p][n] = min(g(p+1, n + A[p].first), g(p+1, n + A[p].second));
}
int main() {
	cin >> N >> M;
	set<pair<int,int>> e;
	for (int i = 0; i < M; ++ i) {
		int x, y;
		cin >> x >> y;
		--x; --y;
		e.insert({min(x,y), max(x,y)});
	}
	E.resize(N);
	for (int i = 0; i < N; ++ i) for (int j = i+1; j < N; ++ j) if (!e.count({i,j})) {
		E[i].push_back(j);
		E[j].push_back(i);
	}
	color.resize(N);
	for (int i = 0; i < N; ++ i) if (color[i] == 0) {
		int n1 = 0, n2 = 0;
		if (!f(i, 1, n1, n2)) {
			cout << -1 << endl;
			return 0;
		}
		A.push_back({n1,n2});
	}
	memo.resize(A.size());
	cout << g(0, 0) << endl;
}

