const int maxn=700+10,inf=0x3f3f3f3f;
int co[maxn],tot1,tot2,n,m;
bitset<maxn> f,g,G[maxn];
void dfs(int x){
	if(co[x]==0) tot1++;
	else tot2++;
	REP(i,1,n) if(G[x][i]==0){
		if(co[i]!=-1 && (co[i]^co[x])==0){
			printf("-1\n");
			exit(0);
		}
		if(co[i]==-1){
			co[i]=(co[x]^1);
