bool dfs(int u,int p,int lev,pair<int,int> &a){
	if(level[u]!=-1){
		if(level[u]!=lev)return false;
		else return true;
	}
	level[u] = lev;
	if(lev==0)a.first++;
	else a.second++;
	for(auto &&e:g[u]){
		if(e.dst==p)continue;
		if(!dfs(e.dst,u,1-lev,a))return false;
	}
	return true;
}

typedef bitset<701> BS;

void solve(Int N, Int M, vector<int> A, vector<int> B){
	vector<vector<bool> > H(N,vector<bool>(N,false));
	REP(i,M){
		H[A[i]][B[i]] = H[B[i]][A[i]] = true;
	}
	g.assign(N,Edges());
	REP(u,N)REP(v,N){
		if(u==v)continue;
		if(H[u][v]==false)addEdge(g,{u,v});
	}
	level.assign(N,-1);
	vector<pii> v;
	REP(u,N){
		if(level[u]==-1){
			pii a = {0,0};
			if(!dfs(u,-1,0,a)){
				fout<<-1<<endl;
				return;
			}
			v.push_back(a);
		}
	}
	BS b[2];
	b[0].set(0);
	b[0].set(N);
	REP(i,v.size()){
		b[1].reset();
		b[1]|=(b[0]<<v[i].first);
		b[1]|=(b[0]<<v[i].second);
		swap(b[0],b[1]);
	}
	Int ans = inf<Int>();
	for(Int i = 0;i<=N;i++){
		if(!b[0].test(i))continue;
		Int j = N - i;
		ans = min(ans,i*(i-1)/2+j*(j-1)/2);
	}
	fout<<ans<<endl;
}

