vector<int> total_diffs(vector<int> diffs) {
    if (diffs.size() == 0) return {0};
    int last = diffs.back();
    diffs.pop_back();
    auto total_diffs_smaller = total_diffs(diffs);

    vector<int> total_diffs;
    for (auto total_diff : total_diffs_smaller) {
        total_diffs.emplace_back(total_diff + last);
        total_diffs.emplace_back(total_diff - last);
    }
    return total_diffs;
}

