    colors.resize(N, 0);

    for (int v = 0; v < N; v++) {
        has_edge[v][v] = false;
    }
    for (int i = 0; i < M; i++) {
        int A,B;
        cin >> A >> B;
        A--;
        B--;
        has_edge[A][B] = false;
        has_edge[B][A] = false;
    }

    for (int v = 0; v < N; v++) {
        if (colors[v] == 0) {
            diff = 0;
            if (!dfs(v, 1)) {
                cout << -1;
                return -1;
            }
            diffs.emplace_back(diff);
        }
    }
    int abs_total_diff_min = INT_MAX;
    for (auto total_diff : total_diffs(diffs)) {
        int t = abs(total_diff);
        if (abs_total_diff_min > t) abs_total_diff_min = t;
    }

    int bigger = (N + abs_total_diff_min) / 2;
    int smaller = (N - abs_total_diff_min) / 2;

    cout << (bigger * (bigger - 1) + smaller * (smaller - 1)) / 2;
    return 0;
}

