constexpr int INF=1e9;
constexpr int MOD=1e9+7;
constexpr double EPS=1e-9;

struct UnionFind{
	vi data;
	UnionFind(int n):data(n,-1){}
	int Find(int i){
		return data[i]<0?i:(data[i]=Find(data[i]));
	}
	bool Unite(int a,int b){
		a=Find(a),b=Find(b);
		if(a==b) return false;
		if(-data[a]<-data[b]) swap(a,b);
		data[a]+=data[b];
		data[b]=a;
		return true;
	}
	int Size(int i){
		return -data[Find(i)];
	}
};

bool IsBipartite(const vvi& g)
{
	int n=g.size();
	UnionFind uf(2*n);
	rep(i,n) repi(j,i+1,n) if(g[i][j]){
		uf.Unite(i,n+j);
		uf.Unite(n+i,j);
	}
	rep(i,n) if(uf.Find(i)==uf.Find(n+i))
		return false;
	return true;
}

void dfs(const vvi& g,int u,int c,vi& vis,int& l,int& r)
{
	if(!vis[u]){
		vis[u]=1;
		int n=g.size();
		(c==0?l:r)++;
		rep(v,n) if(g[u][v])
			dfs(g,v,!c,vis,l,r);
	}
}

int main()
{
	#ifndef _GLIBCXX_DEBUG
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	constexpr char endl='\n';
	#endif

	for(int n,m;cin>>n>>m&&n|m;){
		vvi g(n,vi(n));
		rep(i,m){
			int u,v; cin>>u>>v; u--,v--;
			g[u][v]=g[v][u]=1;
		}
		rep(i,n) repi(j,i+1,n){
			g[i][j]^=1;
			g[j][i]^=1;
		}

		if(!IsBipartite(g)){
			cout<<-1<<endl;
			continue;
		}

		vi dp(n+1); dp[0]=1;

		vi vis(n);
		rep(i,n) if(!vis[i]){
			int l=0,r=0;
			dfs(g,i,0,vis,l,r);
			vi dp2(n+1);
			for(int x:{l,r})
				repi(i,x,n+1)
					dp2[i]|=dp[i-x];
			dp=move(dp2);
		}

		int res=INF;
		rep(i,n) if(dp[i])
			chmin(res,i*(i-1)/2+(n-i)*(n-i-1)/2);
		cout<<res<<endl;
	}
}

