int dfs(int now,int c,int& x,int& y)
{
	col[now]=c;
	x+=(c==1); y+=(c==-1);
	for(int i=1;i<=n;i++)
		if(mp[now][i]){
			if(col[i]){
				if(col[i]==c)return 0;
			}
			else{
				if(!dfs(i,-c,x,y))return 0;
			}
		}
	return 1;
}
int main()
{
	n=read(); m=read();
	for(int i=1;i<=n;i++)
		for(int j=1;j<=n;j++)
			mp[i][j]=(i!=j);
	for(int i=1;i<=m;i++){
		int x=read(),y=read();
		mp[x][y]=mp[y][x]=0;
	}
	f[0]=1;
	for(int i=1;i<=n;i++)
		if(!col[i]){
			int x=0,y=0;
			if(!dfs(i,1,x,y)){
				puts("-1"); return 0;
			}
			for(int j=0;j<=n;j++){
				g[j]=f[j];
				if(j>=x)g[j]|=f[j-x];
				if(j>=y)g[j]|=f[j-y];
			}
			for(int j=0;j<=n;j++)
				f[j]=g[j];
		}
	int sz=n/2;
	while(!f[sz])--sz;
	writeln(sz*(sz-1)/2+(n-sz)*(n-sz-1)/2);
	return 0;
}

