int N, M;

int G[710][710];
bool OK[710][710];
int C[710];

struct node {
    int idx;
    int c;
};

PP process(int n, bool &ok) {
    int o = 0, e = 0;
    queue<node> P;
    node p;
    p.idx = n;
    p.c = 1;
    C[n] = 1;
    o++;
    P.push(p);
    PP res;
    while (P.size() > 0) {
        node r = P.front();
        P.pop();
        int id = r.idx;
        int c = r.c;
        int d = 3 - c;
        for (int i = 0;i < N;i++) {
            if (i == id) continue;
            if (G[i][id] == 0) {
                if (C[i] == c) {
                    ok = 0;
                    return res;
                }
                if (C[i] == d) continue;
                C[i] = d;
                if (d == 2) e++;
                else o++;
                node m;
                m.idx = i;
                m.c = d;
                P.push(m);
            }
        }
    }
    return make_pair(e, o);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N >> M;
    memset(G, 0, sizeof(G));
    memset(C, 0, sizeof(C));
    for (int i = 0;i < M;i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a][b] = 1;
        G[b][a] = 1;
    }
    vector<PP> ans;
    for (int i = 0;i < N;i++) {
        if (C[i] != 0) continue;
        int c = 0;
        for (int j = 0;j < N;j++) c += G[i][j];
        if (c != N - 1) {
            bool ok = 1;
            PP p = process(i, ok);
            ans.push_back(p);
            if (!ok) {
                cout << -1 << endl;
                return 0;
            }
        }
    }
    int assign = 0;
    for (auto p : ans) {
        assign += p.first + p.second;
    }
    int rem = N - assign;
    memset(OK, 0, sizeof(OK));
    OK[0][0] = 1;
    for (int i = 0;i < ans.size();i++) {
        for (int j = 0;j <= N;j++) {
            if (OK[i][j] == 1) {
                OK[i + 1][j + ans[i].first] = 1;
                OK[i + 1][j + ans[i].second] = 1;
            }
        }
    }
    vector<int> ava;
    for (int i = 0;i <= N;i++) {
        if (OK[ans.size()][i] == 1) ava.push_back(i);
    }
    int sol = M;
    for (auto x : ava) {
        int y = assign - x;
        for (int i = 0;i <= rem;i++) {
            int j = rem - i;
            sol = min(sol, (x + i) * (x + i - 1) / 2 + (y + j) * (y + j - 1) / 2);
        }
    }
    cout << sol << endl;
    return 0;
}

