struct unionfind{
  private:
  int par[1401],treesize[1401];
  public:
  unionfind(int N){
    for(int i=0;i<N;++i){
      par[i]=i;
      treesize[i]=1;
    }
  }
  int root(int x){
    while(par[x]!=x){
      x=par[x]=par[par[x]];
    }
    return x;
  }
  bool unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x==y)return false;
    if(treesize[x]>treesize[y])swap(x,y);
    par[x]=y;
    treesize[y]+=treesize[x];
    return true;
  }
  bool parcheck(int x,int y){
    return root(x)==root(y);
  }
};
