}
int main()
{
    cin >> n >> m;
    for (int i = 1; i <= n; ++i)
        g[i][i] = 1;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        g[u][v] = g[v][u] = 1;
    }
    vector<int> a[2];
    for (int i = 1; i <= n; ++i) {
        if (co[i]) {
            continue;
        }
        ++tp;
        if (!dfs(i,1)) {
            cout << "-1" << endl;
            return 0;
        }
        if (w[tp][0].size() > w[tp][1].size())
            w[tp][0].swap(w[tp][1]);
        de[tp] = w[tp][1].size() - w[tp][0].size();
    }
    dp[0][N] = 1;
    for (int i = 1; i <= tp; ++i) {
        for (int j = 0; j < 2*N; ++j) {
            dp[i][j + de[i]] |= dp[i-1][j];
            dp[i][j - de[i]] |= dp[i-1][j];
        }
    }
    int k = 0;
    while (!dp[tp][N+k] && !dp[tp][N-k])
        ++k;
    k = dp[tp][N+k] ? N+k : N-k;
    for (int i = tp; i >= 1; --i) {
        if (k - de[i] >= 0 && dp[i-1][k - de[i]]) {
            k -= de[i];
            for (int j = 0; j <= 1; ++j)
                for (int x : w[i][j])
                    a[j].push_back(x);
        } else {
            k += de[i];
            for (int j = 0; j <= 1; ++j)
                for (int x : w[i][j])
                    a[j^1].push_back(x);
        }
    }
    bool ok = 1;
    for (int i = 0; i <= 1; ++i)
        ok = ok && chk(a[i]);
    if (!ok) {
        cout << "-1" << endl;
        return 0;
    }
    long long x = a[0].size(), y = a[1].size();
    cout << x * (x - 1) / 2 + y * (y - 1) / 2 << endl;
}

