int dfs(int n, vector<int> &vec, vector<vector<int> > &g){
	for(int i=0; i<g[n].size(); i++){
		int m = g[n][i];
		if(vec[m] == 0){
			vec[m] = -vec[n];
			if(dfs(m, vec, g) < 0) return -1;
		}
		else{
			if(vec[n]*vec[m]>0) return -1;
		}
	}
	return 0;
}

int main(){
	cin >> N >> M;
	for(int i=0; i<M; i++){
		cin >> A[i] >> B[i];
		A[i]--; B[i]--;
	}
	vector<vector<int> > adj(N, vector<int>(N));
	for(int i=0; i<M; i++){
		adj[A[i]][B[i]] = 1;
		adj[B[i]][A[i]] = 1;
	}

	vector<vector<int> > g(N);
	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			if(i != j && adj[i][j]==0){
				g[i].push_back(j);
			}
		}
	}

	vector<int> vec(N);
	for(int i=0; i<N; i++){
		if(vec[i] != 0) continue;
		vec[i] = i+1;
		if(dfs(i, vec, g) < 0){
			cout << -1 << endl;
			return 0;
		}
	}

	sort(vec.begin(), vec.end());
	vector<int> s, t;
	for(int i=0; i<N; i++){
		int k = upper_bound(vec.begin(), vec.end(), i+1)-lower_bound(vec.begin(), vec.end(), i+1);
		if(k>0){
			int l = upper_bound(vec.begin(), vec.end(), -i-1)-lower_bound(vec.begin(), vec.end(), -i-1);
			s.push_back(k);
			t.push_back(l);
		}
	}

	vector<vector<int> > dp(s.size()+1, vector<int>(N+1));
	dp[0][0] = 1;
	for(int i=0; i<s.size(); i++){
		for(int j=0; j<N; j++){
			if(dp[i][j]>0){
				dp[i+1][j+s[i]] = 1;
				dp[i+1][j+t[i]] = 1;
			}
		}
	}

	int ans = 1e9;
	for(int i=0; i<=N; i++){
		//if(dp[s.size()][i]) cout << i << endl;
		if(dp[s.size()][i]) ans = min(ans, i*(i-1)/2 + (N-i)*(N-i-1)/2);
	}
	cout << ans << endl;
	return 0;
}

