#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll solve() {
    ll N, M;
    cin >> N >> M;
    vector<vector<int>> g(N, vector<int>(N));
    int a, b;
    for ( int i = 0; i < M; i++ ) {
        cin >> a >> b;
        a--, b--;
        g[a][b] = 1;
        g[b][a] = 1;
    }
    vector<vector<int>> G(N);
    for ( int i = 0; i < N; i++ ) {
        for ( int j = i+1; j < N; j++ ) {
            if ( g[i][j] == 0 ) {
                G[i].push_back(j);
                G[j].push_back(i);
            }
        }
    }
    vector<int> cl(N, -1);
    queue<int> q;
    q.push(0);
    cl[0] = 0;
    while ( !q.empty() ) {
        int v = q.front();
        q.pop();
        for ( int u : G[v] ) {
            if ( cl[u] >= 0 ) {
                if ( cl[u] != 1 - cl[v] ) return -1;
                continue;
            }
            cl[u] = 1 - cl[v];
            q.push(u);
        }
    }

    unordered_map<int, int> m;
    for ( int i = 0; i < N; i++ ) {
        m[cl[i]]++;
    }
    int c0 = max({m[0], m[1], (int)(N+1) / 2});
    int c1 = (int)N - c0;
    ll ans = c0 * (c0 - 1) / 2 + c1 * (c1 - 1) / 2;
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

