const int MAXN = 702;

int n, m;
int mat[MAXN][MAXN];
vi G[MAXN];

bool good=true;
int X[2];
vector<ii>  b;

int vis[MAXN];
void dfs(int v, int c){
	vis[v]=c;
	X[c]++;
	for(int u : G[v]){
		if(vis[u]==-1) dfs(u, 1-c);
		else if(vis[u]==vis[v]) good=false;
	}
}

int c2(int x){
	return x*(x-1)/2;
}

int dp[MAXN][MAXN];
int f(int i, int x, int y){
	if(i==(int)b.size()){
		return c2(x)+c2(y);
	}
	int &ret=dp[i][x];
	if(ret != -1) return ret;
	ret = min(f(i+1, x+b[i].fst, y+b[i].snd),
				f(i+1, x+b[i].snd, y+b[i].fst));
	return ret;
}


int main(){
	scan(n, m);
	for(int i=0; i<n; i++) for(int j=0; j<n; j++) mat[i][j] = i!=j;
	for(int i=0; i<m; i++){
		int v, u; scan(v, u); v--; u--; mat[v][u] = mat[u][v] = 0;
	}
	for(int v=0; v<n; v++) for(int u=0; u<n; u++) if(mat[v][u]) G[v].pb(u);
	ms(vis, -1);
	for(int v=0; v<n; v++) if(vis[v]==-1){
		X[0]=X[1]=0;
		dfs(v, 0);
		b.pb({X[0], X[1]});
	}
	int ans;
	ms(dp, -1);
	if(good) ans = f(0, 0, 0);
	else ans = -1;
	printf("%d\n", ans);
}

