#include<bits/stdc++.h>
using namespace std;
const int N = 710;
int n, m, fa[N], rl[N], g[N][2], mp[N][N], f[N];
inline int Ask(int x) {
	if (!fa[x]) return x;
	int tmp = Ask(fa[x]);
	rl[x] ^= rl[fa[x]];
	return fa[x] = tmp;
}
inline void Merge(int x, int y) {
	int u = Ask(x), v = Ask(y);
	if (u == v) {
		if (rl[x] == rl[y]) puts("-1"), exit(0);
		return;
	}
	fa[u] = v;
	rl[u] = rl[x] ^ rl[y] ^ 1;
}
inline void Append(int x, int y) {
	for (int i = n; ~i; --i) {
		int ans = 0;
		if (i >= x) ans |= f[i - x];
		if (i >= y) ans |= f[i - y];
		f[i] = ans;
	}
}
int main() {
	scanf("%d%d", &n, &m);
	for (int i = 1, x, y; i <= m; ++i) {
		scanf("%d%d", &x, &y);
		if (x > y) swap(x, y);
		mp[x][y] = 1;
	}
	for (int i = 1; i <= n; ++i)
		for (int j = i + 1; j <= n; ++j)
			if (!mp[i][j]) Merge(i, j);
	for (int i = 1; i <= n; ++i) {
		Ask(i);
		++g[Ask(i)][rl[i]];
	}
	f[0] = 1;
	for (int i = 1; i <= n; ++i) if (!fa[i]) Append(g[i][0], g[i][1]);
	int ans = n >> 1;
	while (!f[ans]) --ans;
	printf("%d\n", ans * (ans - 1) / 2 + (n - ans) * (n - ans - 1) / 2);
	return 0;
}

