long long int N, M, K, H, W, L, R;

class UnionFind {
	vector<int>parent;
	vector<int>rank;
public:
	UnionFind(int num) {
		num++;
		parent.resize(num);
		rank.resize(num);
		for (int i = 0; i < num; i++) {
			parent[i] = i;
			rank[i] = 0;
		}
	}
	int Find(int node) {
		if (parent[node] == node)return node;
		else return parent[node] = Find(parent[node]);
	}
	void Unite(int u, int v) {
		u = Find(u);
		v = Find(v);
		if (u == v)return;
		if (rank[u] < rank[v])parent[u] = v;
		else {
			parent[v] = u;
			if (rank[u] == rank[v])rank[u]++;
		}
	}
	bool Check_Same(int u, int v) {
		return Find(u) == Find(v);
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	vector<vector<int>>edge(N, vector<int>(N, 1));
	UnionFind uf(N);
	for (int i = 0; i < M; i++) {
		cin >> L >> R;
		L--;
		R--;
		edge[L][R]--;
		edge[R][L]--;
	}
	for (int i = 0; i < N; i++)edge[i][i]--;
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			if (edge[i][j])uf.Unite(i, j);
		}
	}
	vector<int>odd(N);
	vector<int>even(N);
	set<int>s;
	vector<int>dis(N, MOD);
	vector<bool>flag(N);
	for (int i = 0; i < N; i++)s.insert(uf.Find(i));
	for (auto i : s) {
		queue<int>Q;
		dis[i] = 0;
		Q.push(i);
		while (!Q.empty()) {
			int cn = Q.front();
			Q.pop();
			for (int j = 0; j < N; j++) {
				if (edge[cn][j]) {
					flag[i] = true;
					if (dis[j] > dis[cn] + 1) {
						dis[j] = dis[cn] + 1;
						Q.push(j);
					}
				}
			}
		}
	}
	for (int i = 0; i < N; i++) {
		if (flag[uf.Find(i)]) {
			if (dis[i] % 2)odd[uf.Find(i)]++;
			else even[uf.Find(i)]++;
		}
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			if (edge[i][j]) {
				if (dis[i] % 2 == dis[j] % 2) {
					cout << -1 << endl;
					return 0;
				}
			}
		}
	}
	vector<int>dp(N + 1, 0);
	dp[0] = 1;
	for (int i = 0; i < N; i++) {
		vector<int>ddp(N + 1, 0);
		if (flag[i]) {
		//	cout << i << " " << odd[i] << " " << even[i] << endl;
			for (int j = N; j >= odd[i]; j--) {
				ddp[j] |= dp[j - odd[i]];
			}
			for (int j = N; j >= even[i]; j--) {
				ddp[j] |= dp[j - even[i]];
			}
			dp = ddp;
		}
	}
	int num = 0;
	for (int i = 0; i < N; i++) {
		if (dp[i])num = i;
	}
	for (int i = 0; i < N; i++) {
		if (dp[i]) {
			num += i;
			break;
		}
	}
	//cout << num << endl;
	int a = N, b = 0;
	for (int i = 0; i < (N+1) / 2; i++) {
		if (dp[i]) {
		//	cout << "dp" << i << endl;
			if (i + N - num >= (N + 1) / 2) {
				b = N / 2;
				a = N - b;
			}
			else {
				b = max(i +(int) N - num, b);
				a = N - b;
			}
		}
	}
//	cout << a << " " << b << endl;
	cout << (a - 1)*a / 2 + (b - 1)*b / 2 << endl;
	return 0;
}

