		A--, B--;
		flg[A][B] = flg[B][A] = 0;
	}
	V<V<int>> edge(N);
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			if (flg[i][j]) edge[i].push_back(j);
		}
	}
	V<int> g(N, -1);
	int k = 0;
	for (int i = 0; i < N; ++i) {
		if (edge[i].empty()) continue;
		if (g[i] >= 0) continue;

		queue<P<int, int>> q;
		g[i] = k;
		q.push({ i,0 });
		while (q.size()) {
			int from = q.front().first;
			int prt = q.front().second;
			q.pop();
			for (auto to : edge[from]) {
				if (g[to] == -1) {
					g[to] = k + !prt;
					q.push({ to,!prt });
				}
				else corner(g[to] != (k + !prt), -1);
