    vector<pii> nums;
    rep(v,N){
        if(dir[v]!=-1) continue;
        tmpnums[0]=tmpnums[1]=0;
        dfs(v,0);
        nums.push_back({tmpnums[0],tmpnums[1]});
    }

    if(!isbipartite){
        cout1(-1);
        return 0;
    }

    bool dp[MAXN]={0};
    dp[0]=1;
    rep(i,nums.size()){
        rrep(j,N){
            if(!dp[j]) continue;
            dp[j]=false;
            dp[j+nums[i].first]=true;;
            dp[j+nums[i].second]=true;
        }
    }

    ll a=-1;
    ll mindif=N;
    rep(i,N+1){
        if(!dp[i]) continue;
        if(mindif>abs(i-N/2)) mindif=abs(i-N/2),a=i;
    }
    ll b=N-a;
    cout1(a*(a-1)/2+b*(b-1)/2);
}

