int main() {
  int n(in), m(in);
  AdjacencyList<Edge> graph(in, n, m);
  graph = complement(graph);
  auto color = bipartiteColor(graph);
  if (color.empty()) {
    cout << -1 << endl;
    return 0;
  }
  UnionFind uf(n);
  for (int v = 0; v < n; ++v) {
    for (const auto &edge : graph[v]) {
      uf.unite(v, edge.to);
    }
  }
  Vector<bool> dp(n + 1);
  dp[0] = 1;
  for (const auto &group : uf.groups()) {
    int a = 0, b = 0;
    for (int v : group) {
      if (color[v]) {
        ++a;
      } else {
        ++b;
      }
    }
    Vector<bool> next(n + 1);
    for (int i = 0; i <= n; ++i) {
      if (dp[i]) {
        next[i + a] = true;
        next[i + b] = true;
      }
    }
    dp = next;
  }
  int res = inf<int>();
  for (int i = 0; i <= n; ++i) {
    if (dp[i]) {
      chmin(res, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
  }
  cout << res << endl;
}

