class Graph
{
public:
    int V;
    vector<vector<edge>> G;

    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    bool dfs(int v, vec &u, int p, vec &n){
        u[v] = p;
        n[p]++;
        REP(i, G[v].size()){
            if(u[G[v][i].to] == p) return false;
            else if(u[G[v][i].to] == -1){
                if(!dfs(G[v][i].to, u, 1 - p, n)) return false;
            }
        }
        return true;
    }

};

