bool go(int node, int num) {
	if (gg[node] == num) return true;
	if (gg[node] == -num) return false;
	gg[node] = num;
	REP(i, n) if (g[node][i]) {
		if (!go(i, -num)) return false;
	}
	return true;
}

void solve() {
	MSET(gg, 0);
	vector < pair<int, int> > v;
	REP(i, n) {
		if (gg[i] != 0) continue;
		int num = SZ(v) + 1;
