			cout << -1 << endl;
			return;
		}
		int c1 = 0;
		int c2 = 0;
		REP(j, n) {
			if (gg[j] == num) c1++;
			if (gg[j] == -num) c2++;
		}
		v.push_back(make_pair(c1, c2));
	}
	bool b[SZ(v)+1][n+1];
	REP(i, SZ(v)+1) REP(j, n+1) b[i][j] = false;
	b[0][0] = true;
	REP(i, SZ(v)) {
		REP(j, n+1) {
			if (b[i][j]) {
				b[i+1][j+v[i].first] = true;
				b[i+1][j+v[i].second] = true;
			}
		}
	}
	int res = 1<<30;
	REP(i, n+1) if (b[SZ(v)][i]) {
		chmin(res, i*(i-1)/2 + (n-i)*(n-i-1)/2);
	}
