int main() {
    int n, m;
    std::cin >> n >> m;
    std::vector<std::set<int>> g(n);
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if (i != j) g[i].insert(j);
    for (int i = 0; i < m; i++) {
        int a, b;
        std::cin >> a >> b;
        --a; --b;
        g[a].erase(b);
        g[b].erase(a);
    }

    std::vector<int> c(n);
    std::vector<std::pair<int, int>> w;
    for (int i = 0; i < n; i++) {
        if (c[i]) continue;

        std::deque<int> q { i };
        c[i] = 1;
        int o = 0, e = 0;
        while (!q.empty()) {
            int v = q.front();
            q.pop_front();

            if (c[v] == 1) o++;
            else e++;

            for (int to : g[v]) {
                if (c[to]) {
                    if (c[to] == c[v]) {
                        std::cout << -1 << std::endl;
                        return 0;
                    }
                } else {
                    c[to] = 3 - c[v];
                    q.push_back(to);
                }
            }
        }

        w.emplace_back(o, e);
    }

    B dp;
    dp[0] = 1;
    for (const auto &e : w) {
        dp = dp | (dp << e.first) | (dp << e.second);
    }

    int ret = n * n;
    for (int i = 1; i <= n; i++) {
        if (!dp[i]) continue;
        int tmp = i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2;
        ret = std::min(ret, tmp);
    }

    std::cout << ret << std::endl;

    return 0;
}

