	size.second = 0;
	gone[num] = depth;

	lp(i, vl[num].size()) {
		if (gone[vl[num][i]] == -1) {
			pl bpl=DFS(vl[num][i],depth+1);
			size.first += bpl.first;
			size.second += bpl.second;
		}
		else if ((depth + 1) % 2 != gone[vl[num][i]] % 2) {
			can = false;
		}
	}

	if (depth % 2 == 1)size.first++;
	else size.second++;
	return size;

}


