#include<iostream>
using namespace std;

int mat[800][800];
int n, m;

int checked[800];

pair<int, int> dfs(int u, int c)
{
    pair<int, int> ret = {1, 0};
    checked[u] = c;

    for (int i = 0; i < n; i++) {
        if (i != u && !mat[u][i]) {

            if (checked[i]) {
                if (checked[i] == c)
                    throw 0;
                else
                    continue;
            }

            auto res = dfs(i, 3 - c);
            ret.first += res.second;
            ret.second += res.first;
        }
    }
    return ret;
}

int dp[800][800] = {};

int main()
{
    ios::sync_with_stdio(false);

    cin >> n >> m;

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        mat[a][b] = mat[b][a] = 1;
    }

    vector<pair<int, int>> v;
    try {
        for (int i = 0; i < n; i++) {
            if (checked[i])continue;
            v.push_back(dfs(i, 1));
        }
    } catch(...) {
        printf("-1\n");
        return 0;
    }


    int ss = 0;
    for (auto p: v)
        ss += p.first + p.second;

    if (ss != n)
        return -1;

    dp[0][0] = 1;

    for (int k = 0; k < (int)v.size(); k++) {
        for (int i = 0; i <= n; i++) {
            if (dp[k][i]) {
                dp[k + 1][i + v[i].first] = dp[k + 1][i + v[i].second] = 1;
            }
        }
    }

    int best = n * n;
    for (int i = 0; i <= n; i++)
        if(dp[v.size()][i])
            best = min(best, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);

    cout << best << '\n';

}

