vector<int>opposite(int x,int c,set<int>&rem) {
	vector<int>v;
	int c2 = (c + 1) % 2;
	REP(i, N) {
		if (i == x)continue;

		if (G[x].find(i) == G[x].end()) {
			//pe(i);
			if (st[c].find(i) != st[c].end())ok = false;
			else if (used[i])continue;
			//print("here");
			if (st[c2].find(i) != st[c2].end())continue;
			v.push_back(i);
			st[c2].insert(i); rem.erase(i);
		}
	}
	//cout << endl;
	return v;
}
bool complete(set<int>& rem) {
	for (auto x : rem) {
		for (auto y : rem) {
			if (x == y)continue;
			if (G[x].find(y) == G[x].end())return false;
		}
	}
	return true;
}
int N1, N2;
void func(set<int>rem) {
	int n = rem.size();
	if (complete(rem)) {

		REP(i, n) {
			if (N1 < N2)N1++; else N2++;
		}
	}
	else {
		int mn = INF, id = 0;
		for (auto x : rem) {
			if (G[x].size() < mn) {
				mn = G[x].size();
				id = x;
			}
		}
		queue<int>que[2]; que[0].push(id);
		st[0].clear(); st[1].clear();
		used[id] = true;
		rem.erase(id);
		st[0].insert(id);
		REP(i, 2 * n) {
			int c = i % 2;
			int c2 = (i + 1) % 2;
			if (que[c].empty() && que[c2].empty()) {
				int max_n = max(st[0].size(), st[1].size()), min_n = min(st[0].size(), st[1].size());
				if (N1 < N2) {
					N1 += max_n; N2 += min_n;
				}
				else {
					N1 += min_n; N2 += max_n;
				}
				func(rem);
				return;
			}
			while (!que[c].empty()) {
				int now = que[c].front();
				for (auto nxt : st[c]) {
					if (nxt == now)continue;
					if (G[now].find(nxt) == G[now].end())no();
				}
				que[c].pop();
				used[now] = true;
				vector<int>v = opposite(now, c,rem);
				if (!ok)no();
				for (auto x : v) {
					que[c2].push(x);
				}
			}
		}
	}
}

void solve() {
	cin >> N >> M;
	REP(i, M) {
		int u, v; cin >> u >> v; u--, v--;
		G[u].insert(v);
		G[v].insert(u);
	}

	int id = 0, mn = INF;
	REP(i, N){
		rem.insert(i);
		if (G[i].size() < mn) {
			mn = G[i].size();
			id = i;
		}
	}
	func(rem);
	ll ans = 0;
	ans += N1 * (N1 - 1) / 2 + N2 * (N2 - 1) / 2;
	print(ans);
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	solve();
}

