typedef pair<int, int> P;
const int N = 705;
int e[N][N];
vector<int> G[N];
int color[N], totc[2];
vector<P> ps;
bool dp[N][N];

void add_edge(int u, int v) {
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(int v, int c) {
	color[v] = c;
	totc[c]++;
	bool ans(true);
    for (int u : G[v]) {
        if (color[u] == -1) {
			ans &= dfs(u, c ^ 1);
        }
		else if (color[u] == c) {
			return false;
		}
    }
    return ans;
}

int coloring(int mv) {
    memset(color, -1, sizeof(color));
    REPU(v, 1, mv) if (!G[v].empty()) {
        if (color[v] < 0) {
			totc[0] = totc[1] = 0;
            if (!dfs(v, 0)) return false;
			ps.push_back(P(totc[0], totc[1]));
        }
    }
    return true;
}

int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	int n, m; cin >> n >> m;
	REPU(_, 0, m) {
		int a, b; cin >> a >> b;
		e[a][b] = e[b][a] = 1;
	}
	REPU(i, 1, n + 1) REPU(j, i + 1, n + 1) {
		if (e[i][j] != 1) {
			add_edge(i, j);
		}
	}

	if (!coloring(n + 1)) {
		puts("-1"); return 0;
	}

	int rem = n;
	REPU(i, 0, ps.size()) {
		rem -= ps[i].first + ps[i].second;
	}

	MEM(dp, 0);
	REPU(i, 0, rem + 1) dp[i][rem - i] = 1;

	int tot = rem;
	REPU(k, 0, ps.size()) {
		REPU(i, 0, tot + 1) if (dp[i][tot - i]) {
			dp[i + ps[k].first][tot - i + ps[k].second] = 1;
			dp[i + ps[k].second][tot - i + ps[k].first] = 1;
		}
		tot += ps[k].first + ps[k].second;
	}

	int ans = INT_MAX;
	REPU(i, 0, n + 1) if (dp[i][n - i]) {
		amin(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	}
	cout << ans << endl;

	return 0;
}

