  for (int i = 0; i < m; i++) {
    int u, v;
    cin >> u >> v;
    u--; v--;
    rg[u][v] = rg[v][u] = 1;
  }
  vector< vector<int> > g(n);
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (rg[i][j] == 0) {
        g[i].emplace_back(j);
        g[j].emplace_back(i);
      }
    }
  }
  bitset<1000> dp;
  dp[0] = 1;
  vector<int> color(n, -1);
  function<bool(int, int&, int &, int)> dfs = [&](int v, int &x, int &y, int c) -> bool {
    if (color[v] == c) return true;
    if (color[v] != -1 && color[v] != c) return false;
    color[v] = c;
    if (c == 0) x++;
    else y++;
    bool ok = true;
    for (auto u : g[v]) {
      ok &= dfs(u, x, y, c ^ 1);
    }
    return ok;
  };

  for (int i = 0; i < n; i++) {
    if (color[i] == -1) {
      int x = 0, y = 0;
      if (!dfs(i, x, y, 0)) {
        cout << "-1\n";
        return 0;
      }
      dp |= (dp << x) | (dp << y);
    }
  }
  for (int i = n / 2; i >= 0; i--) {
    if (dp[i] == 1) {
      cout << i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2 << '\n';
      break;
    }
  }
  return 0;
}

