vector<vector<int> > H;
vector<int> colors;

bool paint(int v, int c) {
    colors[v] = c;
    for (int i = 0; i < H[v].size(); i++) {
        if (H[v][i]) {
            if (colors[i] == c) return false;
            if (colors[i] == 0 && !paint(i, -c)) return false;
        }
    }

    return true;
}

pair<int, int> dfs(int v) {
    pair<int, int> ret(0, 0);
    if (colors[v] == 1) ret.first++;
    else if (colors[v] == -1) ret.second++;
    else if (colors[v] == 0) return ret;
    colors[v] = 0;
    for (int i = 0; i < H.size(); i++) {
        if (H[v][i]) {
            pair<int, int> tmp = dfs(i);
            ret.first += tmp.first;
            ret.second += tmp.second;
        }
    }

    return ret;
}

int func(int num) {
    return num * (num - 1) / 2;
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;

    vector<vector<int> > G(N, vector<int>(N));
    H = vector<vector<int> >(N, vector<int>(N));
    colors.resize(N, 0);

    rep(i, 0, M) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a][b] = G[b][a] = 1;
    }

    rep(i, 0, N) {
        rep(j, 0, N) {
            H[i][j] = !G[i][j];
            if (i == j) H[i][j] = 0;
        }
    }

    rep(i, 0, N) {
        if (colors[i] == 0) {
            if (!paint(i, 1)) {
                cout << -1 << endl;
                return 0;
            }
        }
    }

    vector<pair<int, int> > pairs;
    rep(i, 0, N) {
        if (colors[i] != 0) {
            pair<int, int> tmp = dfs(i);
            pairs.push_back(tmp);
        }
    }

    vector<int> dp(N + 1);
    dp[0] = 1;
//    dp[pairs[0].first] = dp[pairs[0].second] = 1;
    rep(i, 0, pairs.size()) {
        vector<int> tmp(N + 1);
        //pairs[i]のどちらを使うか
        for (int j = N; j >= 0; j--) {
            if (dp[j] && j + pairs[i].first <= N) tmp[j + pairs[i].first] = 1;
            if (dp[j] && j + pairs[i].second <= N) tmp[j + pairs[i].second] = 1;
        }
        dp = tmp;
    }

    int min_k = -1;
    int min_v = INF;

    for (int i = 0; i <= N; i++) {
        if (dp[i]) {
            int a = i;
            int b = N - i;
            int tmp = func(a) + func(b);
            if (tmp < min_v) {
                min_k = a;
                min_v = tmp;
            }
        }
    }

    cout << min_v << endl;


    return 0;
}

