        if(!isE[temp[i]][temp[j]]){
          cout << -1 << endl;
          return 0;
        }
      }
    }

    int s = group[0].size();
    int t = group[1].size();

    cout << s * (s - 1) / 2 + t * (t - 1) / 2 << endl;
    return 0;
  }

  vector<vector<int>> rG(N);

  int start = 0;

  rep(i,0,N - 1){
    rep(j,0,N - 1){
      if(i == j) continue;
      if(!isE[i][j]){
        rG[i].push_back(j);
        start = i;
      }
    }
  }

  vector<int> vis(N,-1);

  queue<pair<int,int>> que;
  que.push({start,0});

  vis[start] = 0;

  int cnt[2];
  cnt[0] = 0;
  cnt[1] = 0;
  while(!que.empty()){
    int v = que.front().first;
    int d = que.front().second;
    que.pop();
    cnt[d]++;
    for(int to : rG[v]){
      if(vis[to] != -1 && vis[to] != (d + 1) % 2){
        cout << -1 << endl;
        return 0;
      }
      if(vis[to] != -1) continue;
      vis[to] = (d + 1) % 2;
      que.push({to,(d + 1) % 2});
    }
  }
  int a = min(cnt[0],cnt[1]);
  int b = max(cnt[0],cnt[1]);
  int re = N - a - b;
  int aa = min(b,a + re);
  re = re - (aa - a);
  aa += re / 2 + (re % 2);
  b += re / 2;

  cout << aa * (aa - 1) / 2 + b * (b - 1) / 2 << endl;
}

