		while (!next.empty()) {
			uint32_t cur = next.front();
			next.pop();
			for (uint32_t j = 0;j < n;j++) {
				if (!edge[cur][j]) {
					if (vis[j]) {
						if (vis[j] == vis[cur]) {
							return false;
						}
					} else {
						vis[j] = vis[cur] == 1 ? 2 : 1;
						//std::cerr << "Assign " << j << ": " << vis[j] << "\n";
						next.push(j);
					}
				}
			}
		}

		uint32_t curCnt[] = {0, 0};
		for (uint32_t j = 0;j < n;j++) {
			if ((vis[j] >= 1) && (vis[j] <= 2))  {
				curCnt[vis[j] - 1]++;
				vis[j] = 3;
			} 
		}
		if (curCnt[0] > curCnt[1]) {
			std::swap(curCnt[0], curCnt[1]);
		}
		comps.push_back({curCnt[0], curCnt[1]});
	}
	return true;
}

bool possib[MAX_N + 1];

uint32_t calc_ans() {
	for (uint32_t i = 0;i <= n;i++) {
		possib[i] = false;
	}
	possib[0] = true;
	uint32_t baseSum = 0;
	for (auto c : comps) {
		baseSum += c.first;
		uint32_t delta = c.second - c.first;
		for (uint32_t j = n - delta;j <= n;j--) {
			if (possib[j]) {
				possib[j + delta] = true;
			}
		}
	}
	uint64_t best = n * n;
	for (uint32_t j = 0;j <= n;j++) {
		if (!possib[j]) {
			continue;
		}
		uint64_t a = baseSum + j;
		uint64_t b = n - a;
		//std::cerr << a << " " << b << "\n";
		uint64_t cur = a * (a - 1) / 2 + b * (b - 1) /2;
		best = std::min(cur, best);
	}
	return best;
}

