#define MAXN 705

using namespace std;





int n, cnt, dsu[MAXN], sz[MAXN], col[MAXN];
int mp[MAXN][MAXN];
int n2, c[MAXN][2], sum[MAXN];
int dp[MAXN][MAXN];

int find_dsu(int u)
{
    if (u ^ dsu[u])
        return dsu[u] = find_dsu(dsu[u]);
    else
        return u;
}

void merge_dsu(int u, int v)
{
    u = find_dsu(u);
    v = find_dsu(v);
    if (u ^ v) {
        dsu[u] = v;
        sz[v] += sz[u];
    }
}

bool dfs(int u, int colo)
{
    col[u] = colo;
    if (colo)
        cnt++;
    for (int i = 1; i <= n; i++) {
        if (!mp[u][i] && i != u) {
            if (col[i] == -1) {
                if (!dfs(i, colo ^ 1))
                    return false;
            } else if (col[i] != colo ^ 1)
                return false;
        }
    }
    return true;
}


int solve()
{
    for (int i = 1; i <= n; i++) {
        sz[i] = 1;
        dsu[i] = i;
        col[i] = -1;
    }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < i; j++)
            if (!mp[i][j])
                merge_dsu(i, j);
    for (int i = 1; i <= n; i++)
        find_dsu(i);
    n2 = 0;
    sum[0] = 0;
    for (int i = 1; i <= n; i++)
        dp[0][i] = n * n;
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        if (find_dsu(i) != i)
            continue;
        cnt = 0;
        if (!dfs(i, 0))
            return -1;
        n2++;
        c[n2][0] = cnt;
        c[n2][1] = sz[i] - cnt;
        sum[n2] = sum[n2 - 1] + sz[i];
        for (int j = 0; j <= n; j++) {
            dp[n2][j] = n * n;
            for (int k = 0; k < 2; k++) {
                int last = j - c[n2][k];
                if (last >= 0) {
                    int tmp = dp[n2 - 1][last];
                    tmp += last * c[n2][k];
                    tmp += c[n2][k ^ 1] * (sum[n2 - 1] - last);
                    dp[n2][j] = min(dp[n2][j], tmp);
                }
            }
        }
    }
    int ans = n * n;
    for (int i = 0; i <= n; i++)
        ans = min(ans, dp[n2][i]);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < i; j++)
            if (mp[i][j] && find_dsu(i) == find_dsu(j) && col[i] == col[j])
                ans += mp[i][j];
    return ans;
}

