	queue<int> q;
	q.push(source);
	color[source] = 1;
	int red = 1;
	int blue = 0;
	int edges = 0;
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(int v = 1;v <= n;v++){
			if(mat[u][v])edges++;
			if(!mat[u][v])continue;
			if(color[v] == color[u])f = 1;
			if(color[v])continue;
			color[v] = (color[u] == 1)?2:1;
			(color[v] == 1)?red++:blue++;
			q.push(v);
		}
	}
	comp++;
	l[comp] = blue;
	r[comp] = red;
	ans -= edges/2;
}

void solve(){
  	cin >> n >> m;
  	RE(i,n){
  		color[i] = 0;
  		RE(j,n)mat[i][j] = (i != j);
  	}
  	RE(i,m){
  		int a,b;cin >> a >> b;
  		mat[a][b] = mat[b][a] = 0;
  	}
  	RE(i,n){
  		if(!color[i])bfs(i);
  	}
  	if(f){
  		cout << -1;
  		return;
  	}
  	dp[0][0] = 1;
  	for(int i = 1;i <= comp;i++){
  		for(int j = 1;j <= n;j++){
  			if(j >= r[i])dp[i][j] = max(dp[i-1][j],dp[i-1][j-r[i]]);
  			if(j >= l[i])dp[i][j] = max(dp[i][j],max(dp[i-1][j],dp[i-1][j-l[i]]));
  		}
  	}
  	int cur = ans;
  	for(int i = 1;i <= n;i++){
  		if(dp[comp][i] == 0)continue;
  		cur = max(cur,(n-i)*i+ans);
  	}
  	cout << m-cur;
}

