int v[705];

int dfs(vector<vector<int>>& tree, int node, int& s, int& t) {
    v[node] = 1;
    vector<int>& ne = tree[node];
    vector<int>::iterator iter = ne.begin();
    while (iter != ne.end()) {
        if (v[*iter]) {
            if (c[*iter] == c[node]) return -1;
            iter++;
        } else {
            c[*iter] = 1 - c[node];
            if (c[*iter] == 0) s++;
            else t++;
            if (dfs(tree, *iter, s, t) == -1) return -1;
        }
    }
    return 0;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < 705; i++) {
        c[i] = -1;
        v[i] = 0;
    }
    vector<vector<int>> tree(n + 1, vector<int>());
    for (int i = 1; i <= m; i++) {
        int x, y;
        cin >> x >> y;
        tree[x].push_back(y);
        tree[y].push_back(x);
    }
    vector<vector<int>> com_tree(n + 1, vector<int>());
    for (int i = 1; i <= n; i++) {
        vector<int>& ne = tree[i];
        for (int j = 1; j <= n; j++) {
            if (j != i && find(ne.begin(), ne.end(), j) == ne.end()) {
                com_tree[i].push_back(j);
            }
        }
    }
    vector<int> nums;
    for (int i = 1; i <= n; i++) {
        if (!v[i]) {
            int s = 0, t = 0;
            c[i] = 0;
            s++;
            int ans = dfs(com_tree, i, s, t);
            if (ans == -1) {
                cout << -1 << endl;
                return 0;
            }
            nums.push_back(s - t);
        }
    }
    int size = nums.size();
    vector<set<int>> dp(size, set<int>());
    dp[0].insert(nums[0]); dp[0].insert(-nums[0]);
    for (int i = 1; i < size; i++) {
        set<int>& ts = dp[i - 1];
        if (ts.size() == 0) {
            dp[i].insert(nums[i]);
            dp[i].insert(-nums[i]);
        } else {
            set<int>::iterator iter = ts.begin();
            while (iter != ts.end()) {
                int first = (*iter) + nums[i];
                int second = (*iter) - nums[i];
                dp[i].insert(first);
                dp[i].insert(second);
                iter++;
            }
        }
    }
    vector<int> ts(dp[size - 1].begin(), dp[size - 1].end());
    int abs_x = abs(ts[0]);
    for (int i = 0; i < ts.size(); i++) {
        if (abs(ts[i]) < abs_x) abs_x = abs(ts[i]);
    }
    int a = (n + abs_x) / 2;
    int b = n - a;
    int ans = a * (a - 1) / 2 + b * (b - 1) / 2;
    cout << ans << endl;
}

