    for (int i=0; i<n; ++i) {
        if (!vis[i]) {
            ncomp++;
            comp.push_back(dfs(i, ncomp));
        }
    }

    int ans = -1;
    if (ncomp==2) {
        bool ok = true;
        for (int i=0; i<n; ++i) {
            if (deg[i]<comp[vis[i]]-1) {
                ok = false;
                break;
            }
        }
