#define MAXN 705

int N, M, vis[MAXN], dp[MAXN][MAXN];
bool GC[MAXN][MAXN], vis2[MAXN];
vector<int> adjC[MAXN];
vector<pii> edges, CNT;

bool dfs(int v) {
    for (int w : adjC[v]) {
        if (vis[v] == vis[w]) return false;
        if (vis[w] == 0) {
            if (vis[v] == 1) vis[w] = 2;
            else vis[w] = 1;
            if (!dfs(w)) return false;
        }
    }
    return true;
}

pii cnt(int v) {
    pii ret = {0, 0};
    if (vis2[v]) return ret;
    vis2[v] = 1;
    if (vis[v] == 1) ret.f++;
    else ret.s++;
    for (int w : adjC[v]) {
        pii ret2 = cnt(w);
        ret.f += ret2.f;
        ret.s += ret2.s;
    }
    return ret;
}

int solve(int i, int sum) {
    if (dp[i][sum] != -1) return dp[i][sum];
    if (i == sz(CNT)) return (sum * (sum - 1) / 2) + ((N - sum) * (N - sum - 1) / 2);
    return dp[i][sum] = min(solve(i + 1, sum + CNT[i].f), solve(i + 1, sum + CNT[i].s));
}

int main() {
//    freopen("in.txt", "r", stdin);
//    freopen("out.txt", "w", stdout);
    _iomanager.reset(new IOManager());
    read(N, M);
    assert(M > 3);
    FOR(i, N) {
        vis[i] = vis2[i] = 0;
        FOR(j, N) {
            GC[i][j] = i != j;
            dp[i][j] = -1;
        }
    }
    int a, b;
    FOR(i, M) {
        read(a, b);
        a--; b--;
        edges.eb(a, b);
        GC[a][b] = GC[b][a] = 0;
    }
    FOR(i, N) FOR(j, N) if (GC[i][j]) adjC[i].pb(j);
    FOR(i, N) {
        if (!vis[i]) {
            vis[i] = 1;
            if (!dfs(i)) {
                if (M == N * (N - 1) / 2) writeln(M);
                else writeln(-1);
                return 0;
            }
            CNT.pb(cnt(i));
        }
    }
    writeln(solve(0, 0));
    return 0;
}

