        if (!visited[v]) DFS(v);
    }
}

int tri(int n) {
    return n*(n-1)/2;
}

int main () {
    scanf("%d%d", &n, &m);
    fto(i, 1, m) {
        int u, v;
        scanf("%d%d", &u, &v);
        a[u][v] = a[v][u] = 1;
    }

    fto(u, 1, n) {
        vector<int> adj;
        fto(v, 1, n)
            if (u != v && !a[u][v]) adj.pb(v);
        fto(i, 0, sz(adj)-2) {
            g[adj[i]].pb(adj[i+1]);
            g[adj[i+1]].pb(adj[i]);
        }
    }

    fto(u, 1, n) {
        if (!visited[u]) {
            vtxCnt = 0;
            DFS(u);
            comp.pb(vtxCnt);
        }
    }

    if (sz(comp) == 1) {
        puts("-1");
        return 0;
    }

    dp[0] = true;
    for(int x: comp) {
        fdto(i, n-x, 0)
            dp[i+x] |= dp[i];
    }

    int ans = m;
    fto(i, 1, n) {
        if (dp[i]) ans = min(ans, tri(i) + tri(n-i));
    }

    printf("%d", ans);

    return 0;
}

