int main(){
	int N, M;
	cin >> N >> M;
	bool B[N][N] = {};

	rep(i,M){
		int a, b;
		cin >> a >> b;
		a--; b--;
		B[a][b] = true;
		B[b][a] = true;
	}

	vector<int> G[N];
	rep(i,N){
		repi(j,i+1,N){
			if(!B[i][j]){
				G[i].emplace_back(j);
				G[j].emplace_back(i);
			}
		}
	}

	queue<int> Q;
	vector<int> C(N);

	rep(i, N){
		if(C[i])continue;
		C[i] = i + 1;
		Q.emplace(i);
		while(Q.size()){
			int u = Q.front(); Q.pop();

			for(int v: G[u]){
				if(C[v] == C[u]){
					cout << -1  << endl;
					return 0;
				}
				if(C[v] == 0){
 					C[v] = -C[u];
                    Q.emplace(v);
				}			
			}
		}
	}
	vector<int> P(N + 1);
	vector<int> W(N + 1);
	rep(i, N + 1){
		if(C[i] < 0)P[C[i]]++;
		else W[C[i]]++;
	}

	vector<bool> dp(N + 1);
	dp[0] = true;
	rep(i, N + 1){
		vector<bool> next(N + 1);
		rep(j, N + 1){
			if(dp[j]){
				next[j + P[i]] = true;
				next[j + W[i]] = true;
			} 
		}
		dp = next;
	}

	int ans = INT_MAX;
	//cout << ans << endl;
	rep(i, N + 1){
		if(dp[i]){
			int t = i;
			int s = N - i;
			ans = min(ans, t * (t - 1) / 2 + s * (s - 1) / 2);
		}
	}
	cout << ans << endl;

	return 0;
}

