/* do your best */
pair<int, int> dfs(int c, vector<vector<int>> &g, vector<int> &used, int cur, int par = -1) {
  int b = 0;
  int w = 0;
  if (c == 0) b++;
  else w++;
  used[cur] = c;
  int nc = (c + 1) % 2;

  for (auto nxt : g[cur]) {
    if (nxt == par) continue;

    if (used[nxt] == -1) {
      int bb;
      int ww;
      tie(bb, ww) = dfs(nc, g, used, nxt, cur);
      if (bb == -1) return {-1, -1};
      b += bb;
      w += ww;
    } else {
      if (used[nxt] == c) {
        return {-1, -1};
      }
    }
  }

  return {b, w};
}

