  }

  int cm = 0;
  vector<vector<int>> cg(n);
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (g[i][j] == 0) {
        cm++;
        cg[i].push_back(j);
        cg[j].push_back(i);
      }
    }
  }


  // 連結成分ごとに二分彩色する
  vector<pair<int, int>> cnt;
  vector<int> used(n, -1);
  for (int i = 0; i < n; i++) {
    if (used[i] == -1) {
      int b, w;
      tie(b, w) = dfs(0, cg, used, i);
      cnt.emplace_back(b, w);
