#define REP(i,n) for(int i=0;i<(n);++i)

int N, M;
int color[705];
int white[705];
int black[705];
int E[705][705];
vector<int> G[705];
bool flg = false; // 二部グラフ判定失敗フラグ

void dfs(int s, int c, int p) {
    if(color[s] != 0) return;
    color[s] = c;
    if(c == 1) white[p]++;
    else black[p]++; 
    for(auto x:G[s]) {
        if(color[x] != 0) {
            if(color[x] != -c) {
                flg = true;
                return;
            }
            continue;
        }
        dfs(x, -c, p);
    }
}

void solve() {
    scanf("%d%d", &N, &M);
    memset(E,0,sizeof(E));
    REP(i,M) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--, b--;
        E[a][b]++;
        E[b][a]++;
    }
    REP(i,N) REP(j,N) {
        if(i>=j) continue;
        if(E[i][j]==0) {
            G[i].push_back(j);
            G[j].push_back(i);
        }
    }
    // REP(i,N) { REP(j,G[i].size()) cout << G[i][j] << " "; cout << endl;}
    memset(color,0,sizeof(color));
    memset(white,0,sizeof(white));
    memset(black,0,sizeof(black));
    REP(i,N) dfs(i, 1, i);
    /*
    REP(i,N) cout << color[i] << " "; cout << endl;
    REP(i,N) cout << white[i] << " "; cout << endl;
    REP(i,N) cout << black[i] << " "; cout << endl;
    */
    if(flg) {
        printf("%d\n", -1);
    }
    else {
        vector<int> vec;
        int wa = 0;
        REP(i,N) {
            if(white[i]) {
                vec.push_back(white[i]-black[i]);
                wa += black[i];
            }
        }
        /*
        cout << wa << endl;
        */

        //for(auto x:vec) cout << x << " "; cout << endl;
        /**/
        int sz = vec.size();
        // cout << sz << endl;
        vector<bitset<705>> dp(sz + 1);
        dp[0].set(wa);
        REP(i,sz) {
            dp[i+1] |= dp[i];
            dp[i+1] |= (vec[i]>=0 ? (dp[i]<<vec[i]) : (dp[i]>>(-vec[i])));
        }
        int ans = 5000;
        REP(i,N+1) {
            if(dp[sz][i]) ans = min(ans, i*i-N*i+(N-1)*N/2);
        }
        printf("%d\n", ans);
    }
}

int main(){
    solve();
    return 0;
}

