const int N=705;
int n, m, comp=0, color[N], cnt[N][3];
bool in[N][N], flag;
vi graph[N];
int dp[N][N];

void dfs(int u, int col)
{
	color[u]=col;
	cnt[comp][col]++;

	for(auto v: graph[u])
	{
		if(color[v]!=-1)
		{
			if(color[v]==col)
			{
				flag=false;
				return;
			}
			else continue;
		}
		dfs(v,3-col);
	}
}

bool go(int curr, int rem)
{
	if(curr>comp) return rem==0;
	if(dp[curr][rem]!=-1) return dp[curr][rem];

	bool ret=false;

	if(rem>=cnt[curr][1]) ret|=go(curr+1,rem-cnt[curr][1]);
	if(rem>=cnt[curr][2]) ret|=go(curr+1,rem-cnt[curr][2]);

	return dp[curr][rem]=ret;
}

void solve()
{
	ms(color,-1);

	FOR(i,1,n+1)
	{
		if(color[i]==-1)
		{
			comp++;
			flag=true;
			dfs(i,1);

			if(!flag)
			{
				prnt(-1);
				return;
			}
		}
	}

	// debug("comp",comp);

	ll ans=INF;
	ms(dp,-1);	

	FOR(i,0,n+1)
	{
		if(go(1,i))
		{
			ans=min(ans,((ll)i*(i-1))/2+((ll)(n-i)*(n-i-1))/2);
		}
	}

	prnt(ans);
}

