using namespace std;
typedef long long ll;

const int maxn = 705;
bool bipartite = true, adj[maxn][maxn];
int n, m, x, y, r, b, len, color[maxn];
vector<int> vs[maxn];
pair<ll, ll> balance[maxn];

void dfs(int v){
	r+= int(color[v] == 0), b+= int(color[v] == 1);
	for(int e: vs[v]){
		if (color[e] == -1) color[e] = (color[v]+1)%2, dfs(e);
		else if (color[e] == color[v]) bipartite = false;
	}
}

pair<ll, ll> bin(pair<ll, ll> a){
	return {(a.first*(a.first-1ll))/2ll, (a.second*(a.second-1ll))/2ll};
}

int main(){
	memset(color, -1, sizeof(color));
	scanf("%d %d", &n, &m);
	for(int i = 0; i<m; i++){
		scanf("%d %d", &x, &y);
		--x, --y;
		adj[x][y] = adj[y][x] = 1;
	}
	for(int i = 0; i<n; i++){
		for(int j = i+1; j<n; j++)
			if (!adj[i][j]) vs[i].push_back(j), vs[j].push_back(i);
	}
	for(int i = 0; i<n; i++) if (color[i] == -1){
		color[i] = 0;
		dfs(i);
		if (r<b) swap(r, b);
		balance[len++] = {r, b};
		// first >= second
		r = b = 0;
	}
	if (!bipartite) {puts("-1"); return 0;}
	sort(balance, balance+len, greater<pair<ll, ll>>());
	pair<ll, ll> ans = bin(balance[0]);
	pair<ll, ll> cur = balance[0];
	for(int i = 1; i<len; i++){
		ans.first+= (balance[i].first*cur.second);
		ans.second+= (balance[i].second*cur.first);
		cur.first+= (balance[i].second);
		cur.second+= (balance[i].first);
		if (cur.first<cur.second){
			swap(cur.first, cur.second);
			swap(ans.first, ans.second);
		}
	}
	printf("%lld\n", ans.first+ans.second);
	return 0;
}

