void dfs1(int v, int &oneplus, int &twoplus){
    used[v] = 1;
    for(int i = 0; i < n; ++i){
        if(i == v)continue;
        if(used[i] == 1 && color[i] == color[v] && rg[v][i] == 1)bad();
        if(i != v && rg[v][i] == 1 && used[i] == 0){
            color[i] = 3 - color[v];
            if(color[i] == 1){
                oneplus++;
            } else {
                twoplus++;
            }
            dfs1(i, oneplus, twoplus);
        }
    }

}




void solve(){
    cin >> n >> m;
    g.resize(n, vector < int > (n));
    rg.resize(n, vector < int > (n));
    used.resize(n, 0);
    color.resize(n, -1);
    for(int i = 0; i < m; ++i){
        int v, u;
        cin >> v >> u;
        --v, --u;
        g[v][u] = 1;
        g[u][v] = 1;
    }
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < n; ++j){
            if(i == j)continue;
            rg[i][j] = 1 - g[i][j];
        }
    }
    vector < vector < int > > srt;
    for(int i = 0; i < n; ++i){
        if(!used[i]){
            int oneplus = 1;
            int twoplus = 0;
            color[i] = 1;
            dfs1(i, oneplus, twoplus);
            srt.push_back({abs(oneplus - twoplus), oneplus, twoplus});
        }
    }
    sort(srt.begin(), srt.end());
    reverse(srt.begin(), srt.end());
    int a = 0;
    int b = 0;
    int bal = 0;
    for(int i = 0; i < srt.size(); ++i){
        //cerr << srt[i][1] << " " << srt[i][2] << "\n";
        if(bal >= 0){
            b += max(srt[i][1], srt[i][2]);
            a += min(srt[i][1], srt[i][2]);
            bal = a - b;
        } else {
            a += max(srt[i][1], srt[i][2]);
            b += min(srt[i][1], srt[i][2]);
            bal = a - b;
        }
    }
    int val = a * (a - 1) / 2 + b * (b - 1) / 2;
    //cerr << a << " " << b << "\n";
    cout << val << "\n";
}



