            vec.push_back(make_pair(temp[0], temp[1]));
        }
    }

    bool c[n+1];
    memset(c, false, sizeof(c));
    c[0] = true;
    for (P p : vec) {
        for (int i = n; i >= 0; i--) {
            if (c[i]) {
                c[i+p.first] = true;
                c[i+p.second] = true;
            }
        }
    }

    int res = inf;
    for (int i = 1; i < n; i++) {
        if (c[i]) {
            res = min(res, i * (i-1) / 2 + (n-i) * (n-i-1) / 2);
        }
    }
    return res;
}

