	ids_m.resize(new_size);
}

void Graph::reserve(int edge_count) {
	edges_m.reserve(edge_count);
}

void Graph::add(int from, int to) {
	ids_m[from].push_back(edges_m.size());
	edges_m.push_back(Edge(from, to));
}

const Graph::Edge& Graph::getEdge(EdgeID id) const {
	assert(id >= 0 && id < edges_m.size());
	return edges_m[id];
}

const Graph::List& Graph::row(int from) const {
	return ids_m[from];
}

/* 辺の向きを逆転させたグラフを作成 */
Graph Graph::createReversedGraph() const {
	Graph ret(size());
	ret.reserve(edges_m.size());

	for (const auto& edge : edges_m) {
		ret.add(edge.to, edge.from);
	}
	return ret;
}

