int visited[710];
bool l = 1;
ll cnt = 1;
bool canmake[710][710][710];

void dfs(int now){
  rep(to, N){
    if(E[now][to] == 0) continue;
    if(visited[to] == 0){
      visited[to] = -visited[now];
      dfs(to);
    }else{
      if(visited[now] != -visited[to]) l = 0;
    }
  }
}

bool Bip(){
  rep(i, N){
    if(visited[i] != 0) continue;
    visited[i] = cnt;
    dfs(i);
    cnt++;
  }
  return l;
}

void solve(){
  if(Bip() == 0){
    cout << -1 << endl;
    return;
  }
  //二部グラフである

  ll V = 0;
  rep(i, N)rep(j, N)if(E[i][j]) V++;
  V /= 2;
  vector<pair<int, int>> Cnt(cnt, {0, 0});
  rep(i, N){
    if(visited[i] > 0) Cnt[abs(visited[i])-1].first++;
    else Cnt[abs(visited[i])-1].second++;
  }
  canmake[0][0][0] = 1;
  rep(c, cnt){
    rep(i, N+1)rep(j, N+1){
      if(canmake[c][i][j] == 0) continue;
      canmake[c+1][i+Cnt[c].first][j+Cnt[c].second] = 1;
      canmake[c+1][i+Cnt[c].second][j+Cnt[c].first] = 1;
    }
  }
  ll ans = INF;
  rep(i, N)rep(j, N){
    if(canmake[cnt][i][j] == 0) continue;
    ans = min(ans, M - (i * j - V));
  }
  cout << ans << endl;
}

