    rep(i, M) {
        int a, b; cin >> a >> b;
        connected[a-1][b-1] = true;
        connected[b-1][a-1] = true;
    }
    rep(i, N) rep(j, N) {
        if(i != j && !connected[i][j]) {
            adj[i].push_back(j);
            adj[j].push_back(i);
        }
    }
    rep(i, N) {
        if(C[i] == 0) {
            component++;
            if(!dfs(i, 1)) {
                cout << "-1\n";
                return 0;
            }
        }
    }
    vector<int> X;
    repp(i, 1, component) {
        int t1 = 0, t2 = 0;
        rep(j, N) {
            if(C[j] == i) {
                t1 += T[j] == 1;
                t2 += T[j] == 2;
            }
        }
        X.push_back(abs(t1-t2));
    }
    rep(i, component) {
        repp(j, -N, N) {
            if(i == 0) {
                DP[i][j + N] = (j == X[i] || j == -X[i]);
            } else {
                if(j + N - X[i] < 0 ) DP[i][j + N] = DP[i-1][j + N + X[i]];
              	else if(j + N + X[i] > 2*N+1) DP[i][j + N] = DP[i-1][j + N - X[i]];
                else DP[i][j + N] = DP[i-1][j + N - X[i]] || DP[i-1][j + N + X[i]];
            }
        }
    }
    int d = 0;
    repp(diff, 0, N) {
        if(DP[component - 1][N + diff] || DP[component - 1][N - diff]) {
            d = diff;
            break;
        }
    }
    int x = (N - d) / 2, y = N - x;
    cout << x * (x - 1) / 2 + y * (y - 1) / 2 << endl;
}

