struct Graph {
private:
    int V;
    int E;
    vector<int> *adjList;

public:
    Graph(int V) {
        this->V = V;
        this->E = 0;
        adjList = new vector<int>[V];
    }

    int getV() {
        return this->V;
    }

    int getE() {
        return this->E;
    }

    void addEdge(int v, int w) {
        adjList[v].push_back(w);
        adjList[w].push_back(v);
        E++;
    }

    vector<int> &adj(int v) {
        return adjList[v];
    }

    int degree(int v) {
        return adjList[v].size();
    }

    vector<pair<int, int>> &edges() {
        vector<pair<int, int>> *list = new vector<pair<int, int>>;
        for (int v = 0; v < V; v++) {
            int selfLoops = 0;
            for (int w : adj(v)) {
                if (w > v) {
                    list->push_back(make_pair(v, w));
                }
                // only add one copy of each self loop (self loops will be consecutive)
                else if (w == v) {
                    if (selfLoops % 2 == 0) list->push_back(make_pair(v, w));
                    selfLoops++;
                }
            }
        }
        return *list;
    }
} *G;

class BipartiteX {
private:
    bool WHITE = false;
    bool BLACK = true;

    bool bipartite;   // is the graph bipartite?
    bool *color;       // color[v] gives vertices on one side of bipartition
    bool *marked;      // marked[v] = true if v has been visited in DFS
    int *edgeTo;          // edgeTo[v] = last edge on path to v
    queue<int> cycle;  // odd-length cycle
    vector<int> vectorCycle;

    void bfs(Graph *G, int s) {
        queue<int> q;
        color[s] = WHITE;
        marked[s] = true;
        q.push(s);

        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int w : G->adj(v)) {
                if (!marked[w]) {
                    marked[w] = true;
                    edgeTo[w] = v;
                    color[w] = !color[v];
                    q.push(w);
                }
                else if (color[w] == color[v]) {
                    bipartite = false;

                    // to form odd cycle, consider s-v path and s-w path
                    // and let x be closest node to v and w common to two paths
                    // then (w-x path) + (x-v path) + (edge v-w) is an odd-length cycle
                    // Note: distTo[v] == distTo[w];
                    queue<int> temp;
                    swap(temp, cycle);
                    stack<int> stk;
                    int x = v, y = w;
                    while (x != y) {
                        stk.push(x);
                        cycle.push(y);
                        x = edgeTo[x];
                        y = edgeTo[y];
                    }
                    stk.push(x);
                    while (!stk.empty()) {
                        cycle.push(stk.top());
                        stk.pop();
                    }
                    cycle.push(w);
                    return;
                }
            }
        }
    }

public:
    /**
     * Determines whether an undirected graph is bipartite and finds either a
     * bipartition or an odd-length cycle.
     *
     * @param  G the graph
     */
    BipartiteX(Graph *G) {
        bipartite = true;
        color  = new bool[G->getV()];
        marked = new bool[G->getV()];
        edgeTo = new int[G->getV()];
        for (int i = 0; i < G->getV(); i++) {
            color[i] = false;
            marked[i] = false;
        }
        for (int v = 0; v < G->getV() && bipartite; v++) {
            if (!marked[v]) {
                bfs(G, v);
            }
        }
        while (!cycle.empty()) {
            vectorCycle.push_back(cycle.front());
            cycle.pop();
        }
    }

    /**
     * Returns true if the graph is bipartite.
     *
     * @return {@code true} if the graph is bipartite; {@code false} otherwise
     */
    bool isBipartite() {
        return bipartite;
    }

    /**
     * Returns the side of the bipartite that vertex {@code v} is on.
     *
     * @param  v the vertex
     * @return the side of the bipartition that vertex {@code v} is on; two vertices
     *         are in the same side of the bipartition if and only if they have the
     *         same color
     * @throws IllegalArgumentException unless {@code 0 <= v < V}
     * @throws UnsupportedOperationException if this method is called when the graph
     *         is not bipartite
     */
    bool getColor(int v) {
        if (!bipartite)
            throw runtime_error("Graph is not bipartite");
        return color[v];
    }


    /**
     * Returns an odd-length cycle if the graph is not bipartite, and
     * {@code null} otherwise.
     *
     * @return an odd-length cycle if the graph is not bipartite
     *         (and hence has an odd-length cycle), and {@code null}
     *         otherwise
     */
    vector<int> oddCycle() {
        return vectorCycle;
    }
} *bp;

int main() {
//    freopen("in.txt", "r", stdin);
//    freopen("out.txt", "w", stdout);
    _iomanager.reset(new IOManager());
    read(N, M);
    FOR(i, N) FOR(j, N) GC[i][j] = i != j;
    int a, b;
    FOR(i, M) {
        read(a, b);
        a--; b--;
        edges.eb(a, b);
        GC[a][b] = GC[b][a] = 0;
    }
    G = new Graph(N);
    FOR(i, N) FOR(j, i) if (GC[i][j]) G->addEdge(i, j);
    bp = new BipartiteX(G);
    if (!bp->isBipartite()) {
        if (M == N * (N - 1) / 2) writeln(M);
        else writeln(-1);
        return 0;
    }
    int ans = 0;
    for (pii e : edges) ans += bp->getColor(e.f) == bp->getColor(e.s);
    writeln(ans);
    return 0;
}

