	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			if(!dis[i][j]){
				x1=Find(i),x2=Find(j);
				if(x1==x2){
					puts("-1");return 0;
				}
				int y2=Find(j+n),y1=Find(i+n);
				fa[y2]=x1,fa[y1]=x2;
			}
		}
	}
	for(int i=1;i<=n;i++){x1=Find(i),size[x1]++;}
	f[0][maxn]=1;
	for(int i=1;i<=n;i++){
