vc<int> nowt;
int Buildtuan( int st ){	//return:tuansz
	intuan[st] = 1;
	nowt.clear();
	nowt.Pb(st);
	int sz = 1;
	For(u,n){
		if(intuan[u]) continue;
		bool fail = 0;
		For0(j,nowt.size()){
			int v = nowt[j];
			if(!link[u][v]){
				fail = 1;
				break;
			}
		}
		if(fail) continue;
		intuan[u] = 1;
		sz++;
		nowt.Pb(u);
	}
	return sz;
}
int Solve(){
	int sz1 = Buildtuan(1);
	if( sz1 == n ) assert(0);
	int sz2,st;
	For(i,n)
		if(!intuan[i]){
			st = i;
			sz2 = Buildtuan(i);
			break;
		}
	if( sz1+sz2 != n ) return -1;

	Ms(intuan);
	int ssz1 = Buildtuan(1);
	Ms(intuan);
	int ssz2 = Buildtuan(st);
	int cover = ssz1+ssz2-n;
	int delta = n/2-sz1;
	//cout << sz1 << " " << sz2 << endl;
	//cout << ssz1 << " " << ssz2 << endl;
	//O(cover);
	if( sz1 > sz2 ){
		int delta = n/2-sz2;
		if( cover <= delta ){
			sz1 -= cover;
			sz2 += cover;
		}else{
			sz1 = n/2;
			sz2 = n-sz1;
		}
	}

	return sz1*(sz1-1)/2 + sz2*(sz2-1)/2;
}

