int b, w;
void dfs(int v){
	if(color[v] == 1) b++;
	else w++;
	for(int i = 0; i < G[v].size(); ++i){
		int u = G[v][i];
		if(color[u] != -1){
			if(color[u] == color[v]){
				printf("-1\n");
				exit(0);
			}else continue;
		}
		color[u] = 1 - color[v];
		dfs(u);
	}
}

int C(int x){
	return x * (x - 1) / 2;
}

int solve(){
	for(int i = 0; i < N; ++i){
		color[i] = -1;
		for(int j = i + 1; j < N; ++j){
			if(!flg[i][j]){
				G[i].push_back(j);
				G[j].push_back(i);
