	int best = 0;
	for(int i = 0; i < N; ++i){
		if(color[i] != -1) continue;
		b = 0;
		w = 0;
		color[i] = 0;
		dfs(i);
		best += max(b, w);
	}
	return C(best) + C(N - best);
}

