int F(int x){ return x==d[x]?x:d[x]=F(d[x]); }
void U(int x,int y){ d[F(x)]=F(y); }

void JIZZ(){ cout<<"-1"<<endl; exit(0); }

void dfs(int now,int col){
    c[now]=col;
    v[now]=1;
    for(int i:iG[now]){
        U(now,i);
        if(v[i] && c[i]==col)JIZZ();
        else if(v[i]);
        else dfs(i,!col);
    }
}

