}edge[M<<1];
int head[N], edgeNum;
void addEdge(int from, int to){
	edge[++edgeNum].nxt = head[from];
	edge[edgeNum].to = to;
	head[from] = edgeNum;
}

int col[N], cnt[2];
void dfs(int x, int c){
	col[x] = c;
	cnt[c == 1 ? 1 : 0]++;
	for(int i = head[x]; i; i = edge[i].nxt){
		if(col[edge[i].to] && col[edge[i].to] != -c){
			puts("-1");
			exit(0);
		}
		if(!col[edge[i].to])
			dfs(edge[i].to, -c);
	}
}

