	}
	for(int i = 1; i <= n; i++){
		for(int j = 1; j < i; j++){
			if(g[i][j] == 0){
				addEdge(i, j);
				addEdge(j, i);
			}
		}
	}
	for(int i = 1; i <= n; i++)
		if(head[i] && !col[i])
			dfs(i, 1);
	for(int i = 0; i <= n - cnt[0] - cnt[1]; i++){
		ans = min(ans, n*(n-1)/2 + (i+cnt[0])*(i+cnt[0]-n));
		ans = min(ans, n*(n-1)/2 + (i+cnt[1])*(i+cnt[1]-n));
	}
	if(cnt[0] == 0 && cnt[1] == 0){
		int a = n / 2, b = n / 2;
		if(n % 2)	b++;
		ans = min(ans, a*(a-1)/2+b*(b-1)/2);
	}
