signed main() {
	INIT;

	VAR(int, n, m);
	VEC_ROW(int, m, a, b);

	std::vector<std::vector<int>> g(n, std::vector<int>(n, 0));
	std::vector<std::vector<int>> h(n, std::vector<int>(n, 0));

	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]][b[i]] = g[b[i]][a[i]] = 1;
	}

	REP(i, n) FOR(j, i + 1, n) FOR(k, j + 1, n) {
		int t = g[i][j] + g[j][k] + g[k][i];
		if (t == 0) {
			OUT(-1)BR;
			return 0;
		}
	}

	REP(i, n) REP(j, n) if (i != j) {
		h[i][j] = 1 - g[i][j];
	}

	/*SHOWVECTOR2(g);
	SHOWVECTOR2(h);

	BR
	REP(i, n) FOR(j, i + 1, n) {
		if (h[i][j]) {
			OUT(i)SP OUT(j)BR;
		}
	}*/

	std::vector<int> col(n, -1);

	std::vector<PAIR> v;

	REP(i, n) {
		if (col[i] != -1) continue;
		std::queue<int> que({ i });
		col[i] = 0;

		int cnt[2] = {1, 0};
		while (!que.empty()) {
			int now = que.front(); que.pop();
			REP(to, n) if(h[now][to]) {
				if (col[to] != -1) continue;
				++cnt[col[to] = 1 - col[now]];
				que.push(to);
			}
		}
		v.emplace_back(PAIR(cnt[0], cnt[1]));
	}

	auto check = [&](int d) -> bool {
		std::vector<std::vector<std::vector<bool>>> dp(v.size() + 1, std::vector<std::vector<bool>>(d + 1, std::vector<bool>(d + 1, false)));
		dp[0][0][0] = true;
		REP(i, v.size()) REP(j, d + 1) REP(k, d + 1){
			if (!dp[i][j][k]) continue;
			if (j + v[i].first <= d && k + v[i].second <= d) dp[i + 1][j + v[i].first][k + v[i].second] = true;
			if (j + v[i].second <= d && k + v[i].first <= d) dp[i + 1][j + v[i].second][k + v[i].first] = true;
		}
		bool res = false;
		REP(j, d + 1) REP(k, d + 1) res |= dp[v.size()][j][k];
		return res;
	};
	int ng = 0, ok = n;
	while (ok - ng > 1) {
		int md = (ok + ng) / 2;
		if (check(md)) ok = md;
		else ng = md;
	}
	OUT(num(ok) + num(n - ok))BR;
	return 0;
}

/*

答えは i(i-1)/2 + (n-i)(n-i-1)/2 の形
(もしくは -1)

ある3点がどれも互いに隣接していなければ-1

*/

#include <bits/stdc++.h>

using namespace std;

vector<int> adjlist[705];
int adjmat[705][705];
bool visited[705];
int color[705];
int n, m;
int one, two;
void dfs(int x){
	for(auto i : adjlist[x]){
		if(color[i] == 0){
			color[i] = 3-color[x];
			dfs(i);
		}else if(color[i] != 3-color[x]){
			cout << -1;
			exit(0);
		}
	}
}
void cfs(int x){
	if(visited[x]) return;
	visited[x] = true;
	if(color[x] == 1) one++;
	else two++;
	for(auto i : adjlist[x]){
		if(!visited[i]) cfs(i);
	}
}
typedef pair<int, int> pi;
vector<pi> items;
bool dp[705];
int main(){
	cin >> n >> m;
	for(int i = 0; i<m; i++){
		int a,b; cin >> a >> b;
		adjmat[a][b] = adjmat[b][a] = true;
	}
	for(int i = 1; i<=n; i++){
		for(int j = 1; j<=n; j++){
			if(i == j) continue;
			if(adjmat[i][j] == false) adjlist[i].push_back(j);
		}
	}
	for(int i = 1; i<=n; i++){
		if(color[i] == 0){
			color[i] = 1;
			dfs(i);
			one = two = 0;
			cfs(i);
			items.push_back(pi(one, two));
		}
	}
	dp[0] = true;
	int total = 0;
	for(auto i : items){
		for(int x = n; x>=0; x--){
			if((x-i.first >= 0 and dp[x-i.first]) or (x-i.second >= 0 and dp[x-i.second])){
				dp[x] = true;
			}
		}
		total += i.first + i.second;
	}
	int ans = INT_MAX;
	for(int i=0; i<=n; i++){
		if(dp[i] and dp[total-i]){
			int j = total - i;
			ans = min(ans, i*(i-1)/2 + j*(j-1)/2);
		}
	}
	if(ans == INT_MAX) cout << -1;
	else
	cout << ans;
}

