template <typename T> struct CheckBipartiteGraph{
  vector<bool> is_bipartite_graph;
  vector<pair<int,int>> component_size;
  bool all_bipartite;

  CheckBipartiteGraph(const Graph<T> &g): all_bipartite(true){
    int n = g.size();

    vector<int> check(n,-1);
    vector<bool> visit(n,false);

    REP(i,n){
      if(visit[i]) continue;

      int a,b;
      bool t = aux(g,i,check,visit,a,b);
      is_bipartite_graph.push_back(t);
      component_size.push_back(make_pair(a,b));

      if(not t){
        all_bipartite = false;
      }
    }
  }

  bool aux(const Graph<T> &graph, int root, vector<int> &check, vector<bool> &visit, int &a, int &b){
    stack<int> st;

    a = 1;
    b = 0;
    st.push(root);
    check[root] = 0;

    while(!st.empty()){
      auto cur = st.top(); st.pop();
      if(visit[cur]) continue;
      visit[cur] = true;

      for(auto &e : graph[cur]){
        if(check[e.to] == check[cur]) return false;

        if(check[e.to] == -1){
          if(check[cur] == 0){
            check[e.to] = 1;
            ++b;
          }else{
            check[e.to] = 0;
            ++a;
          }
          st.push(e.to);
        }
      }
    }

    return true;
  }
};


