class UnionFind {
public:
	vector<ll> v;
	UnionFind(size_t size) : v(size, -1) {}

	ll root(ll x) {
		return (v[x] < 0 ? x : v[x] = root(v[x]));
	}

	bool is_root(ll x) {
		return x == root(x);
	}

	bool is_same(ll x, ll y) {
		return root(x) == root(y);
	}

	bool unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (v[x] > v[y]) swap(x, y);
		v[x] += v[y];
		v[y] = x;
		return true;
	}

	ll size(ll x) {
		return -v[root(x)];
	}
};

bool isBipartiteGraph(vector<vector<ll>> &g,ll v,vector<ll> &seen){
	for(ll nextv:g[v]){
		if(seen[nextv]){
			if(seen[nextv]==seen[v])return false;
			else continue;
		}
		seen[nextv]=-1*seen[v];
		bool b=isBipartiteGraph(g,nextv,seen);
		if(!b)return false;
	}
	return true;
}
