int color(int x, int p){
  int r = 0;
  for(auto y: edges[x]){
    if(y == p) continue;
    if(!colors[y]){
//printf("%d = %d\n", y, -colors[x]);
      colors[y] = -colors[x];
      if(colors[y] > 0) r++;
      else r--;
      r += color(y, x);
      if(!bipartite) return 0;
    }
    else if(colors[y] == colors[x]){
//printf("COnflict %d %d\n", x, y);
      bipartite = false;
      return 0;
    }
  }
  return r;
}

