int Root(int u) {
  if (par[u] == u) return u;
  return par[u] = Root(par[u]);
}

bool Same(int u, int v) {
  return Root(u) == Root(v);
}

void Unite(int u, int v) {
  u = Root(u);
  v = Root(v);
  if (u == v) return;

  if (size[u] < size[v]) {
    par[u] = v;
  } else {
    par[v] = u;
  }
  size[u] = size[v] = size[u] + size[v];
  elem[u] = elem[v] = elem[u] + elem[v];
}

bool Join(int u, int v) {
  Unite(u, v+N);
  Unite(u+N, v);
  return Same(u, v);
}

