  rep(i, g) {
    int a, b;
    tie(a, b) = ps[i];
    rep(j, N+1) {
      if (!psum[i][j]) continue;
      if (j+a <= N) psum[i+1][j+a] = true;
      if (j+b <= N) psum[i+1][j+b] = true;
    }
  }

  int ans = M;
