          dp[i + 1][j + cnts[i][1]] = true;
        }
      }
    }
    int ans = -1;
    for (int i = 0; i <= N; i++){
      if (dp[ccnt][i]){
        ans = max(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
      }
    }
    cout << ans << endl;
  }
}

