                if(j>=cur.second)
                    dp[t^1][j]|=dp[t][j-cur.second];
                if(j>=cur.first)
                    dp[t^1][j]|=dp[t][j-cur.first];
            }
            t^=1;
        }
    }
    if(!ok) ans=-1;
    else
    {
        int tmp=0;
        for(int i=1;i<=n;i++)
        {
            if(dp[t][i]) tmp=max(tmp,i*(n-i));
        }
        ans=m-(tmp-cc);
    }
    print(ans);
}

