inline int Ask(int x) {
	if (!fa[x]) return x;
	int tmp = Ask(fa[x]);
	rl[x] ^= rl[fa[x]];
	return fa[x] = tmp;
}
inline void Merge(int x, int y) {
	int u = Ask(x), v = Ask(y);
	if (u == v) {
		if (rl[x] == rl[y]) puts("-1"), exit(0);
		return;
	}
	fa[u] = v;
	rl[u] = rl[x] ^ rl[y] ^ 1;
}
inline void Append(int x, int y) {
	for (int i = n; ~i; --i) {
		f[i] = 0;
		if (i >= x) f[i] |= f[i - x];
		if (i >= y) f[i] |= f[i - y];
	}
}
