		mp[x][y] = 1;
	}
	for (int i = 1; i <= n; ++i)
		for (int j = i + 1; j <= n; ++j)
			if (!mp[i][j]) Merge(i, j);
	for (int i = 1; i <= n; ++i) {
		Ask(i);
		++g[Ask(i)][rl[i]];
	}
	f[0] = 1;
	for (int i = 1; i <= n; ++i) if (!fa[i]) Append(g[i][0], g[i][1]);
	int ans = n >> 1;
	while (!f[ans]) --ans;
	printf("%d\n", ans * (ans - 1) / 2 + (n - ans) * (n - ans - 1) / 2);
	return 0;
}

