template< typename T>
struct UnionFind{
private:
    vector<T> par;
    vector<T> rank;
    vector<Pll> sz;
    int n;

public:
    //n要素で親を初期化、par[x]はxの親を表す
    UnionFind(int n): n(n) {
        par.resize(n,0);
        rank.resize(n,0);
        for(int i = 0; i < n; i++){
            par[i] = i;
        }
    }

    void init(vector<ll> &color){
        sz.resize(n);
        rep(i,0,n){
            if(color[i] == 0)sz[i].first = 1;
            else sz[i].second = 1;
        }
    }

    //木の根を求める
    int root(int x){
        if(par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    //xとyの属する集合を併合
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            swap(x,y);
        }

        par[y] = x;
        sz[x].first += sz[y].first;
        sz[x].second += sz[y].second;
        if(rank[x] == rank[y]) rank[x]++; 
    }

    //xとyが同じ集合に属するか否か
    bool same(int x, int y){
        return root(x) == root(y);
    }

