struct UnionFind
{
    vector< int > data;

    UnionFind(int sz)
    {
        data.assign(sz, -1);
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if(x == y) return(false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return(true);
    }

    int find(int k)
    {
        if(data[k] < 0) return(k);
        return(data[k] = find(data[k]));
    }

    int size(int k)
    {
        return(-data[find(k)]);
    }
};

struct Bipartite_Graph : UnionFind
{
    vector< int > color;

    Bipartite_Graph(int v) : color(v + v, -1), UnionFind(v + v) {}

    bool bipartite_graph_coloring()
    {
        for(int i = 0; i < color.size() / 2; i++) {
            int a = find(i);
            int b = find(i + (int) color.size() / 2);
            if(a == b) return (false);
            if(color[a] < 0) color[a] = 0, color[b] = 1;
        }
        return (true);
    }

    bool operator[](int k)
    {
        return (bool(color[find(k)]));
    }
};

int N;
vector<pair<int, int>> continuities;

int dp[1000][1000];

int choose(int now, int sum){
    if(now == continuities.size()){
        return sum * (sum - 1) / 2 + (N - sum) * (N - sum - 1) / 2;
    }else if(dp[now][sum] != -1){
        return dp[now][sum];
    }else{
        return dp[now][sum] = min(choose(now + 1, sum + continuities[now].first), choose(now + 1, sum + continuities[now].second));
    }
}

int main(){
