const int N=705;

vector<int>G[N];
int is[N][N];

void add_edge(int u,int v){
	G[u].push_back(v);
	G[v].push_back(u);
}

int tag[N];
bool flag=1;

void dfs(int u,int& b,int& w){
	for(int i=0;i<(int)G[u].size();i++){
		int v=G[u][i];
		if(tag[v]==0){
			tag[v]=3-tag[u];
			if(tag[v]==1) b++;
			else w++;
			dfs(v,b,w);
		}
		else{
			if(tag[u]==tag[v]){
				flag=0;
			}
		}
	}
}

int c[N],d[N];
#include <bitset>
bitset<N>dp;

int C(int n){
	return n*(n-1)/2;
}

void solve(){
	int n,m;
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++){
		int u,v;
		scanf("%d%d",&u,&v);
		is[u][v]=is[v][u]=1;
	}
	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			if(!is[i][j]){
				add_edge(i,j);
			}
		}
	}
	mem(tag,0);

	int cnt=0;
	for(int i=1;i<=n;i++){
		if(tag[i]==0){
			int b=0,w=0;
			b++;
			tag[i]=1;
			dfs(i,b,w);
			++cnt;
			c[cnt]=b,d[cnt]=w;
		}
	}

	if(!flag){
		printf("-1\n");
		return ;
	}

	dp.reset();
	dp[0]=1;
	for(int i=1;i<=cnt;i++){
		dp=(dp<<c[i])|(dp<<d[i]);
	}

	for(int i=n/2;i>=0;i--){
		if(dp[i]){
			printf("%d\n",C(i)+C(n-i));
			return ;
		}
	}
}

int main(){
    //freopen("in.txt","r",stdin);
    //freopen("out.txt","w",stdout);

	solve();
    return 0;
}

