struct UF{
	int t[MX], c1[MX], c2[MX];
	int find(int x){ return t[x] ? t[x] = find(t[x]) : x; }
	int merge(int a, int b){ // a <- b
		a = find(a), b = find(b);
		if(a == b) return false;
		t[b] = a; c1[a] += c1[b]; c2[a] += c2[b];
		return true;
	}
