	}
	for(int i = 1; i <= N; i++) uf.c1[i*2] = uf.c2[i*2+1] = 1;
	for(pii c : L){
		uf.merge(c.first*2, c.second*2+1);
		uf.merge(c.second*2, c.first*2+1);
	}

	for(int i = 1; i <= N; i++) if(uf.find(i*2) == uf.find(i*2+1)) return !printf("-1\n");

