		for(int i = 0; i <= N; i++) tdp[i] = dp[i];

		int c = uf.c1[p];
		for(int t = N; t >= c; t--) tdp[t] |= dp[t-c];

		c = uf.c2[p];
		for(int t = N; t >= c; t--) tdp[t] |= dp[t-c];

		for(int i = 0; i <= N; i++) dp[i] = tdp[i];
	}
	int ans = 1e9;
	for(int i = 1; i < N; i++) if(dp[i]) ans = min(ans, i*(i-1)/2 + (N-i)*(N-i-1)/2);
	if(ans == 1e9) ans = -1;
	printf("%d\n", ans);
}

