int main(){
	int N, M;
	while(cin >> N >> M){
		vector<vector<int>> adj(N, vector<int>(N, 0));
		for(int i=0;i<M;i++){
			int a, b; cin >> a >> b;
			--a; --b;
			adj[a][b] = adj[b][a] = 1;
		}
		vector<vector<int>> g(N);
		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				if(adj[i][j]) continue;
				g[i].push_back(j);
				g[j].push_back(i);
			}
		}
		vector<vector<int>> vc;
		vector<int> team(N, -1);
		bool valid = true;
		for(int i=0;i<N;i++){
			if(team[i] != -1) continue;
			vector<int> cnt(2, 0);
			team[i] = 0;
			++cnt[0];
			queue<int> qu; qu.push(i);
			while(!qu.empty()){
				int p = qu.front(); qu.pop();
				for(int t : g[p]){
					if(team[t] == team[p]) valid = false;
					if(team[t] != -1) continue;
					team[t] = 1 - team[p];
					cnt[team[t]]++;
					qu.push(t);
				}
			}
			if(!valid) break;
			vc.push_back(cnt);
		}
		int sum = 0;
		for(const auto& cnt : vc){
			for(auto add : cnt) sum += add;
		}
		if(!valid || sum != N){
			cout << -1 << endl;
			continue;
		}
		vector<int> dp(N+1, 0);
		dp[0] = 1;
		for(const auto& cnt : vc){
			for(int i=N;i>=0;i--){
				if(!dp[i]) continue;
				for(auto add : cnt) dp[i+add] = 1;
			}
		}
		int res = M;
		for(int i=1;i<N;i++){
			if(!dp[i]) continue;
			res = min(res, i*(i-1)/2 + (N-i)*(N-i-1)/2);
		}
		cout << res << endl;
	}
}

