bool used[710];

pi loop(int v, int c) {
	color[v] = c;
	used[v] = true;
	// debug(v, c);
	pi res(0, 0);
	if(c == 0) res.fst++;
	else res.sec++;
	rep(i, 0, N) {
		if(E[v][i]) {
			if(!used[i]) {
				pi p = loop(i, c ^ 1);
				if(p.fst >= inf) return pi(inf, inf);
				res.fst += p.fst;
				res.sec += p.sec;
			}
			else {
				if(color[i] == c) {
					return pi(inf, inf);
				}
			}
		}
	}
	return res;
}

void solve() {
	cin >> N >> M;
	rep(i, 0, N) {
		rep(j, 0, N) {
			if(i == j) continue;
			E[i][j] = 1;
		}
	}
	rep(i, 0, M) {
		int a, b; cin >> a >> b; a--; b--;
		E[a][b] = 0;
		E[b][a] = 0;
	}
	// rep(i, 0, N) {
	// 	rep(j, i + 1, N) {
	// 		// debug(i, j, E[i][j]);
	// 	}
	// }
	int K = 0;
	rep(i, 0, N) {
		if(!used[i]) {
			P[K++] = loop(i, 0);
			if(P[K - 1].fst >= inf) {
				cout << "-1\n";
				return;
			}
		}
	}
	dp[0][0] = 1;
	rep(i, 0, K) {
		rep(j, 0, N + 1) {
			if(!dp[i][j]) continue;
			dp[i + 1][j + P[i].fst] = 1;
			dp[i + 1][j + P[i].sec] = 1;
		}
	}
	int res = inf;
	rep(i, 0, N + 1) {
		if(dp[K][i]) {
			MIN(res, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
		}
	}
	cout << res << "\n";
}

