template <typename T> struct CheckBipartiteGraph{

  static bool is_bipartite_graph(const Graph<T> &g, vector<pair<int,int>> &ret){
    int n = g.size();

    vector<int> check(n,-1);
    vector<bool> visit(n,false);

    REP(i,n){
      if(visit[i]) continue;

      int a,b;
      if(aux(g,i,check,visit,a,b)){
        ret.push_back(make_pair(a,b));
      }else{
        return false;
      }
    }

    return true;
  }

  static bool aux(const Graph<T> &graph, int root, vector<int> &check, vector<bool> &visit, int &a, int &b){
    stack<int> st;

    a = 1;
    b = 0;
    st.push(root);
    check[root] = 0;

    while(!st.empty()){
      auto cur = st.top(); st.pop();
      if(visit[cur]) continue;
      visit[cur] = true;

      for(auto &e : graph[cur]){
        if(check[e.to] == check[cur]) return false;

        if(check[e.to] == -1){
          if(check[cur] == 0){
            check[e.to] = 1;
            ++b;
          }else{
            check[e.to] = 0;
            ++a;
          }
          st.push(e.to);
        }
      }
    }

    return true;
  }
};


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N,M;
  while(cin >> N >> M){
    Graph<int> graph(N);
    REP(i,M){
      int a,b; cin >> a >> b; --a, --b;
      add_undirected(graph,a,b,1);
    }

    Graph<int> cogra(N);

    REP(i,N){
      vector<int> t(N,1);
      t[i] = 0;
      for(auto &e : graph[i]) t[e.to] = 0;

      REP(j,N) if(t[j]) add_edge(cogra,i,j,1);
    }

    vector<pair<int,int>> ps;
    bool no_ans = !CheckBipartiteGraph<int>::is_bipartite_graph(cogra,ps);

    if(no_ans){
      cout << -1 << endl;
    }else{
      vector<bool> dp(2*N+1);

      REP(i,(int)ps.size()){
        auto &p = ps[i];
        vector<bool> dp1(2*N+1);
        if(!i) dp1[p.fst] = true;
        REPE(i,N) dp1[i+p.fst] = dp1[i+p.fst] || dp[i];

        vector<bool> dp2(2*N+1);
        if(!i) dp2[p.snd] = true;
        REPE(i,N) dp2[i+p.snd] = dp2[i+p.snd] || dp[i];

        REPE(i,N) dp[i] = dp1[i] || dp2[i];
      }

      int ans = 1e9;
      REPE(i,N){
        if(dp[i]) chmin(ans, i*(i-1)/2 + (N-i)*(N-i-1)/2);
      }

      cout << ans << endl;
    }
  }

  return 0;
}

