bitset<705> adj[705];
vector<int> G[705];
int col[705];

ii dfs(int u, int c) {
	col[u] = c;
	ii ret(1, 0);
	for (auto& v : G[u]) {
		if (col[v] == c) return ii(-1, -1);
		if (col[v] == -1) {
			ii tmp = dfs(v, !c);
			if (tmp == ii(-1, -1)) return ii(-1, -1);
			ret.first += tmp.second;
			ret.second += tmp.first;
		}
	}
	return ret;
}

int main() {
	int N, M;
	cin >> N >> M;
	while (M--) {
		int a, b;
		cin >> a >> b;
		adj[a][b] = adj[b][a] = 1;
	}

	for (int u = 1; u <= N; ++u) {
		for (int v = 1; v < u; ++v) {
			if (adj[u][v] == 0) {
				G[u].push_back(v);
				G[v].push_back(u);
			}
		}
	}

	memset(col, -1, sizeof(col));
	vector<ii> v;
	for (int i = 1; i <= N; ++i) {
		if (!G[i].empty() && col[i] == -1) {
			ii tmp = dfs(i, 0);
			if (tmp == ii(-1, -1)) {
				cout << -1 << '\n';
				return 0;
			}
			v.push_back(tmp);
		}
	}

	bitset<705> dp[705];
	dp[0][0] = 1;
	for (int i = 0; i < v.size(); ++i) {
		for (int j = 0; j <= N; ++j) {
			if (dp[i][j]) {
				if (j + v[i].first - v[i].second >= 0) dp[i + 1][j + v[i].first - v[i].second] = 1;
				if (j - v[i].first + v[i].second >= 0) dp[i + 1][j - v[i].first + v[i].second] = 1; 
			}			
		}
	}

	int x = 0, y = 0;
	while (!dp[v.size()][x]) ++x;
	for (int i = 1; i <= N; ++i) y += G[i].empty();
	assert((N - y + x) % 2 == 0);
