int used[MAXN], color[MAXN];
int sz[MAXN], head = 0;

int n, m;
int bipartite = 1;

int knapsack[MAXN][MAXN];

void dfs(int v, int c) {
	used[v] = 1;
	color[v] = c;
	sz[head] += c;

	for(int u = 0; u < n; ++u) {
		if(!adj[v][u] && u != v) {
			if(!used[u]) {
				dfs(u, c ^ 1);
			} else {
				DBG(u);
				bipartite &= (color[v] != color[u]);
			}
		}
	}
}

void solve() {
	cin >> n >> m;

	for(int i = 0; i < m; ++i) {
		int v = fetch<int>() - 1;
		int u = fetch<int>() - 1;

		adj[v][u] = adj[u][v] = 1;
	}

	for(int v = 0; v < n; ++v) {
		if(!used[v]) {
			dfs(v, 0);
			++head;
		}
	}

	DBG(bipartite);
	if(bipartite) {
		knapsack[0][0] = 1;

		for(int i = 0; i < head; ++i) {
			for(int j = 0; j < MAXN; ++j) {
				if(!knapsack[i][j]) {
					continue;
				}

				int j2 = j + sz[i];
				knapsack[i + 1][j] = 1;

				if(j2 < MAXN) {
					knapsack[i + 1][j2] = 1;
				}
			}
		}

		int answ = INT_INF;

		for(int a = 0; a < MAXN; ++a) {
			if(knapsack[head][a]) {
				int b = n - a;
				answ = min(answ, (a * (a - 1)) / 2 + (b * (b - 1)) / 2);
			}
		}

		cout << answ << '\n';
	} else {
		cout << NIL << '\n';
	}
}

int main() {
	fast_io();
	solve();

	return 0;
}

