        for(int j = 0; j <= 700; j++){
            if(sum[i - 1][j]){
                sum[i][j + discrete[i]] = true;
            }
        }
    }
    int half = 0;
    for(int j = 0; j <= 700; j++){
        if(sum[discrete.size() - 1][j]){
            if(abs(2 * n - (j + connected)) < abs(2 * n - (half + connected))){
                half = j;
            }
        }
    }
    connected = connected + half;
    cout << connected * (connected - 1) / 2 + (n - connected) * (n - connected - 1) / 2 << endl;
    return 0;
}

