bool dfs(int node,int c,int n) {
    vis[node] = true;
    color[node] = c;
    ++sz[c];
    for(int i=1;i<=n;++i) {
        if(adj[node][i]==0) {
            continue;
        }
        if(i==node) {
            continue;
        }
        if(vis[i]) {
            if(color[i]==c) {
                return false;
            }
        }
        else {
            if(!dfs(i,c^1,n)) {
                return false;
            }
        }
    }
    return true;
}

int dp[N][N];

int solveDp(vector<pair<int,int> >&v,int ind,int sz,int n) {
    if(ind == v.size()) {
        int r = n - sz;
        return (sz*(sz-1))/2 + (r*(r-1))/2;
    }
    int &ret = dp[ind][sz];
    if(ret!=-1) {
        return ret;
    }
    ret = min( solveDp(v,ind+1,sz+ v[ind].first,n),solveDp(v,ind+1,sz+v[ind].second,n));
    return ret;
}

void solve() {
    memset(dp,-1,sizeof(dp));
    int n,m;
    scanf("%d%d",&n,&m);
    memset(adj,1,sizeof(adj));
    for(int i=1;i<=n;++i) {
        adj[i][i] = 0;
    }
    for(int i=0;i<m;++i) {
        int a,b;
        scanf("%d%d",&a,&b);
        adj[a][b] = adj[b][a] = 0;
    }
