        if(!vis[i]) {
            memset(sz,0,sizeof(sz));
            if(!dfs(i,0,n)) {
                printf("-1\n");
                return;
            }
            v.push_back(make_pair(sz[0],sz[1]));
        }
    }
    printf("%d\n", solveDp(v,0,0,n));
}

