    e[A[i]][B[i]] = 1;
    e[B[i]][A[i]] = 1;
  }
  REP(i,N) REP(j,i) {
    if (e[i][j] == 0) {
      uf.unite(i * 2 + 0, j * 2 + 1);
      uf.unite(i * 2 + 1, j * 2 + 0);
    }
  }
