using namespace std;

const int maxn = 700 + 7;

int tot;
int n, m;
int color[maxn];
bool vis[maxn], mat[maxn][maxn];
int o[maxn];
bool ok[maxn];

void bfs(int _u) {
  int s[2]; s[0] = s[1] = 0;

  int h = 0, t = 0;
  o[h] = _u;
  vis[_u] = true;
  color[_u] = 0; s[0]++;

  while (h <= t) {
    int u = o[h]; h++;
    for (int i = 1; i <= n; i++) 
      if (mat[u][i]) {
        if (vis[i]) {
          if (color[u] == color[i]) {
            printf("-1\n");
            exit(0);
          }
          continue;
        }
        vis[i] = true;
        color[i] = color[u] ^ 1;
        s[ color[i] ]++;
        o[++t] = i;
      }
  }
  tot += s[0] + s[1];
  for (int i = n; i >= 1; i--) 
    if (i - s[0] >= 0 && ok[i - s[0]]) ok[i] = true;
    else if (i - s[1] >= 0 && ok[i - s[1]]) ok[i] = true;
}

int main(int argc, char **argv) {
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= n; j++) mat[i][j] = !(i == j);
  for (int i = 1; i <= m; i++) {
    int u, v;
    scanf("%d%d", &u, &v);
    mat[u][v] = mat[v][u] = false;
  }
  ok[0] = true;
  for (int i = 1; i <= n; i++) 
    if (!vis[i]) bfs(i);

  int ans = n * n;
  //assert(tot == n);
  for (int i = 1; i < n; i++) 
    assert(ok[i] == ok[n - i]);
  for (int i = n - 1; i >= 1; i--) {
    if (ok[i]) {
      ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
  }
  printf("%d\n", ans);
  return 0;
}

