int min_unchecked(void) {
	for (int i = 0; i < N; i++) {
		if (team[i] == -1) { return i; }
	}
	return N;
}

int main(void) {
	/*まず辺のあるなしを逆にしておく*/
	scanf("%d %d", &N, &M);
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			edge[i][j] = 1;/*まず全部つないでおく*/
		}
	}

	for (int i = 0; i < N; i++) {
		edge[i][i] = 0;
	}

	for (int i = 0; i < M; i++) {
		scanf("%d %d", &A, &B);
		edge[A - 1][B - 1] = 0;
		edge[B - 1][A - 1] = 0;
	}

	/*各連結成分ごとに、2つに分けたときにいくつずつになるのか調べる*/

	for (int i = 0; i < N; i++) {
		team[i] = -1;
	}

	int pt = 0;

	while (1) {
		p = min_unchecked();
		if (p == N) { break; }

		num_team[0] = 0;
		num_team[1] = 0;

		team[p] = 0;
		num_team[0]++;



		qu.push(p);
		while (qu.empty() == 0) {
			q = qu.front();
			qu.pop();
			for (int i = 0; i < N;i++){
				if (edge[q][i] == 0) { continue; }
				if(team[i] == -1){
					qu.push(i);
					team[i] = 1 - team[q];
					num_team[team[i]]++;
				}
				if (team[i] == team[q]) {
					printf("-1\n");
					return 0;
				}
			}
		}
		a[pt] = num_team[0];
		b[pt] = num_team[1];
