		printf("%d %d\n", a[i], b[i]);
	}
	*/

	dp[0][0] = 1;
	for (int i = 1; i <= N; i++) {
		dp[0][i] = 0;
	}

	for (int i = 1; i <= N; i++) {
		for (int c = 1; c <= pt; c++) {
			dp[c][i] = 0;
		}
	}

	for (int c = 1; c <= pt; c++) {
		for(int i = 0; i <= N; i++) {
			if (i - a[c - 1] >= 0) {
				if (dp[c - 1][i - a[c - 1]] == 1) {
					dp[c][i] = 1;
				}
			}
			if (i - b[c - 1] >= 0) {
				if (dp[c - 1][i - b[c - 1]] == 1) {
					dp[c][i] = 1;
				}
			}
		}
	}

	/*
	for (int c = 0; c <= pt; c++) {
		for (int i = 0; i <= N; i++) {
			printf("dp[%d][%d] = %d\n", c, i, dp[c][i]);
		}
	}
	*/
