	for (int i = 0; i <= N/2; i++) {
		if (dp[pt][i] == 1) {
			MM = i;
		}
	}

	printf("%d\n", (MM*(MM - 1)) / 2 + ((N - MM)*(N - MM - 1)) / 2);

}

