int graph[701][701];
bool bipartite = true;
int color[701];
vector<int> curr;
vector<pair<int,int>> pos;
bool dp[701][701];
int n;
void dfs(int x){
    curr.push_back(x);
    for(int next=0;next<n;next++){
        if(graph[x][next]){
            if(color[next]==color[x]) bipartite = false;
            else{
                if(color[next]==-1){
                    color[next] = (color[x]+1)%2;
                    dfs(next);
                }
            }
        }
    }
}
int main(){
    int m; 
    cin >> n >> m;
    for(int i=0;i<n;i++)
        for(int j=0;j<n;j++)
            graph[i][j] = 1;
    for(int i=0;i<m;i++){
        int u,v; cin >> u >> v;
        --u; --v;
        graph[u][v] = 0;
        graph[v][u] = 0;
    }
    for(int i=0;i<n;i++) graph[i][i] = 0;
    for(int i=0;i<n;i++) color[i] = -1;
    for(int i=0;i<n && bipartite;i++){
        if(color[i]==-1){
            color[i] =0;
            curr.clear();
            dfs(i);
            int x = 0;
            for(int a : curr)
                x+=color[a];
            pos.push_back({x,curr.size()-x});
        }
    }
    if(!bipartite){
        cout << -1 << endl;
        return 0;
    }
    dp[0][pos[0].first] = true;
    dp[0][pos[0].second] = true;
    for(int i=1;i<pos.size();i++){
        for(int j=0;j<701;j++){
            if(pos[i].first<=j){
                dp[i][j] = dp[i][j]||dp[i-1][j-pos[i].first];
            }
            if(pos[i].second<=j){
                dp[i][j] = dp[i][j]||dp[i-1][j-pos[i].second];
            }
        }
    }
    int best = 10000000;
    for(int j=0;j<=n;j++){
        if(dp[pos.size()-1][j]){
            best = min(best,(j*(j-1)+(n-j)*(n-j-1))/2);
        }
    }
    cout << best << endl;
}

