bool rlinked[705][705];
int groups[705];
ll aim;
ll memo_f[705][705];

ll f(const V<t2> &countlist, int idx, int sum)
{
        if (idx >= countlist.size()) return sum;
        if (memo_f[idx][sum] >= 0) return memo_f[idx][sum];

        t2 count = countlist[idx];
        ll x1 = f(countlist, idx + 1, sum + get<0>(count));
        ll x2 = f(countlist, idx + 1, sum + get<1>(count));

        if (abs(x1 - aim) < abs(x2 - aim)) return memo_f[idx][sum] = x1;
        return memo_f[idx][sum] = x2;
}

int _main()
{
        ll n, m;
        llin(n); llin(m);

        V<t2> ablist;
        llinl2(ablist, m);

