        rep (i, 705) rep (j, 705) {
                rlinked[i][j] = true;
                memo_f[i][j] = -1;
        }

        for (auto ab : ablist) {
                ll a = get<0>(ab);
                ll b = get<1>(ab);
                ll tmp = max(a, b);
                a = min(a, b);
                b = tmp;
                rlinked[a][b] = false;
        }

        UnionFind uf(n);
        V<ll> linklist[n+1];

        srep (i, 1, n+1) {
                srep (j, i+1, n+1) {
                        if (rlinked[i][j]) {
                                uf.unite(i, j);
                                linklist[i].pb(j);
                                linklist[j].pb(i);
                        }
                }
        }

        set<ll> rootlist;
        srep (i, 1, n+1) rootlist.insert(uf.root(i));
        V<t2> countlist;

        for (auto root : rootlist) {

                queue<ll> q;
                q.push(root);
                memset(groups, 0, sizeof(groups));
                groups[root] = 1;
                int counts[3];
                counts[1] = 1;
                counts[2] = 0;

                for ( ; !(q.empty()); ) {
