                                        return 0;
                                }
                                if (!groups[next]) {
                                        groups[next] = (nowg ^ 3);
                                        counts[groups[next]]++;
                                        q.push(next);
                                }
                        }
                }

                countlist.pb(t2(counts[1], counts[2]));
        }

