pair<int,int> bfs(auto &E,auto &color,int start){
	pair<int,int> ret(0,0);
	queue<int> Q;
	Q.push(start);
	color[start] = 0;
	ret.first++;
	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();
		for(int i=0;i<E[from].size();i++){
			if(E[from][i]){
				if(color[i]==-1){
					if(color[from]==0){
						color[i]=1;
						ret.second++;
					}
					else{
						color[i]=0;
						ret.first++;
					}
					Q.push(i);
				}
				else{
					if(color[from]==color[i]){
						return make_pair(-1,-1);
					}
				}
			}
		}
	}
	return ret;
}

