bool check(vi& ind) {
  if (!sz(ind)) return 1;
  int sm = 0, nod = 0;
  trav(x, ind) {
    nod++;
    trav(y, adj[x])
      sm += col[y] == col[x];
  }
  return sm == nod * (nod - 1);
}

void solve(vi& ind, int lo) {
  if (!sz(ind)) return;
  // debug(ind); cerr << lo << endl;
  int c = -1, d = inf;
  trav(x, ind)
    if (deg[x] < d)
      d = deg[x], c = x;
  if (d == sz(ind)-1) {
    for (int i = 1; i <= sz(ind); i++)
      dp[i] = 1;
    return;
  }
  col[c] = lo;
  vi lhs, rhs;
  lhs.pb(c);
  while (1) {
    bool ok = 1;
    trav(x, ind) if (!col[x]) {
      int l = 0, r = 0;
      trav(y, adj[x]) {
        l += col[y] == lo;
        r += col[y] == lo+1;
      }
      // debug(lhs);cerr << endl;
      // debug(rhs);cerr << endl;
      // cerr << l << " " << r << " " << x << endl;
      if (l != sz(lhs) && r != sz(rhs)) {
        printf("-1\n");
        exit(0);
      }
      if (l != sz(lhs)) {
        rhs.pb(x);
        col[x] = lo+1;
        ok = 0;
      } else if (r != sz(rhs)) {
        lhs.pb(x);
        col[x] = lo;
        ok = 0;
      }
    }
    if (ok) break;
  }
  if (!check(lhs) || !check(rhs)) {
    printf("-1\n");
    exit(0);
  }
  vi nx;
  trav(x, ind) if (!col[x])
    nx.pb(x);
  solve(nx, lo+2);
  dp = (dp << sz(lhs)) | (dp << sz(rhs));
}

