int color[705];
int n, m;
int one, two;
void dfs(int x){
	for(auto i : adjlist[x]){
		if(color[i] == 0){
			color[i] = 3-color[x];
			dfs(i);
		}else if(color[i] != 3-color[x]){
			cout << -1;
			exit(0);
		}
	}
}
void cfs(int x){
	if(visited[x]) return;
	visited[x] = true;
	if(color[x] == 1) one++;
	else two++;
	for(auto i : adjlist[x]){
		if(!visited[i]) cfs(i);
	}
}
typedef pair<int, int> pi;
vector<pi> items;
bool dp[705][705];
int main(){
	cin >> n >> m;
