int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int n, m; cin >> n >> m;
  vvi g(n, vi(n)), compg(n, vi(n));
  REP(i, m) {
    int a, b; cin >> a >> b;
    a--; b--;
    g[a][b] = 1;
    g[b][a] = 1;
  }

  UnionFind uf(n);
  REP(i, n) {
    REP(j, n) {
      if(i != j && !g[i][j]) {
        compg[i][j] = 1;
        uf.unite(i, j);
      }
    }
  }

  vi col(n, -1);
  bool bipartite = true;
  queue<int> que;
  que.push(0);
  col[0] = 0;
  while(!que.empty()) {
    if(!bipartite) break;
    int now = que.front(); que.pop();
    REP(i, n) {
      if(compg[now][i]) {
        if(col[i] == -1) {
          col[i] = !col[now];
          que.push(i);
        } else if(col[now] == col[i]) {
          bipartite = false;
          break;
        }
      }
    }
  }

  if(!bipartite) {
    cout << -1 << endl;
    return 0;
  }

  map<int, P> mp;
  REP(i, n) {
    int r = uf.root(i);
    if(col[i]) mp[r].first++;
    else mp[r].second++;
  }

  vector<set<int>> dp(SZ(mp)+1);
  dp[0].insert(0);
  int idx = 0;
  for(auto &e1: mp) {
    for(auto &e2: dp[idx]) {
      dp[idx+1].insert(e1.second.first + e2);
      dp[idx+1].insert(e1.second.second + e2);
    }

    idx++;
  }

  ll mi = LINF;
  for(auto &e: dp[idx]) {
    chmin(mi, e * (e - 1) / 2 + (n - e) * (n - e - 1) / 2);
  }
  cout << mi << endl;

}

