int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, m;
  cin >> n >> m;
  vector<vector<int>> a(n, vector<int>(n));
  for (int i = 0; i < m; i++) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    a[x][y] = a[y][x] = 1;
  }
  vector<vector<int>> g(n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (i != j && a[i][j] == 0) {
        g[i].push_back(j);
      }
    }
  }
  vector<int> color(n, -1);
  vector<pair<int, int>> v;
  for (int i = 0; i < n; i++) {
    if (color[i] != -1) {
      continue;
    }
    vector<int> que = {i};
    color[i] = 0;
    int cnt[2] = {0, 0};
    for (int b = 0; b < int(que.size()); b++) {
      int v = que[b];
      cnt[color[v]]++;
      for (int u : g[v]) {
        if (color[u] == -1) {
          color[u] = 1 - color[v];
          que.push_back(u);
        } else if (color[u] == color[v]) {
          cout << -1 << "\n";
          return 0;
        }
      }
    }
    v.emplace_back(cnt[0], cnt[1]);
  }
  vector<int> dp(n + 1);
  dp[0] = 1;
  int sm = 0;
  for (auto& p : v) {
    vector<int> ndp(n + 1);
    for (int i = sm; i >= 0; i--) {
      ndp[i + p.first] |= dp[i];
      ndp[i + p.second] |= dp[i];
    }
    dp = ndp;
    sm += p.first + p.second;
  }
  int ans = 1e9;
  for (int i = 0; i <= n; i++) {
    if (dp[i] == 1) {
      ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);    
    }
  }
  cout << ans << "\n";
  return 0;
}

