vector<int> v[Nmax];

void dfs(int node)
{
    if(color[node] == 1) ++A;
        else ++B;

    for(auto it : v[node])
        if(!color[it])
        {
            color[it] = 3 - color[node];
            dfs(it);
        }
        else if(color[it] + color[node] != 3) NO_SOLUTION;
}

void add_to_sol(int x, int y, int Sz)
{
    int i;
    for(i=Sz; i>=0; --i)
        if(dp[i])
        {
            dp[i] = 0;
            dp[min(i+x, Sz-i+y)] = 1;
            dp[min(i+y, Sz-i+x)] = 1;
        }
}

