ll max(ll a, ll b){return (a > b) ? a : b;}
ll min(ll a, ll b){return (a < b) ? a : b;}
ll pow_long(ll x, ll k){
  ll res = 1;
  while(k > 0){
    if(k % 2) res *= x;
    x *= x;
    k /= 2;
  }
  return res;
}
ll pow_mod(ll x, ll k){
  x %= MOD; x += MOD; x %= MOD;
  ll res = 1;
  while(k > 0){
    if(k % 2){
      res *= x; res %= MOD;
    }
    x *= x; x %= MOD;
    k /= 2;
  }
  return res;
}
ll inverse(ll x){return pow_mod(x, MOD - 2);};

//最大公約数
ll gcd(ll a, ll b){
    if(b == 0) return a;
    return gcd(b, a % b);
}

//最小公倍数
ll lcm(ll x, ll y){return x / gcd(x, y) * y;};

//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

int N, M;
bool E[710][710];
int visited[710];
bool l = 1;

void dfs(int now){
  rep(to, N){
    if(E[now][to] == 0) continue;
    if(visited[to] == -1){
      visited[to] = (visited[now] + 1) & 1;
      dfs(to);
    }else{
      if(visited[now] == visited[to]) l = 0;
    }
  }
}

bool Bip(){
  rep(i, N) visited[i] = -1;
  visited[0] = 1;
  dfs(0);
  return l;
}

void solve(){
  if(Bip() == 0){
    cout << -1 << endl;
    return;
  }
  //二部グラフである
  ll V = 0, A = 0, B = 0;
  rep(i, N)rep(j, N)if(E[i][j]) V++;
  V /= 2;
  rep(i, N){
    if(visited[i] == 1) A++;
    else if(visited[i] == 0) B++;
  }
  rep(i, N) if(visited[i] == -1){
    if(A < B) A++;
    else B++;
  }

  cout << M - (A * B - V) << endl;
}

int main(void){
  cin >> N >> M;
  rep(i, N)rep(j, N) E[i][j] = 1;
  rep(i, N) E[i][i] = 0;
  rep(i, M){
    ll A, B; cin >> A >> B; A--, B--;
    E[A][B] = 0;
    E[B][A] = 0;
  }
  solve();
}

