struct UnionFind {
	vector<int> par, rank;
	vector<int> cnt;

	UnionFind() {}
	UnionFind(int n) {
		par.resize(n);
		rank.resize(n);
		cnt.resize(n);
		REP(i, n) {
		 par[i] = i;
		 rank[i] = 0;
		 cnt[i] = 1;
		}
	}

	int operator[] (int x) {
		return find(x);
	}

	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y]) swap(x, y);

		par[y] = x;
		cnt[x] += cnt[y];
		if (rank[x] == rank[y]) rank[x]++;
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

	int size(int x) {
		return cnt[find(x)];
	}

};

vector<int> g[700];
