ll mod = 1e9 + 7;

int n, m;
int edg[800][800];
int c[800], f[800];
vector<int> g[800];
pii sz[800];
int cnt;

int color(int u)
{
	for (int j = 0; j < g[u].size(); ++j)
	{
		int &v = g[u][j];
		if (!c[v])
		{
			c[v] = c[u] ^ 1;
		}
		else if (c[v] == c[u]) return 0;
	}
	for (int j = 0; j < g[u].size(); ++j)
	{
		int &v = g[u][j];
		if (!color(v)) return 0;
	}
	return 1;
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 0; i < m; i++)
	{
		int u, v;
		scanf("%d%d", &u, &v);
		edg[u][v] = edg[v][u] = 1;
	}

	for (int i = 1; i <= n; i++) for (int j = i + 1; j <= n; j++)
	{
		if (!edg[i][j])
		{
			g[i].push_back(j);
			g[j].push_back(i);
		}
	}

	for (int i = 1; i <= n; i++) if (!c[i])
	{
		++cnt;
		c[i] = cnt << 1;
		if (color(i))
		{
			for (int j = 1; j <= n; j++)
				if (c[i] == cnt << 1) ++sz[cnt].first;
				else if (c[i] == (cnt << 1) ^ 1) ++sz[cnt].second;
		}
		else --cnt;
	}

	f[0] = 1;
	for (int i = 1; i <= cnt; i++)
	{
		for (int j = 1; j <= n; j++)
		{
			if(j>=sz[i].first) f[j] |= f[j - sz[i].first];
			if (j >= sz[i].second) f[j] |= f[j - sz[i].second];
		}
	}

	int ans = 700 * 700;
	for (int j = 1; j <= n; j++) if(f[j])
	{
		ans = min(ans, j*(j - 1) / 2 + (n - j)*(n - j - 1) / 2);
	}
	printf("%d", ans);
}

