#include <bits/stdc++.h>

using namespace std;

const int maxN = 700;

struct DisjointSets {
	static const int maxn = maxN;

	int n;
	int p[maxn];
	int f[maxn];

	DisjointSets() : n(0) {

	}

	void resize(const int & n) {
		this->n = n;
		memset(p, -1, sizeof p[0] * n);
		memset(f, 0, sizeof f[0] * n);
	}

	int root(const int & u) {
		if (p[u] < 0)
			return u;
		else {
			int r = root(p[u]);
			f[u] ^= f[p[u]];
			return p[u] = r;
		}
	}

	bool union_sets(const int & u, const int & v, const int & x) {
		int ur = root(u), vr = root(v);
		if (ur == vr)
			return x == (f[u] ^ f[v]);
		else {
			if (p[ur] > p[vr])
				swap(ur, vr);
			p[ur] += p[vr];
			p[vr] = ur;
			f[vr] = f[u] ^ f[v] ^ x;
			return true;
		}
	}
};

int N, M;
bool E[maxN][maxN];
DisjointSets DS;
int deg[maxN][2];
bool vis[maxN + 1];

int answer() {
	DS.resize(N);
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			if (!E[i][j]) {
				if (!DS.union_sets(i, j, 1))
					return -1;
			}
		}
	}
	for (int u = 0; u < N; u++) {
		int r = DS.root(u);
		deg[r][DS.f[u]]++;
	}

	vector<int> dff;
	for (int u = 0; u < N; u++)
		dff.push_back(abs(deg[u][0] - deg[u][1]));
	int ttl = accumulate(dff.begin(), dff.end(), 0);
	int lmt = ttl / 2;
	vis[0] = true;
	for (const auto & x : dff) {
		for (int i = lmt - x; i >= 0; i--)
			vis[i + x] |= vis[i];
	}
	int lwr = lmt;
	for (; !vis[lwr]; lwr--);
	int lhs = lwr + (N - ttl) / 2, rhs = N - lhs;
	return (lhs * (lhs - 1) + rhs * (rhs - 1)) / 2;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	cin >> N >> M;
	for (int i = 0; i < M; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		E[u][v] = E[v][u] = true;
	}

	cout << answer() << '\n';

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int inf = 1e9;

bool dfs(vector<vector<int>> const& g, vector<int>& col, int v, int& sz1, int& sz2, int c) {
    if(col[v] != -1 && c != col[v]) return false;
    if(col[v] != -1) return true;
    col[v] = c;
    sz1 += c; sz2 += !c;
    bool res = true;
    for(int i = 0; i < (int)g.size(); ++i) {
        if(g[v][i] == 0 || i == v) continue;
        res &= dfs(g, col, i, sz1, sz2, !c);
    }
    return res;
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n, vector<int>(n, 1));
    for(int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        g[a - 1][b - 1] = g[b - 1][a - 1] = 0;
    }

    vector<int> sz1, sz2, col(n, -1);
    for(int i = 0; i < n; ++i) {
        if(col[i] != -1) continue;
        int s1 = 0, s2 = 0;
        if(!dfs(g, col, i, s1, s2, 0)) {
            cout << -1 << endl;
            return 0;
        }
        sz1.push_back(s1), sz2.push_back(s2);
    }
    vector<int> dp(n + 1, -inf);
    dp[0] = 0;
    const int sz = sz1.size();
    int sum = 0;
    for(int i = 0; i < sz; ++i) {
        vector<int> nxt(n + 1, -inf);
        for(int j = 0; j <= n; ++j) {
            if(dp[j] == -inf) continue;
            int k = sum - j;
            nxt[j + sz1[i]] = max(nxt[j + sz1[i]], dp[j] + sz1[i] * k + sz2[i] * j + sz1[i] * sz2[i]);
            nxt[j + sz2[i]] = max(nxt[j + sz2[i]], dp[j] + sz2[i] * k + sz1[i] * j + sz1[i] * sz2[i]);
        }
        dp = move(nxt);
    }

    int ans = 0;
    for(int i = 0; i <= n; ++i) {
        ans = max(ans, dp[i]);
    }
    ans -= n * (n - 1) / 2 - m;
    ans = m - ans;

