	next[e]=begin[x];
	begin[x]=e;
	if(k)add(y,x,0);
}

bool predfs(int p,int c=1)
{
	if(col[p])return col[p]==c;

	col[p]=c;

	for(int i=begin[p];i;i=next[i])
		if(!predfs(to[i],3-c))return 0;

	return 1;
}

bool judge()
{
	for(int i=1;i<=n;i++)
		if(!col[i] && !predfs(i))return 0;
	return 1;
}

