int n, m;

ll solve(vector<int> a, vector<int> b){
    rep(i, m) a[i]--, b[i]--;

    set<int> g[n];
    rep(from, n){
        rep(to, n){
            if(from == to) continue;
            g[from].insert(to);
        }
    }
    rep(i, m){
        g[a[i]].erase(b[i]);
        g[b[i]].erase(a[i]);
    }

    set<int> left, right;

    rep(i, n){
        if(0 < g[i].size()){
            left.insert(i);
            break;
        }
    }

    bool update = true;
    while(update){
        update = false;
        for(auto l : left){
            for(auto to : g[l]){
                if(0 < left.count(to))  return -1;
                if(0 < right.count(to)) continue;

                right.insert(to);
                update = true;
            }
        }

        for(auto r : right){
            for(auto to : g[r]){
                if(0 < right.count(to)) return -1;
                if(0 < left.count(to))  continue;

                left.insert(to);
                update = true;
            }
        }
    }

    set<int> unused;
    rep(i, n) unused.insert(i);
    for(auto x : left) unused.erase(x);
    for(auto x : right) unused.erase(x);

    for(auto x : unused){
        if((int)g[x].size() != 0) return -1;
    }

    int ln = left.size();
    int rn = right.size();
    int rem = n - ln - rn;

    rep(i, rem){
        if(ln < rn) ln++;
        else        rn++;
    }

    return (ln*(ln-1) + rn*(rn-1))/2;
}

