int N, M;
bool edges[700][700];



int main(){
    cin >> N >> M;
    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            edges[i][j] = true;
        }
    }
    for(int i = 0; i < M; i++){
        int a, b;
        cin >> a >> b;
        edges[a-1][b-1] = edges[b-1][a-1] = false;
    }

    stack<pair<int, int> > stk; // now idx, now color
    int color[700] = {};
    int st[2][700];
    bool is_separable = true;
    for(int i = 0; i < N; i++){
        if(color[i] == 0){
            stk.push(make_pair(i, 1));
            color[i] = 1;
            while(!stk.empty()){
                int now = stk.top().first;
                int now_color = stk.top().second;
                stk.pop();
                st[now_color - 1][i]++;
                for(int j = 0; j < N; j++){
                    if(edges[now][j] && now != j && color[now] == color[j]){
                        is_separable = false;
                    }else if(edges[now][j] && color[j] == 0){
                        color[j] = (color[now] % 2) + 1;
                        stk.push(make_pair(j, color[j]));
                    }
                }
            }
        }
    }
    if(!is_separable){
        cout << -1 << endl;
        return 0;
    }
    bool dp[701][701] = {};
    dp[0][0] = true;
    for(int i = 0; i < N; i++){
        for(int j = 0; j <= N; j++){
            if(dp[i][j] && j + st[0][i] <= 700){
                dp[i+1][j + st[0][i]] = true;
            }
            if(dp[i][j] && j + st[1][i] <= 700){
                dp[i+1][j + st[1][i]] = true;
            }
        }
    }
    int  ans = M;
    for(int i = 0; i <= N; i++){
        if(dp[N][i]){
            ans = min(ans, i*(i-1)/2 + (N-i)*(N-i-1)/2);
        }
    }
    cout << ans << endl;

}

