#include <bits/stdc++.h>

using namespace std;

const int N=707;

int adj[N][N];
int mem[N][N],col[N];
int n,m;
vector<pair<int,int> > got;
int co[2];

int go(int node,int c)
{
	if(col[node]!=-1) return col[node]==c;
	col[node]=c;
	co[c]++;
	int ans=1;
	for(int i=1;i<=n;i++)
	{
		if(adj[node][i]||node==i) continue;
		ans&=go(i,c^1);
	}
	return ans;
}

int can(int x,int y)
{
	if(y<0) return 0;
	if(x==got.size()) return (y==0?1:0);
	if(mem[x][y]!=-1) return mem[x][y];
	return mem[x][y]=go(x+1,y-got[x].first)|go(x+1,y-got[x].second);
}

int main()
{
	scanf("%d %d",&n,&m);
	while(m--)
	{
		int x,y;
		scanf("%d %d",&x,&y);
		adj[x][y]=adj[y][x]=1;
	}
	memset(col,-1,sizeof col);
	for(int i=1;i<=n;i++)
	{
		if(col[i]==-1)
		{
			co[0]=co[1]=0;
			if(!go(i,0))
			{
				printf("-1\n");
				return 0;
			}
			got.push_back({co[0],co[1]});
		}
	}
	int ans=(1<<30);
	for(int i=0;i<=n;i++)
	{
		int y=n-i;
		memset(mem,-1,sizeof mem);
		if(can(0,i)) ans=min(ans,i*(i-1)/2+y*(y-1)/2);
	}
	assert(ans!=(1<<30));
	printf("%d\n",ans);
}

#include <bits/stdc++.h>
using namespace std;

const int maxn = 710;
int n, m, col[maxn], fa[maxn];
bool G[maxn][maxn], f[maxn], g[maxn];
vector<int> H[maxn];

int find(int x) {
    return x == fa[x] ? x : fa[x] = find(fa[x]);
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++) {
        fa[i] = i;
        for (int j = 1; j <= n; j++) {
            G[i][j] = 1;
        }
    }
    for (int i = 1, u, v; i <= m; i++) {
        scanf("%d %d", &u, &v);
        G[u][v] ^= 1, G[v][u] ^= 1;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) if (i ^ j && G[i][j]) {
            fa[find(i)] = find(j), H[i].push_back(j);
        }
    }
    memset(col, -1, sizeof(col));
    function<void(int)> dfs = [&](int v) {
        for (int u : H[v]) if (!~col[u]) {
            col[u] = col[v] ^ 1, dfs(u);
        }
    };
    for (int i = 1; i <= n; i++) {
        if (i == find(i)) col[i] = 0, dfs(i);
    }
    for (int i = 1; i <= n; i++) {
        for (int j : H[i]) if (col[i] == col[j]) {
            printf("-1\n"), exit(0);
        }
    }
    for (int i = f[0] = 1; i <= n; i++) if (i == find(i)) {
        int cnt1 = 0, cnt2 = 0;
        for (int j = 1; j <= n; j++) if (i == find(j)) {
            if (col[j]) cnt1++;
            else cnt2++;
        }
        memcpy(g, f, sizeof(g));
        for (int j = 0; j <= n; j++) {
            f[j] = 0;
            if (j >= cnt1) f[j] |= g[j - cnt1];
            if (j >= cnt2) f[j] |= g[j - cnt2];
        }
    }
    int mn = INT_MAX;
    for (int i = 0; i <= n; i++) {
        if (f[i]) mn = min(mn, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
    printf("%d\n", mn);
    return 0;
}

