constexpr int DEBUG = 0;

template<typename T>
vector<vector<T>> Make2DVector(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

struct Edge {
  const int from, to;
  Edge(int from, int to) : from(from), to(to) {}
};

template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}

template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

int Solve() {
  int n, m;
  cin >> n >> m;
  vector<vector<int>> adj = Make2DVector<int>(n, n, false);
  for (int i = 0; i < m; i++) {
    int v1, v2;
    cin >> v1 >> v2;
    v1--;
    v2--;
    adj[v1][v2] = adj[v2][v1] = true;
  }

  vector<vector<Edge>> graph(n);
  for (int v1 = 0; v1 < n; v1++) {
    for (int v2 = v1 + 1; v2 < n; v2++) {
      if (!adj[v1][v2]) {
        graph[v1].emplace_back(v1, v2);
        graph[v2].emplace_back(v2, v1);
      }
    }
  }

  vector<int> xs;
  vector<int> ys;
  vector<int> colors(n, -1);
  function<bool(int)> process = [&](int r) -> bool {
    int x = 0;
    int y = 0;
    function<bool(int, int, int c)> dfs = [&](int v, int p, int c) -> bool {
      if (colors[v] >= 0) {
        return colors[v] == c;
      }

      colors[v] = c;
      if (c == 1) y++;
      else x++;

      for (const auto& e : graph[v]) {
        if (!dfs(e.to, v, c ^ 1)) return false;
      }
      return true;
    };

    if (!dfs(r, -1, 0)) return false;

    xs.push_back(x);
    ys.push_back(y);
    return true;
  };

  for (int r = 0; r < n; r++) {
    if (colors[r] >= 0) continue;
    if (!process(r)) return -1;
  }

  int l = xs.size();
  auto dp = Make2DVector(l + 1, n + 1, 0);
  dp[0][0] = 1;
  for (int k = 0; k < l; k++) {
    for (int i = 0; i <= n; i++) {
      if (dp[k][i]) {
        dp[k + 1][i + xs[k]] = 1;
        dp[k + 1][i + ys[k]] = 1;
      }
    }
  }

  int ans = INT32_MAX;
  for (int i = 0; i <= n; i++) {
    if (!dp[l][i]) continue;
    int j = n - i;
    UpdateMin(ans, i * (i - 1) / 2 + j * (j - 1) / 2);
  }
  return ans;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve() << endl;
}

