    memset(G, 0, sizeof(G));
    memset(C, 0, sizeof(C));
    for (int i = 0;i < M;i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        G[a][b] = 1;
        G[b][a] = 1;
    }
    queue<node> P;
    for (int i = 0;i < N && P.size() == 0;i++) {
        int c = 0;
        for (int j = 0;j < N;j++) c += G[i][j];
        if (c == N - 1) {
            C[i] = 3;
        } else {
            node n;
            n.idx = i;
            n.c = 1;
            C[i] = 1;
            P.push(n);
        }
    }
    // All devidable.
    if (P.size() == 0) {
        int res = M;
        for (int i = 0;i <= N;i++) {
            res = min(res, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
        }
        cout << res << endl;
        return 0;
    }
    while (P.size() > 0) {
        node n = P.front();
        P.pop();
        int id = n.idx;
        int c = n.c;
        int d = 3 - c;
        for (int j = 0;j < N;j++) {
            if (id != j) {
                if (G[id][j] == 0) {
                    if (C[j] == c) {
                        cout << -1 << endl;
                        return 0;
                    }
                    if (C[j] == d || C[j] == 3) continue;
                    C[j] = d;
                    node r;
                    r.idx = j;
                    r.c = d;
                    P.push(r);
                }
            }
        }
    }
    int one = 0, two = 0, three = 0;
    for (int i = 0;i < N;i++) {
        if (C[i] == 0 || C[i] == 3) three++;
        if (C[i] == 1) one++;
        if (C[i] == 2) two++;
    }
    int res = M;
    for (int j = 0;j <= three;j++) {
        int k = three - j;
        res = min(res, (one + j) * (one + j - 1) / 2 + (two + k) * (two + k - 1) / 2);
    }
    cout << res << endl;
    return 0;
}

