        }
    }

    /* 州確認 */
    for (i=0; i<N; i++)
    {
        for(j=i+1; j<N; j++)
        {
            if (bridge[i][j]==0)
            {
#ifdef DEBUG
                printf("%3d<-//->%3d\n", i+1, j+1);
#endif
                if (state[i] != BOTH /* && state[j] != BOTH */ && state[i] == state[j])
                {
                    /* 無理 */
                    printf("-1\n");
                    return 0;
                }

                if (state[j] == TAKA)
                {
                    state[i] = HASI;
                }
                else
                {
                    state[i] = TAKA;
                    state[j] = HASI;
                }
            }
        }
    }

    /* 州都市数計算 */
    for (i=0; i<N; i++)
    {
#ifdef DEBUG
        printf("%3d %d\n", i+1, state[i]);
#endif
        statenum[state[i]]++;
    }

#ifdef DEBUG
    printf("TAKA %d\n", statenum[TAKA]);
    printf("HASI %d\n", statenum[HASI]);
    printf("BOTH %d\n", statenum[BOTH]);
#endif

    /* 両方に属せる州を少ない方に寄せる */
    for (i=0; i<N; i++)
    {
        if (state[i] != BOTH) continue;

        statenum[BOTH]--;
        if (statenum[TAKA] < statenum[HASI])
        {
            state[i] = TAKA;
            statenum[TAKA]++;
        }
        else
        {
            state[i] = HASI;
            statenum[HASI]++;
        }
    }

    /* 答え計算 */
    ans = 0;
    if (statenum[TAKA] >= 2) ans += (statenum[TAKA] * (statenum[TAKA]-1))/2;
    if (statenum[HASI] >= 2) ans += (statenum[HASI] * (statenum[HASI]-1))/2;

    printf("%d\n", ans);

    return(0);
}

