#define MAXN 700
int g[MAXN][MAXN];
int vis[MAXN];
int n, m;

int input() {
	if (scanf("%d %d", &n, &m) < 0) return 0;
	memset(g, 0, sizeof(g));
	for (int i=0; i<m; i++) {
		int x, y;
		scanf("%d %d", &x, &y);
		x--, y--;
		g[x][y] = g[y][x] = 1;
	}
	return 1;
}

void init() {
	for (int i=0; i<n; i++)
		for (int j=0; j<n; j++)
			if (i!=j)
				g[i][j] = 1-g[i][j];
	memset(vis, 0, sizeof(vis));
}

int dfs(int v,int c, int *ct) {
	vis[v] = c;
	ct[c-1]++;
	int m = 0;
	for (int i=0; i<n; i++)
		if (g[v][i]) {
			if (vis[i]) {
				if (vis[i]==c) return 0;
				continue;
			}
			if (!dfs(i, 3-c, ct)) return 0;
		}
	return 1;
}

long solve() {
	int ct[MAXN][2];
	memset(ct, 0, sizeof(ct));
	int m = 0;
	for (int i=0; i<n; i++)
		if (!vis[i]) {
			if (!dfs(i, 1, ct[m++])) return -1;
		}
	int b[2][MAXN+1];
	memset(b, 0, sizeof(b));
	int cur=0, next=1;
	b[cur][0] = 1;
	for (int i=0; i<m; i++) {
		memset(b[next], 0, sizeof(b[next]));
		for (int j=0; j<=n; j++)
			if (b[cur][j]) {
				for (int k=0; k<2; k++)
					b[next][j+ct[i][k]] = 1;
			}
		swap(cur, next);
	}
	int ans = INT_MAX;
	for (int i=0; i<=n; i++) {
		if (b[cur][i]) {
			int j = n-i;
			int s = i*(i-1)/2 + j*(j-1)/2;
			ans = min(ans, s);
		}
	}
	return ans;
}

void output(long ans) {
	printf("%ld\n", ans);
}

void cleanup() {
}

int main() {
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

