bool hoge(vector< vector<int> >& G, int n) {
    vector<int> color(n, -1);

    color[0]=0;
    bool ok=true;
    for(int i=0; i<n; ++i) {
        for(int j=0,size=G[i].size(); j<size; ++j) {
            if(color[G[i][j]]==color[i]) { ok=false; i=n; j=size; }
            else { color[G[i][j]] = !color[i]; }
        }
    }
    return ok;
}

const int MAX_V = 100;

int V;
vector<int> G[MAX_V];
int match[MAX_V];
bool used[MAX_V];

void add_edge(int u, int v) {
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(int v) {
    used[v] = true;
    for (int i = 0; i < G[v].size(); i++) {
        int u = G[v][i], w = match[u];
        if (w < 0 || !used[w] && dfs(w)) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching() {
    int res = 0;
    memset(match, -1, sizeof(match));
    for (int v = 0; v < V; v++) {
        if (match[v] < 0) {
            memset(used, 0, sizeof(used));
            if (dfs(v)) res++;
        }
    }
    return res;
}

