bool dfs (int x, int c, int bw)
{
	u[x] = 1;
	cl[x] = bw;
	cnt[c][bw]++;

	for (int to : g[x])
	{
		if (u[to] && cl[x] == cl[to]) return false;
		if (!u[to] && !dfs (to, c, !bw)) return false;
	}

	return true;
}

