	for (int i = 0; i < m; i++)
	{
		int u, v;

		scanf ("%d%d", &u, &v);

		d[u-1][v-1] = 1;
		d[v-1][u-1] = 1;
	}

	for (int i = 0; i < n; i++)
		for (int j = i + 1; j < n; j++)
			if (!d[i][j])
			{
				g[i].push_back (j);
				g[j].push_back (i);
			}

	int color = 0;

	for (int i = 0; i < n; i++)
		if (!u[i] && !dfs (i, ++color, 0))
		{
			cout << -1;
			return 0;
		}

	vector <int> v;

	int sum = 0;

	for (int i = 1; i <= color; i++)
	{
		sum += min (cnt[i][0], cnt[i][1]);
		v.push_back (abs (cnt[i][0] - cnt[i][1]));
	}

	vector <int> d (n + 1);

	d[0] = 1;

	for (int a : v)
	{
		for (int i = n; i >= 0; i--)
			if (d[i]) d[i + a] = 1;
	}

	int ans = 1e9;

	for (int i = 0; i <= n; i++)
	{
		if (d[i])
			ans = min (ans, f (i + sum, n - i - sum));
	}

	cout << ans / 2;
}

