int compute(int n,int j){
	if(j==-1){
		if(n==0)
			return 1;
		return 0;
	}
	if(wowo[n][j])
		return dp[n][j];
	wowo[n][j]=1;
	if(vec[j].ff<=n){
		dp[n][j]=max(dp[n][j],compute(n-vec[j].ff,j-1));
	}
	if(vec[j].ss<=n){
		dp[n][j]=max(dp[n][j],compute(n-vec[j].ss,j-1));
	}
	return dp[n][j];
}
