inline int read() {
  int x = 0, w = 1;
  char c = ' ';
  while (c < '0' || c > '9') {
    c = getchar();
    if (c == '-') w = -1;
  }
  while (c >= '0' && c <= '9') {
    x = (x << 1) + (x << 3) + (c ^ 48);
    c = getchar();
  }
  return x * w;
}
int n, m, ga[MAXN + 5][MAXN + 5], belong[MAXN + 5], vis[MAXN + 5], sum[2];
bool f;
void dfs(int u, int col) {
  if (f) return;
  belong[u] = col;
  vis[u] = true;
  ++sum[col];
  for (int i = 1; i <= n; ++i) {
    if (i != u && !ga[u][i]) {
      int v = i;
      if (!vis[v]) {
        dfs(v, col ^ 1);
      } else if (col == belong[v]) {
        f = true;
        return;
      }
    }
  }
}
void init() {
  n = read();
  m = read();

  for (int i = 1; i <= m; ++i) {
    int u = read(), v = read();
    ga[u][v] = true;
    ga[v][u] = true;
  }
}
