  for (int i = 1; i <= n; ++i) {
    if (!vis[i]) {
      memset(sum, 0, sizeof(sum));
      dfs(i, 0);
      S = (S << sum[0]) | (S << sum[1]);
    }
  }
  if (f) {
    puts("-1");
