int bfs (int x)
{
	int red = 1, blue = 0;
	queue <int> q;
	q.push(x); 
	visited[x] = 1;

	while (!q.empty())
	{
		int v = q.front();
		q.pop();
		FOR (u, 1, n)
		    if (u == v || adj[u][v]) continue;

		    else if (!visited[u])
			{
				q.push(u);
				visited[u] = -visited[v];
				if (visited[u] == 1) red++;
				else blue++;
			}

			else if (visited[u] == visited[v]) 
	        {
	        	cout << -1;
	        	exit(0);
	        }
	}
	return abs(blue - red);
}

inline int sadness (int x)
{
	return (x*(x - 1) + (n - x)*(n - x - 1))/2;
}

