	cin.tie(0);	
	input();

	vi sorrow;
	int sum = 0, cnt = 0, cpy;
	FOR (i, 1, n)
	   if (!visited[i])
	   {
	      sorrow.push_back(bfs(i));
	      sum += sorrow.back();
	      cnt++;
	   }

	cpy = sum;
	sum /= 2; 
	int dp[cnt + 1][sum + 1] = {}, x;
	FOR (i, 1, cnt)
	   FOR (j, 1, sum)
	   {
	    	dp[i][j] = dp[i - 1][j];
	           if (sorrow[i] <= j)
	             dp[i][j] = max(dp[i][j], dp[i - 1][j - sorrow[i]] + sorrow[i]);
	   }

	x = (abs(dp[cnt][sum] * 2 - cpy) + n)/2;
	cout << sadness(x);
}

