bool dfs(int node, int color, vector<int> &colors, vector<bool> &used, const vector<vector<int>> &graph) {
    colors[node] = color;
    used[node] = true;

    for (int i = 0; i < graph[node].size(); ++i) {
        int next_node = graph[node][i];

        // 隣のノードが同じ色
        if (colors[next_node] == color) { return false; }

            // 隣のノードは未着色
        else if (colors[next_node] == 0) {
            if (dfs(next_node, -color, colors, used, graph) == false) {
                return false;
            }
        }
    }
    return true;
}

