void dfs (int nod, int x) {
    col[nod] = x;
    viz[nod] = 1;

    if (x == 0)
        ++ albe;
    else
        ++ negre;

    for (auto i : g[nod]) {
        if (viz[i] == 0) {
            dfs(i, x ^ 1);
        } else if (col[i] != (x ^ 1)) {
            ok = 0;
        }
    }
