int main() {
    fin.sync_with_stdio(false); fin.tie(); fout.tie();

    int n, m;
    fin >> n >> m;

    for (int i = 1; i <= m; ++ i) {
        int x, y;
        fin >> x >> y;
        e[x][y] = 1;
        e[y][x] = 1;
    }

    for (int i = 1; i <= n; ++ i) {
        for (int j = i + 1; j <= n; ++ j) {
            if (e[i][j] == 0) {
                g[i].push_back(j);
                g[j].push_back(i);
            }
        }
    }

    ok = 1;
    vector<pair<int, int>> v;
    v.push_back({0, 0});
    for (int i = 1; i <= n; ++ i) {
        if (viz[i] == 0) {
            albe = negre = 0;
            dfs(i, 0);

