        s += v[i].first + v[i].second;
        for (int j = v[i].first; j <= s; ++ j) {
            d[i][j] |= d[i - 1][j - v[i].first];
        }
    }

    int k = (int)v.size() - 1;
    int ans = 1 << 30;
    for (int i = 0; i <= n; ++ i) {
        if (d[k][i] == 1) {
            ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
    }

    fout << ans << "\n";
    return 0;
}

