		if (col[from] != c) return dame;
		if (col[from] == c) return PP(0, 0);
	}

	col[from] = c;
	PP ret(1, 0);
	for (int to : G[from]) {
		PP p = DFS(to, 3 - c);
		if (p == dame) return dame;

		ret.first += p.second;
		ret.second += p.first;
	}
	return ret;
}

vector<PP> pairs;
bitset<701> DP;

int Knapsack() {
	int offset = 0;
	DP[0] = 1;
	for (auto p : pairs) {
		int mn = min(p.first, p.second);
		int mx = max(p.first, p.second);
		offset += mn;

		int v = mx - mn;

		DP |= DP << v;
	}

	DP <<= offset;
	REP(i, (N + 1) / 2, N + 1) {
		if (DP[i]) return i;
	}
}

