    }
}

void getComp()
{
    int i, j;
    for(i = 1; i <= n; i ++)
    {
        for(j = 1; j <= n; j ++)
        {
            if(j != i)
            {
                if(are[i][j] == 0)
                    add(i, j);
            }
        }
    }
}

void dfs(int a, int cul)
{
    col[a] = cul;
    viz[a] = 1;
    ap[comp][cul] ++;
    for(auto u : g[a])
    {
        if(viz[u] == 0)
            dfs(u, 1 - cul);

        if(col[u] != 1 - col[a])
        {
            cout << "-1\n";
            exit(0);
        }
    }
}

void getCols()
{
    int i;
    for(i = 1; i <= n; i ++)
    {
        if(viz[i] == 0)
        {
            ++ comp;
            dfs(i, 0);
        }
    }
}

void getDp()
{
    int i, j, h;
    dp[0][0] = 1;
    for(i = 1; i <= comp; i ++)
    {
        for(j = n; j >= 0; j --)
        {
            if(dp[i - 1][j] == 1)
            {
                for(h = 0; h <= 1; h ++)
                    dp[i][j + ap[i][h]] = 1;
            }
        }
    }
}

void getRez()
{
    rez = sqrInf;

    int i;
    for(i = 1; i <= n; i ++)
    {
        if(dp[comp][i] == 1)
            rez = min(rez, ((i * (i - 1)) >> 1) + (((n - i) * (n - i - 1)) >> 1));
    }
}

void solve()
{
    getComp();

    getCols();

    getDp();

    getRez();
}

