        int a, b; cin >> a >> b; a--, b--;
        G[a][b] = G[b][a] = true;
    }
    vector<int> color(N);
    bool fail = false;
    auto recur = [&](auto rec, int node, int t, int& a, int& b) -> void {
        if (fail || color[node] == -t) { fail = true; return; }
        if (color[node] != 0) return;
        color[node] = t;
        if (t > 0) a++; else b++;
        for (int i = 0; i < N; i++) {
            if (node != i && G[node][i] == false) {
                rec(rec, i, -t, a, b);
            }
        }
    };
    vector<pair<int, int>> A;
    int t = 0;
    for (int i = 0; i < N; i++) {
        if (color[i] != 0) continue;
        int a = 0, b = 0;
        recur(recur, i, ++t, a, b);
        A.emplace_back(a, b);
    }
    if (fail) {
        cout << -1 << endl;
    } else {
        vector<bool> dp(N), dp2(N);
        dp[A[0].first] = dp[A[0].second] = true;
        for (int i = 1; i < A.size(); i++) {
            dp2 = vector<bool>(N);
            for (int j = N-1; j >= 0; j--) {
                if (j - A[i].first >= 0) dp2[j] = dp2[j] | dp[j - A[i].first];
                if (j - A[i].second >= 0) dp2[j] = dp2[j] | dp[j - A[i].second];
            }
            swap(dp, dp2);
        }
        for (int i = N/2; i < N; i++) {
            if (dp[i]) {
                int n = i;
                int m = N - n;
                cout << n*(n-1)/2 + m*(m-1)/2 << endl;
                break;
            }
        }
    }
    return 0;
}

