		if (!used[i]) {
			auto p = separate<long,int>(e.E,i);
			if (p.first == (0) && p.second == (0)) {
				cout << (-1) <<  endl;
				exit(0);
			}
			used |= p.first;
			used |= p.second;
			cnt[0].push_back(p.first.count());
			cnt[1].push_back(p.second.count());
		}
	}

	VB dp(N+1,false);
	dp[cnt[0][0]] = true;
	FOR(i,1,cnt[0].size()) {
		RFOR(j,N,-1) {
			if (j - cnt[0][i] >= 0 && dp[j-cnt[0][i]]) dp[j] = true;
			if (j - cnt[1][i] >= 0 && dp[j-cnt[1][i]]) dp[j] = true;
		}
	}
	//dump1d_arr(dp);
