using Graph = vector<vector<int>>;

int solve(auto& N, auto& G) {
  auto bipartite = true;
  vector<vector<int>> parts;
  vector<int> color(N, -1);
  function<void(int, int)> dfs = [&](auto cur, auto c) {
    color[cur] = c;
    ++parts.back()[c];
    for(auto nex: G[cur]) {
      if(color[nex] == c) bipartite = false;
      if(!~color[nex]) dfs(nex, !c);
    }
  };
  for(auto v=0; v<N; ++v) if(!~color[v]) {
    parts.emplace_back(2);
    dfs(v, 0);
  }
  if(!bipartite) return -1;

  set<int> dp = {0};
  for(const auto& p: parts) {
    set<int> nex;
    for(auto x: p) for(auto i: dp) nex.emplace(i + x);
    swap(dp, nex);
  }

  int res = 1e9;
  for(auto i: dp) {
    auto j = N - i;
    res = min(res, i*(i-1)/2 + j*(j-1)/2);
  }
  return res;
}

int main() {
  int N, M;
  cin >> N >> M;
  vector<vector<bool>> A(N, vector<bool>(N));
  for(auto i=0; i<M; ++i) {
    int a, b;
    cin >> a >> b; --a, --b;
    A[a][b] = A[b][a] = true;
  }

  Graph G(N);
  for(auto u=0; u<N; ++u) for(auto v=0; v<N; ++v) if(u!=v) if(!A[u][v]) G[u].emplace_back(v);

  cout << solve(N, G) << endl;
}

