      }
    }
  }

  vector<P> bi_graphs;
  vector<int> used(N, -1);  
  for ( int i = 0; i < N; i++ ) {
    if ( used[i] >= 0 ) continue;
    used[i] = 0;
    int cnt[2] = {0};
    queue<int> Q;
