      if ( !dp[j] ) continue;
      if ( j+a <= N ) nxt[j+a] = 1;
      if ( j+b <= N ) nxt[j+b] = 1;
    }
    swap(dp, nxt);    
  }

  int ans = M;
  for ( int i = 0; i <= N; i++ ) {    
    if ( !dp[i] ) continue;
    int a = 0, b = 0;
    if ( i >= 2 ) a = i*(i-1)/2;
    if ( N-i >= 2 ) b = (N-i)*(N-i-1)/2;          
