const int MAX = 2100;
bool G[MAX][MAX];
int N, M;

bool isbipartite = true; // false になったら二部グラフでない
int dir[MAX]; // 各ノードをとりあえず左右どちらにしているか (左: 0、右: 1)
int tmpnums[2];

void dfs(int v, int tdir) {
    dir[v] = tdir;
    tmpnums[tdir]++;
    for (int e = 0; e < N; ++e) {
        if (e == v || !G[v][e]) continue;
        if (dir[e] == -1) dfs(e, 1 - tdir);
        else if (dir[e] != 1 - tdir) isbipartite = false;
    }
}

int main() {
    cin >> N >> M;
	for (int i = 0; i < MAX; ++i) for (int j = 0; j < MAX; ++j) G[i][j] = 1;
	for (int i = 0; i < M; ++i) {
	  int a, b;
	  cin >> a >> b; --a, --b;
	  G[a][b] = G[b][a] = 0;
	}

    // 二部グラフの構成
	vector<pair<int,int> > nums;
	for (int i = 0; i < MAX; ++i) dir[i] = -1;
	for (int v = 0; v < N; ++v) {
        if (dir[v] != -1) continue;
        tmpnums[0] = tmpnums[1] = 0;
        dfs(v, 0);
        nums.push_back(make_pair(tmpnums[0], tmpnums[1]));
	}

    // そもそも二部グラフじゃなかったらダメ
    if (!isbipartite) {
        cout << -1 << endl;
        return 0;
    }

    // ナップサック DP
    bool dp[MAX] = {0};
    dp[0] = 1;
    for (int i = 0; i < (int)nums.size(); ++i) {
        for (int j = N; j >= 0; --j) {
            if (!dp[j]) continue;
            dp[j] = 0;
            dp[j + nums[i].first] = 1;
            dp[j + nums[i].second] = 1;
        }
    }

    long long a = -1;
    long long mindif = N;
    for (int i = 0; i <= N; ++i) {
        if (!dp[i]) continue;
        if (mindif > abs(i - N/2)) mindif = abs(i - N/2), a = i;
    }
    long long b = N-a;
    cout << a*(a-1)/2 + b*(b-1)/2 << endl;
}

