bool solve(int s) {
	std::queue<int> qu; qu.push(s);
	li[s] = 0;

	while(!qu.empty()) {
		auto p = qu.front(); qu.pop();

		for(auto e : G[p]) {
			if(~li[e] and li[p] == li[e]) return false;
			if(~li[e]) continue;

			li[e] = !li[p];
			qu.push(e);
		}
	}

	for(int i = 0; i < n; i++) {
		if(li[i] == -1) continue;

		for(auto e : G[i]) if(li[i] == li[e]) return false;
	}

	return true;
}

void latte(int s) {
	std::queue<int> qu; qu.push(s);
	std::vector<bool> used(n, false); used[s] = true;
	vec[count][0]++;

	while(!qu.empty()) {
		auto p = qu.front(); qu.pop();

		for(auto e : G[p]) {
			if(used[e]) continue; used[e] = true;

			vec[count][li[e]]++;
			qu.push(e);
		}
	}
	count++;
}

