ll solve(int N,int M,vi& a,vi& b) {
    int mmax = N*(N-1)/2;
    if (M == mmax) {
        int best = 0xffffffff;
        for (int p=0; p<=N; ++p) {
            int q = N-p;
            int score = p*(p-1)/2 + q*(q-1)/2;
            best = min(best, score);
        }
        return best;
    }
    vvi d(N, vi(N, 0));
    rep(i,M){
        d[ a[i] ][ b[i] ] = d[ b[i] ][ a[i] ] = 1;
    }
    rep(i,N) d[i][i] = 1;

    vector<ii> non;
    repC2(i,j,N){
        if (d[i][j]) continue;
        non.pb(ii(i,j));
    }

    int x=non.back().first, y=non.back().second;
    non.pop_back();

    set<int> gx, gy;
    gx.insert(x); gy.insert(y);
#ifdef DEBUG
    // cerr << gx << gy << endl;
    // cerr << non << endl;
#endif
    for (ii p : non) {
        int u=p.first, v=p.second;
        if (d[u][x]==1 && d[v][y]==1) {
            gx.insert(u); gy.insert(v);
        } else if (d[u][y]==1 && d[v][x]==1) {
            gy.insert(u); gx.insert(v);
        } else {
            return -1;
        }
    }
    int Lx = gx.size(), Ly = gy.size(), rem = N-Lx-Ly;
    if (rem) {
        int half = N/2;
        if (Lx < half) {
            int up = min(half - Lx, rem);
            Lx += up;
            rem -= up;
        }
        if (Ly < half) {
            int up = min(half - Ly, rem);
            Ly += up;
            rem -= up;
        }
        if (rem) ++Lx;
    }
    return Lx*(Lx-1)/2 + Ly*(Ly-1)/2;
}

