void solve() {
  int n, m; cin >> n >> m;
  Graph<int> g(n);
  rep(i,m) {
    int a, b; cin >> a >> b; --a, --b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }

  Graph<bool> dist(n, vb(n, true));
  rep(i,n) {
    dist[i][i] = false;
    for (int v : g[i]) {
      dist[i][v] = false;
    }
  }

  vi color(n, -1);
  vb dp(n+1, false);
  dp[0] = true;

  rep(i,n) {
    if (color[i] != -1) continue;

    queue<int> q;
    q.push(i);
    color[i] = 0;
    vi cnt(2);

    while (!q.empty()) {
      int v = q.front(); q.pop();
      ++cnt[color[v]];
      rep(nv,n) {
        if (dist[v][nv]) {
          if (color[nv] == -1) {
            q.push(nv);
            color[nv] = 1 - color[v];
          } else if (color[v] == color[nv]) {
            cout << -1 << endl;
            return;
          }
        }
      }
    }

    int tmp = *min_element(ALL(cnt));
    RREP(j,n,tmp) {
      rep(k,2) {
        int p = j - cnt[k];
        if (p >= 0) {
          dp[j] = dp[j] || dp[p];
        }
      }
    }
  }

  int free = 0;
  rep(i,n) {
    free += (color[i] == -1);
  }

  int group = 0;
  repeq(i,n>>1) {
    if (dp[i]) chmax(group, min((n>>1), i+free));
  }

  int ans = 0;
  ans += group * (group - 1) / 2;
  group = n - group;
  ans += group * (group - 1) / 2;
  cout << ans << endl;
}


