    {

        visited[x] = val;
        if(val == 1)
            value++;
        if(val == 2)
            val2++;
        for(auto i:real_adj[x])
            if(!visited[i])
            {
                dfs(i, 3-val);
            }
            else
                flag = flag ||(3-val != visited[i]);


    };

    for(int i=1 ;i<=n;i++)
    {
        if(!visited[i])
        {
            ind++;
            value = 0;
            val2=0;
            dfs(i, 1);
            sz.pb({value, val2});
