class Solver {
  public:
    bool solve() {
        int N, M; cin >> N >> M;
        vector<vector<int>> G(N, vector<int>(N));
        rep(i, M) {
            int a, b; cin >> a >> b;
            a--; b--;
            G[a][b] = 1;
            G[b][a] = 1;
        }
        rep(i, N) rep(j, N) {
            if(i != j) G[i][j] = 1 - G[i][j];
        }
        vector<int> color(N);
        function<pii(int, int)> coloring = [&] (int now, int c) {
            pii res = make_pair(0, 0);
            color[now] = c;
            (c == 1 ? res.first : res.second) += 1;
            rep(i, N) if(G[now][i]) {
                if(not color[i]) {
                    pii tmp = coloring(i, c == 1 ? 2 : 1);
                    if(tmp.first < 0) return make_pair(-1, -1);
                    res.first += tmp.first;
                    res.second += tmp.second;
                } else if(color[i] == c) return make_pair(-1, -1);
            }
            return res;
        };
        vector<pii> group;
        rep(i, N) {
            if(not color[i]) {
                group.push_back(coloring(i, 1));
                if(group.back().first < 0) {
                    cout << -1 << endl;
                    exit(0);
                }
            }
        }

        vector<vector<int>> dp(N + 1, vector<int>(N + 1));
        dp[0][0] = 1;
        rep(i, N) {
            rep(j, N) {
                if(not dp[i][j]) continue;
                if(j + group[i].first <= N) dp[i + 1][j + group[i].first] = 1;
                if(j + group[i].second <= N) dp[i + 1][j + group[i].second] = 1;
            }
        }
        int ans = INF;
        rep(i, N + 1) {
            if(dp[N][i]) set_min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
        }
        cout << ans << endl;
        return 0;
    }
};

