////////////////////Dynamic Programing////////////////////
	dp[0][offset+cnt[0]]=1;
	dp[0][offset-cnt[0]]=1;
	for(int i=1;i<Cnt;i++){
		int now=i&1,last=(i-1)&1;
		for(int j=-n;j<=n;j++){
			dp[now][offset+j+cnt[i]]|=dp[last][j+offset];
			dp[now][offset+j-cnt[i]]|=dp[last][j+offset];
		}
	}
	for(int i=0;i<=n;i++){
		if(dp[(Cnt-1)&1][offset+i] || dp[(Cnt-1)&1][offset-i]){
