    else 
        ret = P(0, 1);

    for (auto dst : g[v]) if (dst != p) {
        P tmp = dfs(dst, v, f ^ 1);
        ret.fi += tmp.fi;
        ret.se += tmp.se;
    }
    return ret;
}
