    color[u] = c;
    parts[c].emplace_back(u);
    for (int v = 0; v < n; v++) if (v != u && mat[u][v]) {
        if (~color[v]) {
            if (color[v] == color[u]) return false;
        } else {
            if (!dfs(v, c ^ 1)) return false;
        }
    }
    return true;
}

bool is_bipartite() {
    color.assign(n, -1);
    parts.assign(2, vector<int>());
    for (int u = 0; u < n; u++) if (color[u] == -1) {
        if (!dfs(u, 0)) return false;
        ps.emplace_back(parts[0].size(), parts[1].size());
        parts.assign(2, vector<int>());
    }
    return true;
}

