    if (!is_bipartite()) return !(cout << -1 << endl);
    vector<bool> dp(n * 2 + 1);
    dp[0] = true;
    for (auto &p: ps) {
        for (int i = n; i >= 0; i--) if (dp[i]) {
            dp[i] = false;
            dp[i + p.first] = dp[i + p.second] = true;
        }
    }
    int idx = -1;
    for (int i = 0; i <= n; i++) if (dp[i]) {
        if (abs(idx - n / 2) > abs(i - n / 2)) idx = i;
    }
    int a = idx, b = n - idx;
    int res = a * (a - 1) / 2 + b * (b - 1) / 2;
    cout << res << endl;
    return 0;
}

