using namespace std;

struct UnionFind{
    int num;
    vector<int> par,rank;
    UnionFind(int n):num(n),par(n),rank(n,1){
        iota(par.begin(),par.end(),0);
    }
    int root(int x){
        if (par[x]==x) return x;
        return par[x]=root(par[x]);
    }
    bool merge(int x, int y){
        x=root(x),y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x,y);
        par[y]=x;
        rank[x]+=rank[y];
        --num;
        return true;
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    int size(int x){
        return rank[root(x)];
    }
    int count(){
        return num;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N,M; cin >> N >> M;
    vector<vector<bool>> edge(N,vector<bool>(N,false));
    for (int i=0;i<M;++i){
        int A,B; cin >> A >> B;
        if (A>B) swap(A,B);
        edge[--A][--B]=true;
    }
    UnionFind uf(2*N);
    for (int i=0;i<N;++i){
        for (int j=i+1;j<N;++j){
            if (!edge[i][j]){
                uf.merge(i,j+N);
                uf.merge(i+N,j);
            }
        }
    }
    for (int i=0;i<N;++i){
        if (uf.same(i,i+N)){
            cout << -1 << '\n';
            return 0;
        }
    }
    vector<bool> check(N,false);
    vector<pair<int,int>> sz;
    for (int i=0;i<N;++i){
        if (!check[i]){
            int red=0,blue=0;
            for (int j=i;j<N;++j){
                if (uf.same(i,j)||uf.same(i,j+N)){
                    ++(uf.same(i,j)?red:blue);
                    check[j]=true;
                }
            }
            sz.emplace_back(red,blue);
        }
    }
    int n=sz.size();
    vector<int> dp(N+1,0);
    dp[0]=1;
    for (int i=0;i<n;++i){
        for (int j=N;j>=0;--j){
            if (j+sz[i].first<=N) dp[j+sz[i].first]|=dp[j];
            if (j+sz[i].second<=N) dp[j+sz[i].second]|=dp[j];
        }
    }
    int ans=N*N;
    for (int j=0;j<=N;++j){
        if (dp[j]){
            ans=min(ans,j*(j-1)/2+(N-j)*(N-j-1)/2);
        }
    }
    cout << ans << '\n';
}

