#include<bits/stdc++.h>
using namespace std;
#define maxn 705
bool dis[maxn][maxn];
int fa[maxn*2],size[maxn*2],f[2][maxn*2];
int Find(int x){
	return fa[x]==x?x:fa[x]=Find(fa[x]);
}
int main(){
	int n,m;scanf("%d%d",&n,&m);
	int x1=n>>1,x2=n-x1,u,v;
	if(m<((x1-1)*x1+(x2-1)*x2)/2){
		puts("-1");return 0;
	}
	for(int i=0;i<m;i++){
		scanf("%d%d",&u,&v),dis[u][v]=dis[v][u]=1;
	}
	for(int i=1;i<=(n<<1);i++)fa[i]=i;
	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			if(!dis[i][j]){
				x1=Find(i),x2=Find(j);
				if(x1==x2){
					puts("-1");return 0;
				}
				int y2=Find(j+n),y1=Find(i+n);
				fa[y2]=x1,fa[y1]=x2;
			}
		}
	}
	for(int i=1;i<=n;i++){x1=Find(i),size[x1]++;}
	f[0][maxn]=1;
	for(int i=1;i<=n;i++){
		x1=Find(i),x2=Find(i+n);
		if(!size[x1]){
			memcpy(f[i&1],f[(~i)&1],sizeof(f[i&1]));
			continue;
		}
		int k=i&1,w=size[x1]-size[x2];size[x1]=size[x2]=0;
		memset(f[k],0,sizeof(f[k]));
		for(int i=0;i<maxn*2;i++){
			if(f[k^1][i])
			f[k][i-w]=f[k][i+w]=1;
		}
	}
	for(int i=maxn;;i++){
		if(f[n&1][i]){
			x1=(n-i+maxn)>>1,x2=n-x1;break;
		}
	}
	printf("%d",((x1-1)*x1+(x2-1)*x2)>>1);
	return 0;
}

