void rec(int u, int col, int times){
  if(checked[u]){
    if(c[u]!=col){
      cout<<-1<<endl;
      exit(0);
    }
    return;
  }
  checked[u]=true;
  c[u]=col;
  v[times][col]++;
  FOR(i,1,N+1){
    if(u!=i&&!ex[u][i]){
      rec(i,col^1,times);
    }
  }
