      rec(i,0,t);
    }
    t++;
  }
  bool dp[N+1];
  CLR(dp);
  dp[0] = true;
  FOR(t,0,707){
    FOR(i,0,N+1){
      if(dp[i]){
        // 0を選ぶ
        if(i+v[t][0]<=N) dp[i+v[t][0]] = true;
        // 1を選ぶ
        if(i+v[t][1]<=N) dp[i+v[t][1]] = true;
      }
