}G[1000010];
int Head[710];
int tot = 0;
inline void Add(int u, int v)
{
	++ tot;
	G[tot].u = u;
	G[tot].v = v;
	G[tot].Next = Head[u];
	Head[u] = tot;
}
int color[710];
int x[710], y[710], top;
inline bool DFS(int u)
{
	for(int i = Head[u]; i; i = G[i].Next)
	{
		int v = G[i].v;
		if(color[v] == color[u])
			return false;

		if(color[v] == -1)
		{
			color[v] = 1 - color[u];
			if(color[u] == 1)
				++ y[top];
			else
				++ x[top];
			if(! DFS(v))
				return false;
		}
	}
	return true;
}
