template<class T> void chmin(T& x, T y){if(x > y) x = y;}
template<class T> void chmax(T& x, T y){if(x < y) x = y;}

int N, M;
int edge[710][710];
int st[710];
bool flag = true;
vector<pii> ps;

void dfs(int v, int* dat){
    dat[st[v]]++;
    int to = (st[v] + 1) & 1;
    for(int i = 1; i <= N; ++i){
        if(edge[v][i] == 0){
            if(st[i] == -1) st[i] = to, dfs(i, dat);
            else if(st[i] != to) flag = false;
        }
    }
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N >> M;
    for(int i = 1; i <= N; ++i) st[i] = -1, edge[i][i] = 1;

    for(int i = 0; i < M; ++i){
        int A, B;
        cin >> A >> B;
        edge[A][B] = 1;
        edge[B][A] = 1;
    }
    for(int i = 1; i <= N; ++i){
        if(st[i] != -1) continue;

        int dat[2] = {};
        st[i] = 0;
        dfs(i, dat);
        ps.push_back({dat[0], dat[1]});
    }
    if(flag){
        bitset<710> res = {};
        res[0] = 1;
        for(auto u : ps){
            res = (res << u.first) | (res << u.second);
        }

        int ans = inf;
        for(int i = 0; i <= N; ++i){
            if(res[i] == 1){
                auto culc = [] (int a){return a * (a - 1) / 2;};
                chmin(ans, culc(i) + culc(N - i));
            }
        }
        cout << ans << endl;
