using namespace std;

int main(){
	int N, M; cin >> N >> M)
		vector<vector<int>> adj(N, vector<int>(N, 0));
		for(int i=0;i<M;i++){
			int a, b; cin >> a >> b;
			--a; --b;
			adj[a][b] = adj[b][a] = 1;
		}
		vector<vector<int>> g(N);
		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				if(adj[i][j]) continue;
				g[i].push_back(j);
				g[j].push_back(i);
			}
		}
		vector<vector<int>> vc;
		vector<int> team(N, -1);
		bool valid = true;
		for(int i=0;i<N;i++){
			if(team[i] != -1) continue;
			vector<int> cnt(2, 0);
			team[i] = 0;
			++cnt[0];
			queue<int> qu; qu.push(i);
			while(!qu.empty()){
				int p = qu.front(); qu.pop();
				for(int t : g[p]){
					if(team[t] == team[p]) valid = false;
					if(team[t] != -1) continue;
					team[t] = 1 - team[p];
					cnt[team[t]]++;
					qu.push(t);
				}
			}
			if(!valid) break;
			vc.push_back(cnt);
		}
		if(!valid){
			cout << -1 << endl;
             return 0;
		}
		vector<int> dp(N+1, 0);
		dp[0] = 1;
		for(const auto& cnt : vc){
			for(int i=N;i>=0;i--){
				if(!dp[i]) continue;
				for(auto add : cnt) dp[i+add] = 1;
			}
		}
		int res = M;
		for(int i=1;i<N;i++){
			if(!dp[i]) continue;
			res = min(res, i*(i-1)/2 + (N-i)*(N-i-1)/2);
		}
		cout << res << endl;
}

#include <bits/stdc++.h>
using namespace std;

typedef pair <int, int> ii;

const int Maxn = 2005;

int n, m;
bool E[Maxn][Maxn];
int col[Maxn];
bool dp[Maxn];
int res = Maxn * Maxn;

ii Solve(int v, int c, bool &ok)
{
	if (col[v] != 0)
		if (col[v] == c) return ii(0, 0);
		else { ok = false; return ii(0, 0); }
	ii res = ii(1, 0); col[v] = c;
	for (int i = 1; i <= n; i++) if (!E[v][i]) {
		ii got = Solve(i, -c, ok);
		if (!ok) return res;
		res.first += got.second; res.second += got.first;
	}
	return res;
}

int main()
{
	scanf("%d %d", &n, &m);
	for (int i = 0; i < m; i++) {
		int a, b; scanf("%d %d", &a, &b);
		E[a][b] = E[b][a] = true;
	}
	for (int i = 1; i <= n; i++)
		E[i][i] = true;
	dp[0] = true;
	for (int i = 1; i <= n; i++) if (col[i] == 0) {
		bool ok = true;
		ii got = Solve(i, -1, ok);
		if (!ok) { printf("-1\n"); return 0; }
		for (int i = Maxn - 1; i >= 0; i--) if (dp[i]) {
			if (i + got.first < Maxn) dp[i + got.first] = true;
			if (i + got.second < Maxn) dp[i + got.second] = true;
		}
	} 
	for (int i = 0; i <= n; i++) if (dp[i]) {
		int a = i, b = n - i;
		res = min(res, a * (a - 1) / 2 + b * (b - 1) / 2);
	}
	printf("%d\n", res);
	return 0;
}

