vector<int> g[707];
int col[707];

int even,odd,edge;

void fail(){
    cout<<-1<<endl;
    exit(0);
}

void dfs(int now,int c){
    col[now]=c;
    if(c==1) even++;
    else odd++;
    edge+=(int)g[now].size();

    for(auto nex:g[now]){
        if(col[nex]==col[now]) fail();
        if(col[nex]==0) dfs(nex,-c);
    }
}

int dp[2][707][707];
const int INF=1e9;

void chmax(int &a,int b){
    if(a<b) a=b;
}

int main(){
  cin>>N>>M;
  rep(i,M){
      int a,b;
      cin>>a>>b;
      m[a][b]=1;
      m[b][a]=1;
  }

  for(int i=1;i<=N;i++){
      for(int j=1;j<=N;j++){
          if(i==j) continue;
          if(m[i][j]==0) g[i].push_back(j);
      }
  }

  int ans=0;
  vector<pair<int,int>> v;
  for(int i=1;i<=N;i++){
      if(col[i]==0){
          dfs(i,1);
          edge/=2;
          ans+=(odd*even)-edge;
          v.push_back(mkp(odd,even));

          odd=even=edge=0;
      }
  }

  rep(i,2) for(int j=0;j<=N;j++) for(int k=0;k<=N;k++) dp[i][j][k]=-INF;
  dp[0][0][0]=0;
  int t=0;

  for(int i=0;i<v.size();i++){
      for(int j=0;j<=N;j++){
          for(int k=0;k<=N;k++){
              if(dp[t][j][k]==-INF) continue;

              int l=v[i].first;
              int r=v[i].second;

              chmax(dp[1-t][j+l][k+r],dp[t][j][k]+j*r+k*l);
              chmax(dp[1-t][j+r][k+l],dp[t][j][k]+j*l+k*r);
          }
      }
      for(int j=0;j<=N;j++) for(int k=0;k<=N;k++) dp[t][j][k]=-INF;
      t=1-t;
  }

  int res=0;
  for(int j=0;j<=N;j++) for(int k=0;k<=N;k++) chmax(ans,dp[t][j][k]);
  ans+=res;
  cout<<M-ans<<endl;

  return 0;
}

