using Graph=vector<vector<int>>;

Graph g;
vector<int> used;
pair<int,int> dfs(int v){
    pair<int,int> res={used[v],!used[v]};
    for(auto to:g[v]){
        if(used[to]==-1){
            used[to]=!used[v];
            auto tmp=dfs(to);
            res.first+=tmp.first,res.second+=tmp.second;
        }
        else if(used[to]==used[v]){
            throw std::runtime_error("BAD");
        }
    }
    return res;
}
int main(){
    int n,m;
    cin>>n>>m;
    vector<vector<int>> mat(n,vector<int>(n));
    for(int i=0;i<m;i++){
        int a,b;
        cin>>a>>b;
        a--,b--;
        mat[a][b]=true;
        mat[b][a]=true;
    }
    g.resize(n);
    used.assign(n,-1);
    for(int i=0;i<n;i++){
        for(int j=0;j<i;j++){
            if(!mat[i][j]){
                g[i].push_back(j);
                g[j].push_back(i);
            }
        }
    }

    vector<pair<int,int>> bag;
    for(int i=0;i<n;i++){
        if(used[i]==-1){
            try{
                used[i]=0;
                auto ret=dfs(i);
                bag.push_back(ret);
            }
            catch(...){
                cout<<-1<<endl;
                return 0;
            }
        }
    }

    vector<vector<int>> dp(bag.size()+1,vector<int>(n+1));
    dp[0][0]=true;
    for(int i=0;i<bag.size();i++){
        int a=bag[i].first,b=bag[i].second;
        for(int j=0;j<=n;j++){
            if(j+a<=n) dp[i+1][j+a]|=dp[i][j];
            if(j+b<=n) dp[i+1][j+b]|=dp[i][j];
        }
    }
    int res=m;
    for(int i=0;i<=n;i++){
        if(dp[bag.size()][i]) res=min(res,i*(i-1)/2+(n-i)*(n-i-1)/2);
    }
    cout<<res<<endl;
    return 0;
}

