const int N = 701;

int n, m, v[N][N], vis[N], dp[N][N], cnt[2];

int f(int x){
    return x * (x - 1) / 2;
}
void dfs(int node){
    cnt[vis[node]]++;
    for(int i = 1 ; i <= n ; i++){
        if(v[node][i] == 0) continue;
        if(vis[i] != -1 && vis[i] == vis[node]){
            cout << "-1\n";
            exit(0);
        }
        if(vis[i] != -1) continue;
        vis[i] = vis[node] ^ 1;
        dfs(i);
    }
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    memset(vis, -1, sizeof vis);
    cin >> n >> m;
    for(int i = 0 ; i < m ; i++){
        int x, y;
        cin >> x >> y;
        v[x][y] = v[y][x] = 1;
    }
    for(int i = 1 ; i <= n ; i++){
        for(int j = 1 ; j <= n ; j++){
            if(i == j) continue;
            v[i][j] ^= 1;
        }
    }
    vector <pair <int, int> > g;
    for(int i = 1 ; i <= n ; i++){
        if(vis[i] != -1) continue;
        cnt[0] = cnt[1] = 0;
        vis[i] = 0;
        dfs(i);
        g.push_back(make_pair(cnt[0], cnt[1]));
    }
    int s = g.size();
    dp[0][g[0].first] = dp[0][g[0].second] = 1;
    for(int i = 1 ; i < s ; i++){
        for(int j = 0 ; j <= n ; j++){
            dp[i][j] |= dp[i - 1][j];
            if(j - g[i].first >= 0) dp[i][j] |= dp[i - 1][j - g[i].first];
            if(j - g[i].second >= 0) dp[i][j] |= dp[i - 1][j - g[i].second];
        }
    }
    int ans = 1e9;
    for(int i = 0 ; i <= n ; i++){
        if(dp[s - 1][i] == 0) continue;
        int j = n - i;
        ans = min(ans, f(i) + f(j));
    }
    cout << ans << endl;
}

