void solve() {
  cin >> n >> m;
  for(int i = 1; i <= n; i++) {
    for(int j = i+1; j <= n; j++) {
      g[i][j] = true;
      g[j][i] = true;
    }
  }
  while(m--) {
    int a, b;
    cin >> a >> b;
    g[a][b] = false;
    g[b][a] = false;
  }
  dp.set(0);
  for(int i = 1; i <= n; i++) {
    if(color[i] != 0) continue;
    queue<int> q;
    color[i] = 1;
    int pos = 0;
    int neg = 0;
    q.push(i);
    while(!q.empty()) {
      int curr = q.front();
      q.pop();
      (color[curr] > 0 ? pos : neg)++;
      for(int out = 1; out <= n; out++) {
        if(!g[curr][out]) continue;
        if(color[out] == color[curr]) die();
        if(color[out] == 0) {
          color[out] = -color[curr];
          q.push(out);
        }
      }
    }
    dp = (dp << pos) | (dp << neg);
  }
  int ret = 1e9;
  for(int i = 0; i <= n; i++) {
    if(dp[i]) {
      int a = i;
      int b = n-i;
      ret = min(ret, a*(a-1)/2 + b*(b-1)/2);
    }
  }
  cout << ret << "\n";
}

