		ll a=A[i],b=B[i];
		if(a>b)swap(a,b);
		s.insert({a,b});
	}

	vector<vector<ll>> g(N);
	rep(i,N)for(ll j=i+1;j<N;j++){
		if(s.count({i,j})==0){
			g[i].push_back(j);
			g[j].push_back(i);
		}
	}


	vector<ll> seen(N,0);
	vector<pair<ll,ll>> iro;
	rep(i,N){
		if(seen[i]==0){
			ll shiro=0,kuro=0;
			rep(i,N){
				if(seen[i]==1)shiro++;
				else if(seen[i]==-1)kuro++;
			}
			seen[i]=1;
			bool b=isBipartiteGraph(g,i,seen);
			if(!b){
				p(-1);return;
			}
