{

    for (size_t i = 0; i < NMAX + 1; i++) {
        for (size_t j = 0; j < NMAX; j++) {
            E[i][j] = 0;
        }
    }

    for (size_t i = 0; i < NMAX + 1; i ++) {
        V[i] = -1;
    }


    std::cin >> N >> M;
    for (size_t i = 0; i < M; i++) {
        int a, b;
        std::cin >> a >> b;
        E[a][b] = E[b][a] = 1;
    }

    int group = 0;

    for (size_t i = 1; i <= N; i++) {
        if (V[i] != -1) {
            continue;
        }

        V[i] = group;
        setgroup(i, group);
        group += 2;
    }

    size_t maxsum = 0;
    DP[0][0] = true;
    for (size_t i = 1; i <= N; i++) {
        DP[0][i] = false;
    }
    size_t dp = 1;
    for (size_t g = 0; g < group; g += 2) {
        std::pair<size_t, size_t> pair = {0, 0};
        for (size_t i = 1; i <= N; i++) {
            if (V[i] == g) {
                pair.first += 1;
            }
            if (V[i] == g + 1) {
                pair.second += 1;
            }
        }
        if (pair.first + pair.second == 0) { 
            continue;
        }

        for (size_t i = 0; i <= N - std::max(pair.first, pair.second); i++) {
            DP[dp][i + pair.first] |= DP[dp-1][i];
            DP[dp][i + pair.second] |= DP[dp-1][i];
        }
        dp++;
    }

    size_t min = N * (N - 1) / 2;
    for (size_t i = 0; i <= N; i++) {
        if (DP[dp-1][i]) {
            min = std::min(min, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
        }
    }
    std::cout << min << std::endl;

    return 0;
}

