                if (j + c_g[i].first <= N) dp[i + 1][j + c_g[i].first] = 1;
                if (j + c_g[i].second <= N) dp[i + 1][j + c_g[i].second] = 1;
            }
        }
    }

    int ans = N * N;
    for (int i = 0; i <= N; i++) {
        if (dp[c_g.size()][i] == 1) {
            ans = min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
        }
    }
    cout << ans << endl;
    return 0;
}

