/* Bipartite Matching */

struct BipartiteMatching{

  int V;
  vector<vector<int> > G;
  vector<int> match;
  vector<bool> used;

  BipartiteMatching(int n):
    V(n),G(n){}

  void add_edge(int u, int v){
    G[u].push_back(v);
    G[v].push_back(u);
  }

  bool dfs(int v){
    used[v] = true;
    for(int i=0;i<G[v].size();i++){
      int u = G[v][i], w = match[u];
      if(w < 0 || (!used[w] && dfs(w))){
        match[v] = u;
        match[u] = v;
        return true;
      }
    }
    return false;
  }

  int solve(){
    int res = 0;
    match.assign(V,-1);
    for(int i=0;i<V;i++){
      if(match[i] < 0){
        used.assign(V,false);
        if(dfs(i)) res++;
      }
    }
    return res;
  }

};


int main(){
  int n, m;
  bool connect[SIZE][SIZE];

  scanf("%d%d", &n, &m);

  if(n * (n-1)/2 == m){
    printf("%d\n", (n/2)*(n/2+1) / 2 + ((n+1)/2)*((n+1)/2 + 1) / 2);
    return 0;
  }

  for(int i=0;i<m;i++){
    int a, b;
    scanf("%d%d", &a, &b);
    a--; b--;
    connect[a][b] = connect[b][a] = true;
  }

  BipartiteMatching bm(n);
  int c = 0;

  int s = -1, t = -1;

  for(int i=0;i<n;i++){
    for(int j=i+1;j<n;j++){
      if(!connect[i][j]){
        bm.add_edge(i, j);
        c++;
        s = i; t = j;
      }
    }
  }

  int cs=1,ct=1;

  if(bm.solve() == c){
    for(int i=0;i<n;i++){
      if(!connect[i][s] && i != s) cs++;
      if(!connect[i][t] && i != t) ct++;
    }
  }

  int ans = INF;

  for(int i=0;i<=n;i++){
    if(i <= cs && n-i <= ct){
      ans = min(ans, i * (i+1)/2 + i * (i+1) / 2);
    }
  }

  cout << ans << endl;

  return 0;
}

