	for(int i=1; i<=n; i++) {
		if(!vis[i]) {
			cnt[0] = cnt[1] = 0;
			dfs(i);
			if(!flag) {
				cout<<"-1"<<endl;
				return 0;
			}
			x[++tot] = cnt[0], y[tot] = cnt[1];
		}
	}
	dp[0][0] = 1;
	int ans = 1e9;
	for(int i=1; i<=tot; i++)
		for(int j=0; j<=n; j++)
			if(dp[i-1][j]) {
				dp[i][j+x[i]] = 1;
				dp[i][j+y[i]] = 1;
			}
	for(int i=1; i<n; i++)
		if(dp[tot][i]) ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	cout<<ans<<endl;
}

