    for (int w = 0; w < N; w++) {
        if (!has_edge[v][w]) continue;
        if (colors[w] == c) return false;
        if (colors[w] == 0 && !dfs(w, -c)) return false;
    }
    return true;
}

vector<int> total_diffs(vector<int> diffs) {
    if (diffs.size() == 0) return {0};
    int last = diffs.back();
    diffs.pop_back();
    auto total_diffs_smaller = total_diffs(diffs);

    vector<int> total_diffs;
    for (auto total_diff : total_diffs_smaller) {
        total_diffs.emplace_back(total_diff + last);
        total_diffs.emplace_back(total_diff - last);
    }
    sort(total_diffs.begin(), total_diffs.end());
    total_diffs.erase(unique(total_diffs.begin(), total_diffs.end()), total_diffs.end());
    return total_diffs;
}

