            if (col[j]) cnt1++;
            else cnt2++;
        }
        for (int j = n; j; j--) {
            if (j >= cnt1) f[j] |= f[j - cnt1];
            if (j >= cnt2) f[j] |= f[j - cnt2];
        }
    }
    int mn = INT_MAX;
    for (int i = 0; i <= n; i++) {
        if (f[i]) mn = min(mn, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
