	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	// cout << fixed << setprecision(15);
	INT(n, m);
	vvi a(n, vi(n));
	rep(i, m) {
		INT(c, b);
		c--, b--;
		a[c][b] = a[b][c] = 1;
	}

	int n2 = n * 2;
	UF uf(n * 2);

	rep(i, n) {
		Rep(j, i + 1, n) {
			if(a[i][j] == 0) {
				uf.unite(i, j + n);
				uf.unite(j, i + n);
			}
		}
	}
	int sol = 0;
	int rt1 = -1, rt2 = -1;
	rep(i, n) {
		if(uf.size(i) == 1)
			sol++;
		else if(rt1 < 0) {
			rt1 = uf.root(i);
			rt2 = uf.root(i + n);
		}

		if(uf.same(i, i + n)) err();
	}
	int b, c;
	b = c = 0;
	rep(i, n) {
		if(uf.root(i) == rt1) {
			b++;
		}
		if(uf.root(i) == rt2) {
			c++;
		}
	}
	if(b > c) swap(b, c);
	if(abs(b - c) < sol) {
		b = n / 2;
		c = n - b;
	} else {
		b += sol;
	}
	int ans = c * (c - 1) / 2 + b * (b - 1) / 2;
	cout << ans << endl;
}

