//ProblemE
void Solve() {
	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		matrix[x][y] = 1;
		matrix[y][x] = 1;
	}

	vector<vector<int>> groups;
	vector<int> color(n, 2);

	for (int i = 0; i < n; i++) {
		if (color[i] == 2) {
			int c = 0;
			groups.push_back({ 0, 0 });
			auto& last = groups.back();

			vector<int> q{ i };
			color[i] = c;
			last[c] += 1;

			c = 1 - c;
			while (!q.empty()) {
				vector<int> q2;
				for (auto j : q) {
					for (int k = 0; k < n; k++) {
						if (k == j || matrix[j][k] == 1) continue;
						if (color[k] == 2) {
							color[k] = c;
							q2.push_back(k);
							last[c] ++;
						} else if (color[k] != c) {
							cout << -1 << endl;
							return;
						}
					}
				}
				q = std::move(q2);
				c = 1 - c;
			}
		}
	}

	set<int> poss{ 0 };
	for (auto& group : groups) {
		set<int> poss_next;
		for (auto i : poss) {
			poss_next.insert(i + group[0]);
			poss_next.insert(i + group[1]);
		}
		poss = std::move(poss_next);
	}

	int ans = m;
	for (auto i : poss) {
		int j = n - i;
		ans = min(ans, i*(i - 1) / 2 + j * (j - 1) / 2);
	}
	cout << ans << endl;
}

