/*
把图分成两个团.
让团的大小绝对值最小
*/
#define M 705
bool a[M][M],dp[M];
int cnt[M][2],tot,col[M],n,m;
struct ed{
	int x,nx;
}e[M*M*2];
int nx[M],ecnt=1;
void add(int x,int y){
	e[ecnt]=(ed){y,nx[x]};
	nx[x]=ecnt++;
}
void dfs(int f,int x,int v,int id){
	col[x]=v;
	cnt[id][v]++;
	for (int i=nx[x];i;i=e[i].nx)if (e[i].x!=f){
		if (col[e[i].x]==-1){
			dfs(x,e[i].x,!v,id);
		}
		else {
			if (col[x]==col[e[i].x]){
				printf("-1\n");	
				exit(0);
			}
		}
	}
}
int main(){
//	freopen(".in","r",stdin);
//	freopen(".out","w",stdout);
//	freopen("1.in","r",stdin);
	read(n); read(m);
	int i,x,y,j;
	ll res=n*(n+1)/2,sz1,sz2;
	for (i=1;i<=m;i++){
		read(x); read(y);
		a[x][y]=a[y][x]=1;
	}
	for (i=1;i<=n;i++){
		col[i]=-1;
		for (j=i+1;j<=n;j++)if (!a[i][j]){
			add(i,j);
			add(j,i);
		}
	}
	for (i=1;i<=n;i++)if (col[i]==-1){
		dfs(i,i,1,++tot);
	}
	dp[0]=1;
	for (i=1;i<=tot;i++){
		for (j=n;j>=0;j--)if (dp[j]){
			dp[j+cnt[i][0]]=1;
		}
	}
	for (i=0;i<=n;i++)if (dp[i]){
		sz1=i; sz2=n-i;
		Min(res,(sz1)*(sz1-1)/2+(sz2)*(sz2-1)/2);
	}
	printf("%lld\n",res);
	return 0;
}

