constexpr ll mod=1000000007;
constexpr int inf=1000000000;
constexpr ll linf=1000000000000000000;

int n;
bool g[700][700];
int num[700];
vector<pair<int,int>> sz;
int b,w;

bool dfs(int v,int c){
    if(c==1)++b;
    else ++w;
    num[v]=c;
    rep(i,n){
        if(i==v)continue;
        if(!g[v][i]){
            if(num[i]==c)return false;
            if(num[i]==0&&!dfs(i,-c))return false;
        }
    }
    return true;
}

int main(){
    int m;
    cin>>n>>m;
    rep(i,m){
        int a,b;
        cin>>a>>b;
        --a,--b;
        g[a][b]=g[b][a]=true;
    }
    rep(i,n){
        if(num[i]==0){
            b=0,w=0;
            if(!dfs(i,1)){
                cout<<-1<<endl;
                return 0;
            }
            sz.push_back(make_pair(b,w));
        }
    }
    bool dp[sz.size()][n+1]={};
    dp[0][0]=true;
    rep(i,sz.size()){
        for(int j=0;j<=n;++j){
            if(j+sz[i].first<=n)dp[i+1][j+sz[i].first]|=dp[i][j];
            if(j+sz[i].second<=n)dp[i+1][j+sz[i].second]|=dp[i][j];
        }
    }
    int mn=inf;
    int ans;
    rep(i,n+1){
        if(dp[sz.size()][i]){
            if(abs(n-2*i)<mn){
                mn=abs(n-2*i);
                ans=i;
            }
        }
    }
    cout<<ans*(ans-1)/2+(n-ans)*(n-ans-1)/2<<endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const int N = 800;
int gr[N][N];
int cgr[N][N];
bool bprt = 0;
int col[N];
int n;

void dfs(int v, int c) {
    col[v] = c;
    for(int i = 1; i <= n; ++i) {
        if(cgr[v][i]) {
            if(col[i] == -1)
                dfs(i, c ^ 1);
            else if(col[i] != (c ^ 1))
                bprt = 0;
        }
    }
}


int main() {
    int m;
    cin>>n>>m;
    for(int i = 0; i < m; ++i) {
        int u, v;
        cin>>u>>v;
        gr[u][v] = 1;
        gr[v][u] = 1;
    }
    for(int i = 1; i <= n; ++i) {
        for(int j = 1; j <= n; ++j) {
            if(i == j) continue;
            if(!gr[i][j]) cgr[i][j] = 1;
        }
    }

    memset(col, -1, sizeof(col));
    bprt = 1;
    for(int i = 1; i <= n; ++i) {
        if(col[i] == -1)
            dfs(i, 0);
    }
    if(bprt == 0) {
        cout<<-1<<endl;
    }
    else {
        int ans = 0;
        for(int i = 1; i <= n; ++i)
            for(int j = 1; j <= n; ++j) {
                if(gr[i][j] && col[i] == col[j])
                    ans++;
            }
        cout<<ans/2<<endl;
    }

    return 0;
}

