		int nn = v[i].size();
		if(nn == 0) continue;
		map<int, int> mp;
		int cnt = 0;
		for(int x : v[i]) {
			mp[x] = cnt;
			++cnt;
		}
		BipartiteGraph bg(nn);
		for(int x : v[i]) {
			for(int y : v[i]) {
				if(g[x][y]) {
					bg.addEdge(mp[x], mp[y]);
				}
			}
		}
		try {
			int s = bg.bipart();
			set<int> tmp;
			for(int ss : S) {
				tmp.insert(s + ss);
				tmp.insert((n - s) + ss);
			}
			S = tmp;
		}
		catch(...) {
			cout << -1 << '\n';
			return 0;
		}
	}
	int ans = 1e9;
	for(int s : S) {
		int t = n - s;
		int tmp = s * (s - 1) / 2 + t * (t - 1) / 2;
		ans = min(ans, tmp);
	}
	cout << ans << '\n';
	return 0;
}

