bool bfs(int s)
{
	static queue<int> q;
	int g[2] = {0, 0};
	c[s] = 0;
	q.push(s);
	while (!q.empty())
	{
		int u = q.front();
		g[c[u]]++;
		q.pop();
		for (int j = head[u]; j != 0; j = e[j].next)
		{
			int v = e[j].to;
			if (c[v] == -1)
