	for (int i = MAXN - n; i <= MAXN + n; i++)
		if (f[N][i])
			D = min(D, abs(i - MAXN));
	A = (n - D) / 2, B = A + D;
	res = A * (A - 1) / 2 + B * (B - 1) / 2;
	cout << res << endl;
	return 0;
}

