                ++size_c1;
            }
            dfs(adj, neighbor, clique_id, size_c1, size_c2);
        }
    }        
}


// returns number of edges in a complete undirected graph
int num_edges(int v){
    return v * (v - 1) / 2;
}


int main()
{
    int N, M;
    cin >> N >> M;

    // O(N^2)
    vector<unordered_set<int> > adj;
    for (int i = 0; i < N; ++i){
        unordered_set<int> adj_set;
        for (int j = 0; j < N; ++j){
            if (i != j){
                adj_set.insert(j);                
            }
        }
        adj.emplace_back(adj_set);
    }

    // O(M) -> O(N^2)
    int v1, v2;
    for (int i = 0; i < M; ++i){
        cin >> v1 >> v2;
        adj[v1 - 1].erase(v2 - 1);
        adj[v2 - 1].erase(v1 - 1);
    }

    // O(N + M) -> O(N^2) in this question 
    vector<int> clique_id(N, 0);
    int size_c1 = 0, size_c2 = 0;
    list<pair<int, int> > clique_sizes;
    for (int i = 0; i < N; ++i){
        if (clique_id[i] == 0){
            clique_id[i] = 1;
            ++size_c1;

            dfs(adj, i, clique_id, size_c1, size_c2);

            clique_sizes.emplace_back(make_pair(size_c1, size_c2));
            size_c1 = 0;
            size_c2 = 0;
        }
    }

    // clique_sizes <= N/2 -> O(N^2)
    vector<bool> possible(N + 1, false);
    possible[0] = true;  // considering 0 cliques, the size of S can only be 0
    for (const auto &p : clique_sizes){
        vector<bool> possible_tmp(N + 1, false);
        for (int i = 0; i <= N; ++i){
            if (possible[i]){
                possible_tmp[i + p.first] = true;
                possible_tmp[i + p.second] = true;
            }
        }
        possible = move(possible_tmp);
    }

    for (int i = N / 2; i <= N; ++i){
        if (possible[i]){
            cout << num_edges(N - i) + num_edges(i) << endl;
            break;
        }
    }

    return 0;
}

