#define PB push_back  
#define MP make_pair  
#define SZ(v) ((int)(v).size())  
#define FOR(i,a,b) for(int i=(a);i<(b);++i)  
#define REP(i,n) FOR(i,0,n)  
#define FORE(i,a,b) for(int i=(a);i<=(b);++i)  
#define REPE(i,n) FORE(i,0,n)  
#define FORSZ(i,a,v) FOR(i,a,SZ(v))  
#define REPSZ(i,v) REP(i,SZ(v))  
typedef long long ll;
typedef unsigned long long ull;
ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=700;

int n,m;
bool adj[MAXN][MAXN];

vector<pair<int,int> > missing;
bool done[MAXN];

vector<pair<int,int> > pairs;
int single;
bool can[MAXN+1];



void run() {
	scanf("%d%d",&n,&m);
	REP(i,m) { int a,b; scanf("%d%d",&a,&b); --a,--b; adj[a][b]=adj[b][a]=true; }

	pairs.clear(); single=0; REP(i,n) done[i]=false;
	missing.clear(); REP(i,n) FOR(j,i+1,n) if(!adj[i][j]) missing.PB(MP(i,j));
	REPSZ(i,missing) {
		int a=missing[i].first,b=missing[i].second;
		if(done[a]||done[b]) continue;
		vector<int> lst[2];	queue<pair<int,int> > q;
		q.push(MP(a,0)); q.push(MP(b,1)); done[a]=done[b]=true; lst[0].PB(a); lst[1].PB(b);
		while(!q.empty()) {
			int at=q.front().first,side=q.front().second; q.pop();
			REP(to,n) if(!done[to]&&!adj[at][to]) {
				done[to]=true; q.push(MP(to,1-side)); lst[1-side].PB(to);
			}
		}
		REP(side,2) REPSZ(j,lst[side]) FORSZ(k,j+1,lst[side]) { int u=lst[side][j],v=lst[side][k]; if(!adj[u][v]) { printf("-1\n"); return; } }
		REP(side,2) REPSZ(j,lst[side]) REP(k,n) if(!done[k]) assert(adj[lst[side][j]][k]);
		pairs.PB(MP(SZ(lst[0]),SZ(lst[1])));		
	}
	REP(i,n) if(!done[i]) ++single;

	REPE(j,n) can[j]=j<=single;
	REPSZ(i,pairs) for(int j=n;j>=0;--j) if(can[j]) { can[j]=false; can[j+pairs[i].first]=true,can[j+pairs[i].second]=true; }
	int mid=(n+1)/2;
	FORE(i,mid,n) if(can[i]) {
		int a=i,b=n-i;
		int ans=a*(a-1)/2+b*(b-1)/2;
		printf("%d\n",ans); return;
	}
	assert(false);
}

int main() {
	run();
	return 0;
}

