bool chk[705][705];

int r[705][2];
int root(int x) {
	if (x == r[x][0]) return x;

	int t = r[x][0];
	r[x][0] = root(t);
	r[x][1] ^= r[t][1];
	return r[x][0];
}

int cnt[1050][2];
bool dp[705];
bool tdp[705];

int main() {
	int N, M, i, j;
	scanf("%d %d", &N, &M);
	for (i = 1; i <= M; i++) {
		int t1, t2;
		scanf("%d %d", &t1, &t2);
		chk[t1][t2] = chk[t2][t1] = true;
	}

	for (i = 1; i <= N; i++) r[i][0] = i, r[i][1] = 0;
	for (i = 1; i <= N; i++) {
		for (j = i + 1; j <= N; j++) {
			if (chk[i][j]) continue;
			int t1 = root(i), t2 = root(j);
			int x = r[i][1] ^ r[j][1] ^ 1;
			if (t1 == t2) {
				if (x == 1) return !printf("-1\n");
				continue;
			}
			r[t1][0] = t2;
			r[t1][1] = x;
		}
	}

	dp[0] = true;
	for (i = 1; i <= N; i++) {
		int x = root(i);
		cnt[x][r[i][1]]++;
	}
	for (i = 1; i <= N; i++) {
		for (j = 0; j <= N; j++) tdp[j] = false;
		for (j = 0; j <= N; j++) {
			if (!dp[j]) continue;
			tdp[j + cnt[i][0]] = true;
			tdp[j + cnt[i][1]] = true;
		}
		for (j = 0; j <= N; j++) dp[j] = tdp[j];
	}

	int mn = INF;
	for (i = 1; i < N; i++) if (dp[i]) mn = min(mn, i*(i - 1) / 2 + (N - i)*(N - i - 1) / 2);
	return !printf("%d\n", mn);
}

#include<bits/stdc++.h>

const int N = 710;
const int M = N << 1;

int mat[N][N];
std::bitset <N> dp[2];
int fa[M], sz[2][M];
bool vis[N];

int find(int u){
    return fa[u] == u ? u : (fa[u] = find(fa[u]));
}

void unite(int u, int v){
    u = find(u), v = find(v);
    if (u == v) return;
    fa[u] = v;
}

inline int sqr(int n){return n * (n - 1) / 2;}

int main(){
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0, u, v; i < m; ++ i){
        scanf("%d%d", &u, &v);
        mat[u][v] = mat[v][u] = 1;
    }
    for (int i = 1; i < M; ++ i){
        fa[i] = i;
    }
    for (int i = 1; i <= n; ++ i){
        for (int j = i + 1; j <= n; ++ j){
            if (!mat[i][j]){
                if (find(i) == find(j)){
                    puts("-1");
                    return 0;
                }
                unite(i, j + n);
                unite(i + n, j);
            }
        }
    }
    for (int i = 1; i <= n; ++ i){
        ++ sz[0][find(i)];
    }
    for (int i = n + 1; i <= n << 1; ++ i){
        ++ sz[1][find(i)];
    }
    int now = 0;
    dp[now].set(0);
    for (int i = 1; i <= n << 1; ++ i){
        if (find(i) != i || vis[i]) continue;
        vis[i] = vis[find(i + n)] = true;
        dp[now ^ 1] = dp[now] << sz[0][i] | dp[now] << sz[1][i];
        now ^= 1;
    }
    int min = INT_MAX;
    for (int i = 1; i <= n; ++ i){
        if (!dp[now].test(i)) continue;
        min = std::min(min, sqr(i) + sqr(n - i));
    }
    printf("%d\n", min);
    return 0;
}

