bool dp[705][705];

P dfs(int v, int prev, int c)
{
	color[v] = c;
	P ret = make_pair(0, 0);
	if(color[v] == 1) ret.first++; else ret.second++;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		if(color[G[v][i]] == -c) continue;
		if(color[G[v][i]] == c) return make_pair(-1, -1);
		P res = dfs(G[v][i], v, -c);
		if(res.first == -1) return make_pair(-1, -1);
		ret.first += res.first, ret.second += res.second;
	}
	return ret;
}

int comb(int x)
{
	return x * (x-1) / 2;
}

int main(void)
{
	cin >> n >> m;
	int a, b;
	for(int i = 0; i < m; i++){
		cin >> a >> b;
		mat[a][b] = mat[b][a] = 1;
	}
	for(int i = 1; i <= n; i++){
		for(int j = 1; j <= n; j++){
			if(i != j && mat[i][j] == 0) G[i].push_back(j);
		}
	}

	for(int i = 1; i <= n; i++){
		if(color[i] == 0){
			P res = dfs(i, -1, 1);
			if(res.first == -1){
				cout << -1 << endl;
				return 0;
			}
			vec.push_back(res);
		}
	}

	int N = vec.size();
	dp[0][0] = true;
	for(int i = 0; i < N; i++){
		for(int j = 0; j <= n; j++){
			if(!dp[i][j]) continue;
			dp[i+1][j+vec[i].first] = true;
			dp[i+1][j+vec[i].second] = true;
		}
	}

	int ans = inf;
	for(int i = 0; i <= n; i++){
		if(!dp[N][i]) continue;
		ans = min(ans, comb(i) + comb(n-i));
	}
	cout << ans << endl;
	return 0;
}

