/* do your best */
pair<int, int> dfs(int c, vector<vector<int>> &g, vector<int> &used, int cur, int par = -1) {
  int b = 0;
  int w = 0;
  if (c == 0) b++;
  else w++;
  used[cur] = c;
  int nc = (c + 1) % 2;

  for (auto nxt : g[cur]) {
    if (nxt == par) continue;

    if (used[nxt] == -1) {
      int bb;
      int ww;
      tie(bb, ww) = dfs(nc, g, used, nxt, cur);
      if (bb == -1) return {-1, -1};
      b += bb;
      w += ww;
    } else {
      if (used[nxt] == c) {
        return {-1, -1};
      }
    }
  }

  return {b, w};
}

int main() {

  int n, m; cin >> n >> m;
  vector<vector<int>> g(n, vector<int>(n, 0));
  for (int i = 0; i < m; i++) {
    int a, b; cin >> a >> b;
    a--;
    b--;
    g[a][b] = 1;
    g[b][a] = 1;
  }

  int cm = 0;
  vector<vector<int>> cg(n);
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (g[i][j] == 0) {
        cm++;
        cg[i].push_back(j);
        cg[j].push_back(i);
      }
    }
  }


  // 連結成分ごとに二分彩色する
  vector<pair<int, int>> cnt;
  vector<int> used(n, -1);
  for (int i = 0; i < n; i++) {
    if (used[i] == -1) {
      int b, w;
      tie(b, w) = dfs(0, cg, used, i);
      cnt.emplace_back(b, w);
      if (b == -1) {
        cout << -1 << endl;
        return 0;
      }
    }
  }

  /*for (int i = 0; i < cnt.size(); i++) {
    cerr << cnt[i].first << " " << cnt[i].second << endl;
  }*/

  // dp[pos][赤の個数] := true / false
  vector<vector<bool>> dp(cnt.size() + 1, vector<bool>(cnt.size() + 1, false));
  dp[0][0] = true;

  lint ans = -INF; // 最大化する

  for (int i = 0; i < cnt.size(); i++) {
    for (int j = 0; j <= cnt.size(); j++) {
      if (!dp[i][j]) continue;
      dp[i + 1][j + cnt[i].first] = true;
      dp[i + 1][j + cnt[i].second] = true;
    }
  }

  for (int i = 0; i <= n; i++) {
    if (dp[cnt.size()][i]) {
      lint tmp = i * (n - i) - cm;
      ans = max(ans, tmp);
    }
  }

  cerr << m - ans << endl;

  return 0;
}

