pair <int, int> dfs(int u) {
    used[u] = 1;
    pair <int, int> ans = {0, 0};
    if (!c[u]) ++ans.first;
    else ++ans.second;
    for (int v : g[u]) {
        if (!used[v]) {
            auto t = dfs(v);
            ans.first += t.first; ans.second += t.second;
        }   
    }   
    return ans;
}   

