class UnionFind {
#define H pair<int, int>
#define fs first
#define sc second
public:
	int size = 0;
	H pa[400002];
	void init(int n) {
		size = n;
		for (int i = 0; i <= size; i++) pa[i] = H{ i,1 };
	}
	int root(int x) {
		if (pa[x].fs == x) return x;
		return pa[x].fs = root(pa[x].fs);
	}
	void unite(int x, int y) {
		x = root(x); y = root(y);
		if (pa[x].sc < pa[y].sc) swap(x, y);
		if (x == y) return;
		pa[x].sc += pa[y].sc;
		pa[y].fs = x;
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	H operator[](int x) {
		x = root(x);
		return pa[x];
	}
};
UnionFind uf;
int n, m;
int b[1000][1000];
bool dp[2000];
bool c[1000];
signed main() {
	cin >> n >> m;
	uf.init(3 * n);
	rep(i, m) {
		int u, v;
		cin >> u >> v;
		b[u][v] = 1;
		b[v][u] = 1;
	}
	reo(i, n) {
		rng(j, i + 1, n + 1) {
			if (!b[i][j]) {
				uf.unite(i + n, j);
				uf.unite(i, j + n);
			}
		}
	}
	vec<H>a;
	reo(i, n) {
		if (uf.same(i, i + n)) {
			cout << -1 << endl;
			return 0;
		}
		if (uf.root(i) == i&&!c[i]) {
			int k = 0;
			reo(j, n) {
				if (uf[j].fs == i) k++;
				if (uf.same(j, i) || uf.same(i + n, j) || uf.same(i, j + n) || uf.same(i + n, j + n)) {
					c[j] = 1;
				}
			}
			a.pp(k, uf[i].sc - k);
		}
	}
	dp[0] = 1;
	for(auto g:a) {
		req(i, n + 1) {
			dp[i + g.fs] |= dp[i];
			dp[i + g.sc] |= dp[i];
			dp[i] = 0;
		}
	}
	int ans = inf;
	rep(i, n + 1) if (dp[i]) ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	cout << ans << endl;
}

