void dfs(int v, int s, vector<int> &side, bool &ok, int &count0, int &count1,
         vector<vector<int>> &adj) {
  if (side[v] != -1) {
    if (side[v] != s)
      ok = false;
    return;
  }
  side[v] = s;
  if (s == 0) ++count0;
  else ++count1;
  for (int u : adj[v])
    dfs(u, s ^ 1, side, ok, count0, count1, adj);
}

