const int MAX_N = 710;
bool d[MAX_N][MAX_N];

ll calc(int n) {
    vector<vector<int>> es(n);
    vector<int> color(n, -1);
    rep(i, n) rep(j, n) if(!d[i][j]) es[i].pb(j);
    using P = pair<int, int>;
    vector<P> v;
    rep(i, n) {
        if(color[i] != -1) continue;
        vector<int> cnt(2);
        color[i] = 0;
        cnt[0]++;
        queue<int> q;
        q.push(i);
        while(!q.empty()) {
            int p = q.front();
            q.pop();
            for(auto& to : es[p]) {
                if(color[to] == -1) {
                    color[to] = !color[p];
                    q.push(to);
                    cnt[color[to]]++;
                }
                else if(color[p] == color[to]) {
                    return -1;
                }
            }
        }
        v.push_back(make_pair(cnt[0], cnt[1]));
    }
    vector<int> cur(n+10, INF);
    cur[0] = 0;
    rep(i, v.size()) {
        vector<int> nxt(n+10, INF);
        for(int j = 0; j + v[i].fi < nxt.size(); ++j) {
            nxt[j + v[i].fi] = min(nxt[j+v[i].fi], cur[j] + v[i].se);
        }
        for(int j = 0; j + v[i].se < nxt.size(); ++j) {
            nxt[j + v[i].se] = min(nxt[j+v[i].se], cur[j] + v[i].fi);
        }
        swap(cur, nxt);
    }
    ll ret = 4e18;
    rep(i, cur.size()) {
        ret = min(ret, i*(i-1LL)/2LL+(cur[i] * (cur[i]-1LL))/2LL);
    }
    return ret;
}

int main() {
    int n, m;
    cin >> n >> m;
    rep(i, m) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        d[a][b] = d[b][a] = true;
    }
    rep(i, n) d[i][i] = true;
    int ans = calc(n);
    cout << ans << endl;
    return 0;
}

