vector<veci> adj;
veci vis;
veci deg;

int dfs(int nd, int comp) {
    int ret = 1;
    vis[nd] = comp;
    for (int i=0; i<adj[nd].size(); ++i) {
        int t = adj[nd][i];
        if (!vis[t]) {
            ret += dfs(t, comp);
        }
    }

    return ret;
}

void solve() {
    int n, m;
    cin >> n >> m;

    adj.clear();
    adj.resize(n);
    vis.clear();
    vis.resize(n,0);
    deg.clear();
    deg.resize(n,0);
    int a, b;
    for (int i=0; i<m; ++i) {
        cin >> a >> b;
        a--, b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    veci comp = {0};
    int ncomp = 0;
    for (int i=0; i<n; ++i) {
        if (!vis[i]) {
            ncomp++;
            comp.push_back(dfs(i, ncomp));
        }
    }

    int ans = -1;
    if (ncomp==2) {
        bool ok = true;
        for (int i=0; i<n; ++i) {
            if (deg[i]<comp[vis[i]]-1) {
                ok = false;
                break;
            }
        }
        if (ok) {
            ans = (comp[1]>0?(comp[1]*(comp[1]-1)/2):0) + (comp[2]*(comp[2]-1)/2);
        }
    } else if (ncomp==1) {
        int mini = 0, minv = n;
        for (int i=0; i<n; ++i) {
            if (deg[i]<minv) {
                minv = deg[i];
                mini = i;
            }
        }

        int cnt = 1;
        vis[mini] = 2;
        for (int i=0; i<adj[mini].size(); ++i) {
            int t = adj[mini][i];
            vis[t] = 2;
            cnt++;
        }
        comp.back() -= cnt;
        comp.push_back(cnt);
        bool ok = true;
        for (int i=0; i<n; ++i) {
            if (deg[i]<comp[vis[i]]-1) {
                ok = false;
                break;
            }
        }
        if (ok) {
            ans = (comp[1]>0?(comp[1]*(comp[1]-1)/2):0) + (comp[2]*(comp[2]-1)/2);
        }
    }

    cout << ans << endl;
}

