typedef long long ll;
typedef long double ld;
const int N = (int)1e3 + 34;
const ld EPS = 1e-8;

vector<int> es[N];
bool ue[N][N];
int col[N];
vector<int> sz[2] = {{0}, {0}};
bool fail;

void dfs(int v, int cl) {
    if (col[v] != -1 && col[v] != cl) {
        fail = true;
        return;
    }
    if (col[v] != -1) return;
    col[v] = cl;
    sz[cl].back()++;

    for (int w: es[v]) {
        dfs(w, 1 - cl);
    }
}

void solve() {
    fail = false;
    sz[0].clear();
    sz[1].clear();
    for (int i = 0; i < N; i++) {
        col[i] = -1;
        es[i].clear();
        for (int j = 0; j < N; j++) {
            ue[i][j] = false;
        }
    }
    int n, m, v1, v2;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        cin >> v1 >> v2;
        v1--;
        v2--;
        ue[v1][v2] = ue[v2][v1] = true;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && !ue[i][j]) {
                es[i].push_back(j);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (col[i] != -1) continue;
        sz[0].push_back(0);
        sz[1].push_back(0);
        dfs(i, 0);
    }

    if (fail) {
        cout << -1 << "\n";
        return;
    }

    vector<bool> dp(N, false);
    int mn = 0;
    for (int i = 0; i < (int)sz[0].size(); i++) {
        mn += min(sz[0][i], sz[1][i]);
    }
    dp[mn] = true;

    for (int i = 0; i < (int)sz[0].size(); i++) {
        int a = sz[0][i];
        int b = sz[1][i];
        int d = max(a, b) - min(a, b);
        for (int j = N - 1; j >= 0; j--) {
            if (j - d >= 0 && dp[j - d]) dp[j] = true;
        }
    }

    int ans = n * n * 2;
    for (int i = 0; i < N; i++) {
        if (dp[i]) ans = min(ans, i * (i - 1) + (n - i) * (n - i - 1));
    }

    cout << ans / 2 << "\n";
}

