    set<pii> S;
    for(int i = 1; i <= n; ++i) 
        for(int j = i+1; j <= n; ++j) 
            S.emplace(i, j);
    for(int i = 0, u, v; i < m; ++i) {
        scanf("%d %d", &u, &v); 
        if(u > v) swap(u, v);
        S.erase(pii(u, v));
    }
