struct Problem {

	bool road[700][700] = {};

	void Solve() {
		UL N, M; cin >> N >> M;
		rep(i, M) {
			UL a, b; cin >> a >> b; a--; b--;
			road[a][b] = road[b][a] = true;
		}
		rep(i, N) road[i][i] = true;
		vector<int> G(N);
		vector<pair<UL, UL>> Sz;
		rep(s, N) {
			if (G[s]) continue;
			G[s] = s + 1;
			queue<UL> Q; Q.push(s);
			pair<UL, UL> sz = { 0, 0 };
			while (Q.size()) {
				UL p = Q.front(); Q.pop();
				if (G[p] > 0) sz.first++; else sz.second++;
				//rep(i, N) cout << G[i] << " "; cout << endl;
				rep(e, N) {
					if (road[p][e]) continue;
					if (G[e] == G[p]) { cout << -1 << endl; return; }
					if (G[e]) continue;
					G[e] = -G[p];
					Q.push(e);
				}
			}
			Sz.push_back(sz);
		}
		bool dp[701] = {};
		dp[0] = true;
		for (auto p : Sz) {
			bool buf[701] = {};
			for (UL j = p.first; j <= N; j++) buf[j] = buf[j] || dp[j - p.first];
			for (UL j = p.second; j <= N; j++) buf[j] = buf[j] || dp[j - p.second];
			rep(i, N + 1) dp[i] = dp[i] || buf[i];
		}
		UL ans = 1000000000;
		rep(i, N + 1) {
			if (dp[i]) {
				UL buf = i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2;
				ans = min(ans, buf);
			}
		}
		if (ans == 1000000000) cout << -1 << endl;
		else cout << ans << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
