	if(k==v.size()) return cur==0;
	if(d[cur][k]>=0) return d[cur][k];
	if(cur>=v[k].first && f(cur-v[k].first,k+1))
		return d[cur][k]=1;
	if(cur>=v[k].second && f(cur-v[k].second,k+1))
