			if(!T[i][j]) G[i].eb(j);
	}

	dp[0] = true;
	for(int i = 1; i <= N; i++) if(!chk[i]) {
		int a = 0, b = 0;
		f(i, a, b);
		dp = (dp << a) | (dp << b);
	}

	for(int i = 0; i <= N; i++) if(dp[i]) {
		int t = i*(i-1) + (N-i)*(N-i-1);
		t >>= 1;
		if(t < Ans) Ans = t;
	}

	cout << Ans << endl;
	return 0;
}

