p taka_dfs(int m, int i, int tak, int has){
  debug("taka_dfs(%d, %d, %d, %d)\n", m, i, tak, has);
  if(i >= m) return {tak, has};
  if(dp[i][tak] != p{-1, -1}) return dp[i][tak];
  if(dp[i][has] != p{-1, -1}) return dp[i][has];
  p used = taka_dfs(m, i + 1,
              tak + island_vertices[i].fi, has + island_vertices[i].se);
  p unused = taka_dfs(m, i + 1,
              tak + island_vertices[i].se, has + island_vertices[i].fi);
  int diff_used = abs(used.fi - used.se);
  int diff_unused = abs(unused.fi - unused.se);
  return dp[i][tak] = (diff_used <= diff_unused ? used : unused);
}

