  for (int j : Gdash[i])
  {
    if(col[j] == col[i])
      return {false, {-1, -1}};
    if(col[j] == -1){
      auto ret = paint_dfs(j, !color);
      if(!ret.fi) return ret;
      else{
        taka += ret.se.fi;
        hashi += ret.se.se;
      }
    }
  }
  return {true, {taka, hashi}};
}
