const int maxN = 705;
bool a[maxN][maxN];
int n, m;
vector < pair < int, int > > cli;
int can = 0;
bool used[maxN];
void solve(vector < int > &all) {
    if (all.empty()) return;
    for (int i = 1; i <= n; i++) used[i] = true;
    vector < int > cur[2];
    int ind1 = -1;
    int ind2 = -1;
    for (int i = 0; i < all.size(); i++) {
        used[all[i]] = false;
        for (int j = i + 1; j < all.size(); j++) {
            if (a[all[i]][all[j]] == false) {
                ind1 = all[i];
                ind2 = all[j];
                break;
            }
        }
    }
    if (ind1 == -1) {
        can = all.size();
        return;
    }
    cur[0].push_back(ind1);
    cur[1].push_back(ind2);
    queue < pair < int, int > > q;
    q.push(make_pair(ind1, 0));
    q.push(make_pair(ind2, 1));
    used[ind1] = true;
    used[ind2] = true;
    while (!q.empty()) {
        auto t = q.front();
        q.pop();
        int part = t.second;
        int v = t.first;
        for (int i = 1; i <= n; i++) {
            if (v == i) continue;
            if (a[v][i]) continue;
            if (used[i]) continue;
            q.push(make_pair(i, 1 - part));
            used[i] = true;
            cur[1 - part].push_back(i);
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < cur[i].size(); j++) {
            for (int k = j + 1; k < cur[i].size(); k++) {
                if (!a[cur[i][j]][cur[i][k]]) {
                    cout << -1;
                    exit(0);
                }
            }
        }
    }
    cli.push_back(make_pair(cur[0].size(), cur[1].size()));
    vector < int > ne;
    for (int i = 0; i < all.size(); i++) {
        if (used[all[i]]) continue;
        ne.push_back(all[i]);
    }
    solve(ne);
}
