        for (int j = 0; j <= n; j++) {
            if (dp[i][j] == false) continue;
            dp[i + 1][j + cli[i].first] = true;
            dp[i + 1][j + cli[i].second] = true;
        }
    }
    int near = 0;
    for (int i = 0; i <= n; i++) {
        if (dp[cli.size()][i] == true) {
