int N, M;
vector<int> G[700];

int main() {
  cin >> N >> M;

  bool edges[N][N] = {{0}};
  fill_n(*edges, N*N, 0);  
  for ( int i = 0; i < M; i++ ) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    edges[a][b] = edges[b][a] = true;
  }

  // 補グラフ生成
  for ( int i = 0; i < N; i++ ) {
    for ( int j = 0; j < N; j++ ) { 
      if ( i == j ) continue;
      if ( !edges[i][j] ) {
	G[i].push_back(j);
      }
    }
  }

  vector<P> bi_graphs;
  bool flag = true;
  vector<int> used(N, -1);  
  for ( int i = 0; i < N; i++ ) {
    if ( used[i] >= 0 ) continue;
    int cnt[2] = {0};
    queue<P> Q;
    Q.push(P(i, 0)); // node, color
    while ( !Q.empty() ) {
      P p = Q.front(); Q.pop();
      int v = p.first, c = p.second;

      if ( used[v] >= 0 ) {
	if ( used[v] != c ) {
	  flag = false;
	  break;
	} else {
	  continue;
	}
      }

      used[v] = c;
      cnt[c]++;      
      for ( int u: G[v] ) {
	Q.push(P(u, !c));	
      }
    }

    if ( !flag ) break;
    bi_graphs.push_back(P(cnt[0], cnt[1]));    
  }

  if ( !flag ) {
    cout << -1 << endl;
    return 0;
  }

  int n = bi_graphs.size();
  vector<int> dp(N+1, 0), nxt(N+1, 0);
  dp[0] = 1;  
  for ( int i = 0; i < n; i++ ) {
    int a = bi_graphs[i].first, b = bi_graphs[i].second;
    nxt = vector<int>(N+1, 0);    
    for ( int j = N; j >= 0; j-- ) {
      if ( !dp[j] ) continue;
      if ( j+a <= N ) nxt[j+a] = true;
      if ( j+b <= N ) nxt[j+b] = true;
    }
    swap(dp, nxt);    
  }

  int ans = INF;
  for ( int i = 0; i <= N; i++ ) {    
    if ( !dp[i] ) continue;
    int a = 0, b = 0;
    if ( i >= 2 ) a = i*(i-1)/2;
    if ( N-i >= 2 ) b = (N-i)*(N-i-1)/2;          
    ans = min(ans, a+b);
  }

  cout << ans << endl;

  return 0;
}

