bool compgraph(vector<int> &v, vector<vector<int> > &e){
    for(int i = 0; i < v.size(); i++){
        for(int j = 0; j < v.size(); j++){
            if(i == j)continue;
            auto lb = lower_bound(ALL(e[v[i]]), v[j]);
            if(lb == e[v[i]].end())return false;
            else if(v[j] != *lb)return false;
        }
    }
    return true;
}

