#define REP(i, N) for (int i = 0; i < (N); ++i)

const ll INF = 1LL << 60;
int N, M;
bool graph[707][707];
int done[707];
bool dp[707][707];

int a0, a1;
int b0, b1;

template<typename A, typename B>
void chmin(A &a, const B &b) {
    if (a > b) a = b;
}

ll comb(ll x) {
    return x * (x - 1) >> 1;
}

void bip(int cur, int clr = 0) {
    (clr == 0 ? a0 : a1)++;
    done[cur] = clr;
    REP(i, N) {
        if (not graph[cur][i]) continue;
        if (done[i] != -1) {
            if (done[i] != clr ^ 1) {
                cout << -1 << endl;
                exit(0);
            }
            continue;
        }
        bip(i, clr ^ 1);
    }
}

signed main() {
    cin >> N >> M;
    REP(i, N) REP(j, N) if (i != j) graph[i][j] = true;
    REP(i, M) {
        int A, B;
        cin >> A >> B;
        --A, --B;
        //graph[A].emplace_back(B);
        //graph[B].emplace_back(A);
        graph[A][B] = false;
        graph[B][A] = false;
    }
    REP(i, N) done[i] = -1;
    vector<pair<int, int>> prs;
    REP(i, N) {
        if (done[i] != -1) continue;
        bip(i);
        int x = a0 - b0, y = a1 - b1;
        if (x > y) swap(x, y);
        prs.emplace_back(x, y);
        b0 = a0, b1 = a1;
    }
    // for (auto& [x, y]: prs) {
    //     cerr << x << ' ' << y << endl;
    // }
    dp[0][0] = true;
    int sz = prs.size();
    REP(i, sz) {
        REP(j, N + 1) {
            if (not dp[i][j]) continue;
            dp[i + 1][j + prs[i].first] = true;
            dp[i + 1][j + prs[i].second] = true;
        }
    }
    ll res = INF;
    REP(i, N + 1) {
        if (not dp[sz][i]) continue;
        chmin(res, comb(i) + comb(N - i));
    }
    cout << res << endl;
}

