struct edge{
	int v;
	edge *next;
}pool[3*N*N],*h[N];

struct task{
	int x,y;
	inline task(){}
	inline task(int _x,int _y){
		x=_x;
		y=_y;
	}
}c[N];

int n,m,top=-1;
int map[N][N];
int col[N],cnt[2];
int Index,ans=P;
bitset<N> f,_f;

inline void addedge(int u,int v){
	edge *tmp=&pool[++top];
	tmp->v=v;tmp->next=h[u];h[u]=tmp;
}

#define g(x) ((x==1)?1:0)
#define cn2(x) ((x)*((x)-1)/2)

bool dfs(int u,int pre){

	//printf("%d <- %d\n",u,pre);

	col[u]=-col[pre]; cnt[g(col[u])]++;
	for(edge *tmp=h[u];tmp!=NULL;tmp=tmp->next){
		int v=tmp->v;
		if(v==pre) continue;
		if(col[v]==0){
			if(dfs(v,u)==false) return false;
		}
		else if(col[u]+col[v]!=0){
			return false;
		}
	}
	return true;
}

void init(){
	int x1,x2,last[2];
	cin>>n>>m;
	for(int i=1;i<=m;i++){
		scanf("%d%d",&x1,&x2);
		map[x1][x2]=map[x2][x1]=1;
	}
	for(int i=1;i<=n;i++){
		for(int j=1;j<=n;j++){
			if(i==j) continue;
			if(map[i][j]==0) addedge(i,j);
		}
	}
	col[0]=-1;
	for(int i=1;i<=n;i++){
		if(col[i]==0){
			last[0]=cnt[0];
			last[1]=cnt[1];
			if(dfs(i,0)==false){
				printf("-1\n");
				return ;
			}
			c[++Index]=task(cnt[0]-last[0],cnt[1]-last[1]);
		}
	}
	f[0]=1;
	for(int i=1;i<=Index;i++){
		_f=f;
		f|=(_f<<c[i].x);
		f|=(_f<<c[i].y);
	}
	for(int i=1;i<=n;i++){
		if(f[i]==0) continue;
		ans=min(ans,cn2(i)+cn2(n-i));
	}
	printf("%d\n",ans);
}

int main(){
	init();
	return 0;
}

