bool memo[N][N];

bool bipartite(){
	for(int i=1; i<=n; i++){
		if(C[i] == -1){
			queue<int> Q;
			C[i] = 0;
			Q.emplace(i);
			int c1 = 1;
			int c2 = 0;
			while(!Q.empty()){
				int u = Q.front(); Q.pop();
				for(int i=0; i<G[u].size(); i++){
					int v = G[u][i];
					if(C[v] == -1){
						C[v] = 1 - C[u];
						if(C[v] == 0) c1++;
						else c2++;
						Q.emplace(v);
					}
					else if(C[v] == C[u]) return false;
				}
			}
			comps.emplace_back(mp(c1,c2));
		}
	}
	return true;
}

int getValue(int a, int b){
	int ans = a * (a-1) + b * (b-1);
	ans >>= 1;
	return ans;
}

