		b--;c--;
		a[b][c] = 1;
		a[c][b] = 1;
	}
	ll ans = LLINF;
	REP(i, n){
		for(int j = i + 1; j < n; ++j){
			int x = 0, y = 0;
			bool flg = true;
			if(a[i][j]) continue;
			REP(k, n){
				if(a[i][k] + a[j][k] == 0) {
					flg = false;
					break;
				}
				x += a[i][k];
				y += a[j][k];
			}
			if(!flg) break;
			ll befans = ans;
			if(x < n / 2) ans = min(ans, (ll)x * (x - 1) / 2 + (ll)(n - x) * (n - x - 1) / 2);
			else if(y < n / 2)ans = min(ans, (ll)y * (y - 1) / 2 + (ll)(n - y) * (n - y - 1) / 2);
