namespace Header_Template {
  typedef long long li;
  template<class T>inline void read(T &x) {
    x = 0;
    T tmp = 1;
    char c = getchar();
    while ((c < '0' || c > '9') && c != '-') c = getchar();
    if (c == '-') tmp = -1, c = getchar();
    while (c >= '0' && c <= '9')
      x = (x << 1) + (x << 3) + c - '0', c = getchar();
    x *= tmp;
  }
  template<class T>inline void Max(T &x, T y) {
    if (y > x) x = y;
  }
  template<class T>inline void Min(T &x, T y) {
    if (y < x) x = y;
  }
}
using namespace Header_Template;

const int N = 710;
int n, m, a[N][N];
int cnt, fa[N], id[N], col[N], f[N], ans;
vector<int> g[N], sub[N];

int Find(int x) {
  if (fa[x] != x) fa[x] = Find(fa[x]);
  return fa[x];
}
void Color(int x, int cur) {
  col[x] = cur;
  for (int y : g[x]) {
    if (~col[y]) {
      if (col[y] == col[x]) {
        ans = -1;
        return;
      } else continue;
    }
    Color(y, cur ^ 1);
  }
}
void Solve(int x, int y) {
  for (int i = n; ~i; --i) {
    int cur = 0;
    if (i >= x) cur |= f[i - x];
    if (i >= y) cur |= f[i - y];
    f[i] = cur;
  }
}
int main(void) {
  read(n), read(m);
  for (int i = 1, x, y; i <= m; ++i) {
    read(x), read(y);
    a[x][y] = a[y][x] = 1;
  }

  for (int i = 1; i <= n; ++i) fa[i] = i;
  for (int i = 1; i <= n; ++i)
    for (int j = i + 1; j <= n; ++j)
      if (!a[i][j]) {
        g[i].pb(j);
        g[j].pb(i);
        int x = Find(i), y = Find(j);
        if (x != y) fa[x] = y;
      }
  for (int i = 1; i <= n; ++i)
    if (Find(i) == i) id[i] = ++cnt;
  for (int i = 1; i <= n; ++i)
    sub[id[Find(i)]].pb(i);

  f[0] = 1;
  fill(col + 1, col + 1 + n, -1);
  for (int i = 1; i <= cnt; ++i) {
    Color(sub[i][0], 0);
    if (ans == -1) {
      puts("-1");
      return 0;
    }
    int x = 0, y = 0;
    for (int u : sub[i])
      if (col[u]) ++x;
      else ++y;
    Solve(x, y);
  }
  ans = n >> 1;
  while (!f[ans]) --ans;
  ans = ans * (ans - 1) / 2 + (n - ans) * (n - ans - 1) / 2;
  printf("%d\n", ans);

  return 0;
}

