// std::fill of multi dimensions
template<typename A, size_t N, typename T>
void Fill(A (&array)[N], const T &val){
  std::fill( reinterpret_cast<T*>(array),
             reinterpret_cast<T*>(array+N),
             val );
}

// binary search
ll BSearch(ll ok, ll ng, bool (*f)(ll)){
  ll mid;
  while(abs(ok - ng) > 1LL) {
    mid =  (ok + ng) / 2LL;
    if(f(mid)) {
      debug("BSearch: f(%d) == true\n", mid);
      ok = mid;
    }
    else
    {
      debug("BSearch: f(%d) == false\n", mid);
      ng = mid;
    }
  }
  return ok;
}

ll NUM_TEST_CASE = 1;

ll N,M,K,A,B,C,D,E;
unordered_set<int> G[NMAX];
vec Gdash[NMAX];
vec island_vertices;

string S;
vec v;

ll ans = {};

ll dp[NMAX];

ll taka_dfs(int m, int i, int tak){
  if(i >= m) return tak;
  if(tak <= N && tak >= 0 && dp[tak] != -1) return dp[tak];
  if(tak >= 0 && N - tak >= 0 && dp[N - tak] != -1) return N - dp[N - tak];
  ll used = taka_dfs(m, i + 1, tak + island_vertices[i]);
  ll unused = taka_dfs(m, i + 1, tak);
  return dp[tak] = (abs(used - (N - used)) <= abs(unused - (N - unused)) ?
                  used :
                  unused);
}

int col[NMAX];
pair<bool, pair<int, int>>
paint_dfs(int i, int color){
  debug("paint_dfs(%d, %d)\n", i, color);
  col[i] = color;
  int taka = 0, hashi = 0;
  if(color == 0) {
    taka = 1;
  }
  else {
    hashi = 1;
  }
  for (int j : Gdash[i])
  {
    if(col[j] == col[i])
      return {false, {-1, -1}};
    if(col[j] == -1){
      auto ret = paint_dfs(j, !color);
      if(!ret.fi) return ret;
      else{
        taka += ret.se.fi;
        hashi += ret.se.se;
      }
    }
  }
  return {true, {taka, hashi}};
}
void solve(){
  // main algorithm
  // make Gdash
  for (int i = 1; i <= N; ++i)
  {
    for (int j = 1; j <= N; ++j)
    {
      if (i != j && G[i].count(j) == 0)
      {
        Gdash[i].push_back(j);
      }
    }
  }

  // paint digraph
  Fill(col, -1);
  for (int i = 1; i <= N; ++i)
  {
    if(col[i] != -1) continue;
    debug("paint(%d)\n", i);
    auto ret = paint_dfs(i,0);
    DUMP(ret.fi);
    DUMP(ret.se.fi);
    DUMP(ret.se.se);
    if(!ret.fi){
      ans = -1;
      return;
    }
    island_vertices.push_back(ret.se.fi);
    island_vertices.push_back(ret.se.se);
  }

  // unit test
  // island_vertices = {1,1,2,1};
  // calc min composition
  sort(ALL(island_vertices), greater<int>());
  Fill(dp, -1);
  ll taka = taka_dfs(island_vertices.size(), 0, 0);
  ll hashi = N - taka;
  ans = taka * (taka - 1) / 2 + hashi * (hashi - 1) / 2;
  DUMP(taka);
  DUMP(hashi);
}
