using namespace std;

int n, m;
bool gr[800][800];
vector<int> color;
vector< pair<int, int> > paircnts;

void wrong()
{
    printf("-1\n");
    exit(0);
}

void dfs(int u, int& c0, int& c1)
{
    for (int v = 1; v <= n; ++v) {
        if (gr[u][v] == 0 && u != v) {
			if (color[v] >= 0) {
				if (color[v] == color[u]) wrong();
				continue;
			}
            color[v] = color[u] ^ 1;

            if (color[v] == 0) ++c0;
            else ++c1;

            dfs(v, c0, c1);
        }
    }
}

int main()
{
    scanf("%d %d", &n, &m);
    memset(gr, 0, sizeof gr);
    for (int i = 0; i < m; ++i) {
        int u, v; scanf("%d %d", &u, &v);
        gr[u][v] = gr[v][u] = 1;
    }

	color.assign(n+1, -1);

    for (int i = 1; i <= n; ++i) {
        if (color[i] < 0) {
            color[i] = 0;
            int c0 = 1, c1 = 0;
            dfs(i, c0, c1);
            paircnts.push_back({c0, c1});
        }
    }

    int maxdp = n/2+1;
    bool dp[maxdp + 1];
    memset(dp, 0, sizeof dp);
    dp[0] = 1;
    for (pair<int, int> p : paircnts) {
        for (int i = maxdp; i >= 0; --i) {
			bool nxt = 0;
            if (i >= p.first) nxt |= dp[i - p.first];
            if (i >= p.second) nxt |= dp[i - p.second];
			dp[i] = nxt;
        }
    }

//    for (int i = 0; i <= maxdp; ++i) cerr << dp[i]; cerr << endl;

    int ans = 1e9;
    for (int i = 0; i <= maxdp; ++i) {
        if (dp[i]) {
        	int j = n - i;
        	int cur = ((i * (i-1)) + (j * (j-1))) / 2;
			ans = min(ans, cur);
        }
    }
    printf("%d\n", ans);
}

