    parts.clear(); parts.resize(2);
    for (int u = 0; u < V; u++) if (!~color[u]) {
        if (!dfs(u, 0)) return false;
        ab.emplace_back(parts[0].size(), parts[1].size());
        parts.clear(); parts.resize(2);
    }
