P dfs(int now,int color){
	vi[now]=1;
	cl[now]=color;
	P ret=P(0,0);
	if(color==1)ret.fr++;
	else ret.sc++;
	for(int u:cg[now]){
		if(vi[u]&&cl[u]==cl[now])return P(-1,-1);
		else if(!vi[u]){
			int c;
