int main() {
        int n, m;
        scanf("%d%d", &n, &m);
        vector<vector<int>> g(n);
        vector<vector<bool>> forb(n, vector<bool> (n, false));
        for (int i = 0; i < m; i ++) {
                int a, b;
                scanf("%d%d", &a, &b);
                a --, b --;
                forb[a][b] = true;
                forb[b][a] = true;
        }
        for (int i = 0; i < n; i ++) {
                for (int j = i + 1; j < n; j ++) {
                        if (!forb[i][j]) {
                                g[i].push_back(j);
                                g[j].push_back(i);
                        }
                }
        }
        vector<bool> used(n);
        vector<int> color(n, -1);
        int white_cnt = 0, black_cnt = 0;
        function<bool (int, int, int)> dfs = [&](int u, int prev, int c) {
                used[u] = true;
                color[u] = c;
                if (c == 1) white_cnt ++;
                else black_cnt ++;
                for (auto v : g[u]) if (v != prev) {
                        if (color[v] == -1) {
                                if (!dfs(v, u, 1 - c)) return false;
                        } else if (color[v] != 1 - c) {
                                return false;
                        }
                }
                return true;
        };
        vector<pair<int, int>> hoge;
        for (int i = 0; i < n; i ++) {
                if (!used[i]) {
                        white_cnt = 0;
                        black_cnt = 0;
                        if (!dfs(i, -1, 0)) {
                                printf("-1\n");
                                return 0;
                        }
                        hoge.emplace_back(white_cnt, black_cnt);
                }
        }
        bitset<1000> creatable;
        creatable[0] = 1;
        for (int i = 0; i < (int) hoge.size(); i ++) {
                int a, b;
                tie(a, b) = hoge[i];
                creatable = (creatable << a) | (creatable << b);
        }
        // cerr << creatable << endl;
        int ans = 100000000;
        for (int i = 0; i < n; i ++) {
                if (creatable[i]) {
                        ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
                }
        }
        printf("%d\n", ans);
        return 0;
}

