 		hasedge[u][v] = true;
 		hasedge[v][u] = true;
 	}

 	for (int i = 1; i <= n; i++)
 	{
 		if (!visited[i])
 		{
 			++componentID;
 			dfs(i);
 		}
 	}

 	if (componentID >= 3)
 	{
 		cout << "-1\n";
 	}
 	else if (componentID == 2)
 	{
 		int ans = 0;

 		int ap = (components[1].size()*(components[1].size() - 1))/2;
 		int bp = (components[2].size()*(components[2].size() - 1))/2;

 		int tot = 0;

 		for (auto u: components[1])
 		{
 			for (auto v: graph[u])
 			{
 				if (u > v)
 				{
 					tot++;
 				}
 			}
 		}

 		if (ap != tot)
 		{
 			cout << "-1\n";
 			return 0;
 		}

 		tot = 0;

 		for (auto u: components[2])
 		{
 			for (auto v: graph[u])
 			{
 				if (u > v)
 				{
 					tot++;
 				}
 			}
 		}

 		if (tot == bp)
 		{
 			cout << (ap+bp) << "\n";
 		}
 		else
 		{
 			cout << -1 << "\n";
 		}
 	}
 	else
 	{
 		vector<int> curr;
 		for (int i = 1; i <= n; i++)
 		{
 			curr.pb(i);
 		}

 		find(curr);

 		vector<bool> dp(n+1, false);
 		dp[0] = true;

 		for (auto p: data)
 		{
 			vector<bool> newdp(n+1, false);

 			if (p.se == 0)
 			{
 				for (int asz = 0; asz <= p.fi; asz++)
 				{
		 			for (int x = 0; x+asz <= n; x++)
		 			{
		 				if (dp[x])
		 				{
		 					newdp[x+asz] = true;
		 				}
		 			}
 				}
 			}
 			else
 			{
	 			for (int x = 0; x <= n; x++)
	 			{
	 				if (dp[x])
	 				{
	 					//x+p.fi
	 					//x+p.se
	 					newdp[x+p.fi] = true;
	 					newdp[x+p.se] = true;
	 				}
	 			}
 			}

 			dp = newdp;
 		}

 		int ans = MOD;

 		for (int u = 0; u <= n; u++)
 		{
 			int a = u;
 			int b = n - u;

 			if (dp[u])
 			{
 				ans = min(ans, ((a*(a-1))/2) + ((b*(b-1))/2));
 			}
 		}

 		if (ans == MOD)
 		{
 			ans = -1;
 		}

 		cout << ans;
 	}


	clock_t end = clock();
	double elapsed_secs = double(end - begin) / CLOCKS_PER_SEC;

	cerr << elapsed_secs << endl;

	return 0;
}

