bool visit(int idx, int x, vector<int>& col, unordered_map<int, unordered_set<int>>& e, array<int, 2>& a)
{
	col[idx] = x;
	++a[x & 1];
	for (auto i : e[idx])
	{
		if (col[i] == (x ^ 1))
			continue;

		if (col[i] == -1)
		{
			if (!visit(i, x ^ 1, col, e, a))
				return false;
			continue;
		}
		return false;
	}
	return true;
}

int main()
{
	int n, m;
	cin >> n >> m;

	vector<int> col(n, -1);

	unordered_map<int, unordered_set<int>> e;
	REP (i, n)
		REP (j, n)
			if (i != j)
				e[i].insert(j);

	REP (i, m)
	{
		int a, b;
		cin >> a >> b;
		--a, --b;
		e[a].erase(b);
		e[b].erase(a);
	}

	int x = 0;

	set<int> s;
	s.insert(0);

	auto it = find(col.begin(), col.end(), -1);
	while (it != col.end())
	{
		array<int, 2> a{0, 0};
		if (!visit(it - col.begin(), x, col, e, a))
		{
			cout << -1 << endl;

			return 0;
		}
		set<int> n;
		for (auto i : s)
		{
			n.insert(i + a[0] - a[1]);
			n.insert(i + a[1] - a[0]);
		}
		swap(s, n);
		it = find(col.begin(), col.end(), -1);
		x += 2;
	}

	auto r = (n - *s.lower_bound(0)) / 2;
	auto t = n - r;

	cout << r * (r - 1) / 2 + t * (t - 1) / 2 << endl;

	return 0;
}

