#define MAX_N 750

int f[MAX_N][MAX_N];
int g[MAX_N];

int main() {
    int n,m;
    cin >> n >> m;
    rep(i,m){
        int a,b;
        cin >> a >> b;
        f[a][b] = 1;
        f[b][a] = 1;
    }
    srep(i,1,n+1){
        f[i][i] = 1;
    }

    cout << '-1' << endl;
    return 0;

    int flag = 0;
    int g1 = 0;
    int g2 = 0;

    srep(i,1,n+1){
        srep(j,1,n+1){
            if(f[i][j]==0){
                g[i] = 1;
                g[j] = 2;
                g1 = i;
                g2 = j;
                flag = 1;
                break;
            }
        }
    }

    if(flag == 0){
        if(n%2==0){
            cout << (n/2)*(n/2-1) << endl;
        }else{
            cout << (n/2)*(n/2-1)/2 + (n/2+1)*(n/2)/2 << endl;
        }
        return 0;
    }

    srep(i,1,n+1){
        if(f[i][g1] == 0 && f[i][g2] == 0){
            cout << "-1" << endl;
            return 0;
        }
        if(f[i][g1] == 1 && f[i][g2] == 0){
            g[i] = 1;
        }
        if(f[i][g1] == 0 && f[i][g2] == 1){
            g[i] = 2;
        }
    }

    int c[3] = {};
    srep(i,1,n+1){
        c[g[i]]++;
    }

    while(c[0]>0){
        if(c[1]>c[2]){
            c[2]++;
        }else{
            c[1]++;
        }
        c[0]--;
    }

    ll ans = (c[1])*(c[1]-1)/2 + (c[2])*(c[2]-1)/2;

    cout << ans << endl;
    return 0;
}

