using namespace std;

int N, M;
bool edge[700 + 10][700 + 10];
bool complementary_edge[700 + 10][700 + 100];
int color[700 + 100];
bool f = false;
bool dp[700 + 10][700 + 10];
int c1, c2;

void dfs(int pos, int bef) {
	if (color[pos] == 1)c1++;
	else c2++;
	for (int i = 0; i < N; i++) {
		if (complementary_edge[pos][i] && i != bef) {
			if (color[i] == 0) {
				color[i] = color[pos] == 1 ? 2 : 1;
				dfs(i, pos);
			}
			else {
				if ((color[pos] == 1 && color[i] == 2) || (color[pos] == 2 && color[i] == 1)) {
					//ok!
				}
				else f = true;//補グラフは二部グラフではない
			}
		}
	}
}

int main() {
	cin >> N >> M;
	for (int i = 0; i < N; i++)
		for (int j = 0; j < N; j++)
			if(i != j)
				complementary_edge[i][j] = true;

	for (int i = 0; i < M; i++) {
		int A, B;
		cin >> A >> B;
		A--, B--;
		edge[A][B] = true;
		edge[B][A] = true;
		complementary_edge[A][B] = false;
		complementary_edge[B][A] = false;
	}

	vector<pair<int, int>> connected_component;
	for (int i = 0; i < N; i++) {
		if (color[i] == 0) {
			color[i] = 1;
			dfs(i, -1);
			connected_component.push_back(make_pair(c1, c2));
			c1 = 0, c2 = 0;
		}
	}

	if (f) {
		cout << -1 << endl;
		return 0;
	}

	dp[0][0] = true;
	for (int i = 0; i < connected_component.size(); i++) {
		for (int j = 0; j <= N; j++) {
			if (dp[i][j]) {
				if (j + connected_component[i].first <= N)
					dp[i + 1][j + connected_component[i].first] = true;
				if (j + connected_component[i].second <= N)
					dp[i + 1][j + connected_component[i].second] = true;
			}
		}
	}
	int ans = 1145141919;
	for (int i = 0; i <= N; i++) {
		if(dp[connected_component.size()][i])
			ans = min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
	}
	cout << ans << endl;
	return 0;
}

