#include <bits/stdc++.h>
#define inf 0x3f3f3f3f
#define m_k make_pair
using namespace std;
const int N=800;
int n,m,mp[N][N],vi[N];
int tot,first[N],nxt[N*N],point[N*N];
int cnt,ca,cb,dp[N][N];
bool bl;
inline void add_edge(int x,int y)
{
	tot++;
	nxt[tot]=first[x];
	first[x]=tot;
	point[tot]=y;
}
void dfs(int x)
{
	if (vi[x]==1) ca++;
	else cb++;
	for (int i=first[x];i!=-1;i=nxt[i])
	{
		int u=point[i];
		if (vi[u])
		{
			if (vi[x]==vi[u]) bl=0;
			continue;
		}
		vi[u]=3-vi[x];
		dfs(u);
	}
}
signed main()
{
	tot=-1;
	memset(first,-1,sizeof(first));
	memset(nxt,-1,sizeof(nxt));
	scanf("%d%d",&n,&m);
	for (int i=1;i<=m;i++)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		mp[u][v]=mp[v][u]=1;
	}
	for (int i=1;i<=n;i++)
	{
		for (int j=i+1;j<=n;j++)
		{
			if (mp[i][j]) continue;
			add_edge(i,j);add_edge(j,i);
		}
	}
	bl=1;
	dp[0][0]=1;
	for (int i=1;i<=n;i++)
	{
		if (vi[i]) continue;
		vi[i]=1;
		ca=cb=0;
		cnt++;
		dfs(i);
		if (!bl)
		{
			printf("-1\n");
			return 0;
		}
		for (int j=n;j>=ca;j--) dp[cnt][j]|=dp[cnt-1][j-ca];
		for (int j=n;j>=cb;j--) dp[cnt][j]|=dp[cnt-1][j-cb];
	}
	int ans=inf;
	for (int i=1;i<=n;i++)
	{
		if (dp[cnt][i]) ans=min(ans,i*(i-1)/2+(n-i)*(n-i-1)/2);
	}
	printf("%d\n",ans);
}

