vector<vector<int>> adj;

vector<pair<vector<int>, vector<int>>> Bipartite() {
  vector<pair<vector<int>, vector<int>>> result;
  int n = adj.size();
  int used[n] = {};
  rep(i,n) {
    if (used[i]) continue;
    used[i] = 1;
    vector<int> left, right;
    queue<pair<int, int>> q; q.push(make_pair(i,-1));
    while (q.size()) {
      pair<int, int> now = q.front(); q.pop();
      if (used[now.first]==1) left.push_back(now.first);
      else right.push_back(now.first);
      for (auto x: adj[now.first]) {
        if (x==now.second) continue;
        if (used[x]) { if (used[x]==used[now.first]) return {}; }
        else {
          used[x] = used[now.first] * -1;
          q.push(make_pair(x,now.first));
        }
      }
    }
    result.push_back(make_pair(left,right));
  }
  return result;
}

