			}
			a.pp(k, uf[i].sc - k);
		}
	}
	dp[0] = 1;
	for(auto g:a) {
		req(i, n + 1) {
			dp[i + g.fs] |= dp[i];
			dp[i + g.sc] |= dp[i];
			dp[i] = 0;
