    if (colors[v] == 1) ret.first++;
    else if (colors[v] == -1) ret.second++;
    else if (colors[v] == 0) return ret;
    colors[v] = 0;
    for (int i = 0; i < H.size(); i++) {
        if (H[v][i]) {
            pair<int, int> tmp = dfs(i);
            ret.first += tmp.first;
            ret.second += tmp.second;
        }
    }

    return ret;
