    }

    cnt += b+w;
  }

  int ret = INF;
  REP(i, n+1) if(dp[i][n-i]) chmin(ret, i*(i-1)/2 + (n-i)*(n-i-1)/2);
  cout << ret << endl;

  return 0;
}

