		--u; --v;
		e[u][v] = e[v][u] = true;
	}
	g.resize(2 * n);
	for (int i = 0; i < n; ++i)
		for (int j = i + 1; j < n; ++j)
			if (!e[i][j]) {
				addEdge(i, j);
				addEdge(Not(i), Not(j));
			}
	for (int i = 0; i < g.size(); ++i)
		if (!idx[i])
			DFS(i);
	for (int i = 0; i < n; ++i)
		if (comp[i] == comp[i + n]) {
			puts("-1");
			return 0;
		}
	vector<int> in(cmp);
	vector<vector<int> > G(cmp);
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			if (comp[i] != comp[g[i][j]]) {
				G[comp[i]].push_back(comp[g[i][j]]);
				++in[comp[g[i][j]]];
			}
	queue<int> q;
	for (int i = 0; i < in.size(); ++i)
		if (!in[i])
			q.push(i);
	vector<char> res(cmp, -1);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (res[u] == -1) {
			res[u] = false;
			res[comp[Not(compH[u])]] = true;
		}
		for (auto &v : G[u])
			if (!--in[v])
				q.push(v);
	}
	vector<int> v[2];
	for (int i = 0; i < n; ++i)
		v[res[comp[i]]].push_back(i);
	int R = 1e9;
