				v[0].pop_back();
				--i;
			}
			int cR = 0;
			for (int i = 0; i < 2; ++i)
				cR += (int)v[i].size()*((int)v[i].size() - 1) / 2;
			R = min(R, cR);
		}
		v[0].swap(v[1]);
	}
	printf("%d\n", R);
