				g.update(i, j, 1, 0);
			}
		}
	}

	vi chk(n, -1);

	function<pair<int, int>(int)> dfs = [&](int now) {
		int col = chk[now];
		int z = 0, o = 0;
		(col ? o : z) += 1;
		foa(e, g.edges[now]) {
			if(chk[e.to] == col) {
				err();
			} else if(chk[e.to] >= 0)
				continue;
			chk[e.to] = 1 - col;
			int f, s;
			tie(f, s) = dfs(e.to);
			z += f, o += s;
		}
		return pair<int, int>(z, o);
	};
	vector<pair<int, int>> vp;
	rep(i, n) {
		if(chk[i] < 0) {
			chk[i] = 0;
			vp.push_back(dfs(i));
		}
	}

	int h = vp.size();

	V<vector<int>> dp(h + 1, vector<int>(n / 2 + 1));
	dp[0][0] = 1;
	int s = n / 2 + 1;
	rep(i, h) {
		rep(j, s) {
			if(dp[i][j]) {
				int b, c;
				tie(b, c) = vp[i];
				if(j + b < s) {
					dp[i + 1][j + b] = 1;
				}
				if(j + c < s) {
					dp[i + 1][j + c] = 1;
				}
			}
		}
	}
	int b, c;
	rrep(i, s) {
		if(dp[h][i]) {
			b = i, c = n - i;
			break;
		}
	}
	int ans = c * (c - 1) / 2 + b * (b - 1) / 2;

	cout << ans << endl;
}

#include<bits/stdc++.h>
using namespace std;
#define REP(i,n) for(int i=0;i<(n);++i)

int N, M;
int color[705];
int white[705];
int black[705];
int E[705][705];
vector<int> G[705];
bool flg = false; // 二部グラフ判定失敗フラグ

void dfs(int s, int c, int p) {
    if(color[s] != 0) return;
    color[s] = c;
    if(c == 1) white[p]++;
    else black[p]++; 
    for(auto x:G[s]) {
        if(color[x] != 0) {
            if(color[x] != -c) {
                flg = true;
                return;
            }
            continue;
        }
        dfs(x, -c, p);
    }
}

void solve() {
    scanf("%d%d", &N, &M);
    memset(E,0,sizeof(E));
    REP(i,M) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--, b--;
        E[a][b]++;
        E[b][a]++;
    }
    REP(i,N) REP(j,N) {
        if(i>=j) continue;
        if(E[i][j]==0) {
            G[i].push_back(j);
            G[j].push_back(i);
        }
    }
    // REP(i,N) { REP(j,G[i].size()) cout << G[i][j] << " "; cout << endl;}
    memset(color,0,sizeof(color));
    memset(white,0,sizeof(white));
    memset(black,0,sizeof(black));
    REP(i,N) dfs(i, 1, i);
    /*
    REP(i,N) cout << color[i] << " "; cout << endl;
    REP(i,N) cout << white[i] << " "; cout << endl;
    REP(i,N) cout << black[i] << " "; cout << endl;
    */
    if(flg) {
        printf("%d\n", -1);
    }
    else {
        vector<int> vec;
        int wa = 0;
        REP(i,N) {
            if(white[i]) {
                vec.push_back(white[i]-black[i]);
                wa += black[i];
            }
        }
        /*
        cout << wa << endl;
        */

        //for(auto x:vec) cout << x << " "; cout << endl;
        /**/
        int sz = vec.size();
        // cout << sz << endl;
        vector<bitset<10>> dp(sz + 1);
        dp[0].set(wa);
        REP(i,sz) {
            dp[i+1] |= dp[i];
            dp[i+1] |= (vec[i]>=0 ? (dp[i]<<vec[i]) : (dp[i]>>(-vec[i])));
        }
        int ans = 5000;
        REP(i,N+1) {
            if(dp[sz][i]) ans = min(ans, i*i-N*i+(N-1)*N/2);
        }
        printf("%d\n", ans);
    }
}

int main(){
    solve();
    return 0;
}

