void link(int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
}
bool vis[N+1] = {};
int p[N+1] = {};
int depth[N+1] = {};
int sz[N+1] = {};
template <typename PreFunction, typename PostFunction>
int dfs(int u, const PreFunction& pre, const PostFunction& post) {
#ifdef DEBUG
    using pre_actual_type = typename callable_traits<PreFunction>::function_type;
    using pre_expected_type = typename callable_traits<void(int)>::function_type;
    static_assert(is_same<pre_actual_type, pre_expected_type>::value, "dfs 'pre' must be void(int)");
    using post_actual_type = typename callable_traits<PostFunction>::function_type;
    using post_expected_type = typename callable_traits<void(int)>::function_type;
    static_assert(is_same<post_actual_type, post_expected_type>::value, "dfs 'post' must be void(int)");
#endif
    int ans = 1;
    vis[u] = true;
    depth[u] = depth[p[u]] + 1;
    sz[u] = 1;
    pre(u);
    for(int v : adj[u]) {
        if(not vis[v]) {
            p[v] = u;
            ans += dfs(v, pre, post);
            sz[u] += sz[v];
        }
    }
    post(u);
    return ans;
}
int dfs(int u) { return dfs(u, [](int u) {}, [](int u) {}); }
bool color[N+1];
vector<int> black_counts;
vector<int> white_counts;
vector<int> color_counts;
vector<int> color_counts_psum;
int mem[N+1][N+1];
int add_new_nodes(int x, int y, int new_x, int new_y) {
    return new_x * x + new_x * (new_x - 1) / 2
         + new_y * y + new_y * (new_y - 1) / 2;
}
int opt(int i, int x) {
    int& ans = mem[i][x];
    if(ans == -1) {
        if(i == color_counts.size()) {
            ans = 0;
        } else {
            int y = (i == 0 ? 0 : color_counts_psum[i - 1]) - x;
            ans = min(add_new_nodes(x, y, black_counts[i], white_counts[i]) + opt(i + 1, x + black_counts[i]),
                      add_new_nodes(x, y, white_counts[i], black_counts[i]) + opt(i + 1, x + white_counts[i]));
        }
    }
    return ans;
}
