            if(not conn[i][j]) {
                link(i, j);
            }
        }
    }
    fill(vis, vis + n + 1, false);
    bool can = true;
    for(int u = 1; u <= n and can; u++) {
        if(not vis[u]) {
            color[u] = true;
            int black = 0, white = 0;
            dfs(u, [&](int u) {
                color[u] = not color[p[u]];
                (color[u] ? black : white)++;
            }, [&](int u) {
                for(int v : adj[u]) {
                    can &= color[v] != color[u];
                }
            });
            black_counts.push_back(black);
            white_counts.push_back(white);
            color_counts.push_back(black + white);
        }
    }
    if(can) {
        color_counts_psum.resize(color_counts.size());
        partial_sum(color_counts.begin(), color_counts.end(), color_counts_psum.begin());
        memset(mem, -1, sizeof mem);
        cout << opt(0, 0) << endl;
    } else {
        cout << -1 << endl;
    }
    return 0;
}

