int co_cnt(int x, bool t)
{
	if (t)
		vis[x] = 1;
	else
		vis[x] = 2;
	int retval = 0;
	if (t) retval++;
	for (int i = 0; i < n; i++) {
		if (i == x) continue;
		if (vis[i] == 0 && !dc[x][i]) {
			retval += co_cnt(i, !t);
		}
		else if (!dc[x][i] && vis[i]) {
			if (vis[i] == vis[x]) flag = true;
		}
	}
	return retval;
}

void cnt(int x)
{
	vis[x] = 1;
	CNT++;
	for (int i = 0; i < n; i++) {
		if (i == x) continue;
		if (vis[i] == 0 && !dc[x][i]) {
			cnt(i);
		}
	}
}

