bool G[705][705];
int col[705];
int cnt[2];
int n;
bool go(int x, int c) {
	if (col[x] != -1) {
		return col[x] == c;
	}
	col[x] = c;
	++cnt[c];
	for (int y = 1; y <= n; ++y) {
		if (!G[x][y]) continue;
		if (!go(y, 1 - c)) return false;
	}
	return true;
}
int main() {
	int m;
	scanf("%d%d", &n, &m);
	memset(G, 1, sizeof(G));
	for (int i = 0; i < m; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		G[a][b] = G[b][a] = 0;
	}
	for (int i = 1; i <= n; ++i) G[i][i] = 0;
	vector<pair<int, int>> vec;
	memset(col, -1, sizeof(col));
	for (int i = 1; i <= n; ++i) {
		if (col[i] != -1) continue;
		cnt[0] = cnt[1] = 0;
		if (!go(i, 0)) {
			printf("-1\n");
			return 0;
		}
		vec.push_back({cnt[0], cnt[1]});
	}
	bitset<705> can;
	can[0] = 1;
	for (auto v : vec) {
		can = (can << v.first) | (can << v.second);
	}
	int ans = INT_MAX;
	for (int i = 0; i <= n; ++i) {
		if (can[i]) ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	}
	printf("%d\n", ans);
}

