std::bitset<N+1> cans;
bool fail = false;
int n;

int dfs(int i, int g) {
	if (group[i] != -1) {
		if (group[i] == (g ^ 1)) fail = true;
		return 0;
	}
	group[i] = g;
	++gs[g];
	for (int t = 0; t < n; ++t) {
		if (i == t) continue;
		if (! edge[i][t]) {
			dfs(t, g^1);
		}
	}
	return 1;
}

int main() {
	int m;
	std::cin >> n;
	std::cin >> m;
	for (int i = 0; i < m; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		edge[a][b] = true;
		edge[b][a] = true;
	}
	for (int i = 0; i < n; ++i) group[i] = -1;

	int gc = 0;
	for (int i = 0; i < n; ++i) {
		gc += dfs(i, 2 * gc);
	}
	if (fail) {
		std::cout << -1 << '\n';
	} else {
		for (int i = 0; i <= 2 * n; ++i) cans[i] = 0;
		cans[0] = 1;

		for (int j = 0; j < gc; ++j) {
			int side = j & 1;
			cans = ((cans << gs[2*j]) | (cans << gs[2*j+1]));
		}
		int min_ans = n*n;
		for (int i = 0; i <= n; ++i) {
			if (cans[i]) {
				min_ans = std::min(min_ans, std::max(0, i*(i-1)/2) + std::max(0, (n-i) * (n-i-1)/2));
			}
		}
		std::cout << min_ans << '\n';
	}
}

