bool ok[N];

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n >> m;

    for(int i = 1 ; i <= n ; ++i)   E[i][i] = 1;

    while(m--)  {
        int x, y;
        cin >> x >> y;
        E[x][y] = E[y][x] = 1;
    }

    memset(c,-1,sizeof c);

    for(int i = 1 ; i <= n ; ++i)   {
        if(c[i] >= 0)   continue;
        queue<int>  q;
        q.push(i);  c[i] = 0;
        int cnt[] = {0,0};
        while(q.size()) {
            int u = q.front();  q.pop();
            cnt[c[u]]++;
            for(int v = 1 ; v <= n ; ++v)   {
                if(E[u][v]) continue;
                if(c[u] == c[v])
                    return 0 * puts("-1");
