    for(ii tmp : CB)
    for(int i = n ; i >= 0 ; --i)   {
        ok[i] = 0;
        if(i >= tmp.first)  ok[i] |= ok[i - tmp.first];
        if(i >= tmp.second) ok[i] |= ok[i - tmp.second];
    }

