	}
	UF<long long int> uf;
	for( size_t i = 0; i < N; i++ ){
		uf.push(i);
		D[i][i] = 0;
	}
	for( size_t i = 0; i < N; i++ ){
		long long int memo = -1;
		for( size_t j = 0; j < N; j++ ){
			if( D[i][j] ){
				if( uf.same(i, j) ){
					cout << -1 << endl;
					return 0;
				}
				if( memo == -1 ){
					memo = j;
				} else{
					uf.merge(j, memo);
				}
			}
		}
	}
	set<long long int>used;
	vector < pair < long long int, long long int >>X;
	long long int count = 0;
	for( size_t i = 0; i < N; i++ ){
		for( size_t j = i + 1; j < N; j++ ){
			if( D[i][j] ){
				if( !used.count(uf.groupID(i)) && used.count(uf.groupID(j)) ){
					used.insert(uf.groupID(i));
					used.insert(uf.groupID(j));
					X.push_back(make_pair(uf.count(i), uf.count(j)));
				}
			}
		}
		if( uf.count(i) == 1 ){
			count++;
		}
	}
	vector<long long int>dp(351);
	dp[0] = 1;
	for( size_t i = 0; i < count; i++ ){
		dp[i] = 1;
	}
	for( auto x : X ){
		for( int i = 350; i >= 0; i-- ){
			if( i - x.first >= 0 && dp[i - x.first] ){
				dp[i] = 1;
			}
			if( i - x.second >= 0 && dp[i - x.second] ){
				dp[i] = 1;
			}
		}
	}
	long long int ans = 1LL << 60;
	for( size_t i = 0; i < 351; i++ ){
		if( dp[i] ){
			long long int a = i, b = N - i;
			ans = min(ans, a*( a - 1 ) / 2 + b * ( b - 1 ) / 2);
		}
	}
	cout << ans << endl;
}

