        if (!used[i]) {
            auto t = dfs(i);

            #ifdef HOME
            cout << t.first << ' ' << t.second << '\n';
            #endif

            dp = (dp << t.first) | (dp << t.second);
        }   
    }   

    int ans = INF;
    for (int i = 0; i <= n; ++i) {
        if (dp[i]) {
            ans = min(ans, get(i) + get(n - i));
        }   
    }   
    cout << ans << '\n';
}

