	vvll gy(N, vll(N));
	EACH(e, AB){
		ll a; ll b;  tie(a, b) = e;
		a--; b--;
		gy[a][b] = 1;
		gy[b][a] = 1;
	}

	to.resize(N);
	REP(i, N)REP(j, N){
		if (i==j) continue;
		if (gy[i][j] == 1) continue;
		to[i].push_back(j);
	}

	done.resize(N);
	vll df;

	REP(v, N){
		if (done[v] != 0) continue;
		done[v] = 1;
		ll diff=1;
		dfs(v, diff);
		df.push_back(abs(diff));
	}

	ll dfN = (ll)df.size();

	vvll dp(dfN, vll(N));
	auto Dp = [&](ll i, ll d)->ll&{
		static ll dmy=0;
		d = abs(d);
		if (d>=N) return dmy;
		return dp[i][d];
	};

	dp[0][df[0]] = 1;
	REPS(i, 1, dfN-1){
		REP(d, N){
			if (Dp(i-1,d) == 0) continue;
			Dp(i, d+df[i])=1;
			Dp(i, d-df[i])=1;
		}
	}

	ll sa;
	REP(d, N){
		if (Dp(dfN-1, d) == 1) {
			sa=d; break;
		}
	}
	ll x = (N-sa) / 2;
	ll y = N-x;
	ll ans = x*(x-1)/2 + y*(y-1)/2;
	cout << ans << '\n';
}


