using vb = std::vector<bool>;
using vvb = std::vector<vb>;
using pii = std::pair<int, int>;

struct Node {
	std::list<int> edges;
	int odd{-1};
};
std::vector<Node> graph;

int solve();
pii dfs(int, int);

int main()
{
	printf("%d\n", solve());
	return 0;
}

int solve()
{
	int n, m;
	scanf("%d%d", &n, &m);
	vvb road(n, vb(n));
	for (int i{}; i < m; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		a--; b--;
		road[a][b] = road[b][a] = true;
	}
	graph.resize(n);
	for (int i{}; i < n; i++)
		for (int j{}; j < n; j++)
			if (!road[i][j] && i != j)
				graph[i].edges.push_back(j);

	std::vector<pii> connect_size;
	for (int i{}; i < n; i++)
		if (graph[i].odd < 0)
		{
			connect_size.push_back(dfs(i, 0));
			if (connect_size.back().first < 0)
				return -1;
		}

	std::vector<bool> dp(n + 1);
	dp[0] = true;
	for (auto& e: connect_size)
	{
		for (int j{n - 1}; j >= 0; j--)
		{
			if (!dp[j]) continue;
			dp[j] = false;
			dp[j + e.first] = true;
			dp[j + e.second] = true;
		}
	}
	for (int i{n / 2}; i <= n; i++)
		if (dp[i]) return i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2;
	return -1;
}

pii dfs(int index, int odd)
{
	if (graph[index].odd >= 0)
	{
		if (graph[index].odd == odd)
			return pii(0, 0);
		else
			return pii(-1, -1);
	}
	graph[index].odd = odd;
	pii ret;
	if (odd)
		ret.second++;
	else
		ret.first++;
	for (auto& e: graph[index].edges)
	{
		pii tmp{dfs(e, 1 - odd)};
		if (tmp.first < 0) return pii(-1, -1);
		ret.first += tmp.first;
		ret.second += tmp.second;
	}
	return ret;
}

