// modが素数でない場合、挙動がおかしくなる.
const ll mod = 1000000007LL;

// aのb乗を求める.
ll modpow(ll a, ll b) {
	if (a > mod) a %= mod;
	if (b == 0LL) return 1LL;
	ll tmp = modpow(a, b / 2);
	if (b & 1LL)
		return tmp * tmp % mod * a % mod;
	return tmp * tmp % mod;
}

// aの逆元を求める.
ll inverse(ll a) {
	return modpow(a, mod - 2);
}

// kの階乗を計算する.(sgnを0以外に設定すると逆元を返す)
ll fact(ll k, int sgn = 0) {
	static vector<ll> fac(2, 1LL);
	static vector<ll> inv(2, 1LL);
	static vector<ll> finv(2, 1LL);
	static ll nx = 2LL;
	while (nx <= k) {
		fac.push_back(fac[nx - 1] * nx % mod);
		inv.push_back(mod - inv[mod % nx] * (mod / nx) % mod);
		finv.push_back(finv[nx - 1] * inv[nx] % mod);
		++nx;
	}
	if (sgn == 0)
		return fac[k];
	return finv[k];
}

// aCbを計算する.
ll comb(ll a, ll b) {
	if (b < 0 || b > a) return 0;
	return fact(a) * fact(b, 1) % mod * fact(a - b, 1) % mod;
}

bool is_Bi = true;
vector<int> color;
vector<vector<int>> G;
void isBi(int s) {
	static vector<bool> visited(n, false);
	visited[s] = true;
	for (auto e : G[s]) {
		if (visited[e] && color[e] == color[s])
			is_Bi = false;
		else if (!visited[e]) {
			color[e] = color[s] == 0 ? 1 : 0;
			isBi(e);
		}
	}
}

bool isComp(vector<int> s) {
	for (auto e1 : s)
		for (auto e2 : s)
			if (!edge[e1][e2])
				return false;
	return true;
}

signed main() {
	int m; cin >> n >> m;
	for (int i = 0; i < m; ++i) {
		int a, b; cin >> a >> b;
		edge[--a][--b] = 1;
		edge[b][a] = 1;
	}
	for (int i = 0; i < n; ++i) edge[i][i] = 1;
	bool complete = true;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j)
			if (!edge[i][j]) complete = false;
	if (complete) { // 完全グラフのとき
		cout << (comb(n / 2, 2) + comb((ll)n - n / 2, 2)) << endl;
	}
	else { // 完全グラフでないとき
		// 都市を二つの完全グラフに分割できればその時が答え
		// できなければ-1
		color.resize(n, 0);
		vector<vector<int>> g(n);
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				if (!edge[i][j])
					g[i].push_back(j);
		G = g;
		isBi(0);
		if (!is_Bi) {
			cout << -1 << endl;
		}
		else {
			vector<int> zero, one;
			int c0 = 0, c1 = 0;
			for (int i = 0; i < n; ++i) {
				if (color[i]) { ++c1; one.push_back(i); }
				else { ++c0; zero.push_back(i); }
			}
			if (isComp(zero) && isComp(one))
				cout << (comb(c0, 2) + comb(c1, 2)) << endl;
			else cout << -1 << endl;
		}
	}

	return 0;
}

