void dfs(int u,int& b,int& w){
	for(int i=0;i<(int)G[u].size();i++){
		int v=G[u][i];
		if(tag[v]==0){
			tag[v]=3-tag[u];
			if(tag[v]==1) b++;
			else w++;
			dfs(v,b,w);
		}
		else{
			if(tag[u]==tag[v]){
