int C(int n){
	return n*(n-1)/2;
}

void solve(){
	int n,m;
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++){
		int u,v;
		scanf("%d%d",&u,&v);
		is[u][v]=is[v][u]=1;
	}
	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			if(!is[i][j]){
				add_edge(i,j);
			}
		}
	}
	mem(tag,0);

	int cnt=0;
	for(int i=1;i<=n;i++){
		if(tag[i]==0){
			int b=0,w=0;
			b++;
			tag[i]=1;
			dfs(i,b,w);
			++cnt;
			c[cnt]=b,d[cnt]=w;
		}
	}

	if(!flag){
		printf("-1\n");
		return ;
	}

	dp.reset();
	dp[0]=1;
	for(int i=1;i<=cnt;i++){
		dp=(dp<<c[i])|(dp<<d[i]);
	}

	for(int i=n/2;i>=0;i--){
		if(dp[i]){
			printf("%d\n",C(i)+C(n-i));
			return ;
		}
	}
}

int main(){
