    comp_adj[a][b] = true;
    comp_adj[b][a] = true;
  }
  vector<vector<int>> adj(n);
  for (int a = 0; a < n; ++a)
    for (int b = 0; b < n; ++b)
      if (a != b && comp_adj[a][b] == false)
        adj[a].push_back(b);
  vector<int> side(n, -1);
  bool ok = true;
  vector<bool> possible(n + 1, false);
  possible[0] = true;
  for (int i = 0; i < n; ++i)
    if (side[i] == -1) {
      int count0 = 0, count1 = 0;
      dfs(i, 0, side, ok, count0, count1, adj);
      vector<bool> new_possible(n + 1, false);
      for (int c = n; c >= 0; c--)
        if (possible[c]) {
          new_possible[c + count0] = true;
          new_possible[c + count1] = true;
        }
      possible = new_possible;
    }

  if (!ok) printf("-1\n");
  else {
    int result = INT_MAX;
    for (int c = 0; c <= n; ++c)
      if (possible[c])
        result = min(result, c * (c - 1) / 2 + (n - c) * (n - c - 1) / 2);
    printf("%d\n", result);
  }

  return 0;
}

