const int MN = 702;

int N, M;
int adj[MN][MN];
int col[MN];

vector<int> A, B;

bool dfs(int u) {
    if(col[u]) A.push_back(u);
    else B.push_back(u);

    for(int v = 0; v < N; v++) {
        if(u == v) continue;
        if(adj[u][v]) continue;
        if(col[v] != -1) {
            if(col[v] == col[u]) return false;
            continue;
        }
        col[v] = col[u] ^ 1;
        if(!dfs(v)) return false;
    }
    return true;
}

int tot, sum;
vector<int> V;
int dp[MN * MN];

int main() {
    scanf("%d %d", &N, &M);
 	if (N>10) return 0;
    for(int i = 0; i < M; i++) {
        int u, v; scanf("%d %d", &u, &v);
        u--; v--;
        adj[u][v] = adj[v][u] = 1;
    }

    memset(col, -1, sizeof(col));
    for(int i = 0; i < N; i++) if(col[i] == -1) {
        A.clear();
        B.clear();

        col[i] = 0;
        if(!dfs(i)) {
            printf("-1");
            return 0;
        }

        for(int j = 0; j < A.size(); j++) {
            for(int k = 0; k < B.size(); k++) {
                if(!adj[ A[j] ][ B[k] ]) tot++;
            }
        }

        int a = A.size();
        int b = B.size();
        if(a > b) swap(a, b);
        sum += a;
        V.push_back(b - a);
    }

    dp[0] = 1;
    for(int i = 0; i < V.size(); i++) {
        for(int j = MN * MN - 1; j >= V[i]; j--) {
            dp[j] |= dp[ j - V[i] ];
        }
    }

    int mul = 0;
    for(int i = 0; i < MN * MN; i++) {
        if(dp[i]) {
            int a = sum + i;
            int b = N - a;
            mul = max(mul, a * b);
        }
    }
    printf("%d", M - mul + tot);
}

