std::vector<std::vector<int>> g, G, vec(750, std::vector<int>(2, 0));
std::vector<int> li, a, b;
int n, m, count = 0;

bool solve(int s) {
	std::queue<int> qu; qu.push(s);
	li[s] = 0;

	while(!qu.empty()) {
		auto p = qu.front(); qu.pop();

		for(auto e : G[p]) {
			if(~li[e] and li[p] == li[e]) return false;
			if(~li[e]) continue;

			li[e] = !li[p];
			qu.push(e);
		}
	}

	for(int i = 0; i < n; i++) {
		if(li[i] == -1) continue;

		for(auto e : G[i]) if(li[i] == li[e]) return false;
	}

	return true;
}

void latte(int s) {
	std::queue<int> qu; qu.push(s);
	std::vector<bool> used(n, false); used[s] = true;
	vec[count][0]++;

	while(!qu.empty()) {
		auto p = qu.front(); qu.pop();

		for(auto e : G[p]) {
			if(used[e]) continue; used[e] = true;

			vec[count][li[e]]++;
			qu.push(e);
		}
	}
	count++;
}

int main(){
	cin >> n >> m; g.resize(n); G.resize(n); li.resize(n, -1);
	bool edge[n][n] = {}; a.resize(m); b.resize(m);
	for(int i = 0; i < m; i++) {
		cin >> a[i] >> b[i];

		g[a[i] - 1].push_back(b[i] - 1);
		g[b[i] - 1].push_back(a[i] - 1);
		edge[a[i] - 1][b[i] - 1] = edge[b[i] - 1][a[i] - 1] = true;
		a[i]--; b[i]--;
	}

	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			if(edge[i][j] or i == j) continue;
			G[i].push_back(j);
		}
	}

	for(int i = 0; i < n; i++) {
		if(li[i] == -1) {
			if(!solve(i)) {
				cout << -1 << endl;
				return 0;
			} else {
				latte(i);
			}
		}
	}

	bool dp[count + 1][701][701] = {}; dp[0][0][0] = true;
	for(int i = 0; i < count; i++) {
		for(int j = 700; j >= 0; j--) {
			for(int k = 700; k >= 0; k--) {	
				if(j + vec[i][0] <= 700 and k + vec[i][1] <= 700) dp[i + 1][j + vec[i][0]][k + vec[i][1]] = dp[i][j][k];
				if(j + vec[i][1] <= 700 and k + vec[i][0] <= 700) dp[i + 1][j + vec[i][1]][k + vec[i][0]] = dp[i][j][k];
			}
		}
	}

	int mi = 1e9;
	for(int i = 0; i < 701; i++) {
		for(int j = 0; j < 701; j++) {
			if(!dp[count][i][j]) continue;

			mi = std::min(mi, i * (i - 1) / 2 + j * (j - 1) / 2);	
		}
	}

	cout << mi << endl;
	return 0;
}

