int N,M;
vvi edg(700,vi(700,1));
vi used(700,0);
vi color(700,0);

int bfs_color(int v){
	int num[]={0,0};
	queue<int> que;
	que.push(v);
	used[v]=1;
	++num[0];
	while(!que.empty()){
		int p=que.front();
		que.pop();
		rep(i,N){
			if(i==p||!edg[i][p]) continue;
			if(used[i] && color[i]==color[p]){ return -1; }
			if(!used[i]){
				used[i]=1;
				color[i]=1-color[p];
				que.push(i);
				++num[color[i]];
			}
		}
	}
	return abs(num[0]-num[1]);
}

inline void solve(){
	vi diff;
	rep(i,N){
		if(!used[i]){
			int tem=bfs_color(i);
			if(tem==-1){
				cout<<-1<<endl;
				return;
			}
			diff.pub(tem);
		}
	}
	sort(diff.begin(),diff.end());
	int d1=0,d2=0;
	while(!diff.empty()){
		if(d1>d2) d2+=diff.back();
		else d1+=diff.back();
		diff.pob();
	}
	int g1=(N-d1+d2)/2;
	int g2=N-g1;
	cout<<g1*(g1-1)/2+g2*(g2-1)/2<<endl;
