void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}

pair<bool, vector<int>> isBipartite(const Graph &g, int v, int c) {
	bool flag = true;
	vector<int> res(2);

	if(color[v] >= 0) {
		return make_pair(color[v] == c, res);
	}

	color[v] = c;
	res[c]++;
	EACH(i, g[v]) {
		auto r = isBipartite(g, i->to, 1-c);
		flag = flag && r.first;
		res[0] += r.second[0];
		res[1] += r.second[1];
	}

	return make_pair(flag, res);
}

