ll solve() {
    ll N, M;
    cin >> N >> M;
    vector<vector<int>> g(N, vector<int>(N));
    int a, b;
    for ( int i = 0; i < M; i++ ) {
        cin >> a >> b;
        a--, b--;
        g[a][b] = 1;
        g[b][a] = 1;
    }
    vector<vector<int>> G(N);
    for ( int i = 0; i < N; i++ ) {
        for ( int j = i+1; j < N; j++ ) {
            if ( g[i][j] == 0 ) {
                G[i].push_back(j);
                G[j].push_back(i);
            }
        }
    }
    vector<pii> cnt;
    vector<int> used(N, -1);
    for ( int s = 0; s < N; s++ ) {
        vector<int> cl(N, -1); 
        if ( used[s] >= 0 ) continue;
        queue<int> q;
        q.push(s);
        cl[s] = 0;
        while ( !q.empty() ) {
            int v = q.front();
            q.pop();
            for ( int u : G[v] ) {
                if ( cl[u] >= 0 ) {
                    if ( cl[u] != 1 - cl[v] ) return -1;
                    continue;
                }
                cl[u] = 1 - cl[v];
                q.push(u);
            }
        }

        unordered_map<int, int> m;
        for ( int i = 0; i < N; i++ ) {
            if ( cl[i] >= 0 ) used[i] = 1;
            m[cl[i]]++;
        }
        cnt.push_back(pii(m[0],m[1]));
    }

    vector<vector<int>> dp(cnt.size()+1, vector<int>(N+1));
    dp[0][0] = 1;
    for ( int i = 1; i <= cnt.size(); i++ ) {
        pii x = cnt[i-1];
        for ( int j = 0; j <= N; j++ ) {
            if ( j - x.first >= 0 ) dp[i][j] = max(dp[i][j], dp[i-1][j-x.first]);
            if ( j - x.second >= 0 ) dp[i][j] = max(dp[i][j], dp[i-1][j-x.second]);
        }
    }
    int c0 = N/2;
    while ( c0 > 0 && dp[cnt.size()][c0] == 0 ) c0--;
    int c1 = (int)N - c0;
    ll ans = c0 * (c0 - 1) / 2 + c1 * (c1 - 1) / 2;
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

