// 補グラフ上の二部マッチング

using Graph = vector<vector<int>>;
// 補グラフ, 0-indexed を前提にしているので注意
Graph inverse(Graph &g) {
    vector<vector<int>>table(g.size(), vector<int>(g.size(), 0));
    for (int i = 0; i < g.size(); ++i) {
        for (auto x: g[i]) {
            table[i][x] = 1;
        }
    }
    Graph res(g.size());
    for (int i = 0; i < g.size(); ++i) {
        for (int j = 0; j < g.size(); ++j) {
            if (i != j && table[i][j] == 0) {
                res[i].push_back(j);
            }
        }
    }
    return res;
}

ll nC2(ll n) {
    return n * (n-1) / 2;
}

int main() {
    int N, M;
    cin >> N >> M;
    Graph g1(N);
    for (int i = 0; i < M; ++i) {
        int A, B;
        cin >> A >> B;
        A--; B--;
        g1[A].push_back(B);
        g1[B].push_back(A);
    }

    Graph graph = inverse(g1);
    vector<int>flag(N, -1);
    vector<int>block;
    int scale = N, bt = 0;
    for (int i = 0; i < N; ++i) {
        if (flag[i] != -1) continue;
        flag[i] = 0;
        int cnt0 = 1, cnt1 = 0;
        stack<int>st;
        st.push(i);
        while (! st.empty()) {
            auto t = st.top(); st.pop();
            for (auto x: graph[t]) {
                if (flag[x] == -1) {
                    flag[x] = flag[t] ^ 1;
                    if (flag[x]) cnt1++;
                    else cnt0++;
                    st.push(x);
                } else {
                    if (flag[t] == flag[x]) {
                        cout << -1 << "\n";
                        return 0;
                    }
                }
            }
        }
        scale -= cnt0 + cnt1;
        block.push_back(abs(cnt0 - cnt1));
        bt += min(cnt0, cnt1);
    }

    bitset<705> dp;
    dp[bt] = 1;
    for (int i = 1; i <= scale; ++i) {
        dp[bt+i] = 1;
    }
    for (auto x: block) {
        dp |= dp << x;
    }
    ll ans = INT_MAX;
    for (int i = 0; i <= N; ++i) {
        if (! dp[i]) continue;
        ll temp = nC2(i) + nC2(N - i);
        ans = min(ans, temp);
    }
    cout << ans << "\n";
    return 0;
}

