ll N, M;
vector<int> visited;
Graph g;

P dfs(ll now, int color) {
	P ret = P(0, 0);
	visited[now] = color;
	if (color == 0)
		ret.first++;
	else
		ret.second++;
	for (int i = 0;i < g[now].size();i++) {
		if (visited[g[now][i].dst] == -1) {
			P temp = dfs(g[now][i].dst, 1 - color);
			ret.first += temp.first;
			ret.second += temp.second;
		}
		else if (visited[g[now][i].dst] == color)
			ret.first = -INF;
	}
	return ret;
}

