		dist[b][a] = 1;
	}
	for (int i = 0;i < N;i++)
		for (int j = 0;j < N;j++)
			if (i!=j && dist[i][j] == 0)
				g[i].push_back(Edge(i, j, 1));
	vector<P> v;
	visited.assign(N, -1);
	bool ok = true;
	for (int i = 0;i < N;i++) {
		if (visited[i] == -1) {
			v.push_back(dfs(i, 0));
			ok &= v.back().first >= 0;
		}
	}
	if (!ok) {
		cout << -1 << endl;
		return 0;
	}
	vector<vector<int>> dp(v.size()+1, vector<int>(N+1));
	dp[0][0] = 1;
	for (int i = 0;i < v.size();i++) {
		P x = v[i];
		for (int from = N;from >= 0;from--) {
			if (from + x.first <= N)
				dp[i+1][from + x.first] = max(dp[i][from + x.first], dp[i][from]);
			if (from + x.second <= N)
				dp[i+1][from + x.second] = max(dp[i][from + x.second], dp[i][from]);
		}
	}
	ll ans = INF;
	for (ll i = 0;i <= N;i++) {
		if (dp.back()[i] == 1)
			ans = min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
	}
	cout << ans << endl;
	return 0;
}

