    }

    auto inv = makeVector<i64>(n, 0);
    for(const auto& i : Range<>(n))
        for(const auto& j : Range<>(n))
            if(i != j && !v[i][j])
                inv[i].emplace_back(j);

    UnionFind u(n);

    vector<int> col(n, -1);

    for(const auto& i : Range<>(n))
        for(auto& j : inv[i])
            u.Unite(i, j);

    auto f = makeRec([&](auto&& f, int pos) -> bool{
        for(auto& ed : inv[pos]){
            if(col[ed] == -1){
                col[ed] = col[pos] ^ 1;
                if(!f(ed))
                    return false;
            }else if(col[pos] == col[ed]){
                return false;
            }
        }
        return true;
    });

