                cout << -1 << endl;
                return 0;
            }
        }
    }

    auto c = makeVector<i64>(n, 2);
    for(const auto& i : Range<>(n)){
        ++c[u.Find(i)][col[i]];
    }

    bitset<707> bs;
    bs.set(0);
    for(const auto& i : Range<>(n)){
