typedef std::pair<int,int> pii;

const int N=705,M=N*N*2;

int n;

struct gaoxiao
{
	bool f[N*2];

	void reset(){f[0]=1;}
	void insert(int x,int y)
	{
		for(int i=n;~i;i--)
			if(f[i])f[i+x]=1,f[i+y]=1;
	}
	int ask(int x)
	{
		return x*(x-1)/2;
	}
	int calc()
	{
		int ret=M;
		for(int i=0;i<=n;i++)
			if(f[i])ret=std::min(ret,ask(i)+ask(n-i));
		return ret;
	}
}d;

bool G[N][N],vis[N];

int begin[N],next[M],to[M];

int col[N];

int m,e;

void add(int x,int y,bool k=1)
{
	to[++e]=y;
	next[e]=begin[x];
	begin[x]=e;
	if(k)add(y,x,0);
}

bool predfs(int p,int c=1)
{
	if(col[p])return col[p]==c;

	col[p]=c;

	for(int i=begin[p];i;i=next[i])
		if(!predfs(to[i],3-c))return 0;

	return 1;
}

bool judge()
{
	for(int i=1;i<=n;i++)
		if(!col[i] && !predfs(i))return 0;
	return 1;
}

void dfs(int p,pii &A)
{
	if(vis[p])return ;
	vis[p]=1;

	if(col[p]==1)A.first++;
	else A.second++;

	for(int i=begin[p];i;i=next[i])
		dfs(to[i],A);
}

int main()
{
	scanf("%d%d",&n,&m);

	for(int i=1;i<=n;i++)
		for(int j=1;j<=n;j++)
			G[i][j]=i!=j;

	for(int i=1,u,v;i<=m;i++)
		scanf("%d%d",&u,&v),G[u][v]=G[v][u]=0;

	for(int i=1;i<=n;i++)
		for(int j=1;j<i;j++)
			if(G[i][j])add(i,j);

	if(!judge())return printf("-1\n"),0;

	d.reset();
	for(int i=1;i<=n;i++)
		if(!vis[i])
		{
			pii A(0,0);
			dfs(i,A);
			d.insert(A.first,A.second);
		}
	printf("%d\n",d.calc());

	return 0;
}

