const int N = 777, mod = 1e9 + 7;

bool vis[N];
set<int> s0, s1;
vector<int> adj[N];
map<pair<int, int>, bool> meme;
int n, m, ans = 0, col[N], dp[N][N];

void dfs(int v, int c = 1) {
	vis[v] = 1;
	col[v] = c;
	if (c) {
		s1.insert(v);
	} else {
		s0.insert(v);
	}
	for (auto u : adj[v]) {
		if (vis[u]) {
			if (col[u] != 1 - c) {
				cout << -1;
				exit(0);
			}
			continue;
		}
		dfs(u, 1 - c);
	}
}

int main() { cin.tie(0)->sync_with_stdio(0);
	cin >> n >> m;
	for (int i = 1, u, v; i <= m; i++) {
		cin >> u >> v;
		meme[{u, v}] = meme[{v, u}] = 0;
	}
	for (int u = 1; u <= n; u++) {
		for (int v = u + 1; v <= n; v++) {
			if (meme.find({u, v}) == meme.end()) {
				adj[u].push_back(v);
				adj[v].push_back(u);
			}
		}
	}
	memset(col, -1, sizeof col);
	int t = 0;
	dp[t][0] = 1;
	for (int i = 1; i <= n; i++) {
		if (!vis[i]) {
			s0.clear();
			s1.clear();
			dfs(i);
			int a = size(s0), b = size(s1);
			t++;
			for (int k = 1; k <= n; k++) {
				if (k >= a) {
					dp[t][k] |= dp[t - 1][k - a];
				}
				if (k >= b) {
					dp[t][k] |= dp[t - 1][k - b];
				}
			}
			dp[i][0] = 1;
		}
	}
	for (int i = 1; i <= n; i++) {
		if (dp[t][i]) {
			ans = max(ans, i * (n - i));
		}
	}
	cout << n * (n - 1) / 2 - ans;
}

