    queue<int> q;q.emplace(i);

    int cnt = 0;
    int num = 0;
    while(q.size()){
      int j = q.front();
      q.pop();
      if(used[j]) continue;
      if(cols[j] == 0) cols[j] = 1, cnt++;
      num++;
      used[j] = 1;
      for(int k = 0; k < n; k++) if(g[j][k] == 0 && j != k && !used[k]) {
