bool bfs(int x){
	int u, v, st;
	B = W = 0;
	q.push(x);
	color[x] = 1;
	while (!q.empty()){
		u = q.front(); q.pop();
		if (color[u] == 1) B++;
		else W++;
		for (int i = 0; i < (int)G[u].size(); i++){
			v = G[u][i];
			if (color[v] == color[u]) return false;
			else if (color[v] == -1){
				q.push(v);
				color[v] = 3 - color[u];
			}
		}
	}
	return true;
}

