const int MOD = 1000000007;


int T, n, m;

bool dfs(vector<vi> &g, vector<int> &color, int u, int c){
    color[u] = c;
    for(int v : g[u]){
        if(color[v] == c) return false;
        if(!color[v] && !dfs(g, color, v, -c)) return false;
    }
    return true;
}

vector<pii> isBipartite(vector<vi> &g){
    int n = g.size();
    vector<int> color(n);
    vector<pii> counts;
    REP(i, n) {
        if(!color[i]) {
            int p = count(ALL(color), 1);
            int q = count(ALL(color), -1);
            if (!dfs(g, color, i, 1)) return vector<pii>();
            counts.emplace_back(count(ALL(color), 1) - p, count(ALL(color), -1) - q);
        }
    }
    return counts;
}

