    }
    vector<vi> g(n);
    REP(i, n) {
        REP(j, i) {
            if (!gl[i][j]) {
                g[i].push_back(j);
                g[j].push_back(i);
            }
        }
    }
    vector<pii> cnt = isBipartite(g);
    if (cnt.empty()) cout << -1 << endl;
    else {
        vi dp(n + 1);
