                    nxt[i + it.first] |= dp[i];
                }
                if (i + it.second <= n) {
                    nxt[i + it.second] |= dp[i];
                }
            }
            swap(nxt, dp);
        }
        int ans = MOD;
        REP(i, n + 1) {
            if (dp[i]) ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
        cout << ans << endl;
    }
    return 0;
}

