#include <cstdio>
using namespace std;
const int N=710,M=N*N;
const int INF=1e9;
int n,m;
int link[N][N];
int h[N],tot;
struct Edge{
	int v,next;
}e[M*2];
inline int min(int x,int y){
	return x<y?x:y;
}
void addEdge(int u,int v){
	e[++tot]=(Edge){v,h[u]}; h[u]=tot;
	e[++tot]=(Edge){u,h[v]}; h[v]=tot;
}
void readData(){
	scanf("%d%d",&n,&m);
	int u,v;
	for(int i=1;i<=m;i++){
		scanf("%d%d",&u,&v);
		link[u][v]=link[v][u]=1;
	}
}
void buildGraph(){
	for(int u=1;u<n;u++)
		for(int v=u+1;v<=n;v++)
			if(!link[u][v])
				addEdge(u,v);
}
int col[N];
int w[N][2],bcnt;
void paintDfs(int u){
	w[bcnt][col[u]]++;
	for(int i=h[u],v;i;i=e[i].next){
		v=e[i].v;
		if(col[v]==-1){
			col[v]=col[u]^1;
			paintDfs(v);
		}
		else if(col[v]!=(col[u]^1))
			throw 0;
	}
}
bool paint(){
	for(int i=1;i<=n;i++) col[i]=-1;
	for(int i=1;i<=n;i++)
		if(col[i]==-1){
			try{
				bcnt++;
				col[i]=0;
				paintDfs(i);
			}
			catch(int e){
				return false;
			}
		}
	return true;
}
bool f[N][N];
void dp(){
	f[0][0]=1;
	for(int i=0;i<bcnt;i++)
		for(int j=0;j<=n;j++)
			if(f[i][j]){
				f[i+1][j+w[i+1][0]]=true;
				f[i+1][j+w[i+1][1]]=true;
			}
}
void check(){
	int ans=INF;
	for(int i=1;i<n;i++)
		if(f[bcnt][i])
			ans=min(ans,i*(i-1)/2+(n-i)*(n-i-1)/2);
	printf("%d\n",ans);
}
int main(){
	readData();
	buildGraph();
	if(!paint()){
		puts("-1");
		return 0;
	}
	dp();
	check();
	return 0;
}

