int c[700];
bool dfs(int i, int s, pair<int, int> & x) {
	if(c[i] != 0) { return (c[i] == s); }

	c[i] = s;
	(s == +1 ? x.FI : x.SE) += 1;
	for(auto && e: g[i]) {
		if(! dfs(e, -s, x)) { return false; }
	}
	return true;
}

int main() {
