		e[b][a] = 1;
	}

	inc(i, n) {
	inc(j, n) {
		if(i != j && e[i][j] == 0) { g[i].PB(j); }
	}
	}

	vector<pair<int, int>> v;
	bool flag = true;
	inc(i, n) {
		pair<int, int> x = MP(0, 0);
		if(c[i] == 0) {
			if(! dfs(i, +1, x)) { flag = false; break; }
		}
		if(x != MP(0, 0)) { v.PB(x); }
	}
	if(! flag) { cout << -1 << endl; return 0; }

	dp[0][0] = true;
	inc(i, v.size()) {
	inc(j, n) {
		if(dp[i][j]) {
			dp[i + 1][j + v[i].FI] = true;
			dp[i + 1][j + v[i].SE] = true;
		}
	}
	}

	int x = -1;
