int n;

bool dfs(int u, bool c, V<int> &occ) {
    if (color[u] == !c) return false;
    else if (color[u] == c) return true;
    color[u] = c;
    occ[c]++;
    F(v,n) if (adj[u][v])
        if (!dfs(v, !c, occ))
            return false;
    return true;
}

int roads(int x) {
    return x*(x-1)/2;
}

signed main() {
    ios::sync_with_stdio(false);
