    adj.assign(n, V<bool>(n, true));
    F(i,n) adj[i][i] = false;
    F(i,m) {
        int a,b; cin>>a>>b;
        a--,b--;
        adj[a][b] = adj[b][a] = false;
    }
    color.assign(n, -1);
    int off = 0;
    V<bool> knap(n+1, false);
