    bool poss = true;
    F(u,n) if (color[u] == -1) {
        V<int> occ;
        occ.push_back(0);
        occ.push_back(0);
        if (!dfs(u, 0, occ))
            poss = false;
        if (occ[1] < occ[0])
            swap(occ[0], occ[1]);
        H(occ)
        off += occ[0];
        int diff = occ[1]-occ[0];
   //     cout<<"K: ";
        DR(i,diff,n+1){
 //       	cout<<i<<' ';
        	if (knap[i-diff]) {
            knap[i] = true;
        }
		}
     //   cout<<endl;
    }
