//    cout<<endl;
    H(off)
    H(knap)
    int best = n*n;
    F(i,n+1) if (knap[i]) {
        int sa = off + i, sb = n - sa;
        H(sa) H(sb)
        MI(best, roads(sa) + roads(sb));
    }
    cout<<(poss ? best : -1)<<"\n";
}

