using namespace std;

struct UnionFind {
    vector<int> par;
    vector<int> sz;

    UnionFind(int n=0){
        if(n>0) initialize(n);
    }

    void initialize(int n){
        par.resize(n);
        sz.resize(n);
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

int main(){
    int N, M;
    cin >> N >> M;
    int edges[700][700] = {0};
    for(int i=0; i<M; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        edges[a][b] = edges[b][a] = 1;
    }

    UnionFind uf(2*N);
    for(int i=0; i<N; i++) for(int j=0; j<i; j++) if(!edges[i][j]){
        uf.unite(i, j+N);
        uf.unite(j, i+N);
    }
    int num[1400][2] = {0};
    for(int i=0; i<2*N; i++){
        int ra = uf.find(i), rb = uf.find((i+N)%(2*N));
        if(ra == rb){
            cout << -1 << endl;
            return 0;
        }else if(ra < rb){
            num[ra][i/N]++;
        }
    }

    bitset<701> dp;
    dp[0] = 1;
    for(int i=0; i<2*N; i++){
        int a = num[i][0], b = num[i][1];
        dp = (dp<<a) | (dp<<b);
    }
    int ans = 1e9;
    for(int i=0; i<=N; i++) if(dp[i]){
        int j = N-i;
        int res = i*(i-1)/2 + j*(j-1)/2;
        ans = min(ans, res);
    }
    cout << ans << endl;
}

