 			vector<bool> newdp(n+1, false);

 			if (p.se == -1)
 			{
 				for (int asz = 0; asz <= p.fi; asz++)
 				{
		 			for (int x = 0; x <= n; x++)
		 			{
		 				if (dp[x])
		 				{
		 					newdp[x+asz] = true;
		 				}
		 			}
 				}
 			}
 			else
 			{
	 			for (int x = 0; x <= n; x++)
	 			{
	 				if (dp[x])
	 				{
	 					//x+p.fi
	 					//x+p.se
	 					newdp[x+p.fi] = true;
	 					newdp[x+p.se] = true;
	 				}
	 			}
 			}

 			dp = newdp;
 		}

 		int ans = MOD;

 		for (int u = 0; u <= n; u++)
 		{
 			int a = u;
