        int A,B; cin >> A >> B;
        if (A>B) swap(A,B);
        edge[--A][--B]=true;
    }
    UnionFind uf(2*N);
    for (int i=0;i<N;++i){
        for (int j=i+1;j<N;++j){
            if (!edge[i][j]){
                uf.merge(i,j+N);
                uf.merge(i+N,j);
            }
        }
    }
    for (int i=0;i<N;++i){
        if (uf.same(i,i+N)){
            cout << -1 << '\n';
            return 0;
        }
    }
    vector<bool> check(N,false);
    vector<pair<int,int>> sz;
    for (int i=0;i<N;++i){
        if (!check[i]){
            int red=0,blue=0;
            for (int j=i;j<N;++j){
                if (uf.same(i,j)||uf.same(i,j+N)){
                    ++(uf.same(i,j)?red:blue);
                    check[j]=true;
                }
            }
            sz.emplace_back(red,blue);
        }
    }
    int n=sz.size();
    vector<vector<int>> dp(n+1,vector<int>(N+1,0));
    dp[0][0]=1;
    for (int i=0;i<n;++i){
        for (int j=N;j>=0;--j){
            if (j+sz[i].first<=N) dp[i+1][j+sz[i].first]|=dp[i][j];
            if (j+sz[i].second<=N) dp[i+1][j+sz[i].second]|=dp[i][j];
        }
    }
    int ans=M;
    for (int j=0;j<=N;++j){
        if (dp[n][j]){
