	int cnt[2] = {}; // 1, -1

	REP(i, N) {
		if (col[i] == 1) cnt[0]++;
		else if (col[i] == -1) cnt[1]++;
		else if (col[i] == -2) {
			cout << -1 << endl;
			return 0;
		}
	}

	vector<pii> v;
	bool done[700] = {};
	int kori = 0;
	REP(i, N) if (!done[i]) {
		pii cur(1, 0);
		REP(j, N) if (i != j && uf.same(i, j)) {
			if (col[i] == col[j]) cur.fi++;
			else cur.se++;
			done[j] = true;
		}
		done[i] = true;
		v.push_back(cur);
	}

	dp[0][0] = 1;
	REP(i, v.size()) {
		REP(j, N) if (dp[i][j]) {
			dp[i + 1][j + v[i].fi] |= true;
			dp[i + 1][j + v[i].se] |= true;
		}
	}

