void dfs(int pos, int bef, bool now_color, pair<int, int>& cnt) {
	color[pos] = now_color ? 1 : 2;
	if (now_color)cnt.first++;
	else cnt.second++;
	for (int i = 0; i < N; i++) {
		if (!cE[pos][i])continue;
		if (i == bef)continue;
		if (color[i] != 0 && color[i] + color[pos] != 3) {
			//二部グラフではない
			cnt.first -= 114514, cnt.second -= 114514;
			break;
		}
		if (color[i] == 0) {
			dfs(i, pos, !now_color, cnt);
		}
	}
}

