void dfs(int p) {
	if(col[p] == 0) ++W;
	else ++B;
	for(int i = 1; i <= n; i++) {
		if(i == p) continue;
		if(a[p][i] == 0) {
			if(col[i] == -1) {
				col[i] = col[p] ^ 1;
				dfs(i);
			} else if (col[i] == col[p]) {
				bad = true;
				return ;
			}
		}
	}
