int nC2(int n) {
	return (n * (n - 1)) / 2;
}

int dp(int now, int white) {
	if(now == v.size()) {
		int black = n - white;
		return nC2(white) + nC2(black);
	}
	if(mem[now][white] != -1) return mem[now][white];
	int ans = min(dp(now + 1, white + v[now].first), dp(now + 1, white + v[now].second));
	return mem[now][white] = ans;
}

