struct bimatch{
	int n;
	vector<vector<int> >G;
	vector<int>match;
	vector<bool>used;
	bimatch(int _n=0):n(_n),G(n),match(n),used(n){}
	void add_edge(int u,int v)
	{
		G[u].push_back(v);
		G[v].push_back(u);
	}
	bool dfs(int v)
	{
		used[v]=true;
		for(int u:G[v])

		{
			int w=match[u];
			if(w<0||!used[w]&&dfs(w))
			{
				match[v]=u;
				match[u]=v;
				return true;
			}
		}
		return false;
	}
	int count()
	{
		int ans=0;
		fill(match.begin(),match.end(),-1);
		for(int v=0;v<n;v++)
		{
			if(match[v]<0)
			{
				fill(used.begin(),used.end(),false);
				if(dfs(v))ans++;
			}
		}
		return ans;
	}
};
bool G[777][777];
int n,m;
int color[777];
bool dfs(int u,int c,vector<vector<int> >&G)
{
	color[u]=c;
	bool ans=true;
	for(int i=0;ans&&i<G[u].size();i++)
	{
		if(color[G[u][i]]==c)return false;
		else if(color[G[u][i]]<0)ans&=dfs(G[u][i],1-c,G);
	}
	return ans;
}
bool bicheck(vector<vector<int> >&G)
{
	for(int i=0;i<n;i++)color[i]=-1;
	bool ans=true;
	for(int i=0;ans&&i<n;i++)if(color[i]<0)ans&=dfs(i,0,G);
	return ans;
}
main()
{
	cin>>n>>m;
	for(int i=0;i<m;i++)
	{
		int a,b;cin>>a>>b;
		a--,b--;
		G[a][b]=G[b][a]=1;
	}
	bimatch M(n);
	for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)
	{
		if(!G[i][j])M.add_edge(i,j);
	}
	if(!bicheck(M.G))
	{
		cout<<-1<<endl;
		return 0;
	}
	int maxbi=M.count();
	int ans=0;
	int s=n-maxbi,t=maxbi;
	ans=s*(s-1)/2+t*(t-1)/2;
	if(s>t)swap(s,t);
	for(int i=0;i<n;i++)
	{
		if(M.G[i].size()==0)
		{
			s++;t--;
		}
		ans=min(ans,s*(s-1)/2+t*(t-1)/2);
	}
	cout<<ans<<endl;
}

