bool dfs(int now, int c) {
	col[now] = c;
	cnt[conn][c]++;
	for (auto i: edge[now]) {
		if (i == par[now]) continue;
		if (col[i] != -1) {
			if (col[i] == c) return 0;
		} else {
			bool bisa = dfs(i, c^1);
			if (!bisa) return 0;
		}
	}
	return 1;
}

int f(int pos, int rem) {
	if (pos > conn) return rem == 0;
	int &ret = dp[pos][rem];
	if (ret != -1) return ret;
	ret = 0;
	if (rem >= cnt[pos][0]) ret |= f(pos+1, rem-cnt[pos][0]);
	if (rem >= cnt[pos][1]) ret |= f(pos+1, rem-cnt[pos][1]);
	return ret;
}

