bool func(int n)
{
	if (func_flg[n])
	{
		return true;
	}

	int flg[701] = {};
	vector<int> a;
	vector<int> b;

	queue<int> q;
	q.push(n);
	flg[n] = 1;
	func_flg[n] = true;
	a.push_back(n);

	int color = -1;
	while (q.size() > 0)
	{
		int q_size = q.size();
		for (int i = 0; i < q_size; i++)
		{
			int p = q.front();
			q.pop();

			for (int l : link[p])
			{
				if (flg[l] != 0)
				{
					if (flg[l] != color)
					{
						return false;
					}
				}
				else
				{
					flg[l] = color;
					func_flg[l] = true;
					if(color > 0) 
						a.push_back(l);
					else 
						b.push_back(l);
					q.push(l);
				}
			}
		}

		color *= -1;
	}

	group.push_back(P(a.size(), b.size()));

	return true;
}

