	for (int g = 1; g < group.size(); g++)
	{
		for (int i = 0; i <= N; i++)
		{
			if (dp[g - 1][i] > 0)
			{
				dp[g][i + group[g].first] = 1;
				dp[g][i + group[g].second] = 1;
			}
		}
	}

