bool get_fbuk(){
	for(int i=1; i<=n; ++i){
		int a=U::qrt(i<<1),b=U::qrt(i<<1|1);
		if(a==b) return 0;
		fbuk[a].push_back(i<<1);
		fbuk[b].push_back(i<<1|1);
	}
	return 1;
}
void dfs_col(const int x){
	for(std::vector <int> ::iterator it=fbuk[x].begin(); it!=fbuk[x].end(); ++it){
		int to=U::qrt(*it^1);
		if(~col[to]) assert(col[to]==(col[x]^1));
		else col[to]=col[x]^1,dfs_col(to);
	}
}

