vector<pii> data;

void find(vector<int> ids)
{
	if (ids.size() == 1)
	{
		cout << "-1";
		exit(0);
	}

	int n = ids.size();
	int m = 0;

	for (auto u: ids)
	{
		for (auto v: ids)
		{
			if (hasedge[u][v] && u > v)
			{
				m++;
			}
		}
	}

	if (m == ((n*(n-1))/2))
	{
		//fully connected
		data.eb(n, 0);
	}
	else
	{
		int x = -1;
		int y = -1;

		for (auto u: ids)
		{
			for (auto v: ids)
			{
				if (!hasedge[u][v])
				{
					x = u;
					y = v;
					break;
				}
			}
		}

		assert(x != -1);

		vector<int> a;
		vector<int> b;
		a.pb(x);
		b.pb(y);

		vector<int> both;
		for (auto u: ids)
		{
			if (u != x && u != y)
			{
				both.pb(u);
			}
		}

		while (true)
		{
			bool done = false;

			for (auto u: both)
			{
				//check if this can't be added to a
				bool canta = false;
				bool cantb = false;

				{
					for (auto p: a)
					{
						if (!hasedge[p][u])
						{
							canta = true;
							break;
						}
					}
				}


				{
					for (auto p: b)
					{
						if (!hasedge[p][u])
						{
							cantb = true;
							break;
						}
					}

				}

				if (canta && cantb)
				{
					cout << "-1";
					exit(0);
				}
				else if (canta)
				{
					//move u to b
					done = true;
					both.erase(find(ALL(both), u));
					b.pb(u);
					break;
				}
				else if (cantb)
				{
					//move u to a
					done = true;
					both.erase(find(ALL(both), u));
					a.pb(u);
					break;
				}
			}

			if (!done)
			{
				break;
			}
		}

		data.eb(a.size(), b.size());

		if (!both.empty())
		{
			find(both);
		}
	}
}

