      dp[1][j]=false;
    }
  }
  ll optans=0;
  for(int i=0;i<=n;i++){
    if(dp[0][i]==false){
      continue;
    }
    ll lef=i*(n-i);
    for(int j=0;j<zz.size();j++){
      lef-=(zz[j].F)*(zz[j].S);
    }
    optans=max(optans,lef);
  }
  debug(optans,m,ans);
  cout<<m-ans-optans;
}

