int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<vector<int>> mat(n, vector<int>(n));
	for(int i = 0; i < m; ++i){
		int a, b;
		cin >> a >> b;
		--a; --b;
		mat[a][b] = mat[b][a] = 1;
	}
	loquat::adjacency_list<edge> g(n);
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < n; ++j){
			if(!mat[i][j] && i != j){ g.add_edge(i, j); }
		}
	}
	vector<int> done(n);
	vector<pii> sizes;
	bool possible = true;
	for(int r = 0; r < n; ++r){
		if(done[r] != 0){ continue; }
		queue<int> q;
		q.push((r << 1) | 0);
		done[r] |= 1;
		pii size(0, 0);
		while(!q.empty()){
			const int u = q.front() >> 1;
			const int s = q.front() & 1;
			if(s == 0){
				++size.first;
			}else{
				++size.second;
			}
			q.pop();
			for(const auto& e : g[u]){
				const int v = e.to;
				const int mask = (1 << (s ^ 1));
				if(done[v] & mask){ continue; }
				done[v] |= mask;
				q.push((v << 1) | (s ^ 1));
			}
		}
		if(done[r] != 1){ possible = false; }
		sizes.push_back(size);
	}
	if(!possible){
		cout << "-1" << endl;
		return 0;
	}
	vector<int> dp(n + 1);
	dp[0] = 1;
	for(const auto p : sizes){
		vector<int> next(dp);
		for(int i = n - p.first;  i >= 0; --i){ next[i + p.first]  |= dp[i]; }
		for(int i = n - p.second; i >= 0; --i){ next[i + p.second] |= dp[i]; }
		dp = next;
	}
	int best = n * n;
	for(int i = 0; i <= n; ++i){
		if(dp[i] == 0){ continue; }
		const int a = i, b = n - i;
		best = min(best, a * (a - 1) / 2 + b * (b - 1) / 2);
	}
	cout << best << endl;
	return 0;
}

