    vector<int> s(n,0);
    s[0]=1;
    stack<int> task;
    task.push(0);
    while(!task.empty()){
      int p=task.top();
      task.pop();
      rep(j,n){
        if(p==j)continue;
        if(e[p][j]==false){
          if(s[p]==s[j]){
            cout<<-1<<endl;
