			if(hashi[j]==0||i==j)continue;
			if(g[i][j]==0)flg=0;
		}
	}
	if(flg==0){
		cout<<-1<<endl;
		return 0;
	}
	int takaNum = 0,hashiNum=0;
	REP(i,N){
		if(taka[i])takaNum++;
		else hashiNum++;
	}
	int free = 0;
	REP(i,N){
		int flg = 1;
		REP(j,N){
			if(i==j)continue;
			if(g[i][j]==0)flg=0;
		}
		if(flg){
			if(taka[i]){
				takaNum--;
				free++;
			}else{
				hashiNum--;
				free++;
			}
		}
	}
	int ans = INF;
	REP(i,free+1){
		int T = takaNum + i;
		int H = hashiNum + free - i;
		CHMIN(ans,T*(T-1)/2+H*(H-1)/2);
	}
	cout<<ans<<endl;
}

