    costs[i] = 0;

    queue<int> q;
    q.push(i);

    while (!q.empty()) {
        int from = q.front();
        q.pop();
        rep(to, n) {
            if (from == to) continue;
            else if (!edges[from][to]) continue;
            else if (costs[to] != -1) continue;
            else {
                int from_cost = costs[from];
                int to_cost = from_cost ^1;
                costs[to] = to_cost;
                q.push(to);
            }
        }
    }

    int a = count(costs.begin(), costs.end(), 0);
    int b = count(costs.begin(), costs.end(), 1);

    return P(a, b);

}
