int G[MAXN][MAXN];
int tag[MAXN], cnt[2];
bool visit[MAXN], now[MAXN], pre[MAXN];

bool dfs(int N, int cur, int tg) {
     visit[cur] = 1;
     tag[cur] = tg;
     cnt[tg]++;
     bool OK = true;
     for (int i = 1; i <= N; i++) {
         if (cur == i || G[cur][i]) continue;
         if (visit[i] && tg == tag[i]) OK = false;
         else if (!visit[i] && !dfs(N, i, tg ^ 1)) OK = false;
     }
     return OK;
}

int main() {
