    }
    int sum = 0, ans = M;
    now[0] = 1;
    for (int i = 1; i <= N; i++) {
        if (!visit[i]) {
           sum++;
           cnt[1] = cnt[0] = 0;
           memset(pre, 0, sizeof(pre));
           if (!dfs(N, i, 0)) ans = -1;
           for (int j = 0; j <= N; j++) {
               pre[j + cnt[0]] |= now[j];
               pre[j + cnt[1]] |= now[j];
           }
           for (int j = 0; j <= N; j++) now[j] = pre[j];
        }
    }
    for (int i = 0; i <= N; i++) {
        if (now[i]) {
           ans = min(ans, (i * (i - 1) + (N - i) * (N - i - 1)) / 2);
        }
