void dfs(int u, int color) {
    vis[u] = color;
    color == 1 ? n1 ++ : n2 ++;
    for (int v = 1; v <= N; v ++) {
        if (u != v && !m[u][v]) {
            if (vis[v] == color) {
                printf("-1\n");
                exit(0);
            } else if (!vis[v]) {
                dfs(v, color ^ 3);
            }
        }
