        if (!vis[i]) {
            n1 = n2 = 0;
            dfs(i, 1);
            a.push_back(make_pair(n1, n2));
        }
    }
    K = a.size();
    for (int j = 0; j <= N; j ++) {
        f[j] = j;
    }
    for (int i = 1; i <= K; i ++) {
        n1 = a[i - 1].first;
