void solve() {
    MEM(col, -1);

    int N, M;
    cin >> N >> M;
    rep(i, M) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u][v] = adj[v][u] = true;
    }

    rep(i, N)rep(j, i) {
        if (!adj[i][j]) {
            G[i].push_back(j);
            G[j].push_back(i);
        }
    }


    vector<bool> cu(N + 1), ne(N + 1);
    cu[0] = true;
    rep(i, N) {
        if (col[i] == -1) {
            int a = 0, b = 0;
            dfs(i, a, b);
            for (int j = N; j >= 0; --j) {
                if (cu[j]) {
                    ne[j + a] = true;
                    ne[j + b] = true;
                }
            }
            swap(ne, cu);
            fill(all(ne), false);
        }
    }

    int ans = INT_MAX;
    rep(i, N + 1) {
        int j = N - i;
        if (cu[i]) {
            smin(ans, i*(i - 1) / 2 + j * (j - 1) / 2);
