	bool road[MAX][MAX];
	int city[MAX];
	for (int i = 0;i < N;i ++) city[i] = 0;
	for (int i = 0;i < N;i ++) for (int j = 0;j < N;j ++) road[i][j] = false;
	for (int i = 0;i < M;i ++) {
		cin >> A >> B;
		road[A - 1][B - 1] = true;
		road[B - 1][A - 1] = true;
	}
	vector<int> taka, hashi, takahashi;
	queue<int> que;
	for (int i = 0;i < N;i ++) {
		for (int j = i + 1;j < N;j ++) {
			if (!road[i][j]) { // 直接繋がってない都市は必ず別の州
				taka.push_back(i);
				hashi.push_back(j);
				city[i] = 1;
				city[j] = 2;
				i = N;
				break;
			}
		}
	}
	if (taka.size() == 0) { // 全ての都市が直接繋がってる
		int x = N / 2;
		cout << x * (x - 1) / 2 + (N - x) * (N - x - 1) / 2;
		return 0;
	}

	for (int i = 0;i < N;i ++) {
		if (city[i] != 0) continue; // 既に調査済み都市
		for (int j = 0;j < taka.size();j ++) { // 高州に属するか調べる
			if (!road[i][taka[j]]) { // 属さない
				city[i] -= 1;
				break;
			}
		}
		city[i] += 1;
		for (int j = 0;j < hashi.size();j ++) { // 橋州に属するか調べる
			if (!road[i][hashi[j]]) { // 属さない
				city[i] -= 2;
				break;
			}
		}
		city[i] += 2;
		if (city[i] <= 0) { // 両方の都市に属さない場合
			cout << -1;
			return 0;
		} else if (city[i] == 1) { // 高州
			taka.push_back(i);
		} else if (city[i] == 2) { // 橋州
			hashi.push_back(i);
		} else { // 両方に属する可能性あり
			que.push(i);
		}
	}

	for (int i = 0, loop = que.size(), q;i < loop;i ++) {
		q = que.front();
		que.pop();
		for (int j = 0;j < taka.size();j ++) {
			if (!road[taka[j]][q]) { // 実は高州に属さない
				city[q] -= 1;
				break;
			}
		}
		for (int j = 0;j < hashi.size();j ++) {
			if (!road[hashi[j]][q]) { // 実は橋州に属さない
				city[q] -= 2;
				break;
			}
		}
		if (city[q] < 3) { // 結局違うんかい
			if (city[q] <= 0) { // なん……だと……
				cout << -1;
				return 0;
			} else if (city[q] == 1) { // 高州
				taka.push_back(q);
			} else if (city[q] == 2) { // 橋州
				hashi.push_back(q);
			}
			loop --;
			i = -1; // 最初から全チェックのやり直し
			continue;
		}
		que.push(q);
	}

	while (!que.empty()) {
		takahashi.push_back(que.front());
		que.pop();
	}

	vector<int> mid1, mid2, mid3;
	for (int i = 0;i < takahashi.size();i ++) {
		for (int j = i + 1;j < takahashi.size();j ++) {
			if (!road[takahashi[i]][takahashi[j]]) {
				mid1.push_back(takahashi[i]);
				mid2.push_back(takahashi[j]);
				city[takahashi[i]] = 4;
				city[takahashi[j]] = 8;
				i = N;
				break;
			}
		}
	}
	if (mid1.size() == 0) { // 全ての残り都市がどっちの州についても大丈夫
		for (int i = 0;i < takahashi.size();i ++) {
			mid3.push_back(takahashi[i]);
			city[takahashi[i]] = 12;
		}
	}

	for (int i = 0;i < takahashi.size();i ++) {
		if (city[takahashi[i]] > 3) continue; // 既に調査済み
		city[takahashi[i]] = 0;
		for (int j = 0;j < mid1.size();j ++) { // mid1に属するか調べる
			if (!road[takahashi[i]][mid1[j]]) { // 属してない
				city[takahashi[i]] -= 4;
				break;
			}
		}
		city[takahashi[i]] += 4;
		for (int j = 0;j < mid2.size();j ++) { // mid2に属するか調べる
			if (!road[takahashi[i]][mid2[j]]) { // 属してない
				city[takahashi[i]] -= 8;
				break;
			}
		}
		city[takahashi[i]] += 8;
		if (city[takahashi[i]] < 4) { // あれー？
			cout << -1;
			return 0;			
		} else if (city[takahashi[i]] == 4) { // mid1
			mid1.push_back(takahashi[i]);
		} else if (city[takahashi[i]] == 8) { // mid2
			mid2.push_back(takahashi[i]);
		} else { // 両方に属せるかも？
			que.push(takahashi[i]);
		}
	}

	for (int i = 0, loop = que.size(), q;i < loop;i ++) {
		q = que.front();
		que.pop();
		for (int j = 0;j < mid1.size();j ++) {
			if (!road[mid1[j]][q]) { // 実はmid1に属さない
				city[q] -= 4;
				break;
			}
		}
		for (int j = 0;j < mid2.size();j ++) {
			if (!road[mid2[j]][q]) { // 実はmid2に属さない
				city[q] -= 8;
				break;
			}
		}
		if (city[q] < 12) { // また違ったよ
			if (city[q] <= 0) { // なんで今更……
				cout << -1;
				return 0;
			} else if (city[q] == 4) { // mid1
				mid1.push_back(q);
			} else if (city[q] == 8) { // mid2
				mid2.push_back(q);
			}
			loop --;
			i = -1; // 最初から全チェックのやり直し
			continue;
		}
		que.push(q);
	}

	int a = taka.size(), b = hashi.size(), c = mid1.size(), d = mid2.size();
	int e = N - a - b - c - d;
	int diff = min(abs(a+c-b-d), abs(a+d-b-c));
	int diff2 = diff > e ? diff - e : (e - diff) % 2;
	int x2 = (N - diff2) / 2;
	cout << x2 * (x2 - 1) / 2 + (N - x2) * (N - x2 - 1) / 2;
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり

まず、仮に高州の大きさをx、橋州の大きさをN-xとすると、答えはx(x-1)/2+(N-x)(N-x-1)/2に他ならない
ということは、高州の大きさが分かれば求まる訳だ

まず、互いに直接渡れない2つの都市をそれぞれ高州、橋州の都市としよう
え、そんな都市が無かった？おめでとう、全ての都市が直接渡れるのでx=N/2として導出すれば良い
次に、高州の大きさを決めていこう
まず、高州に接しない全ての都市を橋州に、橋州に接しない全ての都市を高州にしよう
この時点で条件に反したら-1ね
さて、この時残った都市は全てどちらの州にも接しているはず
次に、残った都市のうち接してない同士はちゃんと排反として分類しよう
これは、残った都市のうち接しない二つの都市をA,Bとして、そのA,Bに接するかどうかで順にA,Bを増やせば良い
これで、後は高州の数をx、橋州の数をy、Aだけに分類された都市をa、bだけに分類された都市をb、AとBの両方に分類された都市をcとして、
x+a,y+bにcを配るかx+b,y+aにcを配り、なるべく互いの差が小さくなるようにすれば良い
O(N^2)で解けるかな、やばいとO(N^3)になる気もするけどO(N^3)は定数倍が小さいから……

