	vector<vector<int>>dis_edge(N);
	for (int i = 0; i < z_connected.size(); i++) {
		for (int j = i + 1; j < z_connected.size(); j++) {
			if (!edge[z_connected[i]][z_connected[j]]) {
				dis_node[z_connected[i]] = 1;
				dis_node[z_connected[j]] = 1;
				dis_edge[z_connected[i]].push_back(z_connected[j]);
				dis_edge[z_connected[j]].push_back(z_connected[i]);
			}
		}
	}
	queue<int>Q;
	vector<int>pare(N, MOD);
	vector<int>dis(N, MOD);
	for (int i = 0; i < N; i++) {
		if (dis_node[i]) {
			if (pare[i] == MOD) {
				Q.push(i);
				while (!Q.empty()) {
					int cn = Q.front();
					pare[cn] = i;
					Q.pop();
					for (auto i : dis_edge[cn]) {
						if (dis[i] > dis[cn] + 1) {
							dis[i] = dis[cn] + 1;
							Q.push(i);
						}
					}
				}
			}
		}
	}
	vector<pair<int, int>>pnum(N);
	vector<pair<bool, bool>>pflag(N);
	for (int i = 0; i < N; i++) {
