	for (int i = 0; i < N; i++) {
		if (pnum[i].first + pnum[i].second) {
			if (!pflag[i].first&&pflag[i].second) {
				cout << -1 << endl;
				return 0;
			}
		}
	}
	vector<int>dp(N + 1);
	dp[0] = 1;
	for (int i = 0; i < N; i++) {
		if (pnum[i].first + pnum[i].second) {
			for (int j = N; j >= 0; j--) {
				if (!dp[j])continue;
				if (pflag[i].first&&pflag[i].second) {
					dp[j + pnum[i].first] = 1;
					dp[j + pnum[i].second] = 1;
					dp[j] = 0;
				}
				else if (pflag[i].first) {
					dp[j + pnum[i].first] = 1;
				}
				else {
					dp[j + pnum[i].second] = 1;
				}
			}
		}
	}
	for (int i = 0; i < N; i++) {
		if (pare[i] == MOD)continue;
		if (dis[i] % 2) {
			pnum[pare[i]].second++;
		}
		else {
			pnum[pare[i]].first++;
		}
	}
	int ans = MOD;
	for (int i = 0; i <= N; i++) {
		if (!dp[i])continue;
		int l = z_noconnected.size() + i;
		int r = N - l;
		ans = min(ans,l*(l - 1) / 2 + r * (r - 1) / 2);
	}

	if (ans == MOD) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}
	return 0;
}

