}
const int maxn=710;
int n,m,ans,f[maxn],c1,c2;
int a[maxn],b[maxn];
bool d[maxn][maxn],dp[maxn][maxn][maxn];
bool dfs(int u) {
	if (f[u]==1) c1++; else c2++;
	for (int i=1;i<=n;i++) {
		if (!d[i][u]) continue; int v=i;
		if (f[v]!=-1&&f[v]==f[u]) return 0;
		if (f[v]!=-1) continue;
		f[v]=1-f[u];
		if (!dfs(v)) return 0;
	}
	return 1;
}
int main() {
