		d[x][y]=d[y][x]=0;
	}
	memset(f,-1,sizeof(f));
	for (int i=1;i<=n;i++) {
		if (f[i]!=-1) continue;
		f[i]=1; c1=c2=0;
		if (!dfs(i)) {
			ans=-1; break;
		}
		a[i]=c1; b[i]=c2;
	}
	if (ans!=-1) {
		dp[0][0][0]=1;
		for (int i=1;i<=n;i++) {
			for (int j=0;j<=n;j++)
				for (int k=0;k<=n;k++) {
					if (j>=a[i]&&k>=b[i])
						dp[i][j][k]=dp[i-1][j-a[i]][k-b[i]];
					if (j>=b[i]&&k>=a[i])
						dp[i][j][k]|=dp[i-1][j-b[i]][k-a[i]];
				}
		}
		ans=1e9;
		for (int i=1;i<=n;i++) {
			if (!dp[n][i][n-i]) continue;
			ans=min(ans,i*(i-1)/2+(n-i)*(n-i-1)/2);
		}
	}
	printf("%d\n",ans);
	return 0;
}

