int n, m;
vector<vector<int>> g, dist;

int solve();

int main() {
  cin >> n >> m;
  g.assign(n, vector<int>(n, 1));
  dist.assign(n, vector<int>(n, inf));
  for (int i = 0; i < m; ++i) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    g[x][y] = g[y][x] = 0;
  }
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      if (i == j)
        dist[i][j] = 0;
      else if (g[i][j])
        dist[i][j] = 1;
  cout << solve() << endl;
  return 0;
}

int solve() {
  for (int k = 0; k < n; ++k)
    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j)
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      for (int k = 0; k < n; ++k)
        if (dist[i][j] != inf && dist[i][k] != inf &&
            (dist[i][j] & 1) ^ ((dist[i][k] + dist[k][j]) & 1))
          return -1;
  using P = pair<int, int>;
  vector<P> v;
  {
    vector<bool> used(n, 0);
    for (int i = 0; i < n; ++i)
      if (!used[i]) {
        P now(0, 0);
        for (int j = 0; j < n; ++j)
          if (dist[i][j] != inf) {
            used[j] = 1;
            if (dist[i][j] & 1)
              ++now.first;
            else
              ++now.second;
          }
        v.push_back(now);
      }
  }
  int len = v.size(), res = inf;
  vector<vector<int>> dp(len + 1, vector<int>(n + 1, 0));
  dp[0][0] = 1;
  for (int i = 0; i < len; ++i) {
    for (int j = v[i].first; j <= n; ++j) dp[i + 1][j] |= dp[i][j - v[i].first];
    for (int j = v[i].second; j <= n; ++j)
      dp[i + 1][j] |= dp[i][j - v[i].second];
  }
  for (int i = 0; i <= n; ++i)
    if (dp[len][i])
      res = min(res, (i * (i - 1) / 2) + ((n - i) * (n - i - 1) / 2));
  return res;
}

