using namespace std;
using vecint = vector<int>;
using ll = int64_t;

bool dfs(const vector<vecint>&g, vecint& vis, int i, int k) {
  int n=g.size();
  REP(j,n) {
    if (g[i][j]) {
      if (vis[j] == 0) {
        vis[j] = -k;
        if (!dfs(g, vis, j, -k)) return false;
      } else if (vis[j] == k) return false;
    }
  }
  return true;
}

int main()
{
  int n,m;
