  REP(i,n) g[i][i] = 0;
  REP(i,m) {
    int a,b;
    cin>>a>>b;
    --a;--b;
    g[a][b] = 0;
    g[b][a] = 0;
  }
  REP(i,n){
    REP(j,n) {
      cerr<<g[i][j];
    }
    cerr<<endl;
  }
  vecint vis(n, 0);
  int k = 1;
  REP(i,n) {
    if (vis[i] == 0) {
      vis[i] = k;
      if (!dfs(g, vis, i, k)) {
        cout<<-1<<endl;
        return 0;
      }
      ++k;
    }
  }
  map<int,int> num;
  REP(i,n) {
    ++num[vis[i]];
  }
  vecint d(k);
  REP(i,k) {
    int pos = num[i];
    int neg = num[-i];
    d[i] = abs(pos - neg);
  }
  vector<bool> dp(2*n-1, false);
  int offset = n;
  dp[offset] = true;
  REP(i,k) {
    vector<bool> tmp(2*n + 1, false);
    REP(j,2*n+1) {
      int down = j-d[i];
      if (down >= 0) {
        tmp[down] = tmp[down] || dp[j];
      }
      int up = j+d[i];
      if (up <= 2*n) {
        tmp[up] = tmp[up] || dp[j];
      }
    }
    swap(dp, tmp);
  }
  int md = 2*n;
  REP(i,n+1) {
    if (dp[i+offset]) md = min(md, i);
  }
  int a = (n-md) / 2, b = (n+md) / 2;
  int ans = a * (a-1) / 2 + b * (b-1) / 2;
  cout<<ans<<endl;
  return 0;
}

