void init_dsu()
{
	for (int i = 0; i < N; i++)
	{
		dsu[i] = i;
		sz[i] = 1;
	}
}
int find_parent(int u)
{
	return (u == dsu[u] ? u : dsu[u] = find_parent(dsu[u]));
}
bool merge(int u, int v)
{
	u = find_parent(u);
	v = find_parent(v);
	if (u == v)
	{
		return false;
	}
	if (sz[u] > sz[v])
	{
		swap(u, v);
	}
	dsu[u] = v;
	sz[v] += sz[u];
	sz[u] = 0;
	return true;
}
bool dfs(int u, bool col)
{
	if (vis[u])
	{
		if (col != color[u])
		{
			return false;
		}
		return true;
	}
	vis[u] = true;
	color[u] = col;
	freq[color[u]]++;
	for (int v = 0; v < N; v++)
	{
		if (!edge[u][v]) continue;
		if (!dfs(v, !col)) return false;
	}
}
int choose2(int x)
{
	return x * (x - 1) / 2;
}

