	}
	for(int i = 1; i<=n; i++){
		for(int j = 1; j<=n; j++){
			if(i == j) continue;
			if(adjmat[i][j] == false) adjlist[i].push_back(j);
		}
	}
	for(int i = 1; i<=n; i++){
		if(color[i] == 0){
			color[i] = 1;
			dfs(i);
			one = two = 0;
			cfs(i);
			items.push_back(pi(one, two));
		}
	}
	dp[0] = true;
	int total = 0;
	for(auto i : items){
		printf("i %d %d\n", i.first, i.second);
		for(int x = n; x>=0; x--){
			if((x-i.first >= 0 and dp[x-i.first]) or (x-i.second >= 0 and dp[x-i.second])){
				dp[x] = true;
			}
		}
		total += i.first + i.second;
	}
	int ans = INT_MAX;
	for(int i=0; i<=n; i++){
		if(dp[i]){
			int j = total - i;
			assert(dp[j]);
			ans = min(ans, i*(i-1)/2 + j*(j-1)/2);
		}
	}
	if(ans == INT_MAX) cout << -1;
	else
	cout << ans;
}

