const int dx[]={1,0,-1,0,1,1,-1,-1},dy[]={0,-1,0,1,1,-1,-1,1};

pii dfs(int v, int c, vector<int> &color, vector<vector<int>> &E) {
  if (color[v] == -1) {
    color[v] = c;
  } else {
    if (color[v] != c) {
      return mp(-1, -1);
    } else {
      return mp(0, 0);
    }
  }

  int N = E.size();
  pii sum;
  if (c == 0) sum.first += 1; else sum.second += 1;
  for(int i = 0; i < N; i++) {
    if (E[v][i]) {
      pii r = dfs(i, 1 - c, color, E);
      if (r.first == -1) return mp(-1, -1);
      sum.first += r.first;
      sum.second += r.second;
    }
  }
  return sum;
}

int main() {
  int N, M;
  cin >> N >> M;
  vector<vector<int>> E(N, vector<int>(N, 0));
  for (int i = 0; i < M; i++) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    E[a][b] = E[b][a] = 1;
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (i == j) continue;
      E[i][j] = 1 - E[i][j];
    }
  }
  vector<int> color(N, -1);
  vector<pii> k;
  for(int i = 0; i < N; i++) {
    if (color[i] == -1) {
      k.push_back(dfs(i, 0, color, E));
    }
  }
  for (int i = 0; i < k.size(); i++) {
    if (k[i].first == -1) {
      cout << -1 << endl;
      return 0;
    }
  }

  // dp[i][j] := i個目まで考えた時、選んだSの大きさがjとなるか
  vector<vector<int>> dp(k.size() + 1, vector<int>(N + 1, 0));

  dp[0][0] = 1;
  for (int i = 0; i < k.size(); i++) {
    for (int j = 0; j < N; j++) {
      if (!dp[i][j]) continue;
      dp[i + 1][j + k[i].first] |= dp[i][j];
      dp[i + 1][j + k[i].second] |= dp[i][j];
    }
  }
  int ans = 1 << 30;
  for (int j = 0; j < N; j++) {
    if (dp[k.size()][j]) {
      int r = j, b = N - r;
      ans = min(ans, r * (r - 1) / 2 + b * (b - 1) / 2);
    }
  }
  cout << ans << endl;

  return 0;
}

