typedef long long ll;
typedef pair<int, int> P;

int N, M;
bool x[750][750];
vector<int> edge[750];
int check[750];


P dfs(int s, int c){
    if(check[s] != 0){
        if(check[s] != c){
            return P(-1, -1);
        }
        else{
            return P(0, 0);
        }
    }
    check[s] = c;
    P ret = P(0, 0);
    for(auto v: edge[s]){
        P p = dfs(v, -c);
        if(p.fs == -1 && p.sc == -1){
            return P(-1, -1);
        }
        ret.fs += p.fs;
        ret.sc += p.sc;
    }
    if(c == 1){
        ret.fs += 1;
    }
    else{
        ret.sc += 1;
    }

    return ret;
}


int main(){
    cin >> N >> M;
    for(int i = 0; i < 750; i++){
        fill(x[i], x[i]+750, false);
    }
    for(int i = 0; i < M; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        x[a][b] = true;
        x[b][a] = true;
    }

    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            if(i == j){
                continue;
            }
            if(!x[i][j]){
                edge[i].push_back(j);
            }
        }
    }

    fill(check, check+750, 0);
    vector<P> p_list;
    for(int i = 0; i < N; i++){
        if(check[i] != 0){
            continue;
        }
        P p = dfs(i, 1);
        if(p.fs == -1 && p.sc == -1){
            cout << -1 << endl;
            return 0;
        }
        p_list.emplace_back(P(min(p.fs, p.sc), max(p.fs, p.sc)));
    }

    bool can_make[2][450];
    fill(can_make[0], can_make[0]+450, false);
    fill(can_make[1], can_make[1]+450, false);

    can_make[0][0] = true;
    can_make[1][0] = true;
    int mi = 0;
    for(auto p: p_list){
        mi += p.fs;
        for(int i = 0; i <= N/2; i++){
            int dif = p.sc - p.fs;
            if(i >= dif && can_make[0][i-dif]){
                can_make[1][i] = true;
            }
        }
        for(int i = 0; i <= N/2; i++){
            can_make[0][i] = can_make[1][i];
        }
    }

    for(int i = N/2 - mi; i >= 0; i--){
        if(can_make[0][i]){
            mi += i;
            break;
        }
    }

    cout << (mi * (mi-1) + (N-mi)*(N-mi-1)) / 2 << endl;



    return 0;

}

