// ---------------------- template ----------------------

vector<int> memo;

bool DFS(const vector<vector<int> >& G, int node, vector<int>& memo) {
	int res = 1;
	for (auto &to : G[node]){
		if (memo[to] != 0) {
			if (memo[node] == memo[to]) return false;
		}
		else {
			memo[to] = memo[node] * -1;
			if(not DFS(G, to, memo)) return false;
		}
	}
	return true;
}

void solve() {
	int N, M; cin >> N >> M;
	vector<vector<bool> > G(N, vector<bool>(N));
	REP(i, M) {
		int a, b; cin >> a >> b;
		--a; --b;
		G[a][b] = true;
		G[b][a] = true;
	}
	vector<vector<int> > cg(N);
	REP(i, N) REP(j, N) if((not G[i][j]) and (i != j)) {
		cg[i].push_back(j);
	}

	vector<bool> check(N);
	vector<pii> counts;
	REP(i, N) if(not check[i]) {
		vector<int> memo(N);
		memo[i] = 1;
		if (not DFS(cg, i, memo)) {
			cout << -1 << endl;
			return;
		}
		int cnt1=0, cnt2=0;
		REP(i, memo.size()) {
			if (memo[i] == 1) cnt1++;
			else if (memo[i] == -1) cnt2++;
			if (memo[i] != 0) check[i] = true;
		}
		counts.emplace_back(cnt1, cnt2);
	}

	vector<bool> dpOld(N+1);
	vector<bool> dp(N+1);
	dp[0] = true;
	for (auto &count : counts) {
		swap(dp, dpOld);
		REP(i,N+1){
			if (i - count.first >= 0 and dpOld[i - count.first]) dp[i] = true;
			if (i - count.second >= 0 and dpOld[i - count.second]) dp[i] = true;
			if (dpOld[i]) dp[i] = true;
		}
	}

	for (auto &count : counts) {
		if (min(count.first, count.second) != 0) dp[0] = false;
	}

	int ans = inf;
	REP(i, N+1) if(dp[i]) {
		int S = i;
		int T = N - i;
		ans = min(ans, (S)*(S - 1) / 2 + (T)*(T - 1) / 2);
	}
	cout << ans << endl;
}

