bool bfs(const vec<vec<int>>& G, vec<int>& color, int s, int& S, int& T) {
   queue<P> que;
   if (color[s] == 0) {
      que.push(MP(s,1));
      color[s] = 1;
      S++;
   }
   while (!que.empty()) {
      P p = que.front(); que.pop();
      int i = p.first, c = -1 * p.second;
      rep(j, 0, G[i].size()) {
         int to = G[i][j];
         if (color[to] == 0) {
            color[to] = c;
            que.push(MP(to,c));
            if (c == 1) {
               S++;
            } else {
               T++;
            }
         } else if (color[to] != c) {
            return false;
         }
      }
   }
   return true;
}

