using namespace std;
#define REP(i,n) for (int i = 0; i < n; ++i)
#define REPR(i,n) for (int i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (int i = m; i < n; ++i)

inline int other(int n) {
    return n^1;
}

const int MAX = 710;
int G[MAX][MAX];
int group[MAX];
int groupCount[MAX];
int N, M;
bool dp[MAX];

bool dfs(int n, int g) {
    group[n] = g;
    bool res = true;
    REP (i, N) if (i != n) {
        if (G[n][i]) {
            if (group[i] == g) return false;
            if (group[i] == 0) res &= dfs(i, other(g));
        }
    }
    return res;
}

int main() {
    cin >> N >> M;

    REP (i, N) REP (j, N) G[i][j] = 1;
    REP (i, M) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        G[a][b] = G[b][a] = 0;
    }

    int count = 0;
    bool res = true;
    REP (i, N) {
        if (group[i] == 0) {
            count++;
            res &= dfs(i, count*2);
        }
        groupCount[group[i]]++;
    }
    if (!res) {
        cout << -1 << endl;
        return 0;
    }

    dp[groupCount[2]] = true;
    FOR (g, 2, count+1) {
        REPR (i, MAX) if (dp[i]) {
            dp[i+groupCount[g*2]] = dp[i+groupCount[g*2+1]] = true;
            dp[i] = false;
        }
    }
    int ans = MAX*MAX;
    REP (i, MAX) if (dp[i])
        ans = min(ans, (i*(i-1)+(N-i)*(N-i-1))/2);
    cout << ans << endl;
}

