bool dfs(ll num, ll c, ll& plus, ll& minas) {
  color[num] = c;
  if (c == 1) plus++;
  else minas++;
  for (ll i : rev[num]) {
    if (color[i] == 0) {
      if (dfs(i, -c, plus, minas)) return true;
    } else if (color[i] == c) return true;
  }
  return false;
}

