  }
  for (ll i = 0; i < n; i++) {
    for (ll j = 0; j < n; j++) if (i != j) {
      if (e[i].count(j) == 0) {
        rev[i].push_back(j);
      }
    }
  }
  vector<P> temp;
  for (ll i = 0; i < n; i++) if (color[i] == 0) {
    ll plus = 0, minas;
