  for (P p : temp) {
    dp = (dp << p.first) | (dp << p.second);
  }
  ll ans = INF;
  for (ll i = 0; i < n; i++) if (dp[i]) {
    ans = min(ans, n * (n-1) / 2 - i * (n-i));
  }
  printf("%lld\n", ans);
