bitset<N> mp[N],now,vis;

int main(){
	int i;
	scanf("%d%d",&n,&m);
	for (i=1;i<=m;i++){
		scanf("%d%d",&x,&y);
		mp[x][y]=mp[y][x]=1;
	}
	if (m==n*(n-1)/2){
		m=n/2;
		n=n-m;
		printf("%d\n",m*(m-1)/2+n*(n-1)/2);
		return 0;
	}
	c1=c2=0;
	while (1){
		for (i=1;i<=n;i++) if (!vis[i]){
			now[i]=1;
			break;
		}
		if (i>n){
			if (cnt>2){
				printf("-1\n");
				return 0;
			}
			break;
		}
		for (i=1;i<=n;i++)
			if (!vis[i]&&((mp[i]&now)==now))
				now[i]=1;
		vis|=now;
		if (!c1){
			for (i=1;i<=n;i++)
				if (now[i]) a[++c1]=i;
		}
		else{
			for (i=1;i<=n;i++)
				if (now[i]) b[++c2]=i;
		}
		cnt++;
		for (i=1;i<=n;i++) now[i]=0;
	}
	if (c1>c2){
		for (i=1;i<=c1;i++) swap(a[i],b[i]);
		swap(c1,c2);
	}
	for (i=1;i<=n;i++) now[i]=vis[i]=0;
	for (i=1;i<=c1;i++) now[a[i]]=1;
	while (c1<c2){
		tag=0;
		for (i=1;i<=c2;i++)
			if (!vis[i]&&(mp[b[i]]&now)==now){
				tag=1;
				now[b[i]]=1;
				a[++c1]=b[i]; vis[i]=1;
				break;
			}
		if (!tag) break;
	}
	ans=c1*(c1-1)/2+c2*(c2-1)/2;
	printf("%d\n",ans);
	return 0;
}
