             dp[i+1][j+data[i].second]=1;
         }
     }
    int k=n*(n-1)/2,ans=inf;
    rep(i,n+1){
        if(dp[data.size()][i]){
            int cnt=k-i*(n-i);
            ans=min(ans,cnt);
        }
    }
