    }
    --a;
    --b;
    st.emplace(a, b);
  }
  unordered_multimap<ll, ll> graph;
  REP(i, n) FOR(j, i + 1, n) if (st.find(PAIR{i, j}) == st.end()) {
    graph.emplace(i, j);
    graph.emplace(j, i);
  }

  VL isUsed(n, -1);
  V<PAIR> es;
  es.reserve(n);
  REP(f, n) if (isUsed[f] == -1) {
    isUsed[f] = 0;
    PAIR p{0, 0};

    queue<PAIR> q;
    q.emplace(f, 0);
    while (!q.empty()) {
      auto [from, b] = q.front();
      q.pop();
      ++(b ? p.first : p.second);
      ll k = (b + 1) & 1;
      auto range = graph.equal_range(from);
      REPI2(itr, range.first, range.second) {
	ll to = itr->second;
	if (isUsed[to] == -1) {
	  isUsed[to] = k;
	  q.emplace(to, k);
	} else {
	  if (isUsed[to] != k) {
