const int MAXN = 710;
int N;
int M;
bool G[MAXN][MAXN];
vector<int> adj[MAXN];

int color[MAXN];

bool dp[MAXN];

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> M;
	for (int a = 1; a <= N; a++) {
		for (int b = a+1; b <= N; b++) {
			G[a][b] = true;
		}
	}
	for (int e = 0; e < M; e++) {
		int a, b; cin >> a >> b;
		if (a > b) swap(a, b);
		G[a][b] = false;
	}
	for (int a = 1; a <= N; a++) {
		for (int b = a+1; b <= N; b++) {
			if (G[a][b]) {
				adj[a].push_back(b);
				adj[b].push_back(a);
			}
		}
	}

	dp[0] = true;
	for (int st = 1; st <= N; st++) {
		if (color[st]) continue;
		int cnt[2] = {};
		{
			function<void(int, int)> dfs = [&](int cur, int curCol) -> void {
				assert(!color[cur]);
				color[cur] = curCol;
				cnt[curCol-1]++;
				for (int nxt : adj[cur]) {
					if (!color[nxt]) {
						dfs(nxt, 3-curCol);
					} else if (color[nxt] == curCol) {
						cout << -1 << '\n';
						exit(0);
					}
				}
			};
			dfs(st, 1);
		}
		for (int i = N; i >= 0; i--) {
			if (dp[i]) {
				for (int j = 0; j < 2; j++) {
					dp[i + cnt[j]] = true;
				}
			}
		}
	}

	auto c2 = [&](int n) -> int {
		return n * (n-1) / 2;
	};
	int ans = N * N;
	for (int i = 0; i <= N; i++) {
		if (dp[i]) {
			ans = min(ans, c2(i) + c2(N-i));
		}
	}
	cout << ans << '\n';

	return 0;
}

