typedef long long ll;
const int N = 700;
int n, m, e[N][N];
vector<vector<int> > g;
int Not(int u) {
	if (u < n)
		return u + n;
	return u - n;
}
void addEdge(int a, int b) {
	g[Not(a)].push_back(b);
	g[Not(b)].push_back(a);
}
int low[2 * N], idx[2 * N], dfs, cmp, compH[2 * N];
vector<int> S;
int comp[2 * N];
bool vis[2 * N];
void DFS(int u) {
	S.push_back(u);
	low[u] = idx[u] = ++dfs;
	vis[u] = true;
	for (auto &v : g[u]) {
		if (!idx[v])
			DFS(v);
		if (vis[v])
			low[u] = min(low[u], idx[v]);
	}
	if (low[u] == idx[u]) {
		compH[cmp] = u;
		while (true) {
			int v = S.back();
			S.pop_back();
			vis[v] = false;
			comp[v] = cmp;
			if (u == v)
				break;
		}
		++cmp;
	}
}
int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 0; i < m; ++i) {
		int u, v;
		scanf("%d%d", &u, &v);
		--u; --v;
		e[u][v] = e[v][u] = true;
	}
	g.resize(2 * n);
	for (int i = 0; i < n; ++i)
		for (int j = i + 1; j < n; ++j)
			if (!e[i][j]) {
				addEdge(i, j);
				addEdge(Not(i), Not(j));
			}
	for (int i = 0; i < g.size(); ++i)
		if (!idx[i])
			DFS(i);
	for (int i = 0; i < n; ++i)
		if (comp[i] == comp[i + n]) {
			puts("-1");
			return 0;
		}
	vector<int> in(cmp);
	vector<vector<int> > G(cmp);
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			if (comp[i] != comp[g[i][j]]) {
				G[comp[i]].push_back(comp[g[i][j]]);
				++in[comp[g[i][j]]];
			}
	queue<int> q;
	for (int i = 0; i < in.size(); ++i)
		if (!in[i])
			q.push(i);
	vector<char> res(cmp, -1);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (res[u] == -1) {
			res[u] = false;
			res[comp[Not(compH[u])]] = true;
		}
		for (auto &v : G[u])
			if (!--in[v])
				q.push(v);
	}
	vector<int> v[2];
	for (int i = 0; i < n; ++i)
		v[res[comp[i]]].push_back(i);
	if (v[0].size() < v[1].size())
		v[0].swap(v[1]);
	for (int i = 0; v[0].size() > v[1].size() && i < v[0].size(); ++i) {
		int u = v[0][i];
		bool can = true;
		for (auto &v : v[1])
			if (!e[u][v]) {
				can = false;
				break;
			}
		if (can) {
			v[1].push_back(v[0][i]);
			v[0][i] = v[0].back();
			v[0].pop_back();
			--i;
		}
	}
	int R = 0;
	for (int i = 0; i < 2; ++i)
		R += v[i].size()*((int)v[i].size() - 1) / 2;
	printf("%d\n", R);
	return 0;
}

