const int MAXN = 700;
bool adjMat[MAXN + 1][MAXN + 1];
int color[MAXN + 1];
bool dp[MAXN + 1];

int main()
{
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        adjMat[a][b] = adjMat[b][a] = true;
    }
    for (int i = 1; i <= n; i++)
    {
        for (int j = i + 1; j <= n; j++)
        {
            adjMat[i][j] = adjMat[j][i] = !adjMat[i][j];
        }
    }
    bool valid = true;
    vector<pair<int, int>> v;
    for (int i = 1; i <= n; i++)
    {
        if (color[i] == 0)
        {
            pair<int, int> pr = make_pair(0, 0);
            queue<int> q;
            color[i] = 1;
            q.push(i);
            while (!q.empty())
            {
                int cur = q.front();
                q.pop();
                if (color[cur] == 1)
                    pr.first++;
                else
                    pr.second++;
                for (int j = 1; j <= n; j++)
                {
                    if (j == cur)
                        continue;
                    if (adjMat[cur][j])
                    {
                        if (color[j] == 0)
                        {
                            q.push(j);
                            color[j] = color[cur] == 1 ? 2 : 1;
                        }
                        else if (color[j] == color[cur])
                        {
                            valid = false;
                        }
                    }
                }
            }
            v.push_back(pr);
        }
    }
    if (valid)
    {
        dp[0] = true;
        for (pair<int, int> pr : v)
        {
            for (int i = n; i >= 0; i--)
            {
                if (dp[i])
                {
                    dp[i] = false;
                    dp[i + pr.first] = true;
                    dp[i + pr.second] = true;
                }
            }
        }
        int target1, target2;
        target1 = target2 = n / 2;
        if (n % 2 != 0)
            target2++;
        int diff = n + 5;
        int compSize = 0;
        for (int i = 1; i <= n; i++)
        {
            if (dp[i])
            {
                int d = min(abs(i - target1), abs(i - target2));
                if (d < diff)
                {
                    diff = d;
                    compSize = i;
                }
            }
        }
        int c1 = compSize;
        int c2 = n - c1;
        cout << c1 * (c1 - 1) / 2 + c2 * (c2 - 1) / 2 << endl;
    }
    else
    {
        cout << -1 << endl;
    }
    return 0;
}

