bool dfs(int v, int c) {
  color[v] = c;
  for (int i = 1; i <= N; i++) {
    if (v == i) {
      continue;
    }
    if (!A[v][i]) {
      if (color[i] == c) {
        return false;
      }
      if (color[i] == 0 && !dfs(i, c*(-1))) {
        return false;
      }
    }
  }
  return true;
}

int func(int n) {
  int l = n;
  int r = N-n;
  return l*(l-1)/2 + r*(r-1)/2;
}

int main() {
  cin >> N >> M;
  while (M > 0) {
    int i, j;
    cin >> i >> j;
    A[i][j] = true;
    A[j][i] = true;
    M--;
  }
  for (int i=1; i<=N; i++) {
    if (color[i] == 0) {
      if (!dfs(i, numgraph)) {
        cout << -1 << endl;
        return 0;
      }
      numgraph++;
    }
  }
  numgraph--;
  for (int i=1; i<=N; i++) {
    if (color[i] > 0) {
      numcolor[color[i]][0]++;
    } else {
      numcolor[color[i]*(-1)][1]++;
    }
  }
  /**
  for (int i=1; i<=numgraph; i++) {
    cout << "numcolor[" << i << "][" << 0 << "] = " << numcolor[i][0] << endl;
    cout << "numcolor[" << i << "][" << 1 << "] = " << numcolor[i][1] << endl;
  }
  */

  dp[0][0] = true;
  for (int i=1; i<=numgraph; i++) {
    // cout << "processing graph " << i << endl;
    for (int j=0; j<=N; j++) {
      if (j-numcolor[i][0] >= 0) {
        dp[j][1] = dp[j - numcolor[i][0]][0];
      }
      if (j-numcolor[i][1] >= 0) {
        dp[j][1] = dp[j][1] || dp[j - numcolor[i][1]][0];
      }
    }
    for (int j=0; j<=N; j++) {
      // cout << "dp[" << j << "]: " << dp[j][1] << endl;
      dp[j][0] = dp[j][1];
      dp[j][1] = false;
    }
  }

  int mn = N;
  int ans = N*N;
  for (int j=1; j<N; j++) {
    if (dp[j][0]) {
      // cout << "j: " << j << endl;
      ans = min(ans, func(j));
    }
  }
  cout << ans << endl;
}

