    for(ll i=0; i<n; i++)
        for(ll j=0; j<n; j++) {
            if(i == j) continue;
            if(!G[i].count(j))
                iG[i].insert(j);
        }

    vector<pair<ll,ll>> v; // cnt, zc
    {
        ll cnt = 0, zc = 0;
        auto dfs = [&](auto dfs, ll cur, ll pre, ll idx, map<ll,ll> &visited) {
            if(visited.count(cur)) {
                if((visited[cur]^idx)&1) return false;
                return true;
            }
            if(~idx&1) zc++;
            cnt++;
            visited[cur] = idx;

            for(auto &v: iG[cur]) {
                if(v == pre) continue;
                if(!dfs(dfs, v, cur, idx^1, visited)) return false;
            }
            return true;
        };

        bool ok = true;
        set<ll> visited;
        for(ll i=0; i<n; i++) {
            if(visited.count(i)) continue;
            map<ll,ll> m;
            ok &= dfs(dfs, i, -1, 0, m);
            v.push_back({cnt, zc});
            cnt = 0, zc = 0;
            for(auto &t: m)
                visited.insert(t.first);
        }
        if(!ok) {
            cout << -1 << endl;
            return 0;
        }
