    bitset<1000> bs;
    bs[0] = 1;
    for(auto &t: v) {
        ll c, zc;
        tie(c, zc) = t;
        bs = (bs << zc) | (bs << (c-zc));
    }

    ll r = 1e9;
    for(ll i=0; i<1000; i++) {
        if(!bs[i]) continue;
        r = min(r, i*(i-1)/2 + (n-i)*(n-i-1)/2);
    }
    cout << r << endl;
}

