        cin >> a >> b;
        g[a - 1][b - 1] = g[b - 1][a - 1] = 0;
    }

    vector<int> sz1, sz2, col(n, -1);
    for(int i = 0; i < n; ++i) {
        if(col[i] != -1) continue;
        int s1 = 0, s2 = 0;
        if(!dfs(g, col, i, s1, s2, 0)) {
            cout << -1 << endl;
            return 0;
        }
        sz1.push_back(s1), sz2.push_back(s2);
    }
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, -inf));
    dp[0][0] = 0;
    const int sz = sz1.size();
    for(int i = 0; i < sz; ++i) {
        vector<vector<int>> nxt(n + 1, vector<int>(n + 1, -inf));
        for(int j = 0; j <= n; ++j) {
            for(int k = 0; k <= n; ++k) {
                if(dp[j][k] == -inf) continue;
                nxt[j + sz1[i]][k + sz2[i]] = max(nxt[j + sz1[i]][k + sz2[i]], dp[j][k] + sz1[i] * k + sz2[i] * j + sz1[i] * sz2[i]);
                nxt[j + sz2[i]][k + sz1[i]] = max(nxt[j + sz2[i]][k + sz1[i]], dp[j][k] + sz2[i] * k + sz1[i] * j + sz1[i] * sz2[i]);
            }
        }
        dp = move(nxt);
    }

    int ans = 0;
    for(int i = 0; i <= n; ++i) {
        for(int j = 0; j <= n; ++j) {
            ans = max(ans, dp[i][j]);
        }
    }
    ans -= n * (n - 1) / 2 - m;
    ans = m - ans;

    cout << ans << endl;
}

