namespace Problem {
using namespace std;

class Solver {
 public:
  int n, m;
  vector<vector<int>> coGraph;
  vector<pair<int, int>> size;
  vector<int> visit;
  Solver(LL n) : n(n), coGraph(n, vector<int>(n, 1)), visit(n, -1){};

  void solve() {
    cin >> m;
    for (int i = 0; i < n; ++i) {
      coGraph[i][i] = 0;
    }
    for (int i = 0; i < m; ++i) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      coGraph[a][b] = coGraph[b][a] = 0;
    }
    for (int i = 0; i < n; ++i) {
      vector<set<int>> st(2);
      if (visit[i] >= 0) continue;
      dfs(i, 0, st);
      size.emplace_back(st[0].size(), st[1].size());
    }
    vector<vector<int>> dp(size.size() + 1, vector<int>(n + 1));
    dp[0][0] = 1;
    for (int i = 1; i <= size.size(); ++i) {
      for (int j = 0; j <= n; ++j) {
        if (j - size[i - 1].first >= 0) {
          dp[i][j] |= dp[i - 1][j - size[i - 1].first];
        }
        if (j - size[i - 1].second >= 0) {
          dp[i][j] |= dp[i - 1][j - size[i - 1].second];
        }
      }
    }
    int ans = INF;
    for (int i = 0; i <= n; ++i) {
      if (dp[size.size()][i] and i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2 < ans) {
        ans = i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2;
      }
    }
    cout << ans << endl;
  }
  void no() {
    cout << -1 << endl;
    exit(0);
  }
  void dfs(int x, int b, vector<set<int>> &st) {
    if (visit[x] != -1) {
      if (visit[x] != b) {
        no();
      } else {
        return;
      }
    }
    visit[x] = b;
    st[b].insert(x);
    for (int i = 0; i < n; ++i) {
      if (coGraph[x][i]) {
        dfs(i, !b, st);
      }
    }
  }
};
