  REP(i, 0, N) {
    ll c = color[i];
    if(c > 0) mp[c].first++;
    else mp[-c].second++;
  }

  vector<pll> vec;
  for(auto p : mp) vec.push_back(p.second);

  vector<vector<bool>> dp(vec.size() + 1, vector<bool>(N + 1));
  dp[0][0] = true;
  REP(i, 0, vec.size()) REP(j, 0, N) if(dp[i][j]) {
    if(j + vec[i].first <= N) dp[i + 1][j + vec[i].first] = true;
    if(j + vec[i].second <= N) dp[i + 1][j + vec[i].second] = true;
  }

  ll ans = 1LL << 50;
  REP(i, 0, N + 1) if(dp[vec.size()][i]) {
    ll s = i, t = N - i;
    ans = min(ans, M - s * t + cnt);
  }
  cout << ans << endl;
}

