void solve() {
	ll N,M;
	cin>>N>>M;
	vector<ll> A(M),B(M);
	set<pair<ll,ll>> s;
	rep(i,M){
		cin>>A[i]>>B[i];
		A[i]--;B[i]--;
		ll a=A[i],b=B[i];
		if(a>b)swap(a,b);
		s.insert({a,b});
	}

	vector<vector<ll>> g(N);
	rep(i,N)for(ll j=i+1;j<N;j++){
		if(s.count({i,j})==0){
			g[i].push_back(j);
			g[j].push_back(i);
		}
	}

	UnionFind uf(N);
	vector<ll> seen(N,0);
	vector<pair<ll,ll>> iro;
	rep(i,N){
		if(seen[i]==0){
			ll shiro=0,kuro=0;
			rep(i,N){
				if(seen[i]==1)shiro++;
				else if(seen[i]==-1)kuro++;
			}
			seen[i]=1;
			bool b=isBipartiteGraph(g,0,seen,uf);
			if(!b){
				p(-1);return;
			}
			ll shiroaf=0,kuroaf=0;
			rep(i,N){
				if(seen[i]==1)shiroaf++;
				else if(seen[i]==-1)kuroaf++;
			}
			iro.push_back({shiroaf-shiro, kuroaf-kuro});
		}
	}

	auto f = [](ll n, ll k){
		if(n<k)return ll(0);
		ll val(1);
		k=min(k,n-k);
		for(ll i=n;i>(n-k);i--)val*=i;
		for(ll i=k;i>1;i--)val/=i;
		return val;
	};

	rep(i,iro.size()){
		if(iro[i].first==0||iro[i].second==0)continue;
		ll a=iro[i].first;
		ll b=iro[i].second;
		if(a>b)swap(a,b);
		ll nokori=N-a-b;;
		if(b-a >= nokori){
			a+=nokori;
			ll t=f(a,2);
			ll s=f(b,2);
			p(t+s);return;
		}else{
			a=N/2;
			b=N-a;
			ll t=f(a,2);
			ll s=f(b,2);
			p(t+s);return;
		}

	}

}

