const int MAXN = 878;
int dp[MAXN][MAXN], G[MAXN][MAXN];
int tag[MAXN], cnt[2];
bool visit[MAXN];

bool dfs(int N, int cur, int tg) {
     visit[cur] = 1;
     tag[cur] = tg;
     cnt[tg]++;
     bool OK = true;
     for (int i = 1; i <= N; i++) {
         if (cur == i || G[cur][i]) continue;
         if (visit[i] && tg == tag[i]) OK = false;
         else if (!visit[i] && !dfs(N, i, tg ^ 1)) OK = false;
     }
     return OK;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    for (int i = 0; i < M; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        G[x][y] = 1;
        G[y][x] = 1;
    }
    int sum = 0, ans = M;
    dp[0][0] = 1;
    for (int i = 1; i <= N; i++) {
        if (!visit[i]) {
           sum++;
           cnt[1] = cnt[0] = 0;
           if (!dfs(N, i, 0)) ans = -1;
           for (int i = 0; i <= N; i++) {
               dp[sum][i] = dp[sum - 1][i];
               for (int j = 0; j < 2; j++) {
                   if (i >= cnt[j]) dp[sum][i] |= dp[sum - 1][i - cnt[j]];
               }
           }
        }
    }
    for (int i = 0; i <= N; i++) {
        if (dp[sum][i]) {
           ans = min(ans, (i * (i - 1) + (N - i) * (N - i - 1)) / 2);
        }
    }
    printf("%d\n", ans);
    return 0;
}

