typedef int32_t i32;

#define POS(i, j) ((i) * n + (j))

int dfs (i32 v, uint8_t *g, i32 n, uint8_t *c, i32 *cnt) {
  cnt[c[v]]++;
  for (i32 i = 0; i < n; ++i) {
    if (i == v || g[POS(v, i)]) continue;
    if (c[i] == 2) {
      c[i] = c[v] ^ 1;
      if (dfs (i, g, n, c, cnt)) return 1;
    }
    if (c[i] == c[v]) return 1;
  }
  return 0;
}

void run (void) {
  i32 n, m;
  scanf ("%" SCNi32 "%" SCNi32, &n, &m);
  uint8_t *mat = (uint8_t *) calloc (n * n, sizeof (uint8_t));
  while (m--) {
    i32 a, b;
    scanf ("%" SCNi32 "%" SCNi32, &a, &b);
    a--;
    b--;
    mat[POS(a, b)] = mat[POS(b, a)] = 1;
  }
  uint8_t *c = (uint8_t *) calloc (n, sizeof (uint8_t));
  for (i32 i = 0; i < n; ++i) {
    c[i] = 2;
  }
  i32 *a = (i32 *) calloc (n, sizeof (i32));
  i32 *b = (i32 *) calloc (n, sizeof (i32));
  i32 len = 0;
  for (i32 i = 0; i < n; ++i) {
    if (c[i] < 2) continue;
    c[i] = 0;
    i32 cnt[2] = {0, 0};
    if (dfs (i, mat, n, c, cnt)) {
      puts ("-1");
      return;
    }
    a[len] = cnt[0];
    b[len] = cnt[1];
    len++;
  }
  i32 *dp = (i32 *) calloc (n + 1, sizeof (i32));
  dp[0] = 1;
  for (i32 i = 0; i < len; ++i) {
    for (i32 j = n - 1; j >= 0; --j) {
      if (dp[j] == 0) continue;
      dp[j + a[i]] = dp[j + b[i]] = 1;
    }
  }
  i32 min = n * n;
  for (i32 i = 1; i < n; ++i) {
    i32 v = i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2;
    if (dp[i] && v < min) min = v;
  }
  printf ("%" PRIi32 "\n", min);
}

int main (void) {
  run();
  return 0;
}

