typedef struct List {
	struct List *next;
	int v;
} list;

int DFS(list** adj, int s, int flag[])
{
	int size = flag[s];
	list *p;
	for (p = adj[s]; p != NULL; p = p->next) {
		if (flag[p->v] == 0) {
			flag[p->v] = -flag[s];
			size += DFS(adj, p->v, flag);
		} else if (flag[p->v] == flag[s]) return -100000;
	}
	return size;
}

