void f(ll i,ll c){
	a[i]=c;
	if(c==1)cnta++;
	else cntb++;

	rep(j,0,n)if(!ee[i][j]){
		if(a[j]&&a[j]==c){
			puts("-1");
			exit(0);
		}
		if(!a[j])f(j,-c);
