int main()
{
	int i, u, w, N, M, adj[701][701] = {};
	scanf("%d %d", &N, &M);
	for (i = 1; i <= M; i++) {
		scanf("%d %d", &u, &w);
		adj[u][w] = 1;
		adj[w][u] = 1;
	}

	int k, flag[701] = {}, size[701], q[701], head, tail;
	for (i = 1, k = 0; i <= N; i++) {
		if (flag[i] != 0) continue;
		size[++k] = 1;
		flag[k] = k;
		q[0] = k;
		for (head = 0, tail = 1; head < tail; head++) {
			for (u = q[head], w = 1; w <= N; w++) {
				if (w != u && adj[u][w] == 0) {
					if (flag[w] == 0) {
						flag[w] = -flag[u];
						size[k] += flag[w] / k;
						q[tail++] = w;
					} else if (flag[w] == flag[u]) break;
				}
			}
			if (w <= N) break;
		}
		if (head < tail) break;
		size[k] = abs(size[k]);
	}
	if (i <= N) {
		printf("-1\n");
		fflush(stdout);
		return 0;
	}

	int j, dp[701][701] = {{1}};
	for (i = 1; i <= k; i++) {
		for (j = 0; j <= N - size[i]; j++) {
			dp[i][j+size[i]] |= dp[i-1][j];
			if (j >= size[i]) dp[i][j-size[i]] |= dp[i-1][j];
		}
	}

	for (j = 0; j <= N; j++) if (dp[k][j] == 1) break;
	printf("%d\n", ((N + j) * (N + j - 2) + (N - j) * (N - j - 2)) / 8);
	fflush(stdout);
	return 0;
}

