import java.io.*;
import java.util.*;

class Solver {
  final int n, m;
  final int[] as, bs;
  List<List<Integer>> complementEdgeMatrix;
  int[] group;

  Solver(int n, int m, int[] as, int[] bs) {
    this.n = n;
    this.m = m;
    this.as = as;
    this.bs = bs;
  }

  private boolean assignDfs(int index, int value) {
    if (group[index] == value) {
      return true;
    }
    if (group[index] != 0) {
      return false;
    }
    group[index] = value;
    for (int nextIndex : complementEdgeMatrix.get(index)) {
      if (!assignDfs(nextIndex, -value)) {
        return false;
      }
    }
    return true;
  }

  public int solve() {
    boolean[][] graph = new boolean[n + 1][n + 1];
    for (int i = 0; i < m; i++) {
      graph[as[i]][bs[i]] = true;
      graph[bs[i]][as[i]] = true;
    }

    complementEdgeMatrix = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      complementEdgeMatrix.add(new ArrayList<>());
    }
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= n; j++) {
        if (i != j && !graph[i][j]) {
          complementEdgeMatrix.get(i).add(j);
        }
      }
    }
    group = new int[n + 1];
    int groupIndex = 1;
    for (int i = 1; i <= n; i++) {
      if (group[i] != 0) {
        continue;
      }
      if (!assignDfs(i, groupIndex)) {
        return -1;
      }
      groupIndex++;
    }
    int[] positiveCount = new int[groupIndex];
    int[] negativeCount = new int[groupIndex];
    for (int i = 1; i <= n; i++) {
      if (group[i] > 0) {
        positiveCount[group[i]]++;
      } else {
        negativeCount[-group[i]]++;
      }
    }
    Set<Integer> possibleSize = new HashSet<>();
    possibleSize.add(0);
    for (int i = 1; i < groupIndex; i++) {
      Set<Integer> nextPossibleSize = new HashSet<>();
      for (int size : possibleSize) {
        nextPossibleSize.add(size + positiveCount[i]);
        nextPossibleSize.add(size + negativeCount[i]);
      }
      possibleSize = nextPossibleSize;
    }

    int answer = Integer.MAX_VALUE;
    for (int size : possibleSize) {
      int otherSize = n - size;
      int count = size * (size - 1) / 2 + otherSize * (otherSize - 1) / 2;
      answer = Math.min(answer, count);
    }
    return answer;
  }
}

