class ModCalculator {
  private final long mod;

  ModCalculator(long mod) {
    this.mod = mod;
  }

  public long add(long a, long b) {
    return (a + b) % mod;
  }

  public long sub(long a, long b) {
    return (a - b + mod) % mod;
  }

  public long mul(long a, long b) {
    return (a * b) % mod;
  }

  public long pow(long a, long b) {
    if (b == 0) {
      return 1;
    }
    long v = pow(mul(a, a), b / 2);
    if (b % 2 == 1) {
      return mul(v, a);
    } else {
      return v;
    }
  }

  public long inverse(long a) {
    return pow(a, mod - 2);
  }

  public long div(long a, long b) {
    return mul(a, inverse(b));
  }
}

class ModCombinationCache {
  private final ModCalculator modCalculator;
  private final List<Long> factorialCache;
  private final List<Long> factorialInverseCache;

  public ModCombinationCache(ModCalculator modCalculator) {
    this.modCalculator = modCalculator;
    factorialCache = new ArrayList<>();
    factorialCache.add(1L);
    factorialInverseCache = new ArrayList<>();
    factorialInverseCache.add(1L);
  }

  private void resize(int n) {
    for (int i = factorialCache.size() - 1; i < n; i++) {
      long v = modCalculator.mul(factorialCache.get(i), i + 1);
      factorialCache.add(v);
      factorialInverseCache.add(modCalculator.inverse(v));
    }
  }

  public long getP(int n) {
    resize(n);
    return factorialCache.get(n);
  }

  public long getC(int n, int k) {
    resize(n);
    return modCalculator.mul(factorialCache.get(n), modCalculator.mul(factorialInverseCache.get(k), factorialInverseCache.get(n-k)));
  }
}

class Algorithm {
  private static void swap(Object[] list, int a, int b) {
    Object tmp = list[a];
    list[a] = list[b];
    list[b] = tmp;
  }

  public static <T extends Comparable<? super T>> boolean nextPermutation(T[] ts) {
    int rightMostAscendingOrderIndex = ts.length - 2;
    while (rightMostAscendingOrderIndex >= 0 &&
        ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostAscendingOrderIndex + 1]) >= 0) {
      rightMostAscendingOrderIndex--;
    }
    if (rightMostAscendingOrderIndex < 0) {
      return false;
    }

    int rightMostGreatorIndex = ts.length - 1;
    while (ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostGreatorIndex]) >= 0) {
      rightMostGreatorIndex--;
    }

    swap(ts, rightMostAscendingOrderIndex, rightMostGreatorIndex);
    for (int i = 0; i < (ts.length - rightMostAscendingOrderIndex - 1) / 2; i++) {
      swap(ts, rightMostAscendingOrderIndex + 1 + i, ts.length - 1 - i);
    }
    return true;
  }

  public static void shuffle(int[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      int temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void shuffle(long[] array) {
    Random random = new Random();
    int n = array.length;
    for (int i = 0; i < n; i++) {
      int randomIndex = i + random.nextInt(n - i);

      long temp = array[i];
      array[i] = array[randomIndex];
      array[randomIndex] = temp;
    }
  }

  public static void sort(int[] array) {
    shuffle(array);
    Arrays.sort(array);
  }

  public static void sort(long[] array) {
    shuffle(array);
    Arrays.sort(array);
  }
}

class UnionFind {
  int[] parents;
  int[] ranks;

  UnionFind(int n) {
    parents = new int[n];
    ranks = new int[n];

    for (int i = 0; i < n; i++) {
      parents[i] = i;
    }
  }

  public int getRoot(int index) {
    if (parents[index] == index) {
      return index;
    } else {
      parents[index] = getRoot(parents[index]);
      return parents[index];
    }
  }

  public boolean sameGroup(int a, int b) {
    return getRoot(a) == getRoot(b);
  }

  public void merge(int a, int b) {
    int rootA = getRoot(a);
    int rootB = getRoot(b);
    if (rootA == rootB) {
      return;
    }
    if (ranks[rootA] < ranks[rootB]) {
      parents[rootA] = rootB;
    } else if (ranks[rootB] < ranks[rootA]) {
      parents[rootB] = rootA;
    } else {
      parents[rootA] = rootB;
      ranks[rootB]++;
    }
  }
}

import java.io.*;
import java.util.*;

public class Main {

    static int N, M;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        A = new int[M];
        B = new int[M];
        for (int i = 0; i < M; i++) {
            A[i] = sc.nextInt() - 1;
            B[i] = sc.nextInt() - 1;
        }

        System.out.println(solve());
    }

    static int solve() {
        int[][] G = adjB(N, A, B);
        int[][] H = complement(N, G);

        if( !isBipartite(N, H)) return -1;

        List<int[]> components = calcComponents(H);

        boolean[][] dp = new boolean[components.size()+1][N+1];
        dp[0][0] = true;

        for (int i = 0; i < components.size(); i++) {
            int[] comp = components.get(i);
            for (int j = N-1; j >= 0; j--) {
                if( dp[i][j] ) {
                    dp[i+1][j+comp[0]] = true;
                    dp[i+1][j+comp[1]] = true;
                }
            }
        }

        int ans = Integer.MAX_VALUE;
        for (int s = 0; s <= N; s++) {
            if( dp[components.size()][s] ) {
                int t = N-s;
                ans = Math.min(perfect(s) + perfect(t), ans);
            }
        }
        return ans;
    }

    static int perfect(int n) {
        return n * (n-1) / 2;
    }

    // 連結成分てどうやってだすのが正しいのか
    static List<int[]> calcComponents(int[][] H) {
        int[] flag = new int[N];
        List<int[]> components = new ArrayList<>();

        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < N; i++) {
            if( flag[i] != 0 ) continue;

            int s = 1, t = 0;
            flag[i] = 1;
            q.add(i);

            while( !q.isEmpty() ) {
                int a = q.poll();

                for (int next : H[a]) {
                    if( flag[next] == 0 ) {
                        flag[next] = -flag[a];
                        if( flag[next] == 1 ) {
                            s++;
                        } else {
                            t++;
                        }
                        q.add(next);
                    }
                }
            }
            components.add(new int[]{s, t});
        }

        return components;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    // どうなんでしょう
    static int[][] complement(int n, int[][] G) {
        int[][] H = new int[N][];
        for (int i = 0; i < N; i++) {
            int[] row = new int[N];
            for (int j : G[i]) {
                row[j] = 1;
            }
            int len = N - G[i].length - 1;
            int[] arr = new int[len];
            for (int j = 0; j < N; j++) {
                if( i == j ) continue;
                if( row[j] == 0 ) {
                    arr[--len] = j;
                }
            }
            H[i] = arr;
        }
        return H;
    }

    static boolean isBipartite(int V, int[][] G) {
        int[] C = new int[V];
        for (int v = 0; v < V; v++) {
            if( C[v] == 0 ) {
                if( !_isBipartite(v, 1, C, G) ) {
                    return false;
                }
            }
        }
        return true;
    }

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    static boolean _isBipartite(int v, int c, int[] C, int[][] G) {
        C[v] = c;

        for (int next : G[v]) {
            if( C[next] == c ) return false;
            if( C[next] == 0 && !_isBipartite(next, -c, C, G) ) return false;
        }
        return true;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
