				col[i]=0;
				pair p=color(i);
				if(p.S>=inf)
				{
					System.out.println(-1);
					return;
				}
				pairs.add(p);
				for(int j=0;j<=n;j++)
					if(reachable[cc-1][j])
						reachable[cc][j+p.S]=reachable[cc][j+p.T]=true;
				cc++;

			}
		cc--;
		long ans=n*1L*(n-1);
		for(int i=0;i<=n;i++)
			if(reachable[cc][i])
			{
				long A=i,B=n-i;
				ans=Math.min(ans, A*(A-1)+B*(B-1));
			}
		pw.println(ans/2);




		pw.close();

	}
