    static class arc099_c {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int m = in.nextInt();

            List[] g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList();
            }

            int[] u = new int[m];
            int[] v = new int[m];

            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;

                u[i] = a;
                v[i] = b;

                g[a].add(b);
                g[b].add(a);
            }

            int midDver = -1;
            int midD = 100000;

            for (int i = 0; i < n; i++) {
                if (g[i].size() < midD) {
                    midD = g[i].size();
                    midDver = i;
                }
            }

            Set<Integer> s = new HashSet<>();

            s.add(midDver);

            for (int ver : (List<Integer>) g[midDver]) {
                s.add(ver);
            }

            while (s.size() > 0) {
                int crossEdge = 0;
                int sub1Edge = 0;
                int sub2Edge = 0;

                int sub1Size = s.size();
                int sub2Size = n - sub1Size;
                int[] sub1Edges = new int[n];
                for (int i = 0; i < m; i++) {
                    if (s.contains(u[i]) && s.contains(v[i])) {
                        sub1Edge++;
                        sub1Edges[u[i]]++;
                        sub1Edges[v[i]]++;
                    } else if (s.contains(u[i])) {
                        crossEdge++;
                    } else if (s.contains(v[i])) {
                        crossEdge++;
                    } else {
                        sub2Edge++;
                    }
                }


                int clique1 = (sub1Size * (sub1Size - 1)) / 2;
                int clique2 = (sub2Size * (sub2Size - 1)) / 2;

                if (clique1 == sub1Edge && clique2 == sub2Edge) {
                    out.println(clique1 + clique2);
                    return;
                }

                int minDver = -1;
                int minD = 10000;

                for (int i = 0; i < n; i++) {
                    if (s.contains(i) && sub1Edges[i] < minD &&
                            sub1Edges[i] + sub2Size == g[i].size()) {
                        minD = sub1Edges[i];
                        minDver = i;
                    }
                }

                if (minDver == -1) {
                    out.println(-1);
                    return;
                }

                s.remove(minDver);
            }

            out.println(-1);
        }

    }

