import java.lang.reflect.Array;
import java.util.*;

public class Main {
    TreeSet<Integer> g[];
    int n;
    int lvl[];

    boolean isT(int v) {
        for (int u : g[v]) {
            if (lvl[u] == -1) {
                lvl[u] = lvl[v] + 1;
                if (!isT(u)) return false;
            } else if ((lvl[u] - lvl[v]) % 2 == 0) {
                return false;
            }
        }
        return true;
    }

    int cnt = 0, cur = 0;

    void dfs(int v) {
        for (int u : g[v]) {
            if (lvl[u] == -1) {
                lvl[u] = lvl[v] + 1;
                cnt++;
                if (lvl[u] % 2 == 0) cur++;
                dfs(u);
            }
        }
    }

    int a[][];

    public void solve() throws IOException {
        n = nextInt();
        int m = nextInt();
        g = new TreeSet[n];
        lvl = new int[n];
        Arrays.fill(lvl, -1);
        for (int i = 0; i < n; i++) {
            g[i] = new TreeSet<>();
            for (int j = 0; j < n; j++) {
                if(i == j) continue;
                g[i].add(j);
            }
        }
        for (int i = 0; i < m; i++) {
            int x = nextInt() - 1, y = nextInt() - 1;
            g[x].remove(y);
            g[y].remove(x);
        }
        for (int i = 0; i < n; i++) {
            if (lvl[i] == -1) {
                lvl[i] = 0;
                if (!isT(i)) {
                    out.print(-1);
                    return;
                }
            }
        }
        Arrays.fill(lvl, -1);
        ArrayList<Integer> arr = new ArrayList<>();
        int sum = 0;
        for (int i = 0; i < n; i++) {
            if (lvl[i] == -1) {
                cnt = 1;
                cur = 1;
                lvl[i] = 0;
                dfs(i);
                arr.add(Math.abs(cnt - 2 * cur));
                sum += Math.abs(cnt - 2 * cur);
            }
        }
        Collections.sort(arr);

        int dp[][] = new int[sum / 2 + 1][arr.size() + 1];
        for (int j = 1; j <= arr.size(); j++) {
            for (int w = 1; w <= sum / 2; w++) {
                if (arr.get(j - 1) <= w) {
                    dp[w][j] = Math.max(dp[w][j - 1], dp[w - arr.get(j - 1)][j - 1] + 1);
                } else {
                    dp[w][j] = dp[w][j - 1];
                }
            }
        }

        long ans = dp[sum / 2][arr.size()];
        long d = Math.abs(sum - 2 * ans);
        long a = (n - d) / 2;
        long b = a + d;
        out.print(a * (a - 1) / 2 + b * (b - 1) / 2);
    }

    BufferedReader br;
    StringTokenizer sc;
    PrintWriter out;

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        new Main().run();
    }

    public void run() throws IOException {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    public String nextToken() throws IOException {
        while (sc == null || !sc.hasMoreTokens()) {
            try {
                sc = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                return null;
            }
        }
        return sc.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }
}

import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;


public class Main {

	public static Scanner scanner = new Scanner(System.in);
	public static void main(String[] args) {
		int n = scanner.nextInt();
		int m = scanner.nextInt();

		Graph g = new Graph(n);

		for(int i=0; i<m; i++) {
			int a = scanner.nextInt() - 1;
			int b = scanner.nextInt() - 1;
			g.addEdge(a, b);
		}
		int island = g.countIsland();
		if(island == 1) {
			System.out.println(m - 1);
		} else if(island == 2) {
			System.out.println(m);
		} else if(island > 2) {
			System.out.println(-1);
		}
//		g.bridge();
	}
	// This class represents a undirected graph using adjacency list
	// representation
	static class Graph
	{
	    private int V;   // No. of vertices

	    // Array  of lists for Adjacency List Representation
	    private LinkedList<Integer> adj[];
	    int time = 0;
	    static final int NIL = -1;

	    // Constructor
	    Graph(int v)
	    {
	        V = v;
	        adj = new LinkedList[v];
	        for (int i=0; i<v; ++i)
	            adj[i] = new LinkedList();
	    }


		public void dfs(int from, boolean[] visited) {
			Stack<Integer> nodeStack = new Stack<Integer>();
			nodeStack.add(from);
			visited[from] = true;

			while(!nodeStack.isEmpty()) {
				Integer node = nodeStack.pop();
				List<Integer>adjacentEdgeList = adj[node];
				for(Integer adjacentEdge : adjacentEdgeList) {
					if(!visited[adjacentEdge]) {
						nodeStack.add(adjacentEdge);
						visited[adjacentEdge] = true;
					}
				}
			}
		}


		public int countIsland() {
			int count = 0;
			boolean[] visited = new boolean[V];
			for(int i=0; i<visited.length; i++) {
				if(!visited[i]) {
					this.dfs(i, visited);
					count++;
				}
			}
			return count;
		}



	    // Function to add an edge into the graph
	    void addEdge(int v, int w)
	    {
	        adj[v].add(w);  // Add w to v's list.
	        adj[w].add(v);    //Add v to w's list
	    }

	    // A recursive function that finds and prints bridges
	    // using DFS traversal
	    // u --> The vertex to be visited next
	    // visited[] --> keeps tract of visited vertices
	    // disc[] --> Stores discovery times of visited vertices
	    // parent[] --> Stores parent vertices in DFS tree
	    void bridgeUtil(int u, boolean visited[], int disc[],
	                    int low[], int parent[])
	    {

	        // Count of children in DFS Tree
	        int children = 0;

	        // Mark the current node as visited
	        visited[u] = true;

	        // Initialize discovery time and low value
	        disc[u] = low[u] = ++time;

	        // Go through all vertices aadjacent to this
	        Iterator<Integer> i = adj[u].iterator();
	        while (i.hasNext())
	        {
	            int v = i.next();  // v is current adjacent of u

	            // If v is not visited yet, then make it a child
	            // of u in DFS tree and recur for it.
	            // If v is not visited yet, then recur for it
	            if (!visited[v])
	            {
	                parent[v] = u;
	                bridgeUtil(v, visited, disc, low, parent);

	                // Check if the subtree rooted with v has a
	                // connection to one of the ancestors of u
	                low[u]  = Math.min(low[u], low[v]);

	                // If the lowest vertex reachable from subtree
	                // under v is below u in DFS tree, then u-v is
	                // a bridge
	                if (low[v] > disc[u])
	                    System.out.println(u+" "+v);
	            }

	            // Update low value of u for parent function calls.
	            else if (v != parent[u])
	                low[u]  = Math.min(low[u], disc[v]);
	        }
	    }


	    // DFS based function to find all bridges. It uses recursive
	    // function bridgeUtil()
	    void bridge()
	    {
	        // Mark all the vertices as not visited
	        boolean visited[] = new boolean[V];
	        int disc[] = new int[V];
	        int low[] = new int[V];
	        int parent[] = new int[V];


	        // Initialize parent and visited, and ap(articulation point)
	        // arrays
	        for (int i = 0; i < V; i++)
	        {
	            parent[i] = NIL;
	            visited[i] = false;
	        }

	        // Call the recursive helper function to find Bridges
	        // in DFS tree rooted with vertex 'i'
	        for (int i = 0; i < V; i++)
	            if (visited[i] == false)
	                bridgeUtil(i, visited, disc, low, parent);
	    }

	}
}

