/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        arc099_c solver = new arc099_c();
        solver.solve(1, in, out);
        out.close();
    }

    static class arc099_c {
        int inf = 100000000;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int m = in.nextInt();

            List[] g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList();
            }

            int[] u = new int[m];
            int[] v = new int[m];

            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;

                u[i] = a;
                v[i] = b;

                g[a].add(b);
                g[b].add(a);
            }

            int midDver = -1;
            int midD = 100000;

            for (int i = 0; i < n; i++) {
                if (g[i].size() < midD) {
                    midD = g[i].size();
                    midDver = i;
                }
            }

            Set<Integer> s = new HashSet<>();

            s.add(midDver);

            for (int ver : (List<Integer>) g[midDver]) {
                s.add(ver);
            }

            int ans = inf;

            while (s.size() > 0) {
                int crossEdge = 0;
                int sub1Edge = 0;
                int sub2Edge = 0;

                int sub1Size = s.size();
                int sub2Size = n - sub1Size;
                int[] sub1Edges = new int[n];
                for (int i = 0; i < m; i++) {
                    if (s.contains(u[i]) && s.contains(v[i])) {
                        sub1Edge++;
                        sub1Edges[u[i]]++;
                        sub1Edges[v[i]]++;
                    } else if (s.contains(u[i])) {
                        crossEdge++;
                    } else if (s.contains(v[i])) {
                        crossEdge++;
                    } else {
                        sub2Edge++;
                    }
                }


                int clique1 = (sub1Size * (sub1Size - 1)) / 2;
                int clique2 = (sub2Size * (sub2Size - 1)) / 2;

                if (clique1 == sub1Edge && clique2 == sub2Edge) {
                    //out.println(clique1 + clique2);
                    ans = Math.min(ans, clique1 + clique2);
                }

                int minDver = -1;
                int minD = 10000;

                for (int i = 0; i < n; i++) {
                    if (s.contains(i) && sub1Edges[i] < minD &&
                            sub1Edges[i] + sub2Size == g[i].size()) {
                        minD = sub1Edges[i];
                        minDver = i;
                    }
                }

                if (minDver == -1) {
                    if (ans == inf)
                        out.println(-1);
                    else
                        out.println(ans);
                    return;
                }

                s.remove(minDver);
            }

            if (ans == inf)
                out.println(-1);
            else
                out.println(ans);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;


public class Main {
    static final int UNCALC = -1;
    static final int INF = (int) 1e9;
    static ArrayList<Integer> adjList[];
    static int[] color;
    static int n, m, wb[];
    static ArrayList<Integer> one, two;
    static boolean poss;
    static int memo[][];
    static int[] cum;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        n = sc.nextInt();
        int e = sc.nextInt();
        boolean[][] edges = new boolean[n][n];
        while (e-- > 0) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            edges[u][v] = true;
            edges[v][u] = true;
        }
        adjList = new ArrayList[n];
        for (int i = 0; i < n; i++)
            adjList[i] = new ArrayList<>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i != j && !edges[i][j])
                    adjList[i].add(j);
        solve();
        m = one.size();
        cum = new int[m + 1];
        for (int i = 1; i <= m; i++)
            cum[i] = one.get(i - 1) + two.get(i - 1) + cum[i - 1];
        memo = new int[m][n + 1];
        for (int[] b : memo)
            Arrays.fill(b, UNCALC);
        out.println(poss ? dp(0, 0) : -1);
        out.flush();
        out.close();
    }

    static void solve() {
        color = new int[n];
        poss = true;
        Arrays.fill(color, UNCALC);
        one = new ArrayList<>();
        two = new ArrayList<>();
        for (int i = 0; i < n && poss; i++) {
            if (color[i] != UNCALC) continue;
            wb = new int[2];
            wb[0]++;
            color[i] = 0;
            poss = bipartiteCheck(i);
            one.add(wb[0]);
            two.add(wb[1]);
        }
    }

    static int dp(int idx, int taka) {
        int hashi = cum[idx] - taka;
        if (idx == one.size()) return calc(taka) + calc(hashi);
        if (memo[idx][taka] != UNCALC)
            return memo[idx][taka];
        int a = one.get(idx);
        int b = two.get(idx);
        return memo[idx][taka] = Math.min(dp(idx + 1, taka + a), dp(idx + 1, taka + b));
    }

    static int calc(int x) {
        return x * (x - 1) / 2;
    }


    static boolean bipartiteCheck(int u) {
        for (int v : adjList[u]) {
            if (color[v] == UNCALC) {
                color[v] = 1 - color[u];
                wb[color[v]]++;
                if (!bipartiteCheck(v)) return false;
            } else if (color[u] == color[v]) return false;
        }
        return true;
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream system) {
            br = new BufferedReader(new InputStreamReader(system));
        }

        public Scanner(String file) throws Exception {
            br = new BufferedReader(new FileReader(file));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }

        public Long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public void waitForInput() throws InterruptedException {
            Thread.sleep(3000);
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

    }
}

