/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        C solver = new C();
        solver.solve(1, in, out);
        out.close();
    }

    static class C {
        static boolean fail = false;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            boolean[][] g = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int x = in.readInt() - 1;
                int y = in.readInt() - 1;
                g[x][y] = g[y][x] = true;
            }
            if (m == n * (n - 1) / 2) {
                int cnt1 = n / 2;
                int cnt2 = n - cnt1;
                System.err.println(cnt1 + " " + cnt2);
                out.printLine(cnt1 * (cnt1 - 1) / 2 + cnt2 * (cnt2 - 1) / 2);
                return;
            }
            boolean[] vis = new boolean[n];
            List<List<Integer>> comps = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (!vis[i]) {
                    List<Integer> comp = new ArrayList<>();
                    dfs0(i, vis, n, g, comp);
                    comps.add(comp);
                }
            }
            if (comps.size() > 2) {
                out.printLine(-1);
                return;
            }
            int[] color = new int[n];
            List<Integer> c0, c1;
            if (comps.size() == 2) {
                c0 = comps.get(0);
                c1 = comps.get(1);
                if (!isClique(c0, g) || !isClique(c1, g)) {
                    out.printLine(-1);
                    return;
                }
                for (int i : c0) color[i] = 0;
                for (int i : c1) color[i] = 1;
            } else {
                Arrays.fill(color, -1);
                for (int i = 0; i < n; i++) {
                    if (color[i] == -1) {
                        dfs(i, color, n, g, 0);
                    }
                }
                if (fail) {
                    out.printLine(-1);
                    return;
                }
                c0 = new ArrayList<>();
                c1 = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (color[i] == 0) {
                        c0.add(i);
                    } else if (color[i] == 1) {
                        c1.add(i);
                    } else {
                        throw new AssertionError();
                    }
                }
                if (!isClique(c0, g) || !isClique(c1, g)) {
                    out.printLine(-1);
                    return;
                }
            }
            System.err.println("c0 = " + c0);
            System.err.println("c1 = " + c1);
            int ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (color[i] != color[j]) {
                        if (g[i][j]) {
                            ans++;
                        }
                    }
                }
            }
            out.printLine(m - ans);
        }

        private boolean isClique(List<Integer> list, boolean[][] g) {
            for (int i : list) {
                for (int j : list) {
                    if (i != j) {
                        if (!g[i][j]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private void dfs0(int x, boolean[] vis, int n, boolean[][] g, List<Integer> comp) {
            comp.add(x);
            vis[x] = true;
            for (int y = 0; y < n; y++) {
                if (x == y) {
                    continue;
                }
                if (g[x][y]) {
                    if (!vis[y]) {
                        dfs0(y, vis, n, g, comp);
                    }
                }
            }
        }

        private void dfs(int x, int[] color, int n, boolean[][] g, int curColor) {
            color[x] = curColor;
            for (int y = 0; y < n; y++) {
                if (x == y) {
                    continue;
                }
                if (!g[x][y]) {
                    if (color[y] == -1) {
                        dfs(y, color, n, g, 1 - curColor);
                    }
                    if (color[y] == color[x]) {
                        fail = true;
                    }
                }
            }
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Main {
  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    Set<Integer> con = new HashSet<>();
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
      con.add(from[i] * 1000 + to[i]);
      con.add(to[i] * 1000 + from[i]);
    }
    int[][] g = packU(n, from, to);
    boolean[] all = new boolean[n];
    int allCount = 0;
    for (int i = 0; i < n; i++) {
      all[i] = g[i].length == n - 1;
      if (all[i]) {
        allCount ++;
      }
    }

    List<Integer> ok = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      boolean[] color = new boolean[n];
      color(i, color, g, all, con);

      if (check(color, g)) {
        int cnt = 0;
        for (int j = 0; j < n; j ++) {
          if (color[j]) {
            cnt ++;
          }
        }
        ok.add(cnt);
      }
    }
    if (ok.size() == 0) {
      System.out.println(-1);
      return;
    }

    // edgeの数
    int min = Integer.MAX_VALUE;
    for (int x : ok) {
      int s = x;
      int e = x + allCount;
      for (int i = s; i <= e; i ++) {
        int n1 = i;
        int n2 = n - i;
        min = Math.min(n1 * (n1 - 1) / 2 + n2 * (n2 - 1)  /2, min);
      }
    }
    System.out.println(min);
  }

  private static boolean check(boolean[] used, int[][] g) {
    int n = used.length;
    int m = 0;
    int edges = 0;
    for (int i = 0; i < n; i++) {
      if (!used[i]) {
        m++;
        for (int v : g[i]) {
          if (!used[v]) {
            edges++;
          }
        }
      }
    }
    return edges == m * (m - 1);
  }


  private static void color(int now, boolean[] color, int[][] g, boolean[] all, Set<Integer> con) {
    color[now] = true;
    int n = g.length;
    outer: for (int next : g[now]) {
      for (int i = 0; i < n; i ++) {
        if (color[i]) {
          if (!con.contains(next * 1000 + i)) { 
            continue outer;
          }
        }
      }
      if (all[next])
        continue;

      color(next, color, g, all, con);
    }
  }

  public static int[][] packU(int n, int[] from, int[] to) {
    return packU(n, from, to, from.length);
  }

  public static int[][] packU(int n, int[] from, int[] to, int sup) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int i = 0; i < sup; i++)
      p[from[i]]++;
    for (int i = 0; i < sup; i++)
      p[to[i]]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < sup; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

  private static java.io.InputStream is = System.in;
  private static java.io.PrintWriter out = new java.io.PrintWriter(System.out);
  private static java.util.StringTokenizer tokenizer = null;
  private static java.io.BufferedReader reader;

  public static String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  private static double nd() {
    return Double.parseDouble(next());
  }

  private static long nl() {
    return Long.parseLong(next());
  }

  private static int[] na(int n) {
    int[] a = new int[n];
    for (int i = 0; i < n; i++)
      a[i] = ni();
    return a;
  }

  private static char[] ns() {
    return next().toCharArray();
  }

  private static long[] nal(int n) {
    long[] a = new long[n];
    for (int i = 0; i < n; i++)
      a[i] = nl();
    return a;
  }

  private static int[][] ntable(int n, int m) {
    int[][] table = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[i][j] = ni();
      }
    }
    return table;
  }

  private static int[][] nlist(int n, int m) {
    int[][] table = new int[m][n];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        table[j][i] = ni();
      }
    }
    return table;
  }

  private static int ni() {
    return Integer.parseInt(next());
  }

  private static void tr(Object... o) {
    if (is != System.in)
      System.out.println(java.util.Arrays.deepToString(o));
  }
}

