					add = false;
					break;
				}
			}
			if(add){
				taka.remove(i);
				takahasies++;
			}
		}

		int takas = taka.size();
		int ans = Integer.MAX_VALUE;
		for(int i=0;i<=takahasies;++i){
			int a = takas+i;
			int b = N-a;
