public class Main implements Runnable {
	public static void main(String[] args) throws FileNotFoundException {
		new Thread(null, new Main(), "", Runtime.getRuntime().maxMemory()).run();
	}

	int N, M;
	int[] A, B;
	int[] col;
	int[][] cnt;
	ArrayList<Integer>[] g;

	public void run() {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		M = sc.nextInt();
		A = new int[M];
		B = new int[M];
		col = new int[N];
		g = new ArrayList[N];
		boolean[][] connect = new boolean[N][N];
		cnt = new int[N][2];
		for (int i = 0; i < N; ++i)
			g[i] = new ArrayList<>();
		Arrays.fill(col, -1);
		for (int i = 0; i < M; ++i) {
			A[i] = sc.nextInt();
			B[i] = sc.nextInt();
			--A[i];
			--B[i];
			connect[A[i]][B[i]] = true;
			connect[B[i]][A[i]] = true;
		}
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j < N; ++j) {
				if (i != j && !connect[i][j]) {
					g[i].add(j);
				}
			}
		}
		for (int i = 0; i < N; ++i) {
			if (col[i] == -1) {
				col[i] = 0;
				dfs(i, -1);
				++p;
			}
		}

		boolean[][] ok = new boolean[1000][1000];
		ok[0][0] = true;
		for (int i = 0; i + 1 <= N; ++i) {
			for (int j = 0; j < 1000; ++j) {
				if (ok[i][j]) {
					if (ok[i + 1].length > j + cnt[i][0])
						ok[i + 1][j + cnt[i][0]] = ok[i][j];
					if (ok[i + 1].length > j + cnt[i][1])
						ok[i + 1][j + cnt[i][1]] = ok[i][j];
				}
			}
		}

		long ans = Long.MAX_VALUE / 3;
		for (int i = 0; i < ok[p].length; ++i) {
			if (ok[p][i]) {
				ans = Math.min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
			}
		}
		System.out.println(ans);
	}

	int p = 0;

	void dfs(int cur, int par) {
		cnt[p][col[cur]]++;
		for (int dst : g[cur]) {
			if (dst == par)
				continue;
			if (col[dst] == -1) {
				col[dst] = col[cur] ^ 1;
				dfs(dst, cur);
			} else {
				if (col[dst] != (col[cur] ^ 1)) {
					System.out.println(-1);
					System.exit(-1);
				}
			}
		}
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static java.lang.Math.max;
import static java.util.Collections.*;

public class Main {
    BufferedReader rd;

    Main() throws IOException {
        rd = new BufferedReader(new InputStreamReader(System.in));
        compute();
    }

    private void compute() throws IOException {
        int[] nm = intarr();
        int n = nm[0];
        int m = nm[1];
        List<Set<Integer>> edges = new ArrayList<>();
        for(int i=0;i<n;i++) {
            edges.add(new HashSet<>());
        }
        for(int i=0;i<m;i++) {
            int[] a = intarr();
            a[0]--;
            a[1]--;
            edges.get(a[0]).add(a[1]);
            edges.get(a[1]).add(a[0]);
        }

        int maxCross = -1;
        if(n <= 10) {
            int[] ix = new int[n];
            int s = 1<<n;
            for(int k=0;k<s;k++) {
                int left = k*2;
                int right = left+1;
                for(int j=0;j<n;j++) {
                    ix[j] = (k&(1<<j))>0?left:right;
                }
                boolean ok = true;
                outer: for(int z=left;z<=right;z++) {
                    for (int a = 0; a < n; a++) {
                        if(ix[a] == z) {
                            for (int b = 0; b < n; b++) {
                                if(a != b && ix[b] == z) {
                                    if(!edges.get(a).contains(b)) {
                                        ok = false;
                                        break outer;
                                    }
                                }
                            }
                        }
                    }
                }
                if(ok) {
                    int cross = 0;
                    for(int a=0;a<n;a++) {
                        for(int b=0;b<n;b++) {
                            if(a < b && ix[a] != ix[b] && edges.get(a).contains(b)) {
                                cross++;
                            }
                        }
                    }
                    maxCross = max(maxCross, cross);
                }
            }
        } else {
            Set<Integer> w2 = new HashSet<>();
            w2.add(0);
            w2.add(1);
            w2.add(n/2);
            w2.add(n-1);
            w2.add(n);
            for(Integer w: w2) {
                Set<Integer> clique0 = attain(w, n, edges, emptySet());
                if (clique0.size() == n) {
                    maxCross = 0;
                    break;
                } else {
                    int nextFree = -1;
                    for (int i = 0; i < n; i++) {
                        if (!clique0.contains(i)) {
                            nextFree = i;
                            break;
                        }
                    }
                    Set<Integer> nextClique = attain(nextFree, n, edges, clique0);
                    if (clique0.size() + nextClique.size() == n) {
                        int cross = computeCross(clique0, n, edges);
                        maxCross = max(maxCross, cross);
                    }
                }
            }
        }
        out(maxCross == -1 ? -1 : (m - maxCross));
    }

    private int computeCross(Set<Integer> c1, int n, List<Set<Integer>> edges) {
        int cross = 0;
        for(int a=0;a<n;a++) {
            for(int b=0;b<n;b++) {
                if(a < b && c1.contains(a) != c1.contains(b) && edges.get(a).contains(b)) {
                    cross++;
                }
            }
        }
        return cross;
    }

    private Set<Integer> attain(int start, int n, List<Set<Integer>> edges, Set<Integer> other) {
        Set<Integer> res = new HashSet<>();
        res.add(start);
        for(int i=0;i<n;i++) {
            if(i != start && !other.contains(i)) {
                boolean ok = true;
                for(Integer v: res) {
                    if(!edges.get(i).contains(v)) {
                        ok = false;
                        break;
                    }
                }
                if(ok) {
                    res.add(i);
                }
            }
        }
        return res;
    }

    private int[] intarr() throws IOException {
        return intarr(rd.readLine());
    }

    private int[] intarr(String s) {
        String[] q = split(s);
        int n = q.length;
        int[] a = new int[n];
        for(int i=0;i<n;i++) {
            a[i] = Integer.parseInt(q[i]);
        }
        return a;
    }

    private String[] split(String s) {
        if(s == null) {
            return new String[0];
        }
        int n = s.length();
        int start = -1;
        int end = 0;
        int sp = 0;
        boolean lastWhitespace = true;
        for(int i=0;i<n;i++) {
            char c = s.charAt(i);
            if(isWhitespace(c)) {
                lastWhitespace = true;
            } else {
                if(lastWhitespace) {
                    sp++;
                }
                if(start == -1) {
                    start = i;
                }
                end = i;
                lastWhitespace = false;
            }
        }
        if(start == -1) {
            return new String[0];
        }
        String[] res = new String[sp];
        int last = start;
        int x = 0;
        lastWhitespace = true;
        for(int i=start;i<=end;i++) {
            char c = s.charAt(i);
            boolean w = isWhitespace(c);
            if(w && !lastWhitespace) {
                res[x++] = s.substring(last,i);
            } else if(!w && lastWhitespace) {
                last = i;
            }
            lastWhitespace = w;
        }
        res[x] = s.substring(last,end+1);
        return res;
    }

    private boolean isWhitespace(char c) {
        return c==' ' || c=='\t';
    }

    private static void out(Object x) {
        System.out.println(x);
    }

    public static void main(String[] args) throws IOException {
        new Main();
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;


public class Main {
    static final int UNCALC = -1;
    static final int INF = (int) 1e9;
    static ArrayList<Integer> adjList[];
    static int[] color;
    static int n, wb[];
    static ArrayList<Integer> one, two;
    static boolean poss;
    static int memo[][][];

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        n = sc.nextInt();
        int m = sc.nextInt();
        boolean[][] edges = new boolean[n][n];
        while (m-- > 0) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            edges[u][v] = true;
            edges[v][u] = true;
        }
        adjList = new ArrayList[n];
        for (int i = 0; i < n; i++)
            adjList[i] = new ArrayList<>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i != j && !edges[i][j])
                    adjList[i].add(j);
        solve();
        memo = new int[one.size()][n + 1][n + 1];
        for (int[][] a : memo)
            for (int[] b : a)
                Arrays.fill(b, UNCALC);
        out.println(poss ? dp(0, 0, 0) : -1);
        out.flush();
        out.close();
    }

    static void solve() {
        color = new int[n];
        poss = true;
        Arrays.fill(color, UNCALC);
        one = new ArrayList<>();
        two = new ArrayList<>();
        for (int i = 0; i < n && poss; i++) {
            if (color[i] != UNCALC) continue;
            wb = new int[2];
            wb[0]++;
            color[i] = 0;
            poss = bipartiteCheck(i);
            one.add(wb[0]);
            two.add(wb[1]);
        }
    }

    static int dp(int idx, int taka, int hashi) {
        if (idx == one.size()) return calc(taka) + calc(hashi);
        if (memo[idx][taka][hashi] != UNCALC)
            return memo[idx][taka][hashi];
        int a = one.get(idx);
        int b = two.get(idx);
        return memo[idx][taka][hashi] = Math.min(dp(idx + 1, taka + a, hashi + b), dp(idx + 1, taka + b, hashi + a));
    }

    static int calc(int x) {
        return x * (x - 1) / 2;
    }


    static boolean bipartiteCheck(int u) {
        for (int v : adjList[u]) {
            if (color[v] == UNCALC) {
                color[v] = 1 - color[u];
                wb[color[v]]++;
                if (!bipartiteCheck(v)) return false;
            } else if (color[u] == color[v]) return false;
        }
        return true;
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream system) {
            br = new BufferedReader(new InputStreamReader(system));
        }

        public Scanner(String file) throws Exception {
            br = new BufferedReader(new FileReader(file));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }

        public Long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public void waitForInput() throws InterruptedException {
            Thread.sleep(3000);
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

    }
}

