/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        C solver = new C();
        solver.solve(1, in, out);
        out.close();
    }

    static class C {
        static boolean fail = false;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            boolean[][] g = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int x = in.readInt() - 1;
                int y = in.readInt() - 1;
                g[x][y] = g[y][x] = true;
            }
            if (m == n * (n - 1) / 2) {
                out.printLine(m);
                return;
            }
            boolean[] vis = new boolean[n];
            List<List<Integer>> comps = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (!vis[i]) {
                    List<Integer> comp = new ArrayList<>();
                    dfs0(i, vis, n, g, comp);
                    comps.add(comp);
                }
            }
            if (comps.size() > 2) {
                out.printLine(-1);
                return;
            }
            int[] color = new int[n];
            List<Integer> c0, c1;
            if (comps.size() == 2) {
                c0 = comps.get(0);
                c1 = comps.get(1);
                if (!isClique(c0, g) || !isClique(c1, g)) {
                    out.printLine(-1);
                    return;
                }
                for (int i : c0) color[i] = 0;
                for (int i : c1) color[i] = 1;
            } else {
                Arrays.fill(color, -1);
                for (int i = 0; i < n; i++) {
                    if (color[i] == -1) {
                        dfs(i, color, n, g, 0);
                    }
                }
                if (fail) {
                    out.printLine(-1);
                    return;
                }
                c0 = new ArrayList<>();
                c1 = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (color[i] == 0) {
                        c0.add(i);
                    } else if (color[i] == 1) {
                        c1.add(i);
                    } else {
                        throw new AssertionError();
                    }
                }
                if (!isClique(c0, g) || !isClique(c1, g)) {
                    out.printLine(-1);
                    return;
                }
            }
            System.err.println("c0 = " + c0);
            System.err.println("c1 = " + c1);
            int ans = 0;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (color[i] != color[j]) {
                        if (g[i][j]) {
                            ans++;
                        }
                    }
                }
            }
            out.printLine(m - ans);
        }

        private boolean isClique(List<Integer> list, boolean[][] g) {
            for (int i : list) {
                for (int j : list) {
                    if (i != j) {
                        if (!g[i][j]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private void dfs0(int x, boolean[] vis, int n, boolean[][] g, List<Integer> comp) {
            comp.add(x);
            vis[x] = true;
            for (int y = 0; y < n; y++) {
                if (x == y) {
                    continue;
                }
                if (g[x][y]) {
                    if (!vis[y]) {
                        dfs0(y, vis, n, g, comp);
                    }
                }
            }
        }

        private void dfs(int x, int[] color, int n, boolean[][] g, int curColor) {
            color[x] = curColor;
            for (int y = 0; y < n; y++) {
                if (x == y) {
                    continue;
                }
                if (!g[x][y]) {
                    if (color[y] == -1) {
                        dfs(y, color, n, g, 1 - curColor);
                    }
                    if (color[y] == color[x]) {
                        fail = true;
                    }
                }
            }
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.StringTokenizer;
import java.util.BitSet;
import java.io.BufferedReader;
import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author kessido
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        BitSet currentGroup;
        BitSet currentOtherGroup;
        int maxMinSize = -1;
        ArrayList<Integer> options;
        int n;
        BitSet[] edges;
        long start;
        int p = 0;
        int pMax = 1000;

        boolean stateIsValid() {
            BitSet COG = new BitSet(n);
            COG.or(currentOtherGroup);
            int card = COG.cardinality();
            for (int i = 0; i < n; i++) {
                if (COG.get(i)) {
                    COG.and(edges[i]);
                    if (COG.cardinality() != card) return false;
                    COG.or(currentOtherGroup);
                }
            }
            return true;
        }

        void findOne() {
            if (stateIsValid()) {
                int card = currentGroup.cardinality();
                maxMinSize = Math.max(maxMinSize, Math.min(card, n - card));
                p++;
                if (card == n) return;
                if (p > pMax) return;
            }
            for (int i1 = 0; i1 < n && p < pMax && checkTime(); i1++) {
                int i = options.get(i1);
                if (currentOtherGroup.get(i)) {
                    for (int j1 = i1 + 1; j1 < n && p < pMax; j1++) {
                        int j = options.get(j1);
                        if (currentOtherGroup.get(j)) {
                            if (!edges[i].get(j)) {
                                BitSet x = (BitSet) edges[i].clone();
                                x.and(currentGroup);
                                tryToContinue(i, x);
                                x = (BitSet) edges[j].clone();
                                x.and(currentGroup);
                                tryToContinue(j, x);
                            }
                        }
                    }
                }
            }
        }

        private void tryToContinue(int j, BitSet x) {
            if (x.cardinality() == currentGroup.cardinality()) {
                currentOtherGroup.flip(j);
                currentGroup.flip(j);
                findOne();
                currentOtherGroup.flip(j);
                currentGroup.flip(j);
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            start = System.nanoTime();
            n = in.NextInt();
            int m = in.NextInt();
            edges = new BitSet[n];
            for (int i = 0; i < n; i++) {
                edges[i] = new BitSet(n);
                edges[i].set(i, true);
            }
            for (int i = 0; i < m; i++) {
                int u = in.NextInt() - 1;
                int v = in.NextInt() - 1;
                edges[u].set(v, true);
                edges[v].set(u, true);
            }

            currentGroup = new BitSet(n);
            currentOtherGroup = new BitSet(n);
            currentOtherGroup.set(0, n, true);
            options = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                options.add(i);
            }
            while (checkTime()) {
                Collections.shuffle(options);
                p = 0;
                findOne();
            }
            if (maxMinSize == -1) {
                out.println(-1);
            } else {
                out.println(maxMinSize * (maxMinSize - 1) / 2 + (n - maxMinSize) * (n - maxMinSize - 1) / 2);
            }
        }

        boolean checkTime() {
            return System.nanoTime() - start < 1_800_000_000L;
        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine(), " \t\n\r\f,");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int NextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    int sum(int n) {
        return n < 10 ? n : (n % 10 + sum(n / 10));
    }

    int n;
    boolean[][] g;
    int[] color;
    int cnt0 = 0, cnt1 = 0;

    boolean go(int v, int col) {
        if (color[v] == -1) {
            color[v] = col;
            if (col == 0) {
                cnt0++;
            } else {
                cnt1++;
            }
            for (int i = 0; i < n; i++) {
                if (g[v][i] && !go(i, 1 - col)) {
                    return false;
                }
            }
            return true;
        } else {
            return color[v] == col;
        }
    }

    void solve() {
        n = in.nextInt();
        g = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(g[i], true);
            g[i][i] = false;
        }
        int m = in.nextInt();
        for (int i = 0; i < m; i++) {
            int fr = in.nextInt() - 1;
            int to = in.nextInt() - 1;
            g[fr][to] = g[to][fr] = false;
        }
        color = new int[n];
        Arrays.fill(color, -1);
        List<Integer> sizes = new ArrayList<>();
        List<Integer> sizes2 = new ArrayList<>();
        int can = 0;
        for (int i = 0; i < n; i++) {
            if (color[i] == -1) {
                cnt0 = 0;
                cnt1 = 0;
                if (!go(i, 0)) {
                    out.println(-1);
                    return;
                }
                if (cnt1 == 0) {
                    can += cnt0;
                } else {
                    sizes.add(cnt0);
                    sizes2.add(cnt1);
                }
            }
        }
        boolean[] v = new boolean[n + 1];
        v[0] = true;
        for (int it = 0; it < sizes.size(); it++) {
            int q = sizes.get(it);
            int w = sizes2.get(it);
            boolean[] nv = new boolean[n + 1];
            for (int i = n; i >= 0; i--) {
                if (v[i]) {
                    nv[i + q] = true;
                    nv[i + w] = true;
                }
            }
            v = nv;
        }
        int bestAns = 0;
        for (int firstPart = 0; firstPart <= n; firstPart++) {
            if (!v[firstPart]) {
                continue;
            }
            for (int realFirst = firstPart; realFirst <= firstPart + can; realFirst++) {
                bestAns = Math.max(bestAns, m - f(firstPart) - f(n - firstPart));
            }
        }
        out.println(m - bestAns);
    }

    int f(int x) {
        return x * (x - 1) / 2;
    }

    void solve123() {
        final int MAX = 10000000;
        double[] f = new double[MAX];
        for (int n = 1; n < MAX; n++) {
            f[n] = n / (double) sum(n);
        }
        double curMin = Double.MAX_VALUE;
        for (int i = MAX - 1; i >= 0; i--) {
            if (f[i] <= curMin + 1e-9) {
                if (i < 1000000) {
                    System.err.println(i);
                }
            }
            curMin = Math.min(curMin, f[i]);
        }
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
