    void solve(){
        int n = ni();
        int m = ni();
        boolean[][] exist = new boolean[n][n];
        for(int i = 0; i < m; i++){
            int f = ni()-1;
            int t = ni()-1;
            exist[f][t] = true;
            exist[t][f] = true;
        }
        ArrayList<Integer>[] edge = new ArrayList[n];
        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<Integer>();
        }
        for(int i = 0; i < n; i++){
            for(int j = 0; j < n; j++){
                if(i==j||exist[i][j]) continue;
                edge[i].add(j);
            }
        }
        boolean[] seen = new boolean[n];
        int[] c = new int[n];
        Arrays.fill(c,-1);
        int[] num = new int[701];
        num[0] = 1;
        int sum = 0;
        for(int i = 0; i < n; i++){
            if(!edge[i].isEmpty()&&!seen[i]){
                Queue<int[]> q = new ArrayDeque<>();
                q.add(new int[]{i,0});
                seen[i] = true;
                int b = 0;
                int w = 0;
                while(!q.isEmpty()){
                    int[] r = q.poll();
                    c[r[0]] = r[1];
                    if(r[1]==0) b++;
                    else w++;
                    sum++;
                    for(int j : edge[r[0]]){
                        if(seen[j]){
                            if(c[j]==r[1]){
                                out.println(-1);
                                return;
                            }
                            continue;
                        }
                        q.add(new int[]{j,1-r[1]});
                        seen[j] = true;
                    }
                }
                int[] nnum = new int[701];
                for(int j = 0; j <= 700; j++){
                    if(num[j]==1){
                        nnum[j+b] = 1;
                        nnum[j+w] = 1;
                    }
                }
                for(int j = 0; j <= 700; j++){
                    num[j] = nnum[j];
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for(int i = 0; i <= n; i++){
            if(num[i]==1){
                int b1 = i;
                int w1 = sum-i;
                for(int j = 0; j <= n-sum; j++){
                    int b2 = b1 + j;
                    int w2 = w1 + n-sum - j;
                    int total = b2*(b2-1)/2 + w2*(w2-1)/2;
                    ans = Math.min(total,ans);
                }
            }
        }
        out.println(ans);
