		}
		int A=0,B=0;
		for(int i=0;i<n;i++)
			if(col[i]==0)
				A++;
			else if(col[i]==1)
				B++;
		int rem=n-A-B;
		int diff=Math.abs(A-B);
		if(A<B)
			A+=Math.min(diff, rem);
		else
			Math.min(diff, rem);
		rem-=Math.min(diff, rem);
		if(rem>0)
		{
			A+=rem/2;
			B+=(rem+1)/2;
		}
		long ans=A*1L*(A-1)/2+B*1L*(B-1)/2;
		pw.println(ans);
		pw.close();

	}

