        if (!set.contains(i * 1000 + j)) {
          from[ptr] = i;
          to[ptr] = j;
          ptr ++;
        }
      }
    }
    int[][] g = packU(n, from, to, ptr);
    int[] color = new int[n];
    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;
