        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();

        int tosi = inpt[0];
        int roadCount = inpt[1];

        Dictionary<int, Dictionary<int, bool>> road = new Dictionary<int, Dictionary<int, bool>>();

        for (int i = 0; i < roadCount; i++)
        {
            inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            if (!road.ContainsKey(inpt[0]))
            {
                road.Add(inpt[0], new Dictionary<int, bool>());
            }
            road[inpt[0]].Add(inpt[1], true);
            if (!road.ContainsKey(inpt[1]))
            {
                road.Add(inpt[1], new Dictionary<int, bool>());
            }
            road[inpt[1]].Add(inpt[0], true);
        }

        List<KeyValuePair<int, Dictionary<int, bool>>> sorted = road.OrderBy(a => a.Value.Count).ToList();
        int groupA = 0;
        int groupB = 0;
        for (int i = 0; i < sorted.Count - 1; i++) {
            for (int j = i + 1; j < sorted.Count; j++) {
                if(!sorted[i].Value.ContainsKey(sorted[j].Key)) {
                    groupA = sorted[i].Key;
                    groupB = sorted[j].Key;
                    break;
                }
            }
            if(groupA != 0) {
                break;
            }
        }

        if(groupA == 0) {
            int tmp = tosi / 2;
            int subAns = tmp * (tmp - 1) / 2;
            tmp = tosi - tmp;
            subAns += tmp * (tmp - 1) / 2;
            Console.WriteLine(subAns);
            return;
        }

        List<int> kaburi = new List<int>();
        foreach(int item in road[groupA].Keys) {
            if(road[groupB].ContainsKey(item)) {
                kaburi.Add(item);
            }
        }

        int groupACount = road[groupA].Count - kaburi.Count + 1;
        int groupBCount = road[groupB].Count - kaburi.Count + 1;

        if(groupACount + groupBCount + kaburi.Count < tosi) {
            Console.WriteLine(-1);
            return;
        }

        groupACount = Math.Min(groupA + kaburi.Count, tosi / 2);
        groupBCount = tosi - groupACount;

        int ans = groupACount * (groupACount - 1) / 2;
        ans += groupBCount * (groupBCount - 1) / 2;
        Console.WriteLine(ans);
    }



