            var G = new bool[n, n];
            for (int i = 0; i < m; i++)
            {
                var f = ri - 1; var t = ri - 1;
                G[f, t] = G[t, f] = true;
            }
            var set = new DisjointSet(2 * n);
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                    if (!G[i, j])
                    {
                        set.Unite(i, j + n);
                        set.Unite(i + n, j);
                    }
            for (int i = 0; i < n; i++)
                if (set[i] == set[i + n])
                {
                    Console.WriteLine(-1); return;
                }
            var cnt = new List<KeyValuePair<int, int>>();
            var used = new bool[n];
            for (int i = 0; i < n; i++)
            {
                if (used[i]) continue;
                var a = new int[2];
                Action<int, int> dfs = null;
                dfs = (v, k) =>
                {
                    used[v] = true;
                    a[k]++;
                    for (int j = 0; j < n; j++)
                        if (!G[v, j] && !used[j]) dfs(j, k ^ 1);
                };
                dfs(i, 0);
                cnt.Add(new KeyValuePair<int, int>(a[0], a[1]));
