                {
                    dp[j + x.Key] |= dp[j];
                    dp[j + x.Value] |= dp[j];
                }
            }
            var max = 0;
            for (int i = 0; i <= n; i++)
                if (dp[i]) max = Max(max, i * (n - i));
            Console.WriteLine(m - (max - (n * (n - 1) / 2 - m)));
        }

