using P = pair<int, int>;

using Binary = System.Func<System.Linq.Expressions.ParameterExpression, System.Linq.Expressions.ParameterExpression,
                           System.Linq.Expressions.BinaryExpression>;
using Unary = System.Func<System.Linq.Expressions.ParameterExpression, System.Linq.Expressions.UnaryExpression>;

class Program
{
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    // const int M = 998244353;
    const long LM = (long)1e18;
    const double eps = 1e-11;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    const string dstring = "RDLU";
    static void Main()
    {
        int n, m;
        sc.Multi(out n, out m);
        var _edge = new bool[n][];
        for (int i = 0; i < n; i++)
        {
            _edge[i] = new bool[n];
        }
        for (int i = 0; i < m; i++)
        {
            int a, b;
            sc.Multi(out a, out b);
            --a;
            --b;
            _edge[a][b] = _edge[b][a] = true;
        }
        var edge = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
            for (int j = 0; j < n; j++)
            {
                if (i == j) continue;
                if (!_edge[i][j])
                    edge[i].Add(j);
            }
        }
        var w = new List<P>();
        var col = new int[n];

        for (int i = 0; i < n; i++)
        {
            if (col[i] == 0) {
                var q = new Queue<int>();
                q.Enqueue(i);
                col[i] = 1;
                int c1 = 1, c2 = 0;
                while (q.Any())
                {
                    var p = q.Dequeue();
                    foreach (var item in edge[p])
                    {
                        if (col[item] == col[p]) {
                            DBG(-1);
                            return;
                        }
                        if (col[item] == 0) {
                            if (col[p] == 1) {
                                col[item] = 2;
                                ++c2;
                            }
                            else {
                                col[item] = 1;
                                ++c1;
                            }
                            q.Enqueue(item);
                        }
                    }
                }
                w.Add(new P(c1, c2));
            }
        }
        var dp = new bool[n + 1];
        dp[0] = true;
        foreach (var item in w)
        {
            var nex = new bool[n + 1];
            for (int i = item.v1; i < n + 1; i++)
            {
                nex[i] |= dp[i - item.v1];
            }
            for (int i = item.v2; i < n + 1; i++)
            {
                nex[i] |= dp[i - item.v2];
            }
            dp = nex;
        }
        int ans = M;
        for (int i = 0; i < n + 1; i++)
        {
            if (dp[i]) {
                ans = Math.Min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
            }
        }
        Prt(ans);
        sw.Flush();
    }

    static void DBG(string a) => Console.WriteLine(a);
    static void DBG<T>(IEnumerable<T> a) => DBG(string.Join(" ", a));
    static void DBG(params object[] a) => DBG(string.Join(" ", a));
    static void Prt(string a) => sw.WriteLine(a);
    static void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    static void Prt(params object[] a) => Prt(string.Join(" ", a));
}
