using static System.Math;
using static System.Array;
using static AtCoder.Cout;
using static AtCoder.Tool;
using static AtCoder.ModInt;
namespace AtCoder
{
    class AC
    {
        //const int MOD = 1000000007;
        const int MOD = 998244353;
        const int INF = int.MaxValue / 2;
        const long SINF = long.MaxValue / 3;
        const double EPS = 1e-8;
        static readonly int[] dI = { 0, 1, 0, -1, 1, -1, -1, 1 };
        static readonly int[] dJ = { 1, 0, -1, 0, 1, 1, -1, -1 };
        static void Main(string[] args)
        {
            //var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false }; Console.SetOut(sw);

            var th = new Thread(Run, 1 << 26);
            th.Start();
            th.Join();

            //Run();
            Console.Out.Flush();
        }
        static void Run()
        {
            int Testcase = 1;
            //Testcase = Cin.Int;
            for (var _ = 0; _ < Testcase; _++) Solve();
        }
        static void Solve()
        {
            Cin.Scanf(out int N, out int M);
            var e = new int[N][];
            for(var i = 0; i < N; i++)
            {
                e[i] = new int[N];
            }
            for(var i = 0; i < M; i++)
            {
                Cin.Scanf(out int a, out int b);
                a--;b--;
                e[a][b] = e[b][a] = 1;
            }
            var col = new int[N];
            Fill(col, -1);
            int[] cn = { 0, 0 };
            void dfs(int v)
            {
                cn[col[v]]++;
                for(var nx = 0; nx < N; nx++)
                {
                    if (nx == v || e[v][nx] == 1) continue;
                    if (col[nx] != -1)
                    {
                        if (col[v] == col[nx])
                        {
                            OutL(-1);
                            Environment.Exit(0);
                        }
                        continue;
                    }
                    col[nx] = col[v] ^ 1;
                    dfs(nx);
                }
            }
            var B = new List<int>();
            var W = new List<int>();
            for(var i = 0; i < N; i++)
            {
                if (col[i] == -1)
                {
                    col[i] = 0;
                    dfs(i);
                    B.Add(cn[0]);
                    W.Add(cn[1]);
                    cn[0] = cn[1] = 0;
                }
            }
            int L = B.Count();
            var dp = new bool[L + 1, N + 1];
            dp[0, 0] = true;
            for(var i = 0; i < L; i++)
            {
                for(var j = 0; j <= N; j++)
                {
                    if (j + B[i] <= N) dp[i + 1, j + B[i]] |= dp[i, j];
                    if (j + W[i] <= N) dp[i + 1, j + W[i]] |= dp[i, j];
                }
            }
            int ans = N * (N - 1) / 2;
            //Out_Sep(col);
            for(var i = 0; i <= N; i++)
            {
                if (dp[L, i])
                {
                    //OutL($"{i}:ok");
                    ans = Min(ans, i * (i - 1) / 2 + (N - i) * (N - i - 1) / 2);
                }
            }
            OutL(ans);
        }

        public struct Edge
        {
            public int from;

            public int to;
            public long dist;

            public Edge(int t, long c)
            {
                from = -1;
                to = t;
                dist = c;
            }
            public Edge(int f, int t, long c)
            {
                from = f;
                to = t;
                dist = c;
            }
        }
