class Program
{
    public static bool chmin<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == 1) { num = val; return true; } return false; }
    public static bool chmax<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == -1) { num = val; return true; } return false; }
    public static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    public static void Fail() => Fail("No");
    public static void Fail<T>(T s) { WriteLine(s); Console.Out.Close(); Environment.Exit(0); }
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        var p = new Program();
        for (var i = 1; i > 0; --i) 
            p.Solve();
        Console.Out.Flush();
    }
    int[] color;
    List<int>[] edge;
    int ct1, s;
    void Solve()
    {
        int num, m;
        Input.Make(out num, out m);
        var e = Input.create(num, _ => new bool[num]);
        for (var i = 0; i < m; i++)
        {
            int a, b;
            Input.Make(out a, out b);
            a--; b--;
            e[a][b] = e[b][a] = true;
        }
        edge = Input.edge<int>(num);
        for (var i = 0; i < num; i++)
            for (var j = 0; j < num; j++)
                if (i != j && !e[i][j])
                    edge[i].Add(j);
        color = new int[num];
        var t = true;
        var list = new List<Pi>();
        for (var i = 0; i < num; i++)
            if (color[i] == 0)
            {
                s = ct1 = 0;
                t &= IsBipartite(i);
                list.Add(new Pi(ct1, s - ct1));
            }
        if (!t) Fail(-1);
        var dp = new bool[num << 1]; dp[0] = true;
        foreach (var ar in list)
            for (var j = num; j >= 0; j--)
            {
                if (!dp[j]) continue;
                dp[j] = false;
                dp[j + ar.v1] = dp[j + ar.v2] = true;
            }
        var ct = -1;
        for (var i = 0; i <= num; i++)
            if (dp[i] && Abs(num / 2 - ct) > Abs(num / 2 - i))
                ct = i;
        WriteLine(ct * (ct - 1) / 2 + (num - ct) * (num - ct - 1) / 2);
    }
    public bool IsBipartite(int index, int c = 1)
    {
        if (color[index] != 0) return color[index] == c;
        s++; color[index] = c;if (c == 1) ct1++;
        var t = true;
        foreach (var ad in edge[index])
            if (t)
                t &= IsBipartite(ad, 3 - c);
            else break;
        return t;
    }
}

