        static void Solve()
        {
            Cin.Scanf(out int N, out int M);
            var e = new int[N][];
            for(var i = 0; i < N; i++)
            {
                e[i] = new int[N];
            }
            for(var i = 0; i < M; i++)
            {
                Cin.Scanf(out int a, out int b);
                a--;b--;
                e[a][b] = e[b][a] = 1;
            }
            var col = new int[N];
            Fill(col, -1);

            void dfs(int v)
            {
                for(var nx = 0; nx < N; nx++)
                {
                    if (nx == v) continue;
                    if (e[v][nx] == 1) continue;
                    if (col[nx] != -1)
                    {
                        if (col[nx] == col[v])
                        {
                            OutL(-1);
                            Environment.Exit(0);
                        }
                        continue;
                    }
                    col[nx] = col[v] ^ 1;
                    dfs(nx);
                }
            }
            col[0] = 0;
            dfs(0);
            int m = col.Count(x => x == -1);
            int tak = col.Count(x => x == 0);
            int has = col.Count(x => x == 1);
            int ans = INF;
            //Out_Sep(col);
            for(var i = 0; i <= m; i++)
            {
                ans = Min(ans, (tak + i) * (tak + i - 1) / 2 + (has + (m - i)) * (has + (m - i) - 1) / 2);
            }
            OutL(ans);
        }

