    }
    void dfs(int i,int c)
    {
        if (col[i] != 0)
        {
            if (col[i] != c) Fail(-1);
            return;
        }
        col[i] = c;
        if (c == 1) t++;
        else h++;
        for (var j = 0; j < g.Length; j++)
            if (g[i][j] == 1) dfs(j,-c);
    }
