func main() {
  var direct [700][700]bool
  input := Input{bufio.NewReaderSize(os.Stdin,1000000)}
  n,m := input.NextInts()
  graph := make([][]int,n)
  for i:=0;i<m;i++ {
    a,b := input.NextInts()
    graph[a-1] = append(graph[a-1],b-1)
    graph[b-1] = append(graph[b-1],a-1)
    direct[a-1][b-1] = true
    direct[b-1][a-1] = true
  }
  num := make([][]int,n+1)
  for i:=0;i<n;i++ {
    num[len(graph[i])+1] = append(num[len(graph[i])+1],i)
  }
  for i:=n/2;i>0;i-- {
    if len(num[i])*len(num[n-i]) == 0 { continue }
    LoopA:
    for _,a := range num[i] {
      for j:=0;j<len(graph[a])-1;j++ {
        for k:=j+1;k<len(graph[a]);k++ {
          if !direct[graph[a][j]][graph[a][k]] { continue LoopA }
        }
      }
      LoopB:
      for _,b := range num[n-i] {
        for j:=0;j<len(graph[b])-1;j++ {
          for k:=j+1;k<len(graph[b]);k++ {
            if !direct[graph[b][j]][graph[b][k]] { continue LoopB }
          }
        }
      }
    }
    fmt.Println((i*(i-1))/2+((n-i)*(n-i-1))/2)
    return
  }
  if m == (n*(n-1))/2 {
    fmt.Println(m)
  } else {
    fmt.Println(-1)
  }
}

type Input struct {
  reader *bufio.Reader
}
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInts() (int,int) {
  s := strings.Split(i.NextLine()," ")
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}

