	writer := bufio.NewWriter(wfp)
	defer func() {
		r := recover()
		if r != nil {
			fmt.Fprintln(writer, r)
		}
		writer.Flush()
	}()
	solve(scanner, writer)
	for i := 0; i < extra; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	ee := makeGrid(n, n)
	for i := 0; i < m; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		ee[a][b] = 1
		ee[b][a] = 1
	}
	g := newGraph(n)

	id := 0
	for i := 0; i < n; i++ {
		for j := 0; j < i; j++ {
			if ee[i][j] == 1 {
				continue
			}
			g.appendEdge(i, j, id)
			g.appendEdge(j, i, id)
			id++
		}
	}
	g.dfs(0, 1)
	cnt := make([]int, 3)
	for i := 0; i < n; i++ {
		if g.v[i].invalid {
			fmt.Fprintln(writer, -1)
			return
		}
		cnt[g.v[i].color]++
	}
	for cnt[0] > 0 {
		cnt[0]--
		if cnt[1] < cnt[2] {
			cnt[1]++
			continue
		}
		cnt[2]++
	}
	fmt.Fprintln(writer, cnt[1]*(cnt[1]-1)/2+cnt[2]*(cnt[2]-1)/2)
}

func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

type vertex struct {
	color   int
	invalid bool
}
type edge struct {
	to, id int
}
type graph struct {
	v []vertex
	e [][]edge
}

func newGraph(n int) graph {
	return graph{
		v: make([]vertex, n),
		e: make([][]edge, n),
	}
}
func (g *graph) appendEdge(from, to, id int) {
	g.e[from] = append(g.e[from], edge{
		to: to,
		id: id,
	})
}
func (g *graph) dfs(i, color int) {
	g.v[i].color = color
	for _, e := range g.e[i] {
		if g.v[e.to].color == 0 {
			g.dfs(e.to, 3-color)
			continue
		}
		if g.v[e.to].color != 3-color {
			g.v[e.to].invalid = true
