var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func MaxInt(A ...int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}

func Solve() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  G := make([][]int, N)
  for i := range G {
    G[i] = make([]int, N)
    for j := range G[i] {
      G[i][j] = 1
    }
  }
  for i := 0; i < M; i++ {
    AB := NextIntVec()
    a, b := AB[0] - 1, AB[1] - 1
    G[a][b] = 0
    G[b][a] = 0
  }
  D := make([]int, N)
  B := make([][]int, 0)
  for i, d := range D {
    if 0 < d { continue }
    D[i] = 1
    UV := make([]int, 2)
    UV[1]++
    Q := make([]int, 0)
    Q = append(Q, i)
    for 0 < len(Q) {
      q := Q[0]
      Q = Q[1:]
      for adj, e := range G[q] {
        if e < 1 { continue }
        if q == adj { continue }
        if 0 < D[adj] {
          if (D[q] - D[adj]) % 2 == 0 {
            Write(-1)
            return
          }
          continue
        }
        D[adj] = D[q] + 1
        Q = append(Q, adj)
        UV[D[adj] % 2]++
      }
    }
    B = append(B, UV)
  }
  DP := make([][]int, len(B) + 1)
  for i := range DP {
    DP[i] = make([]int, N + 1)
  }
  DP[0][0] = 1
  for i, b := range B {
    for _, v := range b {
      for j, dp := range DP[i] {
        if dp < 1 { continue }
        DP[i + 1][j + v] = 1
      }
    }
  }
  ans := N * (N - 1) / 2
  for j, dp := range DP[len(B)] {
    if dp < 1 { continue }
    ans = MinInt(j * (j - N) + N * (N - 1) / 2, ans)
  }
  Write(ans)
  return
}

func main() {
  Solve()
  Output()
}

