func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	ee := makeGrid(n, n)
	for i := 0; i < m; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		ee[a][b] = 1
		ee[b][a] = 1
	}
	g := newGraph(n)

	id := 0
	for i := 0; i < n; i++ {
		for j := 0; j < i; j++ {
			if ee[i][j] == 1 {
				continue
			}
			g.appendEdge(i, j, id)
			g.appendEdge(j, i, id)
			id++
		}
	}
	group := 0
	for i := 0; i < n; i++ {
		if g.v[i].color == 0 {
			g.dfs(i, 1, group)
			group++
		}
	}
