	b.x.SetBit(b.x, geta, 1)
	for i := 0; i < group; i++ {
		shift := cnt[i][1] - cnt[i][2]
		if cnt[i][1] < cnt[i][2] {
			shift = -shift
		}
		b = b.lsh(shift).or(b.rsh(shift))
	}
	var ans int
	ans = n * n
	for i := 0; i < n; i++ {
		if b.x.Bit(geta+i) == 1 || b.x.Bit(geta-i) == 1 {
			a := count((n-i)/2) + count(n-(n-i)/2)
			if ans > a {
				ans = a
			}
		}
	}
	fmt.Fprintln(writer, ans)
}

func count(n int) int {
	return n * (n - 1) / 2
}
func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

