	color, group int
	invalid      bool
}
type edge struct {
	to, id int
}
type graph struct {
	v []vertex
	e [][]edge
}

func newGraph(n int) graph {
	return graph{
		v: make([]vertex, n),
		e: make([][]edge, n),
	}
}
func (g *graph) appendEdge(from, to, id int) {
	g.e[from] = append(g.e[from], edge{
		to: to,
		id: id,
	})
}
func (g *graph) dfs(i, color, group int) {
	g.v[i].color = color
	g.v[i].group = group
	for _, e := range g.e[i] {
		if g.v[e.to].color == 0 {
			g.dfs(e.to, 3-color, group)
			continue
		}
		if g.v[e.to].color != 3-color {
			g.v[e.to].invalid = true
		}
	}
}

