    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func Solve() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  G := make([][]int, N)
  for i := range G {
    G[i] = make([]int, N)
    G[i][i] = 1
  }
  D := make([]int, N)
  for i := 0; i < M; i++ {
    AB := NextIntVec()
    a, b := AB[0] - 1, AB[1] - 1
    G[a][b] = 1
    G[b][a] = 1
    D[a]++
    D[b]++
  }
  v, min := 0, D[0]
  for i, d := range D {
    if d < min {
      v = i
      min = d
    }
  }
  C := make([][]int, 2)
  for i := range C {
    C[i] = make([]int, 0)
  }
  V := make([]int, N)
  for i := range V {
    V[i] = -1
  }
  V[v] = 0
  C[0] = append(C[0], v)
  Q := make([]int, 0)
  Q = append(Q, v)
  for 0 < len(Q) {
    v := Q[0]
    Q = Q[1:]
    for adj, e := range G[v] {
      if 0 < e { continue }
      if -1 < V[adj] { continue }
      c := 1 - V[v]
      V[adj] = c
      for _, j := range C[c] {
        if G[adj][j] < 1 {
          Write(-1)
          return
        }
      }
      C[c] = append(C[c], adj)
      Q = append(Q, adj)
    }
  }
  for i, v := range V {
    if -1 < v { continue }
    if len(C[0]) < len(C[1]) {
      C[0] = append(C[0], i)
    } else {
      C[1] = append(C[1], i)
    }
  }
  N0, N1 := len(C[0]), len(C[1])
  Write(N0 * (N0 - 1) / 2 + N1 * (N1 - 1) / 2)
  return
}

func main() {
  Solve()
  Output()
}

