  Tuple!(long[], bool) dfs(long i, long d, long prev) {
    if (memo[i] != -1) {
      if (abs(memo[i] - d) % 2 == 1) {
        return tuple([0L, 0L], false);
      } else {
        return tuple([0L, 0L], true);
      }
    } else {
      auto ret = [1L, 0L];
      memo[i] = d;
      foreach (j; iota(n)) {
        if (j == i || j == prev) {
          continue;
        }
        if (!g[i][j]) {
          continue;
        }
        auto tmp = dfs(j, d + 1, i);
        if (!tmp[1]) {
          return tmp;
        }
        ret[0] += tmp[0][1];
        ret[1] += tmp[0][0];
      }
      return tuple(ret, true);
    }
  }

  foreach (i; iota(n)) {
    if (memo[i] != -1) {
      continue;
    }
    auto tmp = dfs(i, 0, -1);
    if (!tmp[1]) {
      writeln(-1);
      return;
    }
    c ~= tmp[0];
  }
  auto dp = new bool[][](c.length + 1, n + 1);
  dp[0][0] = true;
  foreach (i; iota(c.length)) {
    foreach (j; iota(n)) {
      if (dp[i][j]) {
        foreach (ci; c[i]) {
          if (j + ci <= n) {
            dp[i + 1][j + ci] = true;
          }
        }
      }
    }
  }
  long ans = long.max;

  foreach (i; iota(n + 1)) {
    if (dp[$ - 1][i]) {
      ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
    }
  }
  writeln(ans);
}

