int[][700] PS;
bool[700] F;

void main()
{
    auto nm = readln.split.to!(int[]);
    auto N = nm[0];
    auto M = nm[1];
    auto QS = new bool[][](N, N);
    foreach (_; 0..M) {
        auto ab = readln.split.to!(int[]);
        auto A = ab[0]-1;
        auto B = ab[1]-1;
        PS[A] ~= B;
        PS[B] ~= A;
        QS[A][B] = true;
        QS[B][A] = true;
    }

    auto SS = new int[](N);
    foreach (int i; 1..N) SS[i] = SS[i-1] + i;

    int[] solve(int i, int[] ss) {
        int[] ret = ss;
        foreach (n; PS[i]) if (!F[n]) {
            int[] r;
            foreach (s; ss) if (!QS[n][s]) goto ng;
            F[n] = true;
            r = solve(n, ss ~ n);
            F[n] = false;
            if (r.length > ret.length) ret = r;
            ng:
        }
        return ret;
    }
    auto ss = solve(0, [0]);

    auto FX = new int[](N);
    foreach (s; ss) FX[s] = 1;

    int x = -1;
