type Mark = enum
  None, Black, White, Mult

proc creek(g: seq2[bool]; vs: seq[int]): bool =
  for v in vs:
    for u in vs:
      if v == u:
        continue
      if not g[v][u]:
        return false
  return true

proc solve(n, m: int; g: seq2[bool]): int =
  var mark = newSeq[Mark](n)
  mark.fill(None)

  for v in 0..<n:
    var edgeCount = 0

    for u in 0..<n:
      if g[v][u]:
        edgeCount += 1

    if edgeCount == n - 1:
      mark[v] = Mult

  var vs = -1
  for v in 0..<n:
    if mark[v] == None:
      vs = v

  var stack = newSeq[int](0)
  if vs >= 0:
    stack.add(vs)
    mark[vs] = Black

  while stack.len() > 0:
    let v = stack.pop()
    let opposite = if mark[v] == Black: White else: Black

    for u in 0..<n:
      if v == u or g[v][u] or mark[u] == Mult:
        continue

      if mark[u] == None:
        mark[u] = opposite
        stack.add(u)
        continue

      if mark[u] == mark[v]:
        return -1

  var mults: seq[int] = @[]
  var blacks: seq[int] = @[]
  var whites: seq[int] = @[]
  for v in 0..<n:
    if mark[v] == Black:
      blacks.add(v)
    if mark[v] == White:
      whites.add(v)
    if mark[v] == Mult:
      mults.add(v)

  if not creek(g, blacks) or not creek(g, whites):
    return -1

  var k0 = blacks.len()
  var k1 = whites.len()
  for i in 0..<mults.len():
    if k0 < k1:
      k0 += 1
    else:
      k1 += 1

  return (k0 * (k0 - 1) div 2) + (k1 * (k1 - 1) div 2)

proc main() =
  let (n, m) = readInt2()

  var g = newSeq2[bool](n, n)
  for _ in 0..<m:
    let (a, b) = readInt2()
    g[a - 1][b - 1] = true
    g[b - 1][a - 1] = true

  echo solve(n, m, g)

main()

