def dfs(v, cmp_list, visited, even, odd):
    visited[v] = True
    even.add(v)
    for w in cmp_list[v]:
        if w in even:
            return False
        if not visited[w]:
            r = dfs(w, cmp_list, visited, odd, even)
            if not r:
                return False

    return True


def solve(n, m, d):

    f = False
    cmp_list = [[] for _ in range(n)]
    for v in range(n):
        for w in range(v + 1, n):
            if not (v, w) in d:
                cmp_list[v].append(w)
                cmp_list[w].append(v)
                f = True

    if not f:
        m = n // 2
        l = n - m
        return m * (m - 1) // 2 + l * (l - 1) // 2


    graph_sizes = []
    l = 0
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if len(cmp_list[i]):
                even = set()
                odd = set()
                r = dfs(i, cmp_list, visited, even, odd)
                if not r:
                    return -1
                l0 = len(even)
                l1 = len(odd)
                if l1 < l0:
                    l0, l1 = l1, l0
                graph_sizes.append((l0, l1))
                l += l0 + l1


    nh = n - n // 2
    dp = [[0] * (nh + 1) for _ in range(len(graph_sizes) + 1)]
    for i in range(len(graph_sizes)):
        l0, l1 = graph_sizes[i]
        for j in range(nh + 1):
            if j < l0:
                dp[i + 1][j] = dp[i][j]
            elif j < l1:
                dp[i + 1][j] = dp[i][j - l0] + l0
            else:
                dp[i + 1][j] = max(dp[i][j - l0] + l0, dp[i][j - l1] + l1)

    m = dp[len(graph_sizes)][nh]
    l -= m
    r = n - m - l
    if nh < m + r:
        m = nh
        l = n - nh
    else:
        m += r

    return m * (m - 1) // 2 + l * (l - 1) // 2


def main():
    n, m = input().split()
    n = int(n)
    m = int(m)
    d = set()
    for _ in range(m):
        a, b = input().split()
        a = int(a) - 1
        b = int(b) - 1
        if b < a:
            a, b = b, a
        d.add((a, b))


    print(solve(n, m, d))


if __name__ == '__main__':
    main()

