from itertools import combinations
def spl(target:set,connections:list):
    Agroup = set()
    Bgroup = set()

    for i in target:
        if i in connections[0]:
            Agroup.add(i)
        else:
            Bgroup.add(i)
    Bcon= set(target)
    for i in Bgroup:
        Bcon &= connections[i]


    if not Bgroup.issubset(Bcon):
        print(-1)
        return

    bconwith0 = Bcon - Bgroup

    Agroup -= bconwith0

    Acon= set(target)
    for i in Agroup:
        Acon &= connections[i]

    if not Agroup.issubset(Acon):
        print(-1)
        return

    while len(bconwith0) != 0:
        ns = set()
        for i in bconwith0:
            if i in Acon:
                if i in Bcon:
                    ns.add(i)
                else:
                    Agroup.add(i)
                    Acon &= connections[i]
            else:
                if i in Bcon:
                    Bgroup.add(i)
                    Bcon &= connections[i]
                else:
                    print(-1)
                    return

        if bconwith0.__len__() == ns.__len__():
            break
        bconwith0= ns
    return(Agroup,Bgroup,bconwith0)

