def graph_coloring(G, color):
    N = len(G)

    def dfs(v, c):
        """
        :param v: node
        :param c: color (1 or -1)
        :return:
        """
        color[v] = c
        for j in range(N):
            if G[v, j] == 1:
                if color[j] == c:
                    # 隣が同じ色
                    return False
                elif color[j] == 0:
                    # まだ塗ってなければ塗る
                    if not dfs(j, c * -1):
                        return False

        # 全ての頂点を塗れた
        return True

    # グラフが連結でない
    c = 1
    for i in range(N):
        if color[i] == 0:
            if not dfs(i, c):
                return G, None  # impossible
            c += 1

    return G, color


def c2(n):
    return n * (n-1) // 2


def partial_sum(integer_list, target_sum, i=0, sum_=0):
    if target_sum < sum_:
        return False

    if i == len(integer_list):
        return sum_ == target_sum

    if partial_sum(integer_list, target_sum, i + 1, sum_):
        return True

    if partial_sum(integer_list, target_sum, i + 1, sum_ + integer_list[i]):
        return True

    return False


def main():
    N, M = lii()
    G = np.eye(N)
    for _ in range(M):
        x, y = lii()
        G[x-1, y-1] = 1
        G[y-1, x-1] = 1

    G = 1 - G  # 補グラフ
    color = np.array([0 for _ in range(N)])

    G, color = graph_coloring(G, color=color)
    if color is None:
        return -1

    c = 1
    base = 0
    int_list = []
    while True:
        p = len(color[color == c])
        q = len(color[color == -c])
        if p == 0 and q == 0:
            break

        base += min(p, q)
        diff = max(p, q) - min(p, q)
        if diff > 0:
            int_list.append(diff)

        c += 1

    if int_list:
        int_list = sorted(int_list, reverse=True)
        for s in range((N - base) // 2, N - base):
            if partial_sum(int_list, target_sum=s):
                return c2(base + s) + c2(N - base - s)

    else:
        return c2(base) * 2


