class UnionFind(object):

    def __init__(self, n):
        # 親のnodeを表す
        self.par = [i for i in range(n)]

    def root(self, x):
        if self.par[x] == x:
            return x
        else:
            # 経路圧縮
            self.par[x] = self.root(self.par[x])
            return self.par[x]

    def same(self, x, y):
        return self.root(x) == self.root(y)

    def union(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if x == y:
            return

        self.par[x] = y



class UnionFindRankCount(UnionFind):

    def __init__(self, n):
        UnionFind.__init__(self, n)

        self.rank = [0 for _ in range(n)]
        self.count = [1 for _ in range(n)]

    def union(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if x == y:
            return

        if self.rank[x] < self.rank[y]:
            self.par[x] = y
            self.count[y] += self.count[x]
        else:
            self.par[y] = x
            self.count[x] += self.count[y]
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1


def graph_coloring(G):
    N = len(G)
    color = np.array([0 for _ in range(N)])

    def dfs(v, c):
        """
        :param v: node
        :param c: color (1 or -1)
        :return:
        """
        color[v] = c
        for j in range(N):
            if G[v, j] == 1:
                if color[j] == c:
                    # 隣が同じ色
                    return False
                elif color[j] == 0:
                    # まだ塗ってなければ塗る
                    if not dfs(j, c * -1):
                        return False

        # 全ての頂点を塗れた
        return True

    # # グラフが連結でない
    # for i in range(N):
    #     if color[i] == 0:
    #         if not dfs(i, 1):
    #             return None  # impossible

    # 連結の前提
    if not dfs(0, 1):
        return None

    return color


def c2(n):
    return n * (n-1) // 2


def partial_sum(integer_list, target_sum, i=0, sum_=0):
    if target_sum < sum_:
        return False

    if i == len(integer_list):
        return sum_ == target_sum

    if partial_sum(integer_list, target_sum, i + 1, sum_):
        return True

    if partial_sum(integer_list, target_sum, i + 1, sum_ + integer_list[i]):
        return True

    return False


def partial_sum_list(integer_list):
    B = sum(integer_list)
    N = len(integer_list)
    dp = np.zeros([N, B+1])
    dp[0][integer_list[0]] = 1

    for v in range(1, N):
        for b in range(B+1):
            w = integer_list[v]
            if dp[v-1, b]:
                dp[v, b] += dp[v-1, b]
                dp[v, b+w] += dp[v-1, b]

    return dp[-1]


def main():
    N, M = lii()
    G = np.eye(N)

    for _ in range(M):
        x, y = lii()
        G[x-1, y-1] = 1
        G[y-1, x-1] = 1

    G = 1 - G  # 補グラフ

    u = UnionFindRankCount(N)
    for i in range(N):
        for j in range(i, N):
            if G[i, j]:
                u.union(i, j)

    d = defaultdict(list)
    for n in range(N):
        d[u.par[n]].append(n)

    base = 0
    int_list = []
    # print(G, d)
    for s in d.values():
        Gs = np.array(G[s][:, s])
        color = graph_coloring(Gs)

        if color is None:
            return -1

        p = len(color[color == 1])
        q = len(color) - p

        base += min(p, q)
        diff = max(p, q) - min(p, q)
        if diff > 0:
            int_list.append(diff)

    if int_list:
        int_list = sorted(int_list, reverse=True)
        res = partial_sum_list(int_list)

        for s in range((N - base) // 2, N - base):
            if res[s]:
                return c2(base + s) + c2(N - base - s)

    else:
        return c2(base) * 2


if __name__ == '__main__':
    print(main())

