#!/usr/bin/python3

def sm(n):
    a = 0
    while n >= 1:
        a += n
        n -= 1
    return a


def solve(N, G):
    unused = set(range(N))
    groups = []

    while unused:
        a = unused.pop()
        group = set([a])
        for b in range(N):
            if not G[a][b] or b not in unused:
                continue

            cxn = True
            for c in group:
                if not G[b][c]:
                    cxn = False
                    break

            if not cxn:
                continue

            group.add(b)
            unused.remove(b)
        groups.append(group)

    # print(groups)

    if len(groups) > 2:
        return -1

    if len(groups) == 2:
        g0 = groups[0]
        g1 = groups[1]

        return sm(len(g0) - 1) + sm(len(g1) - 1)

    best = sm(N - 1)
    for i in range(1, N):
        best = min(best, sm(i - 1) * sm(N - i - 1))
    return best


def main():
    N, M = [int(e) for e in input().split(' ')]
    G = [[False] * N for _ in range(N)]

    for _ in range(M):
        a, b = [int(e) for e in input().split(' ')]
        a -= 1
        b -= 1
        G[a][b] = G[b][a] = True

    print(solve(N, G))


