def graph_coloring(G, color):
    N = len(G)

    def dfs(v, c):
        """
        :param v: node
        :param c: color (1 or -1)
        :return:
        """
        color[v] = c
        for j in range(N):
            if G[v, j] == 1:
                if color[j] == c:
                    # 隣が同じ色
                    return False
                elif color[j] == 0:
                    # まだ塗ってなければ塗る
                    if not dfs(j, c * -1):
                        return False

        # 全ての頂点を塗れた
        return True

    # グラフが連結でない
    c = 1
    for i in range(N):
        if color[i] == 0:
            if not dfs(i, c):
                return G, None  # impossible
            c += 1

    return G, color


