        """
        color[v] = c
        for j in range(N):
            if G[v, j] == 1:
                if color[j] == c:
                    # 隣が同じ色
                    return False
                elif color[j] == 0:
                    # まだ塗ってなければ塗る
                    if not dfs(j, c * -1):
