def partial_sum(integer_list, target_sum, i=0, sum_=0):
    if target_sum < sum_:
        return False

    if i == len(integer_list):
        return sum_ == target_sum

    if partial_sum(integer_list, target_sum, i + 1, sum_):
        return True

    if partial_sum(integer_list, target_sum, i + 1, sum_ + integer_list[i]):
        return True

    return False


def partial_sum_list(integer_list):
    B = sum(integer_list)
    N = len(integer_list)
    dp = np.zeros([N, B+1])
    dp[0][integer_list[0]] = 1

    for v in range(1, N):
        for b in range(B+1):
            w = integer_list[v]
            if dp[v-1, b]:
                dp[v, b] += dp[v-1, b]
                dp[v, b+w] += dp[v-1, b]

    return dp[-1]


