def solve(f):
    n, m = f.read_int_list()
    g = collections.defaultdict(list)
    for _ in xrange(m):
        a, b = f.read_int_list()
        g[a].append(b)
        g[b].append(a)

    both = set()
    a = set()
    b = set()
    for i in xrange(1,n+1):
        if len(g[i]) == n-1:
            both.add(i)
        else:
            if i in a:
                for j in xrange(1,n+1):
                    if i != j and j not in g[i]:
                        b.add(j)
            else:
                for j in xrange(1,n+1):
                    if i != j and j not in g[i]:
                        a.add(j)

    for i in xrange(1,n+1):
        if i in a and i in b:
            return -1

    ans = float('inf')
    na = len(a)
    nb = len(b)
    nboth = len(both)
    for i in xrange(len(both)+1):
        ans = min(ans, (na+i)*(na+i-1)/2 + (nb+nboth-i)*(nb+nboth+i-1)/2)

    return ans


