        return

    bconwith0 = Bcon - Bgroup

    Agroup -= bconwith0

    Acon= set(target)
    for i in Agroup:
        Acon &= connections[i]

    if not Agroup.issubset(Acon):
        print(-1)
        return

    while len(bconwith0) != 0:
        ns = set()
