def dfs(v, cmp_list, visited, even, odd):
    visited[v] = True
    even.add(v)
    for w in cmp_list[v]:
        if w in even:
            return False
        if not visited[w]:
            r = dfs(w, cmp_list, visited, odd, even)
            if not r:
                return False

    return True


def solve(n, m, d):

    cmp_list = [[] for _ in range(n)]
    for v in range(n):
        for w in range(v + 1, n):
            if not (v, w) in d:
                cmp_list[v].append(w)
                cmp_list[w].append(v)

    graph_sizes = []
    full = []
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if len(cmp_list[i]):
                even = set()
                odd = set()
                r = dfs(i, cmp_list, visited, even, odd)
                if not r:
                    return -1
                graph_sizes.append((len(even), len(odd)))
            else:
                full.append(i)

    nh = n // 2
    if len(graph_sizes):
        dp = [[0] * (nh + 1) for _ in range(len(graph_sizes) + 1)]
        for i, p in enumerate(graph_sizes):
            w0, w1 = p
            if w1 < w0:
                w0, w1 = w1, w0
            for w in range(nh + 1):
                if w < w0:
                    dp[i + 1][w] = dp[i][w]
                elif w < w1:
                    dp[i + 1][w] = dp[i][w - w0] + w0
                else:
                    dp[i + 1][w] = max(dp[i][w - w0] + w0, dp[i][w - w1] + w1)
        l = min(nh, dp[len(graph_sizes)][nh] + len(full))
        m = n - l
    else:
        l = n // 2
        m = (n + 1) // 2

    return l * (l - 1) // 2 + m * (m - 1) // 2


