fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn dfs(target: usize, color: i32, edges: &Vec<Vec<usize>>, draw_result: &mut Vec<i32>) -> bool {
    if draw_result[target] != 0 {
        return color == draw_result[target];
    }
    draw_result[target] = color;
    for &to in edges[target].iter() {
        if !dfs(to, -color, edges, draw_result) {
            return false;
        }
    }
    true
}

fn main() {
    let v: Vec<usize> = read_vec();
    let (n, m) = (v[0], v[1]);
    let mut a = vec![0; m];
    let mut b = vec![0; m];

    let mut edges = vec![std::collections::HashSet::new(); n];

    for i in 0..m {
        let v: Vec<usize> = read_vec();
        let (a, b) = (v[0] - 1, v[1] - 1);
        edges[a].insert(b);
        edges[b].insert(a);
    }

    // make complement graph
    let mut complement_edges = vec![Vec::new(); n];
    for i in 0..n {
        for j in 0..n {
            if !edges[i].contains(&j) && i != j {
                complement_edges[i].push(j);
            }
        }
    }

    // draw
    let mut draw_result = vec![0; n]; //0: undrawn, -1 or 1

    let mut plus_group = Vec::new();
    let mut minus_group = Vec::new();

    for i in 0..n {
        if draw_result[i] == 0 {
            if !dfs(i, 1, &complement_edges, &mut draw_result) {
                println!("-1");
                return;
            }
        }
        let mut plus_count = 0;
        let mut minus_count = 0;
        for j in 0..n {
            if draw_result[j] == 1 {
                plus_count += 1;
            } else if draw_result[j] == -1 {
                minus_count += 1;
            }
        }
        let plus_group_new = plus_count - plus_group.iter().sum::<usize>();
        plus_group.push(plus_group_new);
        let minus_group_new = minus_count - minus_group.iter().sum::<usize>();
        minus_group.push(minus_group_new);
    }

    let mut dp = vec![false; n + 1];
    dp[plus_group.iter().sum::<usize>()] = true;

    for gi in 0..plus_group.len() {
        let diff = minus_group[gi] as i32 - plus_group[gi] as i32;
        for i in 0..n + 1 {
            let index = (diff + i as i32);
            if 0 <= index && index as usize <= n && dp[i] {
                dp[index as usize] = true;
            }
        }
    }

    let mut ans = std::usize::MAX;
    if dp[0] || dp[n] {
        ans = n * (n - 1) / 2;
    }
    for i in 1..n {
        if dp[i] {
            ans = std::cmp::min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
    }
    println!("{}", ans);
}

