use proconio::{input, marker::Usize1};

fn main() {
    input!(n: usize, m: usize, uv: [(Usize1, Usize1); m]);
    let mut adj = vec![vec![true; n]; n];
    (0..n).for_each(|i| adj[i][i] = false);
    for (u, v) in uv {
        adj[u][v] = false;
        adj[v][u] = false;
    }
    let mut g = vec![vec![]; n];
    for u in 0..n {
        for v in 0..n {
            if adj[u][v] {
                g[u].push(v);
            }
        }
    }

    let mut dp = vec![false; n + 1];
    dp[0] = true;
    let mut ckd = vec![false; n];
    let mut dist = vec![0; n];
    for s in 0..n {
        if ckd[s] {
            continue;
        }
        let mut que = std::collections::VecDeque::from(vec![s]);
        ckd[s] = true;
        let mut cnt = [0, 0];
        while let Some(x) = que.pop_front() {
            cnt[dist[x]] += 1;
            for &y in &g[x] {
                if ckd[y] {
                    if dist[x] == dist[y] {
                        println!("-1");
                        std::process::exit(0);
                    }
                    continue;
                }
                ckd[y] = true;
                dist[y] = 1 - dist[x];
                que.push_back(y);
            }
        }
        for x in cnt.iter() {
            for i in (0..=n - x).rev() {
                dp[i + x] |= dp[i];
            }
        }
    }
    let k = dp
        .iter()
        .copied()
        .enumerate()
        .skip(n / 2)
        .find(|&(_, b)| b)
        .unwrap()
        .0;
    println!("{}", k * (k - 1) / 2 + (n - k) * (n - k - 1) / 2);
}

