fn biparate(n: usize, edges: &Vec<Vec<usize>>) -> Option<Vec<i64>> {
    let mut xs = vec![0; n];
    let mut k = 0;
    for i in 0..n {
        if xs[i] == 0 {
            k += 1;
            xs[i] = k;
            if ! biparate_dfs(n, edges, &mut xs, i, k) {
                return None;
            }
        }
    }
    return Some(xs);
}

fn biparate_dfs(n: usize, edges: &Vec<Vec<usize>>, xs: &mut Vec<i64>, i: usize, k: i64) -> bool {
    for &to in &edges[i] {
        if xs[to] == 0 {
            xs[to] = -1 * xs[i];
            if ! biparate_dfs(n, edges, xs, to, k) {
                return false;
            }
        }
        else {
            if xs[to] == xs[i] {
                return false;
            }
        }
    }
    return true;
}

// minimize abs difference of (sum of x.0 or x.1) and reverse
fn select_dp(xs: Vec<(usize,usize)>) -> (usize,usize) {
    let mut total = 0;
    for &x in &xs {
        total += x.0 + x.1;
    }
    let mut dp = vec![false; total+1];
    dp[0] = true;
    for &x in &xs {
        for i in (0..total+1).rev() {
            if i >= x.0 && dp[i-x.0] {
                dp[i] = true;
            }
            else if i >= x.1 && dp[i-x.1] {
                dp[i] = true;
            }
            else {
                dp[i] = false;
            }
        }
    }
    let mut res = None;
    let mut diff = 0;
    for i in 0..total+1 {
        if total < i + i {
            break;
        }
        if dp[i] {
            if res.is_none() || diff > (total - i) - i {
                res = Some((i, total-i));
                diff = total - i - i;
            }
        }
    }
    match res {
        Some(a) => a,
        None => panic!(),
    }
}

