fn dfs(v: usize, color: usize, adj: &Table<bool>, colors: &mut [Option<usize>]) -> Option<[usize; 2]> {
    match colors[v] {
        Some(c) => (c == color).then([0; 2]),
        None => {
            colors[v] = Some(color);
            let mut res = [0; 2];
            res[color] = 1;
            for next in adj[v].iter().enumerate().filter(|&(_, &b)| b).map(|(i, _)| i) {
                match dfs(next, (color+1) % 2, adj, colors) {
                    None => return None,
                    Some(sub) => {
                        res[0] += sub[0];
                        res[1] += sub[1];
                    }
                }
            }
            Some(res)
        }
    }
}

fn main() {
    read!(n = usize, _ = ());
    let mut adj_complement = table![true; n,n];
    for v in 0..n {
        adj_complement[v][v] = false;
    }
    for (a, b) in read_lines::<(usize_, usize_)>() {
        adj_complement[a][b] = false;
        adj_complement[b][a] = false;
    }
    let mut colors = vec![None; n];
    let mut pairs = Vec::new();
    for v in 0..n {
        if colors[v].is_some() {
            continue;
        }
        match dfs(v, 0, &adj_complement, &mut colors) {
            None => exit(-1),
            Some(p) => pairs.push(p)
        }
    }

    let mut init = BitSet::new(n/2+1);
    *init.at(0) = true;
    let reachable = pairs.into_iter().fold(init, |reachable, p| {
        let r1 = reachable.clone() << p[0];
        let r2 = reachable << p[1];
        r1 | &r2
    });
    let i = (0..n/2+1).rev().find(|&i| reachable.get(i).unwrap()).unwrap();
    println!("{}", i*(i-1)/2 + (n-i)*(n-i-1)/2)
}

