        mat[a][b] = false;
        mat[b][a] = false;
    }
    let mut uf = UnionFind::new(n * 2);
    for u in 0..n - 1 {
        for v in u + 1..n {
            if mat[u][v] {
                uf.unite(u, v + n);
                uf.unite(u + n, v);
            }
        }
    }
    for u in 0..n {
        if uf.same(u, u + n) {
            println!("-1");
            return;
        }
    }
    let mut v = vec![];
    let mut used = vec![false; n];
    for (r, g) in uf.all_group_members() {
        if used[r % n] {
            continue;
        }
        for &u in g.iter() {
            used[u % n] = true;
        }
        let c = g.iter().filter(|&&u| u < n).count();
        v.push((c, g.len() - c));
    }
    let mut dp = vec![false; n + 1];
    dp[0] = true;
    for (a, b) in v {
        let mut ndp = vec![false; n + 1];
        for i in (a..=n).rev() {
            ndp[i] |= dp[i - a];
        }
        for i in (b..=n).rev() {
            ndp[i] |= dp[i - b];
        }
        dp = ndp;
    }
    let mut ans = !0usize;
    let c2 = |n: usize| n * (n.saturating_sub(1)) / 2;
    for i in 0..n {
        if dp[i] {
            chmin!(ans, c2(i) + c2(n - i));
        }
    }
    println!("{}", ans);
}

