    let mut ps = Vec::new();

    for i in 0..n {
        if vs[i].is_none() {
            let mut x = 0;
            let mut y = 0;

            let mut stack = vec![(i, true)];

            while let Some((i, c)) = stack.pop() {
                if vs[i] == Some(c) {
                    continue;
                }

                if vs[i] == Some(!c) {
                    println!("-1");
                    return;
                }

                if c {
                    x += 1;
                } else {
                    y += 1;
                }
                vs[i] = Some(c);
                for &to in &es[i] {
                    stack.push((to, !c));
                }
            }

            ps.push((x, y));
        }
    }

    let mut dp = vec![vec![false; n + 1]; ps.len() + 1];
    dp[0][0] = true;

    for i in 1..ps.len() + 1 {
        let (x, y) = ps[i - 1];

        for j in (x..n + 1).rev() {
            dp[i][j] = dp[i][j] || dp[i - 1][j - x];
        }
        for j in (y..n + 1).rev() {
            dp[i][j] = dp[i][j] || dp[i - 1][j - y];
        }
    }

    let ans = (0..n)
        .filter(|&i| dp[ps.len()][i])
        .map(|i| {
            let j = n - i;
            ((if i > 1 { i * (i - 1) / 2 } else { 0 }) + (if j > 1 { j * (j - 1) / 2 } else { 0 }))
                as i64
        })
        .min()
        .unwrap_or(-1);

    println!("{}", ans);
}

