// minimize abs difference of (sum of x.0 or x.1) and reverse
fn select_dp(xs: Vec<(usize,usize)>) -> (usize,usize) {
    let mut total = 0;
    for &x in &xs {
        total += x.0 + x.1;
    }
    let mut dp = vec![false; total+1];
    dp[0] = true;
    for &x in &xs {
        for i in (0..total+1).rev() {
            if i >= x.0 && dp[i-x.0] {
                dp[i] = true;
            }
            else if i >= x.1 && dp[i-x.1] {
                dp[i] = true;
            }
            else {
                dp[i] = false;
            }
        }
    }
    let mut res = None;
    let mut diff = 0;
    for i in 0..total+1 {
        if i >= total - i {
            break;
        }
        if dp[i] {
            if res.is_none() || diff > (total - i) - i {
                res = Some((i, total-i));
                diff = total - i - i;
            }
        }
    }
    match res {
        Some(a) => a,
        None => panic!(),
    }
}

