                return;
            }
            turn += 1;
        }
    }

    let mut count = vec![[0; 2]; turn];
    for i in 0..n {
        count[t[i]][color[i] - 1] += 1;
    }
    let mut dp = vec![false; n + 1];
    dp[0] = true;
    for [a, b] in count.into_iter() {
        let mut next = vec![false; n + 1];
        for cur in 0..(n + 1) {
            if cur + a <= n {
                next[cur + a] |= dp[cur];
            }
            if cur + b <= n {
                next[cur + b] |= dp[cur];
            }
        }
        dp = next;
    }

    let mut ans = n * n;
    for one in 0..(n + 1) {
