fn biparate(n: usize, edges: &Vec<Vec<usize>>) -> Option<Vec<i64>> {
    let mut xs = vec![0; n];
    let mut k = 0;
    for i in 0..n {
        if xs[i] == 0 {
            k += 1;
            xs[i] = k;
            if ! dfs(n, edges, &mut xs, i, k) {
                return None;
            }
        }
    }
    return Some(xs);
}

fn dfs(n: usize, edges: &Vec<Vec<usize>>, xs: &mut Vec<i64>, i: usize, k: i64) -> bool {
    for &to in &edges[i] {
        if xs[to] == 0 {
            xs[to] = -1 * xs[i];
            if ! dfs(n, edges, xs, to, k) {
                return false;
            }
        }
        else {
            if xs[to] == xs[i] {
                return false;
            }
        }
    }
    return true;
}

