fn run() {
    input! {
        n: usize,
        m: usize,
        e: [(usize1, usize1); m],
    }
    let mut g = vec![vec![true; n]; n];
    for (i, g) in g.iter_mut().enumerate() {
        g[i] = false;
    }
    for (a, b) in e {
        g[a][b] = false;
        g[b][a] = false;
    }
    let mut used = vec![false; n];
    let mut dp = vec![false; n + 1];
    dp[0] = true;
    for i in 0..n {
        if used[i] {
            continue;
        }
        let mut d = vec![0usize; n];
        let mut cnt = [0; 2];
        used[i] = true;
        let mut stack = vec![i];
        while let Some(v) = stack.pop() {
            cnt[d[v]] += 1;
            for (u, g) in g[v].iter().enumerate() {
                if !g {
                    continue;
                }
                if !used[u] {
                    d[u] = d[v] ^ 1;
                    used[u] = true;
                    stack.push(u);
                } else if d[u] == d[v] {
                    println!("-1");
                    return;
                }
            }
        }
        let mut next = vec![false; n + 1];
        for &c in cnt.iter() {
            for (x, p) in next.iter_mut().skip(c).zip(dp.iter()) {
                *x |= *p;
            }
        }
        dp = next;
    }
    let mut ans = std::usize::MAX;
    for (i, p) in dp.into_iter().enumerate() {
        if p {
            ans = std::cmp::min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
        }
    }
    println!("{}", ans);
}

