use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

struct App {
    // input
    n: usize,
    adj: Vec<Vec<bool>>,
    // intermediate variables
    col: Vec<i32>,
    fail: bool,
}

impl App {
    fn input() -> App {
        let n: usize = read();
        let m: usize = read();
        let mut adj: Vec<Vec<bool>> = vec![vec![false; n]; n];
        for _ in 0..m {
            let a = read::<usize>() - 1;
            let b = read::<usize>() - 1;
            adj[a][b] = true;
            adj[b][a] = true;
        }
        return App {
            n: n, adj: adj,
            col: vec![-1; n],
            fail: false
        };
    }

    fn solve(&mut self) {
        let mut ts: Vec<(usize, usize)> = Vec::new();

        for v in 0..self.n {
            if self.col[v] != -1 {
                continue;
            }

            let (a, b) = self.dfs(v, 0);
            ts.push((a, b));
        }

        if self.fail {
            println!("-1");
            return;
        }

        let mut crr: Vec<bool> = vec![false; self.n + 1];
        crr[0] = true;
        for &(a, b) in ts.iter() {
            let mut nxt: Vec<bool> = vec![false; self.n + 1];
            for i in 0..self.n {
                if crr[i] {
                    nxt[i + a] = true;
                    nxt[i + b] = true;
                }
            }
            crr = nxt;
        }

        let mut ans = 1000000000;
        for i in 0..self.n {
            if crr[i] {
                let a = i as i64;
                let b = (self.n - i) as i64;
                ans = std::cmp::min(ans, a * (a - 1) / 2 + b * (b - 1) / 2);
            }
        }
        println!("{}", ans);
    }

    fn dfs(&mut self, v: usize, c: i32) -> (usize, usize) {
        if self.col[v] != -1 {
            if self.col[v] != c {
                self.fail = true;
            }
            return (0, 0);
        }
        self.col[v] = c;
        // println!("{}: {}", v, c);

        let mut a = 0;
        let mut b = 0;

        if c == 0 {
            a += 1;
        } else {
            b += 1;
        }

        for w in 0..self.n {
            if v == w || self.adj[v][w] {
                continue;
            }
            let (da, db) = self.dfs(w, 1 - c);
            a += da;
            b += db;
        }

        return (a, b);
    }
}

