fn dfs(n: usize, edges: &Vec<Vec<usize>>, xs: &mut Vec<i64>, i: usize) -> bool {
    for &to in &edges[i] {
        if xs[to] == 0 {
            xs[to] = -1 * xs[i];
            if ! dfs(n, edges, xs, to) {
                return false;
            }
        }
        else {
            if xs[to] == xs[i] {
                return false;
            }
        }
    }
    return true;
}

