const INF: i64 = 0x3f3f3f3f3f3f3f3f;
const MOD: i64 = 1000000007;
const NOTHING: usize = std::usize::MAX;
const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];

fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.read();
    let mut g: Vec<Vec<bool>> = vec![vec![true;n];n];
    for i in 0..n {
        g[i][i] = false;
    }

    for _ in 0..m {
        let (x, y): (usize, usize) = io.read();
        let x = x - 1;
        let y = y - 1;
        g[x][y] = false;
        g[y][x] = false;
    }

    let mut edges = vec![];
    for i in 0..n {
        for j in i + 1..n {
            if g[i][j] {
                edges.push((i, j));
            }
        }
    }

    let option_components = BipartiteGraph::components(n, &edges);
    if option_components.is_none() {
        io.writeln("-1");
        return;
    }
    let components = option_components.unwrap();

    let mut set: Vec<bool> = vec![false;n+1];
    set[0] = true;
    for component in components {
        let s0 = component.color0.len();
        let s1 = component.color1.len();
        let mut new = vec![false;n+1];
        for i in (0..n + 1).rev() {
            if s0 <= i {
                new[i] |= set[i - s0];
            }
            if s1 <= i {
                new[i] |= set[i - s1];
            }
        }
        std::mem::swap(&mut set, &mut new);
    }


    let mut res = m;
    for s in 1..n {
        if set[s] {
            res = min(res, s * (s - 1) / 2 + (n - s) * (n - s - 1) / 2);
        }
    }

    io.writeln(res)

}

#[derive(Debug)]
pub struct BipartiteComponent {
    color0: Vec<usize>,
    color1: Vec<usize>,
}

pub struct BipartiteGraph {}

impl BipartiteGraph {
    pub fn is_bipartite(num_v: usize, edges: &Vec<(usize, usize)>) -> bool {
        let mut uf = UnionFind::new(2 * num_v);
        for &(x, y) in edges {
            uf.unite(2 * x, 2 * y + 1);
            uf.unite(2 * y, 2 * x + 1);
        }
        for i in 0..num_v {
            if uf.equiv(2 * i, 2 * i + 1) {
                return false;
            }
        }
        true
    }

    pub fn components(num_v: usize,
                      edges: &Vec<(usize, usize)>)
                      -> Option<Vec<BipartiteComponent>> {
        let mut uf = UnionFind::new(2 * num_v);
        for &(x, y) in edges {
            uf.unite(2 * x, 2 * y + 1);
            uf.unite(2 * y, 2 * x + 1);
        }
        let mut reprs = HashSet::new();
        for i in 0..num_v {
            let p0 = uf.find(2 * i);
            let p1 = uf.find(2 * i + 1);
            if p0 == p1 {
                return None;
            } else if !reprs.contains(&p0) && !reprs.contains(&p1) {
                reprs.insert(p0);
            }
        }

        Some(uf.groups()
            .iter()
            .filter(|(repr, _)| reprs.contains(repr))
            .map(|(_, group)| {
                let (color0, color1): (Vec<usize>, Vec<usize>) = group.into_iter()
                    .partition(|&x| x & 1 == 0);
                BipartiteComponent {
                    color0: color0.iter().map(|&x| x >> 1).collect(),
                    color1: color1.iter().map(|&x| x >> 1).collect(),
                }
            })
            .collect())
    }
}

pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: vec![NOTHING; n],
            rank: vec![0; n],
            size: vec![1; n],
        }
    }

    pub fn iter(&self) -> Range<usize> {
        0..self.parent.len()
    }

    pub fn find(&mut self, x: usize) -> usize {
        if self.parent[x] == NOTHING {
            x
        } else {
            let px = self.parent[x];
            let root = self.find(px);
            self.parent[x] = root;
            root
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) {
        let px = self.find(x);
        let py = self.find(y);

        if px == py {
            return;
        }

        if self.rank[px] < self.rank[py] {
            self.parent[px] = py;
            self.size[py] += self.size[px];
        } else {
            self.parent[py] = px;
            self.size[px] += self.size[py];
            if self.rank[px] == self.rank[py] {
                self.rank[px] += 1;
            }
        }

    }

    pub fn equiv(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    pub fn group_size(&mut self, x: usize) -> usize {
        let px = self.find(x);
        self.size[px]
    }

    pub fn groups(&mut self) -> HashMap<usize, Vec<usize>> {
        let mut res = HashMap::new();
        for i in self.iter() {
            let p = self.find(i);
            let ref mut gp = res.entry(p).or_insert(vec![]);
            gp.push(i);
        }
        res
    }

    pub fn count_group(&self) -> usize {
        self.parent.iter().filter(|&p| *p == NOTHING).collect::<Vec<_>>().len()
    }
}

