        es: [(usize1, usize1); m]
    }
    let mut g = vec![(0..n).collect::<BTreeSet<usize>>(); n];
    for i in 0..n {
        g[i].remove(&i);
    }
    for &(a, b) in &es {
        g[a].remove(&b);
        g[b].remove(&a);
    }
    let g = g.iter().map(|s| s.iter().cloned().collect::<Vec<usize>>()).collect::<Vec<_>>();
    let mut done = vec![None; n];
    let mut ds = vec![];
    for i in 0..n {
        if done[i].is_some() {
            continue;
        }
        let mut ct: i64 = 1;
        let mut cf: i64 = 0;
        done[i] = Some(true);
        let mut st = vec![i];
        while let Some(v) = st.pop() {
            let f = !done[v].unwrap();
            for &c in &g[v] {
                if let Some(fc) = done[c] {
                    if fc ^ f {
                        println!("-1");
                        return;
                    }
                    continue;
                }
                if f {
                    ct += 1;
                } else {
                    cf += 1;
                }
                done[c] = Some(f);
                st.push(c);
            }
        }
        ds.push((ct - cf).abs() as usize);
    }
    let mut dp = vec![false; n + 1];
    dp[ds[0]] = true;
    for i in 1..ds.len() {
        let mut next = vec![false; n + 1];
        for j in 0..n + 1 - ds[i] {
            next[j + ds[i]] |= dp[j];
        }
        for j in 0..n + 1 {
            next[(j as i64 - ds[i] as i64).abs() as usize] |= dp[j];
        }
        dp = next;
    }
    for i in 0..n + 1 {
        if dp[i] {
            println!("{}", ((n + i) / 2) * ((n + i) / 2 - 1) / 2 + ((n - i) / 2) * ((n - i) / 2 - 1) / 2);
            return;
        }
    }
}

