    let mut graph = vec![vec![false; n]; n];
    for _ in 0..m {
        let a = sc.usize_read() - 1;
        let b = sc.usize_read() - 1;
        graph[a][b] = true;
        graph[b][a] = true;
    }

    for i in 0..n {
        graph[i][i] = true;
    }

    let mut graph2 = vec![vec![]; n];
    for i in 0..n {
        for j in 0..n {
            if !graph[i][j] {
                graph2[i].push(j);
            }
        }
    }

    let mut color = vec![0; n];
    let mut st = vec![];
    for i in 0..n {
        if color[i] != 0 {
            continue;
        }
        let mut vis = vec![];
        color[i] = 1;
        if !dfs(i, &graph2, &mut color, &mut vis) {
            println!("-1");
            return;
        }
        let mut count = 0;
        for &v in &vis {
            if color[v] == 1 {
                count += 1;
            }
        }
        st.push((vis.len() - count, count));
    }

    let mut ok = vec![false; n + 1];
    ok[0] = true;
    for &(s, t) in &st {
        for i in (0..n).rev() {
            if ok[i] {
                ok[i + s] = true;
                ok[i + t] = true;
            }
        }
    }

    let mut ans = n * (n - 1) / 2;
    for i in 1..n {
        if ok[i] {
            let j = n - i;
            ans = cmp::min(ans, j * (j - 1) / 2 + i * (i - 1) / 2);
        }
    }

