const INF: i64 = 0x3f3f3f3f3f3f3f3f;
const MOD: i64 = 1000000007;
const NOTHING: usize = std::usize::MAX;
const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];

fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.read();
    let mut g: Vec<Vec<bool>> = vec![vec![true;n];n];
    let mut uf = UnionFind::new(2 * n);
    for i in 0..n {
        g[i][i] = false;
    }

    for _ in 0..m {
        let (x, y): (usize, usize) = io.read();
        let x = x - 1;
        let y = y - 1;
        g[x][y] = false;
        g[y][x] = false;
    }

    for i in 0..n {
        for j in i + 1..n {
            if g[i][j] {
                uf.unite(i << 1, (j << 1) + 1);
                uf.unite(j << 1, (i << 1) + 1);
            }
        }
    }

    let mut ok = true;
    for i in 0..n {
        ok &= !uf.equiv(i << 1, (i << 1) + 1);
    }

    if !ok {
        io.writeln("-1");
        return;
    }

    let gs = uf.groups();

    let mut used: Vec<bool> = vec![false;n];
    let mut comps = vec![];
    for i in 0..n {
        if used[i] {
            continue;
        }

        let p = uf.find(i << 1);
        let g = gs.get(&p).unwrap();
        let mut s0 = 0;
        let mut s1 = 0;
        for x in g {
            used[x >> 1] = true;
            if x % 2 == 0 {
                s0 += 1;
            } else {
                s1 += 1;
            }
        }
        comps.push((s0, s1));
    }

    let mut set: Vec<bool> = vec![false;n+1];
    set[0] = true;
    for &(s0, s1) in &comps {
        for i in (0..n + 1).rev() {
            if s0 <= i {
                set[i] |= set[i - s0];
            }
            if s1 <= i {
                set[i] |= set[i - s1];
            }
        }
    }


    let mut res = m;
    for s in 1..n {
        if set[s] {
            res = min(res, s * (s - 1) / 2 + (n - s) * (n - s - 1) / 2);
        }
    }

    io.writeln(res)

}

pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: vec![NOTHING; n],
            rank: vec![0; n],
            size: vec![1; n],
        }
    }

    pub fn iter(&self) -> Range<usize> {
        0..self.parent.len()
    }

    pub fn find(&mut self, x: usize) -> usize {
        if self.parent[x] == NOTHING {
            x
        } else {
            let px = self.parent[x];
            let root = self.find(px);
            self.parent[x] = root;
            root
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) {
        let px = self.find(x);
        let py = self.find(y);

        if px == py {
            return;
        }

        if self.rank[px] < self.rank[py] {
            self.parent[px] = py;
            self.size[py] += self.size[px];
        } else {
            self.parent[py] = px;
            self.size[px] += self.size[py];
            if self.rank[px] == self.rank[py] {
                self.rank[px] += 1;
            }
        }

    }

    pub fn equiv(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    pub fn group_size(&mut self, x: usize) -> usize {
        let px = self.find(x);
        self.size[px]
    }

    pub fn groups(&mut self) -> HashMap<usize, Vec<usize>> {
        let mut res = HashMap::new();
        for i in self.iter() {
            let p = self.find(i);
            let ref mut gp = res.entry(p).or_insert(vec![]);
            gp.push(i);
        }
        res
    }

    pub fn count_group(&self) -> usize {
        self.parent.iter().filter(|&p| *p == NOTHING).collect::<Vec<_>>().len()
    }
}

