const INF: i64 = 0x3f3f3f3f3f3f3f3f;
const MOD: i64 = 1000000007;
const NOTHING: usize = std::usize::MAX;
const DX: [usize; 4] = [1, 0, std::usize::MAX, 0];
const DY: [usize; 4] = [0, 1, 0, std::usize::MAX];

fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, m): (usize, usize) = io.read();
    let mut d: Vec<Vec<i64>> = vec![vec![INF;n];n];
    for _ in 0..m {
        let (x, y): (usize, usize) = io.read();
        d[x - 1][y - 1] = 1;
        d[y - 1][x - 1] = 1;
    }

    for i in 0..n {
        d[i][i] = 0;
    }

    let mut res = m;
    let mut found = false;
    for i in 0..n {
        for j in i + 1..n {
            let mut x: usize = 1;
            let mut y: usize = 1;
            let mut xy: usize = 0;
            for k in 0..n {
                if k == i || k == j {
                    continue;
                }
                if d[i][k] == 1 {
                    if d[j][k] == 1 {
                        xy += 1;
                    } else {
                        x += 1;
                    }
                } else if d[j][k] == 1 {
                    y += 1;
                }

            }

            if x + xy + y < n {
                continue;
            }
            found = true;
            if x > y {
                std::mem::swap(&mut x, &mut y);
            }
            if x + xy <= y {
                x += xy;
            } else {
                let diff = x + xy - y;
                y += diff;
                x = y;
                if diff & 1 == 1 {
                    y += 1;
                }
            }

            debug_assert!(x <= y);

            if x > 0 {
                res = min(res, x * (x - 1) / 2 + y * (y - 1) / 2);
            }
        }
    }
    if found {
        io.writeln(res)
    } else {
        io.writeln("-1")
    }
}

